-- What a page sounds like: which pack narrates it, where the file is, how long it runs.
--
-- Narration ships in a separate sound-pack addon because it is a large download, and it is
-- optional: without one there is nothing to play, so the addon stays quiet and says why.
--
-- THERE IS NO STAND-IN CLIP, for the reason addons/Spoken_Places/Audio.lua gives at length:
-- substituting unrelated audio is worse than silence, because silence is honest about what
-- is missing and a borrowed clip is not.

local ADDON_NAME, SpokenReadables = ...

-- A value the game hands over as a secret, in an instance or in combat, reads as nil.
local NotSecret = Spoken and Spoken.NotSecret or function(value) return value end

local L = SpokenReadables.L

-- The pack table shape this version knows how to read. A pack declaring anything else is
-- ignored with a warning: refusing to read it is recoverable, guessing at an unknown layout
-- plays silence and reports nothing.
local PACK_FORMAT = 1

-- The player's own book art. Pointed at rather than copied: Spoken is installed
-- alongside this addon by definition -- it is what the clips are queued through -- and a
-- second copy of the same texture is a second thing to keep in step.
local BOOK_TEXTURE = [[Interface\AddOns\Spoken\Textures\Book]]

-- A page's picture: a bag item's own icon, else the material it is on, else the book.
local ICON_CROP = { 0.08, 0.92, 0.08, 0.92 }
local MATERIALS = {
	Stone = [[Interface\Icons\INV_Misc_StoneTablet_01]],
	Marble = [[Interface\Icons\INV_Misc_StoneTablet_07]],
	Bronze = [[Interface\Icons\INV_Misc_StoneTablet_03]],
	Silver = [[Interface\Icons\INV_Misc_StoneTablet_11]],
	Valentine = [[Interface\Icons\INV_Letter_15]],
}
SpokenReadables.MATERIALS = MATERIALS

-- What a kind of writing is written on where no page is open to ask the game (a readable played
-- from Azeroth's Compendium): gravestones and tablets in stone, plaques and exhibits in bronze,
-- the rest on paper. The book window draws the stone ones in stone.
local KIND_MATERIAL = { grave = "Stone", tablet = "Stone", plaque = "Bronze", exhibit = "Bronze" }

-- Whether `pageId` is a page of the book open in the world, whose item and material the game can
-- tell: they are the same on every page, and the next page is built while another is open.
local function IsOpen(self, pageId)
	return self.lastPage ~= nil and (pageId == nil or self:PlaceOf(pageId) == self:PlaceOf(self.lastPage))
end

--- What `pageId`'s readable is written on by its kind, or nil for paper.
function SpokenReadables:KindMaterial(pageId)
	local place = pageId and self:Data() and self:Data().pages[pageId]
	local places = _G.SpokenReadablesPlaces and SpokenReadablesPlaces.books
	local entry = place and places and places[place.book]
	return entry and KIND_MATERIAL[entry.type] or nil
end

--- Open is what the item text events say, not the game's frame, which DialogueUI hides. A page
--- not open (of another book than the one open, or nothing open) takes what its kind is written
--- on, else the book.
function SpokenReadables:PagePicture(pageId)
	if IsOpen(self, pageId) then
		local item = ItemTextGetItem and NotSecret(ItemTextGetItem())
		local icon, crop
		if Spoken and Spoken.BagItemIcon then icon, crop = Spoken:BagItemIcon(item) end
		if icon then return { kind = "texture", texture = icon, texCoord = crop } end
		local material = ItemTextGetMaterial and NotSecret(ItemTextGetMaterial())
		if self.Explain then self:Explain("picture: %s is not in the bags; its material is %s", tostring(item), tostring(material)) end
		if material and MATERIALS[material] then
			return { kind = "texture", texture = MATERIALS[material], texCoord = ICON_CROP }
		end
	end
	local material = not IsOpen(self, pageId) and self:KindMaterial(pageId)
	if material then return { kind = "texture", texture = MATERIALS[material], texCoord = ICON_CROP } end
	return { kind = "texture", texture = BOOK_TEXTURE }
end

--- What `pageId` is written on (ItemTextGetMaterial: Parchment, Stone, Marble...): the game's
--- word for the page open, else its kind's (KindMaterial), else nil.
function SpokenReadables:PageMaterial(pageId)
	if IsOpen(self, pageId) then return ItemTextGetMaterial and NotSecret(ItemTextGetMaterial()) or nil end
	return self:KindMaterial(pageId)
end

-- What a readable can be (Data/Places.lua's `type`), in the order the Compendium lists them,
-- and the keys of its names: `one` of it, over its line in the queue, and `all`, the Compendium's.
SpokenReadables.TYPES = { "book", "journal", "letter", "note", "scroll", "tablet", "plaque", "grave", "exhibit",
	"picture", "other" }
SpokenReadables.TYPE_NAMES = {
	book = { one = "READABLE_BOOK", all = "TYPE_BOOK" },
	journal = { one = "READABLE_JOURNAL", all = "TYPE_JOURNAL" },
	letter = { one = "READABLE_LETTER", all = "TYPE_LETTER" },
	note = { one = "READABLE_NOTE", all = "TYPE_NOTE" },
	scroll = { one = "READABLE_SCROLL", all = "TYPE_SCROLL" },
	tablet = { one = "READABLE_TABLET", all = "TYPE_TABLET" },
	plaque = { one = "READABLE_PLAQUE", all = "TYPE_PLAQUE" },
	grave = { one = "READABLE_GRAVE", all = "TYPE_GRAVE" },
	exhibit = { one = "READABLE_EXHIBIT", all = "TYPE_EXHIBIT" },
	picture = { one = "READABLE_PICTURE", all = "TYPE_PICTURE" },
	other = { one = "READABLE_OTHER", all = "TYPE_OTHER" },
}

--- What `book` is (a book, a letter, a gravestone...), as the Compendium sorts it.
function SpokenReadables:KindOf(book)
	local places = _G.SpokenReadablesPlaces and SpokenReadablesPlaces.books
	local place = places and places[book]
	return L[(self.TYPE_NAMES[place and place.type] or self.TYPE_NAMES.other).one]
end

--- Whether a book is one line in the queue (Read Book as One Line), rather than a line per page.
function SpokenReadables:OneLine()
	return not (SpokenReadablesSettings and SpokenReadablesSettings.bookAsOneLine == false)
end

--- Every installed pack this version can read, newest format first. Packs released as
--- SpokenBooksAudio write SpokenBooksAudioPacks, and stay on players' disks, so it is read too; one
--- whose SpokenReadablesAudio replacement is installed beside it is the same pack, one release older.
--- The list is kept for as long as the registries hold the same packs: it is asked for on every
--- readable the Compendium lists, and every page of one.
-- Embedded SpokenReadablesAudio_esMX registry so /reload works without restarting WoW.exe
do
	SpokenReadablesAudioPacks = SpokenReadablesAudioPacks or {}
	if not SpokenReadablesAudioPacks['SpokenReadablesAudio_esMX'] then
		local pack = {
	version = 1,
	addon = 'SpokenReadablesAudio_esMX', packVersion = '1.0.3',
	quality = "high",
	bitrate = 128,
	language = "esMX",
	pages = {
		[15] = { file = "15", len = 25.731, text = "Hola, Morgan, Los negocios en Villadorada van muy bien, tan bien que no he tenido tiempo de hacerte ningún envío. He encargado al portador de esta nota que entregue un paquete de velas de cera grandes (sabes a cuáles me refiero, ¿no?, las que los kóbolds suelen llevar en sus cabezas). Te ruego que se lo agradezcas a esta persona de nuestra parte y le pagues lo que sea justo." },
		[16] = { file = "16", len = 35.135, text = "Para el honorable rector Crillian: Mi antiguo maestro, te escribo para que sepas lo que tu antiguo alumno ha estado haciendo últimamente. Siguiendo tu consejo, he procurado cultivar mis conocimientos y aumentar mi sabiduría viajando fuera de nuestra amada Ventormenta. Los viajes me han llevado a muchos lugares, pero he decidido instalarme en el bello poblado de Arroyo de la Luna. Los campos que rodean los Páramos de Poniente son más bellos a medida que se avecina la cosecha." },
		[17] = { file = "17", len = 28.134, text = "A los pocos días de mi visita, ya estaba dando clases a los niños que habitan los cultivos vecinos. Las lecciones tuvieron tanto éxito que el alcalde del pueblo me encargó que abriera una escuela, de manera que se inició la construcción de unas aulas totalmente nuevas. De Argénteos a Ventormenta, y ahora Arroyo de la Luna. ¡Quién iba a imaginar que conocería tanto Azeroth! Un saludo afectuoso, Stalvan Mantoniebla" },
		[18] = { file = "18", len = 34.9, text = "Querido y noble señor: A la Posada Orgullo de León de Villadorada, donde resido temporalmente, me han llegado noticias de su necesidad de un tutor para sus hijos. Debido a los desafortunados acontecimientos que han tenido lugar en la región, me he visto obligado a abandonar mi cargo de rector de la Escuela de Arroyo de la Luna. Les ruego que acepten mi solicitud para trabajar como tutor de sus hijos. Si es necesario, el rector Crillian de la Academia les proporcionará referencias de mi trabajo." },
		[19] = { file = "19", len = 11.154, text = "Iré a conoceros en persona cuando las lluvias invernales amainen y los caminos vuelvan a ser transitables. Hasta pronto, Stalvan Mantoniebla de Argénteos" },
		[20] = { file = "20", len = 38.322, text = "... Giles, el chico, parece un poco arrogante y su educación será todo un desafío. No obstante, Tilloa, la hija mayor, parece extraordinariamente inteligente. Por otra parte, no he podido obviar su cautivadora belleza. Está en la flor de la vida. Al parecer, el señor ha fijado su boda para el próximo año. Pero cambio de tema. Esta semana acompañaré a la familia a su casita de verano junto al aserradero de la Vega del Este en Elwynn, cerca de las montañas Crestagrana. Espero escribir con mayor asiduidad cuando esté allí." },
		[21] = { file = "21", len = 28.604, text = "... qué sentimiento tan extraño e incontrolable. No había sentido nunca lo que sentí hoy. Mientras ayudaba a Giles con sus lecciones de historia, Tilloa cuidaba del jardín de flores. Transcurridos unos minutos, entró en casa y colocó una begonia escarlata en la palma de mi mano y me sonrió de un modo tan especial, que sentí cómo mi corazón palpitaba con fuerza..." },
		[22] = { file = "22", len = 22.465, text = "... estoy totalmente seguro de que ahora ella comparte los mismos sentimientos por mí. Esta mañana, incluso, posó su mano en la mía. Cuando sonríe, sus ojos brillan como diamantes. Nos entendemos con solo mirarnos. Puedo sentirla en los latidos de mi corazón y en mis acaloradas venas." },
		[23] = { file = "23", len = 38.557, text = "... ¡una rabia y furia como no creía que pudieran existir! ¡Cómo se atreve! Cuando enseñaba a Giles el misterio de los números, Tilloa apareció con un pretendiente, ¡los dos cogidos de la mano, y en público, nada menos! Qué joven más zafio. En lugar de presentarnos como es debido, Tilloa simplemente dijo: \"Oh, este es el tío Stalvan, mi tutor. Es un viejo muy agradable.\" ¡Viejo! Esa palabra hizo que la sangre estallara en mis mejillas. Si solo soy unos cuantos años mayor que ella y, aun así, ella me traiciona de esa manera. . ." },
		[24] = { file = "24", len = 28.369, text = "... he entrado en una espiral de desesperación. Primero se burla de mí y ahora está comprometida. Esa charlatana descortés fingía que me amaba cuando en realidad solo deseaba herirme. Me abruma un oscuro vacío que crece con el tiempo y se hace más intenso al despertar. La sangre que derramaré palidece frente a las lágrimas que he vertido. . ." },
		[25] = { file = "25", len = 35.37, text = "Tommy Joe, Cada hora que pasa, mi corazón se marchita sin tu presencia. Oh, si nuestros padres pudieran ver más allá de los absurdos crímenes que han cometido unos contra otros, sabrían que el único verdadero crimen es el odio. El odio consume, y me temo que, en estos tiempos oscuros, se apoderará no solo de nuestras familias. Si se dieran cuenta de ello, al fin podríamos estar juntos. Sueño con que llegue ese día, vivo para ese día. Con todo mi amor, Maybell" },
		[26] = { file = "26", len = 29.753, text = "Hola, William, Han pasado años desde que hablamos la última vez, pero espero que tú y tu hermano estén bien, y que prosperes como boticario. William, tengo que pedirte un favor. Para ser breve, mi hijo Tommy Joe se ha enamorado locamente de la joven Maybell Maclure. Y a pesar del gran amor que sienten el uno por el otro, nuestras familias... verás, nuestras familias llevan años enemistadas." },
		[28] = { file = "28", len = 29.336, text = "Argus: Como ya sabéis, estoy hasta arriba de solicitudes de reparación por parte del ejército. No puedo quejarme por tanto trabajo, pero lo cierto es que están agotando mis reservas de hierro. No tengo suficiente hierro para herraduras. Sé que siempre dispones de abundantes reservas, por eso quería pedirte prestados 50 pares de herraduras hasta que consiga mi próximo envío de hierro. Te lo agradezco de antemano, Verner" },
		[29] = { file = "29", len = 31.634, text = "El cajón lleva una nota adjunta. La nota dice: \"Verner, lamento saber que Crestagrana tiene tantos problemas. Aquí están las herraduras que necesitas. Por favor, no olvides pagarme 100 monedas de plata en cuanto te sea posible.\" \"O bien, si lo prefieres, puedes pagarme con escamas de vientre de cría (he oído que las crías de dragón son comunes en las montañas Crestagrana). Porque somos amigos... 4 escamas serán suficiente. Gracias, Argus\"" },
		[30] = { file = "30", len = 27.69, text = "Mi señor: La guerra se cierne sobre nosotros. La fatalidad nos acecha. Como magistrado del municipio de Villa del Lago, es mi deber informar acerca de la reciente actividad militar que ha tenido lugar en la colonia de su Majestad, situada en el extremo este. En estas páginas encontrará un informe sobre el estado de Villa del Lago, enclavado en las montañas Crestagrana." },
		[31] = { file = "31", len = 28.186, text = "La pérdida del Fuerte de Petravista nos ha afectado terriblemente. Anteriormente les informé acerca de la alianza existente entre el clan de orcos Roca Negra y el brujo conocido como Morganth. Los orcos Roca Negra lucharon salvajemente, reforzados por la magia perversa de Morganth. Muchos de los más valientes soldados de Su Majestad perecieron intentando defender el fuerte, pero finalmente no se pudo hacer nada." },
		[32] = { file = "32", len = 27.402, text = "Curiosamente, Morganth se volvió contra sus seguidores orcos tras su nefasta victoria. El brujo construyó una torre arcana en el noreste y usó sus poderes para crear un pequeño ejército de gnolls Pielsombra a su servicio. Tanto los orcos como los hombres fueron víctimas de las bestias viscosas que servían al brujo. En cuanto a la traición entre Morganth y Gath'Ilzogg, Señor de la Guerra Roca Negra, solo caben especulaciones." },
		[33] = { file = "33", len = 32.522, text = "Para nuestra preocupación, los apestosos orcos parecen dedicarse a matar a los honrados ciudadanos de Su Majestad. Durante la última quincena, el clan Roca Negra desató una implacable ofensiva sobre Villa del Lago. Muchos hombres valientes perdieron la vida aquel aciago día. Las fuerzas de los orcos avanzaron tan rápidamente y con tanta furia que destruyeron el puente sobre el lago Sempiterno. Nuestros suministros de guerra disminuyeron ostensiblemente. Carecemos de vendas para curar las heridas de los caídos." },
		[34] = { file = "34", len = 31.556, text = "Ahora solicito a Su Majestad el apoyo para esta buena gente de Villa del Lago en estos aciagos momentos. Necesitamos nuevos soldados para defender el territorio, así como nuevas armas de guerra para sustituir las que hemos perdido en el campo de batalla. Asimismo, escasean los alimentos y los suministros para la construcción. Mi señor, te ruego nos ayudes a mantener en pie el último bastión que queda entre los hombres y los orcos. El enemigo debe permanecer fuera del Reino de Ventormenta." },
		[35] = { file = "35", len = 22.622, text = "Temo que un mal aún más siniestro y terrible se cierna sobre la caldera fétida de las tierras del norte. Resulta crucial que el Reino de Ventormenta entre en acción para evitar convertirnos en un triste recuerdo para los vivos o en esclavos del enemigo. Firmado, Magistrado Solomon Municipio de Villa del Lago Reino de Ventormenta" },
		[36] = { file = "36", len = 31.634, text = "Honorable Magistrado Solomon: Te acompaño en el sentimiento por la muerte de nuestros compañeros. Me encargaré personalmente de informar al Rey sobre esta situación y deseo fervientemente poder llevar refuerzos a Villa del Lago. Últimamente, Su Majestad ha resultado inaccesible y actúa de un modo bastante extraño. Te comento esto por la confianza que te tengo. Hasta pronto, General Marcus Jonathan Reino de Ventormenta" },
		[38] = { file = "38", len = 40.046, text = "Mantorrecio: Hay que tener osadía para enviar a un total desconocido a tratar el asunto de la banda Defias. Salvaste mi vida una vez y ahora la pones gravemente en peligro. No obstante, estoy en deuda contigo. La Hermandad Defias es más grande de lo que crees. Todas las minas de los Páramos de Poniente al bosque de Elwynn están bajo su control. Kóbolds y gnolls han sido reclutados para hacer el trabajo sucio. Tienen a los goblins fabricando monstruos metálicos para colocarlos en los campos de los Páramos de Poniente y así alimentar las supersticiones de los habitantes de la zona." },
		[39] = { file = "39", len = 37.146, text = "Han mandado construir una extensa red subterránea. Más grande de lo que te puedes imaginar, Mantorrecio. De la Bahía del Botín hasta el Castillo de Ventormenta. Podrás ser un valiente paladín, pero no estás en tu sano juicio si crees que puedes detenerlos. Están trabajando en la construcción de armas de destrucción masiva. Después de todo, si hay algo que la hermandad de los Albañiles sabe es cómo erigir grandes construcciones. No habrás creído que se trataba de granjas de hortalizas o de viñedos, ¿verdad? Te he devuelto el favor. ¡Ahora déjame en paz! --W" },
		[41] = { file = "41", len = 31.713, text = "Señor Mantorrecio: La Hermandad de los Albañiles, encabezada por Edwin VanCleef, estaba compuesta por los albañiles más hábiles entre los hombres. Los Albañiles ayudaron a reconstruir los restos de la Ciudad de Ventormenta, arrasada por los orcos durante la Primera Guerra. VanCleef y sus mercaderes fueron inigualables albañiles: su obra y su arte se ponen de manifiesto en la grandeza de la Catedral de la Luz y en el propio Castillo de Ventormenta." },
		[42] = { file = "42", len = 28.369, text = "No obstante, los nobles de Ventormenta acumularon una gran deuda al aumentar la presencia militar del reino en Elwynn y en Tuercespina. Esta enorme deuda paralizó la economía del reino y despojó a VanCleef y a sus Albañiles de sus prometidas recompensas. Tras varios años de intenso trabajo para reconstruir el antiguo esplendor de la ciudad, los Albañiles se arruinaron y fueron olvidados por los funcionarios corruptos que la gobernaban." },
		[43] = { file = "43", len = 26.279, text = "Habiendo conocido a Edwin VanCleef a lo largo mi vida, puedo deciros que resulta sobrecogedor tenerlo de enemigo. Verá, él fue mi amigo de infancia y yo personalmente lo instruí en el pensamiento oscuro cuando decidió iniciar una carrera paralela a la mía. Si VanCleef dirige la Hermandad Defias, que la Luz se apiade de nuestras almas. Maestro Mathias Shaw Hermandad de Asesinos de Ventormenta" },
		[45] = { file = "45", len = 19.357, text = "¡Buen trabajo, colega! Ahora tienes que dirigirte al este. A los acantilados del este, al este del camino. Busca las viejas ruinas de la chimenea que están al pie del camino. Allí encontrarás un viejo barril con la siguiente pista." },
		[46] = { file = "46", len = 19.722, text = "Cuando hayas llegado hasta el barril, dirígete hacia el norte. Recto como el vuelo de un cuervo, sigue tu camino hasta la tinaja vacía que está junto al molino de viento del acantilado. Si husmeas en la jarra, tal vez encuentres lo que estabas buscando." },
		[47] = { file = "47", len = 21.708, text = "¡Ahora que has encontrado la vieja jarra de whisky, estás a punto de dar con el tesoro! Mira hacia el oeste desde ahí y camina hasta llegar a la costa. Cuando hayas llegado al agua, ¡no te detengas! ¡Nada hacia el oeste hasta que encuentres la isla con mi arqueta!" },
		[48] = { file = "48", len = 30.224, text = "Uñasnegras, La mar nos aguarda. Necesitamos tus suministros procedentes del norte. Desmantélalo todo: rieles de ferrocarril, cubos de agua... Necesitamos metal. Hace tiempo que tenía que haber llegado un cargamento de BB. No me falles, Uñasnegras. Esta vez, envía tus provisiones directamente al \"granero\". No hay tiempo que perder. VanCleef" },
		[49] = { file = "49", len = 31.504, text = "Señor Mantorrecio: El municipio de Villa del Lago solicita humildemente la ayuda de tu milicia. Mientras escribo estas líneas, estamos bajo el asedio de los orcos Roca Negra y los gnolls Pielsombra de Morganth. No haría esta petición si nuestra situación no fuera límite. Esperamos ayuda de Ventormenta, pero mientras no la recibamos, te ruego vuestro apoyo. Si el Reino se derrumba, toda la humanidad estará en peligro. Magistrado Solomon" },
		[50] = { file = "50", len = 37.46, text = "Su Señoría: En los Páramos de Poniente lloramos vuestra pérdida, pero también libramos nuestra propia guerra. Los granjeros han sido atacados por ladrones y golems mecánicos. Ventormenta retiró sus tropas, dejando a la gente desprotegida. He reunido a las Milicias del Pueblo tras el abandono de Ventormenta para preservar lo que ha quedado de esta tierra. Conducir a las milicias hasta Crestagrana supone una catástrofe para los Páramos de Poniente. Recibid mis condolencias, Gryan Mantorrecio" },
		[51] = { file = "51", len = 32.627, text = "Señor Cerranegro: El municipio de Villa del Lago solicita humildemente la ayuda de la Guardia Nocturna. Estamos bajo el asedio de los orcos Roca Negra y los gnolls Pielsombra de Morganth. No haría esta petición si nuestra situación no fuera límite. Esperamos ayuda de Ventormenta, pero hasta que la recibamos, os ruego vuestro apoyo. Si el Reino se resquebraja, toda la humanidad estará en peligro. Magistrado Solomon" },
		[52] = { file = "52", len = 33.176, text = "Su Señoría: Lamento informaros que en estos momentos, la Guardia Nocturna no puede abandonar su posición en Villa Oscura. Tal vez no os han informado que Ventormenta ya no presta apoyo militar en esta región. La Guardia Nocturna está formada en su totalidad por los habitantes del bosque para defender Villa Oscura en ausencia de Ventormenta. Sin la Guardia Nocturna, la ciudad sucumbiría. Os deseo suerte en vuestra crisis. Lord Ello Cerranegro" },
		[53] = { file = "53", len = 10.423, text = "Las letras de esta nota parecen parpadear y bailar sobre la superficie. Resulta imposible encontrarles significado..." },
		[54] = { file = "54", len = 37.042, text = "Saludos, Ello Cerranegro, Alcalde de Villa Oscura. Me temo que traigo noticias para tu ciudad. Noticias muy serias. Sabes, soy un creador. He engañado al portador de esta nota para que me ayudase en mi creación definitiva: ¡un demonio de carne, hueso y metal retorcido! Cuando leas esto, esta bestia estará junto a mi humilde morada, rechinando sus dientes y esperando mis órdenes para masacrar toda criatura viviente. Pronto tendrás noticias mías. El embalsamador" },
		[55] = { file = "55", len = 22.831, text = "Estas son las escrituras de un terreno en la región de los Páramos de Poniente. Otorga a los firmantes derechos de propiedad sobre el área en cuestión, así como sobre todos los objetos fabricados y todas las estructuras construidas dentro de sus fronteras. Firman este documento: Theodore Cejade Verna Cejade" },
		[56] = { file = "56", len = 15.203, text = "[Las palabras que aparecen a continuación fueron garabateadas en la otra cara de las escrituras] Presionamos a Cejade y conseguimos estas escrituras. Pensé que, si quieres falsificar una para ti, te vendría bien. Los Cejade no nos darán problemas. La última vez que los vi, abandonaban los Páramos de Poniente con un carro roto." },
		[58] = { file = "58", len = 21.133, text = "Brilla la luna sobre el valle, resplandeciendo sobre la selva valientes guerreros escuchan el clamor para defender nuestra nación y sus sagradas tierras. Brilla la luna sobre el valle en lo alto, sobre el fragor de la batalla allí donde se funde la sangre del enemigo con la del compañero." },
		[59] = { file = "59", len = 20.558, text = "Cuando nuestros hermanos marchen hacia reinos de otro mundo, el alma y el espíritu se curtirán en las profundidades del valle. Cuando nuestros hermanos marchen hasta el templo de la montaña, protegeremos su espíritu eterno tallado en el sagrado añil del cristal. Cuando nuestros hermanos marchen, la luna brillará sobre el valle." },
		[62] = { file = "62", len = 15.047, text = "Bajo la luna y el fuego, en la carne y el hueso, escrito con sangre, grabado en la piedra. Abandona este lugar o aguarda tu fin. La muerte vigila la tumba del Emperador." },
		[63] = { file = "63", len = 34.456, text = "Maestro Carevin, El portador de esta nota ha probado su integridad al amparo de la Luz, demostrando su destreza en el combate contra los no-muertos y los demonios que asolan las lindes del Bosque del Ocaso, deseoso de unirse a la familia Carevin en la causa de la Luz. Por esta razón sugiero que asignes a este guerrero de la Luz nuevas tareas, por ejemplo, investigar a algunos de los habitantes del lugar, sospechosos de colaborar con los enemigos de la Luz. Te saluda atentamente, Calor" },
		[64] = { file = "64", len = 34.273, text = "Morgan Ladimor fue un noble caballero que luchó en defensa de los inocentes, los pobres y los afligidos. Durante años, trabajó diligentemente en la periferia de Azeroth, aliviando a las víctimas y castigando a los malhechores. En el verano en el que cumplió dieciocho años, contrajo matrimonio con una joven llamada Lys. Estaban muy enamorados y tuvieron tres hijos, un varón y dos chicas. Morgan tenía treinta y dos años cuando estalló la guerra en" },
		[65] = { file = "65", len = 31.138, text = "Lordaeron. Morgan fue reclutado por el legendario Uther el Iluminado para combatir contra los orcos y los no-muertos. Tras dejar a su mujer y a sus hijos a salvo en su hogar, Morgan partió hacia la guerra. Pasaron los años y la guerra se prolongó; Morgan presenció espantosas escenas, incluyendo la desbandada de los paladines de la Mano de Plata, la muerte de Uther y la propagación de la peste. Lo único que lo mantenía a salvo de la locura era la certeza de que algún día" },
		[66] = { file = "66", len = 32.836, text = "se reuniría con su mujer y sus hijos. Morgan regresó finalmente a su hogar, pero lo que encontró nada tenía que ver con lo que recordaba. El bosque, antes verdeante, ahora estaba contaminado, infestado de no-muertos y otras fuerzas oscuras. Por doquier había casas y granjas destruidas, y el Cementerio del Cerro del Cuervo cubría gran parte del territorio. Morgan, indignado y perplejo, llegó hasta su casa, encontrándola en ruinas. Ignorando lo que le había ocurrido a su tierra," },
		[67] = { file = "67", len = 37.381, text = "se dirigió al pueblo para encontrar respuesta, deseoso de hallar a su mujer y a sus hijos. Morgan preguntó por su familia, pero no recibió respuesta alguna. Un sacerdote de Villa Oscura, nombre con el que ahora se designaba al lugar, le sugirió que buscara una lápida en el Cementerio del Cerro del Cuervo. Morgan se negó a aceptar que su familia había muerto y continuó buscando en vano por todas las granjas y casas de Bosque del Ocaso. Así, cabalgó desde Villa Oscura hasta las afueras de Villa del Lago, deseando que su familia hubiera podido escapar. En el camino," },
		[68] = { file = "68", len = 33.959, text = "obviando el sentido común, decidió parar en el cementerio del Cerro del Cuervo. Morgan paseó durante horas entre las lápidas. Reconoció los nombres de muchas personas que había conocido y cada vez estaba más consternado por el dolor. Entonces los vio: una descuidada parcela en medio de tantas otras, con tres pequeñas lápidas. A medida que se acercaba, una ola de pánico se apoderaba de él. Morgan quitó el polvo de la lápida más grande para leer el nombre grabado en su superficie. Las letras sobre la tumba constataron" },
		[69] = { file = "69", len = 40.542, text = "el temido presagio: Lys Ladimor Amada esposa y madre El temor de Morgan se transformó en consternación y luego en dolor, postrándolo de rodillas mientras vertía lágrimas amargas. Permaneció durante horas frente a la tumba, suplicando perdón a la fría piedra y disculpándose entre sollozos. Luego, horas más tarde, algo se resquebrajó en su interior y la emprendió a golpes contra todo lo que lo rodeaba. Desenfundó la espada y empezó a golpear las lápidas una y otra vez, gritando de rabia. Ciego de ira, intentaba golpear algo y arremetía contra todo, llamando la atención" },
		[70] = { file = "70", len = 32, text = "de tres guardas del cementerio. Cuando intentaron detenerlo, se abalanzó sobre ellos, acusando a los pobres guardas inocentes, y luego les dio muerte. Más tarde, cuando la ira se había disipado, Morgan tomó conciencia de lo ocurrido y vio su espada ensangrentada, clavada en el pecho de uno de los guardas. Al borde del límite, extrajo el puñal de su cinturón y lo hundió en su propio pecho. El cuerpo de Morgan Ladimor y los de sus víctimas fueron hallados" },
		[71] = { file = "71", len = 34.273, text = "al día siguiente. Fue enterrado rápidamente, sin ceremonia, en una tumba excavada en las afueras del cementerio. Puesto que había cometido asesinato contra personas inocentes, algo que iba totalmente en contra de sus creencias y su naturaleza, y por el dolor que sentía por haber sido incapaz de salvar a su familia, Morgan no tuvo una muerte pacífica y vagó por el mundo como un muerto viviente. Pocos días más tarde, su tumba fue profanada y su cuerpo había desaparecido. Quien un día fuera Morgan ahora" },
		[72] = { file = "72", len = 17.842, text = "vaga por el Bosque del Ocaso, consumido por la pena de haber perdido a su mujer y sus hijos, así como por el desprecio hacia sí mismo. Mor'Ladim, nombre actual de Morgan, vaga ciego de venganza y odio por el Bosque del Ocaso, cometiendo asesinatos indiscriminadamente." },
		[73] = { file = "73", len = 17.789, text = "El terror de estas últimas semanas ha supuesto más de lo que puedo soportar, sin embargo, siento que escribir lo que he vivido me reconforta en cierta medida. Por eso lo hago y es el único consuelo que tengo en estos días aciagos." },
		[74] = { file = "74", len = 31.478, text = "PRIMER DÍA Mi aprendiz y yo hemos llegado hoy al Valle de Crestanevada. El recorrido por la caverna prácticamente no tuvo incidencias. Acampamos bastante lejos de la cueva en la que, según nos dijeron, se habían reunido los trols. SEGUNDO DÍA El aullido de un maldito lobo me mantuvo despierto toda la noche. En un par de días tendré un nuevo traje de piel de lobo. El chico se enfrascó en una pelea con un trogg hoy y" },
		[78] = { file = "78", len = 13.662, text = "Este marcador de armaduras es útil para marcar una armadura de cuero o tela, canjeable en el la casa de los Timberlain, en el Aserradero de la Vega del Este." },
		[79] = { file = "79", len = 38.922, text = "A continuación se describe el proceso y el programa de excavación y transporte del oro de Defias de las minas de Elwynn a nuestro puesto de mando en los Páramos de Poniente. Programa de excavación: Domingo: 12.30 p. m. Miércoles: 12.30 p. m. Durante todos los días señalados, el oro extraído de las minas de Elwynn se recogerá en la plantación de calabazas de Brackwell. El agente encargado de estos cargamentos o \"Recolector\" se reconocerá por su anillo grabado. Un anillo que yo le entregué." },
		[80] = { file = "80", len = 25.913, text = "Grelin: Me queda poco tiempo y muchos asuntos me preocupan, así que espero que tu investigación sobre los trols no sea una preocupación más. Por esta razón, permitiré que utilices mi autoridad como mejor te parezca para tratar con los trols, sobre todo si te permite encontrar una solución oportuna. Magni Barbabronce" },
		[81] = { file = "81", len = 31.347, text = "logró extraer lo mejor de la bestia espantosa, pero ahora se está curando de una herida inmunda en el brazo. Todo indica que tendré que ocuparme de las tareas domésticas durante un tiempo. \\TERCER DÍA Hace frío. Ha nevado un poco cerca del mediodía. CUARTO DÍA El chico volvió hoy y de buen humor, así que echamos un primer vistazo a los trols. Pertenecían al clan Peloescarcha, a juzgar por las marcas en la piel y los diversos abalorios que llevaban en el cuerpo." },
		[82] = { file = "82", len = 30.694, text = "QUINTO DÍA Encargué al chico que vigilara el campamento mientras yo husmeaba en la cueva y echaba un vistazo por los alrededores. Son muchos trols y esto genera ciertos problemas. Tal vez haya que convocar a los montaraces por si resulta necesario limpiar la cueva de la plaga de trols. \\Soy consciente de no haber mencionado a los troggs últimamente. Aparecen por la zona en grandes grupos, pero son tan primitivos que no suponen una amenaza. El tiempo dirá si esto es verdad o no." },
		[83] = { file = "83", len = 26.175, text = "Ni gota de cerveza durante casi una semana. SEXTO DÍA Vuelve a hacer frío. Nieva. Trols y nada de cerveza. SÉPTIMO DÍA La nieve es blanca, el cielo es añil, los lobos aúllan de noche, y yo sin cerveza de barril. OCTAVO DÍA Quizás los trols no representen un problema tan grande como el que inicialmente supusimos. Son bastantes," },
		[84] = { file = "84", len = 8.281, text = "pero no están bien armados ni organizados. Una pequeña demostración de fuerza deberá ser más que suficiente para neutralizarlos." },
		[85] = { file = "85", len = 38.635, text = "Mi diario: El terror experimentado durante las últimas semanas casi supera lo que soy capaz de soportar. ¿Por qué cuando lo escribo todo en este libro, de alguna manera evito caer en la locura? Quizás sea como confesar mis pecados a un compañero silencioso, liberando mi mente de tortuosos pensamientos y confinándolos en el papel. Empecé un diario antes de escribir este, pero permanece en un lugar al que no podré regresar. Por eso empezaré desde cero. Pero esta vez, empezaré desde el verdadero principio." },
		[86] = { file = "86", len = 33.855, text = "Informe sobre el estado de los trols Peloescarcha en el área general del Valle de Crestanevada Elaborado por Grelin Barbablanca, enviado especial del senado Desde el momento en que empecé a observar el movimiento de los trols Peloescarcha en el área del Valle de Crestanevada, he determinado que no representan una especial amenaza para los asentamientos enanos de la zona. De hecho, constituyen esa clase de amenazas que pueden eliminarse con un pequeño apoyo adicional por parte del ejército. Con la ayuda de los montaraces instalados en" },
		[87] = { file = "87", len = 16.353, text = "el Valle de Crestanevada y unos cuantos mercenarios (pagados con fondos apartados por el senado antes de mi envío), confío en que el problema se resolverá muy pronto. Esta acción ha sido autorizada mediante la sanción que me otorgó el rey Barbabronce." },
		[88] = { file = "88", len = 40.202, text = "Informe sobre el estado de los trols Peloescarcha en el área general de Dun Morogh Los trols situados en Dun Morogh están fundamentalmente ubicados en el poblado Peloescarcha, una cueva de montaña en la frontera oeste. Son lo suficientemente numerosos como para causar cierta preocupación, no obstante, parecen estar más que contentos dentro de su cueva. Sin duda, esto se debe a que no desean volver a desatar la ira de los enanos, arriesgándose al exterminio total de su raza. Sus acciones pueden considerarse de carácter territorial, por así decirlo, y creo" },
		[89] = { file = "89", len = 27.716, text = "que no suponen una verdadera amenaza para nosotros, siempre que no invadamos su territorio. Esta situación puede resultar poco agradable para el pueblo de los enanos, pero dada la dispersión de los recursos militares, puede ser prudente relegar el exterminio de los trols a un segundo plano, para poder centrarnos en la amenaza de los troggs y los Hierro Negro. Adjunto copia del informe de mi hermano Grelin sobre Yunquemar." },
		[90] = { file = "90", len = 33.489, text = "Informe sobre el estado de los trols Peloescarcha en el área general del Valle de Crestanevada Elaborado por Grelin Barbablanca, enviado especial del senado Desde el momento en que empecé a observar el movimiento de los trols Peloescarcha en el área del Valle de Crestanevada, he determinado que no representan una especial amenaza para los asentamientos enanos de la zona. De hecho, constituyen esa clase de amenaza que puede eliminarse con un pequeño apoyo adicional por parte del ejército. Con la ayuda de los montaraces instalados en" },
		[91] = { file = "91", len = 16.457, text = "el Valle de Crestanevada y unos cuantos mercenarios (pagados con fondos apartados por el senado antes de mi envío), confío en que el problema se resolverá muy pronto. Esta acción ha sido autorizada por la sanción otorgada por el rey Barbabronce." },
		[92] = { file = "92", len = 23.589, text = "Mi querido Tarrel: Te ruego disculpes las prisas con las que escribo esta carta, pero el tiempo no es un lujo del que dispongamos por aquí. El equipo de excavación ha realizado grandes avances desenterrando importantes artefactos de los titanes. Pero empezamos a descubrir otros objetos antiguos, especialmente huesos largos." },
		[93] = { file = "93", len = 27.533, text = "Poco después de excavar los huesos, fuimos víctimas del ataque de raptores. El batallón de hombres del regimiento Largatrenza luchó valientemente. Pero, finalmente, fueron arrollados. Casi todos murieron. Solo 3 de nosotros sobrevivimos. Un obrero llamado Ormer Trenzaferro demostró mayor valentía, pues se encargó de velar por mi seguridad y la del prospector Whelgar." },
		[94] = { file = "94", len = 30.981, text = "Ahora nos hemos refugiado en una cueva protegida, al parecer a salvo del peligro. Pero, sin duda, hasta que no recibamos refuerzos para hacer frente a los raptores, estamos atrapados. Whelgar intenta continuar trabajando, pero sospecho que sigue bastante asustado. Esa es nuestra situación, Tarrel. Dile a Largatrenza que reúna un comando de rescate inmediatamente. Mi amor por ti sigue siendo fuerte, incluso en estos azarosos tiempos. Merrin" },
		[95] = { file = "95", len = 33.176, text = "Las verdes colinas de Tuercespina Nuestro primer día transcurrió perfectamente, como era de esperar. La mayor parte del tiempo lo dedicamos a instalar el campamento base. Encontré un paraje ideal junto a un río de aguas cristalinas. A juzgar por los muelles viejos y abandonados, este lugar fue habitado en el pasado. En cuanto a los primeros habitantes, su historia solo puede contarse ahora que el tiempo ha transcurrido." },
		[98] = { file = "98", len = 33.646, text = "En los años a venir, después de que Ventormenta traicionara a la Hermandad de los Albañiles, Sir Elrgadin estaba cada vez menos de acuerdo con el papel de los nobles en el Reino. Ya no deseaba ostentar la posición que la línea de sangre de su padre le había legado en la Casa de Nobles. Pero me estoy apartando del tema. Esta historia no pretende ser un tratado político o una biografía. Este es el relato de mis experiencias de caza en las verdes colinas de Tuercespina." },
		[100] = { file = "100", len = 30.198, text = "Justo cuando iba a cuestionar la falta de interés de Ajeck por la estrategia a seguir ese día, ella extrajo una flecha de su carcaj y la lanzó directamente hacia el pobre Barnil. Sin embargo, Barnil no era el objetivo de Ajeck. Cuando este se apartó boquiabierto, un gran crocolisco de río flotaba en la superficie con la flecha perfectamente clavada en medio de sus grandes ojos." },
		[102] = { file = "102", len = 34.22, text = "Durante semejante tropiezo, Erlgadin posó su mano pesadamente sobre el hombro de Barnil. Ajeck y yo apenas advertimos la escena, suponiendo que el hombre solo estaba dando una merecida reprimenda a Barnil por su descuido. No obstante, Erlgadin, hizo un gesto lento con la cabeza en dirección a un árbol que estaba a punto de caer. Desde allí nos acechaban dos ojos negros penetrantes justo encima de un par de afilados colmillos." },
		[104] = { file = "104", len = 26.201, text = "La caza generó euforia en la expedición. Barnil sirvió hidromiel a todos los presentes. Sin embargo, la alegría duró poco. Cuando preparábamos el cadáver para llevarlo al campamento base, un espantoso gruñido nos cogió desprevenidos. Jamás había oído nada capaz de helarme la sangre como aquello." },
		[105] = { file = "105", len = 30.563, text = "En un rocoso precipicio en lo alto, perfilado por el sol poniente, podía distinguir el felino depredador más grande que he visto jamás. Pude liberar una descarga con mi rifle, pero el felino siguió su camino. Rugió una vez más, en esta ocasión vez con más fuerza que la anterior, y desapareció. Recogimos nuestras pertenencias y nos dirigimos solemnemente de vuelta al campamento." },
		[108] = { file = "108", len = 40.882, text = "Aquel día nos internamos hacia el sur, siguiendo las pistas recientes de una pantera. Pronto encontramos un enorme puente de soga que atravesaba un barranco. Cuando vi aquella magnífica obra de ingeniería, no pude evitar recordar los textos descriptivos de Brann sobre esta región. Con demasiada frecuencia se decía que los trols que habitaban aquella zona eran una raza primitiva e inculta, pero cuando vi la maestría con que había sido construido aquel puente, pude admirar la destreza de los trols que habían realizado aquella hazaña inimaginable." },
		[110] = { file = "110", len = 32.914, text = "Tanto Ajeck como Sir Erlgadin se mantuvieron erguidos, con las armas al nivel de la hirsuta maleza que había bajo unos árboles que se mecían de un lado a otro. El sol del mediodía ardía con fuerza sobre nosotros. Una lenta gota de sudor rodó por la sien de Erlgadin, al tiempo que retiraba el gatillo. Tras el chasquido, las hojas exuberantes se dividieron y una pantera negra, espécimen hermoso, saltó veloz sobre la llanura." },
		[112] = { file = "112", len = 39.784, text = "El arma dio una violenta sacudida. El cañón rodó lateralmente y cayó bajo el rifle de Ajeck. Ajeck había elegido ese preciso momento para apretar el gatillo. El rifle, con el mira orientada torpemente hacia la fila de árboles, se disparó con un estruendo inconfundible. Una bandada de pájaros chilló desde la copa de un árbol, dispersándose por todas partes. Una columna de humo emergió del árbol. Sobrecogidos, vimos cómo una tremenda rama caía sobre la pantera que intentaba escapar, partiéndole el lomo." },
		[114] = { file = "114", len = 41.064, text = "Nos fuimos al alba en dirección al sur, más allá de las ruinas de Tkashi. Barnil expresó su preocupación sobre la posibilidad de encontrarnos con miembros de la tribu Sangrapellejo. Recordé a Barnil que los Sangrapellejo estaban ocupados intentando destruir a su enemigo tribal, los Machacacráneos. De más está decir que Barnil no estaba en absoluto tranquilo. Yo, por mi parte, tenía el rifle cargado, un saco lleno de pólvora y tres cazadores infalibles que me acompañaban para aplacar mis preocupaciones sobre una posible emboscada." },
		[115] = { file = "115", len = 38.609, text = "Una vez, en el campo de batalla, apareció un infernal altísimo, con el ejército de la Legión Ardiente avanzando desde todas las direcciones. Una banda de trols revoltosos parece tan inofensiva como una liebre en las colinas de Dun Morogh. Pasamos por las ruinas de Tkashi sin contratiempos, lo que tranquilizó a Barnil. El grupo avanzó hacia el oeste, en dirección al Mare Magnum, bordeando las ruinas de Zul'Kunda, situadas al sur. Al subir por los altos acantilados, divisamos el primer raptor." },
		[118] = { file = "118", len = 28.63, text = "Nuestros disparos, que dirigimos apresuradamente, fueron suficientes para comprar la huida de Barnil. Barnil lanzó un clamor colina abajo y se volvió a unir al grupo. Corrimos a refugiarnos en la jungla; una manada de feroces raptores colazote acechaba todos nuestros movimientos. Los cazadores eran, ahora, los cazados." },
		[119] = { file = "119", len = 27.193, text = "Con el fin de que la costa nos protegiera de los raptores, conduje a la expedición hasta el mar. En nuestro apresuramiento, nos desviamos y acabamos en el norte, en un monte peligrosamente elevado. Pero nos equivocamos. Fue culpa mía. Nos detuvimos delante de un escarpado acantilado, con los raptores justo detrás de nosotros." },
		[120] = { file = "120", len = 31.216, text = "Avancé lentamente con el arma levantada. Había conducido a estos valientes cazadores a su fin. Tenía que morir defendiéndolos. Los raptores colazote son particularmente feroces, conocidos por ser unos sanguinarios implacables. Eran muchos más que nosotros. Pero si hubiera dejado que nos mataran a mis camaradas y a mí, sin antes derramar parte de su propia sangre, no me lo habría perdonado." },
		[121] = { file = "121", len = 28.604, text = "Ajeck y Sir Erlgadin prepararon sus armas, flanqueándome a ambos lados, con las espaldas orientadas al mar. Barnil lanzó un suspiro de derrota y sacó su hacha. Los colazotes estaban casi encima de nosotros. Sus firmes zancadas eran ahora más pausadas. Estaban observando a su presa, ya que sabían que nos tenían acorralados." },
		[153] = { file = "153", len = 35.788, text = "Nuestro primer día fue todo lo bien que se puede esperar que vayan los primeros días. La mayor parte del tiempo nos preocupamos de realizar los preparativos necesarios para establecer un campamento base. Encontré un lugar ideal, junto a la ensenada de un río de agua dulce. A juzgar por los viejos y abandonados muelles que hay cerca, este emplazamiento estuvo habitado hace algún tiempo. Por lo que respecta a los habitantes primitivos, solo el tiempo puede contar esa historia." },
		[154] = { file = "154", len = 26.593, text = "Para esta expedición he reunido a Ajeck Rouack y a Sir S. J. Erlgadin, junto con mi sirviente de confianza, Barnil Jarropetra. Libré muchas batallas al lado del padre de Ajeck en defensa de la Alianza. Verla crecida es bastante especial. Su padre la instruyó bien en las artes de las armas. Su habilidad con el arco me hace preguntarme si corre sangre élfica por esas venas." },
		[155] = { file = "155", len = 20.036, text = "Sir S. J. Erlgadin proviene de la aristocracia humana. Su padre, el conde Erlgadin, era célebre por su generosidad. Fue el conde quien presionó por una mejora en las condiciones de trabajo de la Hermandad de los Albañiles durante la restauración de Ventormenta después de la Segunda Gran Guerra." },
		[156] = { file = "156", len = 31.817, text = "En los años que siguieron, después de que Ventormenta traicionara a la hermandad de los albañiles, Sir Erlgadin se fue volviendo más rencoroso sobre el papel de los nobles en el Reino. Ya no deseaba defender la posición que la estirpe de su padre había ganado para él en la Casa de Nobles. Pero me estoy yendo por las ramas. El propósito de esta historia no es que sirva como tratado político o biografía. Este es el relato de mis experiencias en busca de caza mayor por las verdes colinas de Tuercespina...." },
		[157] = { file = "157", len = 28.264, text = "Nos levantamos al amanecer. Barnil empezó a preparar el desayuno. Advertí que Ajeck estaba un poco distraída. La caminata del día prometía ser larga y nos esperaban peligrosos episodios de caza. Cualquier descuido podía ponernos en una situación difícil. No obstante, Ajeck parecía incapaz de desviar su mirada de Barnil, que estaba de pie frente al río, limpiando su equipo." },
		[158] = { file = "158", len = 26.749, text = "Justo cuando estaba a punto de cuestionar la falta de interés de Ajeck en la estrategia de caza del día, alargó la mano hacia su arco, lo tensó con una flecha y la soltó justo hacia el pobre Barnil. Pero no era a Barnil a quien Ajeck disparaba, pues, cuando Barnil se echó a un lado boquiabierto, un gran crocolisco de río flotó a la superficie con la flecha de Ajeck perfectamente colocada entre sus grandes ojos." },
		[159] = { file = "159", len = 35.762, text = "Nos pusimos en camino hacia el oeste, a través de la espesa maleza de la enmarañada jungla. Con pasos lentos y cuidadosos, avanzamos a través de un espeso follaje en busca de presa. La mañana pasó en un silencio frustrante. Nada se agitaba en la Vega, ni una brisa. Hacia la tarde, la expedición se mostraba impaciente. Barnil ya no andaba con los pasos cautelosos de un depredador que rastrea a su presa. En su lugar, caminaba pesada y torpemente por el camino, a menudo pisando ruidosamente hojas secas o ramas caídas." },
		[160] = { file = "160", len = 29.074, text = "Durante semejante tropiezo, Erlgadin posó su mano pesadamente sobre el hombro de Barnil. Ajeck y yo apenas advertimos la escena, suponiendo que el hombre solo estaba dando una merecida reprimenda a Barnil por su descuido. No obstante, Erlgadin, hizo un gesto lento con la cabeza en dirección a un árbol que estaba a punto de caer. Desde allí nos acechaban dos ojos negros penetrantes justo encima de un par de afilados colmillos." },
		[161] = { file = "161", len = 32.47, text = "La bestia era un tigre macho de Tuercespina. Antes de que pudiera amartillar el rifle, Erlgadin levantó la ballesta y disparó en dirección al animal. El virote dejó su marca y sorprendió a la bestia con fuerza en el costado izquierdo. El tigre hizo un intento en vano por huir, pero la herida era demasiado grave. La bestia fue dando traspiés durante varios trágicos segundos, hasta que Barnil lo remató lanzando un hacha." },
		[162] = { file = "162", len = 22.779, text = "La matanza provocó un ánimo festivo en la expedición. Barnil sirvió aguamiel para disfrute de todos. Pero nuestros festejos fueron efímeros. Mientras preparábamos el cadáver para transportarlo de vuelta al campamento base, un rugido espantoso nos cogió desprevenidos a todos. En todos mis años nunca he oído nada que helara la sangre de tal modo." },
		[163] = { file = "163", len = 25.469, text = "En un rocoso precipicio en lo alto, perfilado por el sol poniente, podía distinguir el felino depredador más grande que he visto jamás. Pude liberar una descarga con mi rifle, pero el felino siguió su camino. Rugió una vez más, en esta ocasión vez con más fuerza que la anterior, y desapareció. Recogimos nuestras pertenencias y nos dirigimos solemnemente de vuelta al campamento." },
		[164] = { file = "164", len = 17.345, text = "Había prometido a la expedición que pasaríamos el día siguiente cazando panteras, ya que sus pieles son muy valoradas en Azeroth. Esta demanda se debe a que todos los cazadores, tramperos y comerciantes de pieles arriesgan valientemente su vida en nombre de la Alianza." },
		[165] = { file = "165", len = 15.909, text = "Ajeck y Sir Erlgadin estaban ansiosos por aprender a cazar eficazmente con un rifle de los enanos. Hice que los dos humanos dejaran sus primitivas armas en el campamento base. Barnil y yo los equipamos con algunas de las mejores armas de fuego de Forjaz." },
		[166] = { file = "166", len = 34.351, text = "Ese día nos aventuramos al sur, siguiendo algunos rastros recientes de pantera. Pronto llegamos a un barranco que se cruzaba por un enorme puente colgante. No pude evitar pensar en la descriptiva obra de Brann sobre aquella región cuando vi aquella maravilla de la ingeniería. Se suponía tan a menudo que los trols nativos eran una raza primitiva e inculta, pero, mientras observaba fijamente la artesanía maestra del puente, pude reconocer la habilidad con la que los albañiles trols superaron la hazaña, aparentemente imposible." },
		[167] = { file = "167", len = 37.015, text = "Al poco tiempo, Ajeck rastreó a la pantera en dirección al sudoeste. Anduvimos en silencio, con las armas preparadas, anticipándonos a nuestra presa. Un chasquido de ramas en un bosquecillo cercano llamó nuestra atención de inmediato. Allí había algo. Una mirada seria a Barnil bastó para transmitirle mis pensamientos. Barnil bajó su rifle lentamente. Esta presa no era para nosotros, sino para nuestros compañeros humanos. Innumerables panteras habían perdido la vida al enfrentarse a nuestros humeantes cañones. Esta presa era para los humanos." },
		[168] = { file = "168", len = 29.936, text = "Tanto Ajeck como Sir Erlgadin se mantuvieron erguidos, con las armas al nivel de la hirsuta maleza que había bajo unos árboles que se mecían de un lado a otro. El sol del mediodía ardía con fuerza sobre nosotros. Una lenta gota de sudor rodó por la sien de Erlgadin, al tiempo que retiraba el gatillo. Tras el chasquido, el follaje exuberante se abrió en dos y una pantera negra, espécimen hermoso, saltó veloz sobre la llanura." },
		[170] = { file = "170", len = 33.881, text = "El arma dio una violenta sacudida. El cañón rodó lateralmente y cayó bajo el rifle de Ajeck. Ajeck había elegido ese preciso momento para apretar el gatillo. El rifle, con la mira orientada torpemente hacia la fila de árboles, se disparó con un estruendo inconfundible. Una bandada de pájaros chilló desde la copa de un árbol, dispersándose. Una columna de humo emergió del árbol. Sobrecogidos, vimos cómo una tremenda rama caía sobre la pantera que intentaba escapar, partiéndole el lomo." },
		[171] = { file = "171", len = 28.578, text = "Unas semanas después, nuestras reservas de piel de pantera y tigre crecieron ostensiblemente. Decidí que era hora de que la expedición cambiara de objetivo: Raptores. Los humanos, valorando la instrucción que Barnil y yo les proporcionamos, decidieron abstenerse de cazar con armas de fuego. Ajeck estaba mucho más cómoda con un arco de cuerda fina, mientras que Sir Erlgadin nunca abandonaba el campamento sin su maciza ballesta." },
		[172] = { file = "172", len = 35.631, text = "Nos fuimos al alba en dirección al sur, más allá de las ruinas de Tkashi. Barnil expresó su preocupación ante la posibilidad de encontrarnos con miembros de la tribu Sangrapellejo. Recordé a Barnil que los Sangrapellejo estaban ocupados intentando destruir a su enemigo tribal, los Machacacráneos. De más está decir que Barnil no estaba en absoluto tranquilo. Yo, por mi parte, tenía el rifle cargado, un saco lleno de pólvora y tres cazadores infalibles que me acompañaban para aplacar mis preocupaciones ante una posible emboscada." },
		[173] = { file = "173", len = 35.709, text = "Una vez, en el campo de batalla, tuve delante a un infernal altísimo, con el ejército de la Legión Ardiente avanzando desde todas partes. Una banda de trols revoltosos parece tan inofensiva como una liebre en las colinas de Dun Morogh. Pasamos por las ruinas de Tkashi sin contratiempos, lo que tranquilizó a Barnil en gran medida. El grupo avanzó hacia el oeste, en dirección al Mare Magnum, bordeando las ruinas de Zul'Kunda, situadas al sur. Al subir por los altos acantilados, divisamos al primer raptor." },
		[174] = { file = "174", len = 34.586, text = "La bestia ni siquiera detectó nuestra presencia. De hecho, el único saludo que recibió por parte de la expedición fue una bala en medio de la frente. Sir Erlgadin lanzó un grito de alegría, mientras Ajeck asentía y me miraba, haciendo un gesto de entusiasta aprobación. Revolví mi mochila en busca de mi pipa, esperando celebrar la hazaña con el humo de la victoria. Barnil empezó a correr por la cuesta para recuperar el cadáver del raptor. Miré a la bestia abatida con la satisfacción que produce una caza importante." },
		[175] = { file = "175", len = 26.175, text = "Sin embargo, no pude disfrutar de la victoria del cazador por mucho tiempo, pues al contemplar el horizonte, numerosas siluetas aparecieron en la cresta de la colina, justo encima del pobre Barnil. *¡Huye, Barnil!*, grité. Ajeck, Sir Erlgadin y yo lanzamos una descarga de balas y flechas por encima de Barnil, directo sobre los raptores. Alguien soltó la presa en medio de la confusión." },
		[177] = { file = "177", len = 26.802, text = "Conduje a la expedición hasta el mar, con el fin de que la costa nos protegiera de los raptores. En nuestro apresuramiento, nos desviamos y acabamos en el norte, en un monte peligrosamente elevado. Pero nos equivocamos. Fue culpa mía. Nos detuvimos delante de un escarpado acantilado, con los raptores justo detrás de nosotros." },
		[178] = { file = "178", len = 26.07, text = "Avancé lentamente con el arma levantada. Había conducido a estos valientes cazadores a su fin. Tenía que morir defendiéndolos. Los raptores colazote son particularmente feroces, conocidos por ser unos sanguinarios implacables. Eran muchos más que nosotros. Pero no me habría perdonado dejar que nos mataran a mis camaradas y a mí, sin antes derramar parte de su propia sangre." },
		[179] = { file = "179", len = 23.432, text = "Ajeck y Sir Erlgadin prepararon sus armas, flanqueándome a ambos lados, con las espaldas orientadas al mar. Barnil lanzó un suspiro de derrota y sacó su hacha. Los colazotes estaban casi encima de nosotros. Sus firmes zancadas eran ahora más pausadas. Estaban observando a su presa, ya que sabían que nos tenían acorralados." },
		[180] = { file = "180", len = 29.806, text = "Entonces ocurrió algo milagroso. Desde donde estábamos escuchamos el inconfundible y aterrador rugido del gran tigre blanco. A pesar de ser numerosos, los raptores dieron media vuelta y se dispersaron. Solo vimos el breve destello blanco de un tigre que salió disparado junto a nosotros, abalanzándose sobre uno de los raptores. No fue necesario dar ninguna orden. Los cuatro miembros de la expedición sabíamos que era el momento de salir corriendo." },
		[181] = { file = "181", len = 36.258, text = "Corrimos a toda velocidad hasta el campamento base, sin reducir la marcha en ningún momento. Más tarde aquella noche, nos sentamos en silencio alrededor de la hoguera, sabiendo que un extraño golpe de suerte nos había salvado la vida. Esos son los riesgos que corre el cazador de caza mayor. Jugamos con la suerte, desafiándola. No obstante, todos, en algún momento de nuestras vidas, debemos afrontar las afiladas garras del destino. Este enano se alegra, porque ese momento aún no ha llegado a las verdes colinas de Tuercespina." },
		[182] = { file = "182", len = 34.09, text = "Honorables compañeros y sabios buscadores de la verdad La excavación continúa, pero su ritmo ha disminuido debido a los troggs que mencioné en mi último informe. Confío en que los neutralizaremos, aunque algunos son más agresivos de lo habitual. Recientemente se encontraron más artefactos, si bien en todos los casos, salvo en uno (que en breve detallaré), los recientes hallazgos tienen la misma relevancia que los anteriores: son interesantes, pero no esclarecedores." },
		[183] = { file = "183", len = 31.033, text = "Hubo una excepción. Los ídolos tallados recientemente encontrados (una breve descripción de los mismos aparece en mi último informe) parecen afectar de algún modo a los troggs. Se sienten atraídos por la talla en piedra y algunos troggs enloquecen ante su presencia. Es preciso estudiar este fenómeno con mayor profundidad para llegar a una conclusión válida en relación con estos ídolos, si bien espero que el estudio arroje luz sobre un posible vínculo entre los troggs y los titanes." },
		[184] = { file = "184", len = 25.104, text = "Finalmente, debo reiterar mi petición para que se me suministre más pólvora. Mis suministros son muy escasos, lo que dificulta seriamente el éxito de la excavación. Me dijeron que un nuevo suministro de pólvora estaba en camino, sin embargo aún no he recibido nada. ¿Puedo preguntar a qué se debe este retraso? Respetuosamente, Prospector Darteus Vetaferro" },
		[185] = { file = "185", len = 25.104, text = "Todo empezó con el hallazgo de esa maldita guadaña en la Condena de Roland. Antes de que apareciera la guadaña, los terrores de este lugar parecían tan mansos como el valle de Villanorte. Pero desde que encontré el mango de la guadaña sobresaliendo entre la pila de escombros en la mina y lo saqué de ahí, ¡ay de mí!, ¡la Condena de Roland se ha convertido en un lugar de destrucción y muerte!" },
		[186] = { file = "186", len = 35.03, text = "Todo empezó con el hallazgo de esa maldita hoz en la mina conocida como Condena de Roland. Sí, ahí empezó todo. Antes de que aquello ocurriera, la Hermandad Defias estaba satisfecha con nuestros avances en el Bosque del Ocaso. Antes de que apareciera la guadaña, los terrores de este lugar parecían tan mansos como el valle de Villanorte. Pero desde que encontré el mango de la guadaña sobresaliendo entre la pila de escombros en la mina y lo saqué de ahí, ¡ay de mí!, ¡la Condena de Roland se ha convertido en un lugar de destrucción y muerte!" },
		[187] = { file = "187", len = 30.041, text = "Si hubiera sabido lo que iba a suceder, habría cortado mi propia mano antes de tocar ese trozo de madera tallada con runas. ¡Cuánto arrepentimiento! Pensé que ese era solo un privilegio de los ancianos. Ahora sé que no son los ancianos, sino los desesperados, los que visten el manto del arrepentimiento, incapaces y sin deseos de quitárselo de los hombros, encorvados por el sufrimiento. Ahora basta de poesía barata. Debo continuar con esta crónica..." },
		[188] = { file = "188", len = 41.195, text = "Tras el rescate de la guadaña, en la mina empezaron a ocurrir cosas extrañas. La luz procedente de nuestras antorchas parpadeantes se deformaba y la fuerza de nuestras voces parecía escapar a nuestro control. A veces, el susurro de un hombre provocaba un estruendo que atravesaba los túneles, obligando a los demás a taparse los oídos y, en otras ocasiones, nuestros gritos apenas se oían a unos cuantos metros antes de apagarse como un soplo en el viento. Ciertamente, era desconcertante, pero rápidamente dejamos de extrañarnos por lo insólito del asunto. Lo que en realidad nos apartó de la mina, fue un presagio. El huargen." },
		[189] = { file = "189", len = 33.646, text = "Emergieron desde todos los rincones, clavando sus zarpas en nuestros tobillos desde ocultos agujeros y cayendo sobre nosotros desde lo alto. La mitad de nuestros hombres cayeron en esos primeros minutos de pánico. El resto, entre los que me incluyo, intentaron escapar. A medida que corría, veía a mis hermanos atrapados por la zarpa y el colmillo, oí tantos alaridos truncados o desvaneciéndose en el silencio. Hasta donde tengo conocimiento, fui el único humano que escapó de aquel lugar." },
		[190] = { file = "190", len = 35.448, text = "Solo puedo suponer por qué sobreviví aquella noche. Siempre he sido cuidadoso, rápido a la hora de escapar de las fauces de alguna bestia, o cuando se trataba de saltar algún escollo. Mi sobrenombre, Alterio, obedece a esta característica. Así que tal vez fue el don de la prudencia lo que me salvó... O tal vez fue la guadaña que extraje de los escombros. No puede ser la guadaña, puesto que la perdí durante mi frenética huida. Pero si fui yo quien atrajo los huargen al Bosque del Ocaso, quizás me hayan hecho un extraño obsequio. ¡Los maldigo!" },
		[191] = { file = "191", len = 30.224, text = "O quizás, estoy condenado a presenciar los cambios que he traído al Bosque del Ocaso. Quizás sea mi destino contemplar la invasión de huargen en estas tierras, contaminándolas paulatinamente con su podredumbre. Si esa es mi suerte, tiene dos caras. Porque los huargen no son la única fuerza que se ha apoderado del Bosque del Ocaso: los demonios del Paso de la Muerte también han reclamado su parte. Ese será el último capítulo de mi historia, y rezo porque sea el último..." },
		[192] = { file = "192", len = 36.702, text = "Tras sobrevivir a la huida de la Condena de Roland, me oculté en el granero de un hombre llamado Sven. Pasé unos cuantos días en el granero y aquel horror caló tan hondo en mí que nunca me presenté ante Sven o su familia. Pero considerando lo que vi desde mi escondite, me di cuenta de que aquellos granjeros eran personas bastante decentes. De haber salido de mi refugio, seguramente me habrían aceptado, pero me cuesta confiar en los demás. Y mucho más después de aquella impresión en la mina. Así que permanecí escondido. Y por ello salvé mi vida." },
		[193] = { file = "193", len = 37.407, text = "Pocos días después de llegar al granero, Sven abandonó su granja para partir a Villa Oscura. Besó a su mujer, sonrió a sus hijos y prometió volver pronto con regalos y golosinas. Pobre hombre. Fue la última vez que vio a su familia sana y entera. Al menos se despidieron contentos. Y por suerte, su mujer fue la primera en morir, evitando el dolor de ver cómo asesinaban a sus hijos. Pero estas supuestas contrapartidas no me compensarán tanto dolor. Vi lo que ocurrió y la escena siempre me perseguirá en sueños." },
		[194] = { file = "194", len = 33.411, text = "Me tiemblan las manos cuando recuerdo los detalles de aquella noche, Sven estaba ausente y su familia tuvo que enfrentarse sola a los jinetes negros. El remordimiento vuelve a consumirme, pues yo estaba allí y pude haber luchado contra aquellos demonios del Paso de la Muerte. Pero es falso remordimiento. Es el mismo que abruma a cualquier superviviente de una tragedia. Sé que de haber abandonado mi escondite también habría muerto desgarrado y descuartizado, los miembros esparcidos por todas partes hasta quedar irreconocible." },
		[195] = { file = "195", len = 33.802, text = "Pero a pesar de saber que no habría podido hacer nada para detener aquel atroz asesinato, perdura el sentimiento de culpabilidad: Fui yo quien atrajo a los jinetes negros hasta la granja de Sven. Mi descubrimiento de la guadaña no solo desató a los huargen hasta el Bosque del Ocaso, sino que atrajo a los jinetes del Paso de la Muerte. Lo sé porque antes de iniciar la masacre, formularon una pregunta a la mujer de Sven mientras esta aferraba a sus hijos, ofreciéndoles consuelo, a pesar de presentir la inminencia de su muerte." },
		[196] = { file = "196", len = 35.422, text = "\"La Guadaña de Elune\", gritó uno de los jinetes en un tono áspero y estridente a la vez, como el chirrido de un hacha sobre la piedra. La última palabra, Elune, brotó en un grito ahogado. El terror se apoderó de mí cuando escuché aquella voz, no solo por su tono espantoso, sino porque sabía a qué guadaña se refería el jinete. Debe de tratarse del mismo objeto abominable que extraje de las rocas en la Condena de Roland hace unos días, pensé. ¡Es lo que los jinetes negros estaban buscando! Y es lo que mató a la familia de Sven." },
		[197] = { file = "197", len = 26.775, text = "Nunca supe el nombre de la mujer de Sven, ya que su marido y sus hijos solo la llamaban \"querida\", \"mi amor\" o \"mami\". Pero me habría gustado saberlo. Soy el único recuerdo viviente de su valerosa actuación aquel fatídico día y, a pesar de tratarse tan solo de la mujer de un granjero, jamás vi a hombre o mujer proceder con tanta valentía. Si tan solo hubiera servido para algo." },
		[198] = { file = "198", len = 31.112, text = "\"¿La Guadaña?\", dijo tranquilamente. \"Claro que sí. ¿Quién no la ha visto por aquí?\" Miró a los jinetes con firmeza y, de no conocer los hechos, yo habría jurado que decía la verdad. ¡Era imposible que supiera lo de la Guadaña. Su estrategia daba resultado. El mismo jinete que formuló la pregunta se inclinó ligeramente hacia ella y chilló: \"¿Dónde?\" \"Te llevaré hasta ella. Todos vosotros,\" dijo, y pude observar un destello de esperanza que asomaba a sus ojos." },
		[199] = { file = "199", len = 38.06, text = "\"Pero el camino es largo y mis hijos solo nos harán ir más despacio. Debemos dejarlos aquí.\" Su coartada era simple, pero son ese tipo de coartadas las que mayor éxito tienen. Si funcionaba, al menos alejaría a los jinetes de la granja. Ella habría sucumbido, pero sus hijos estarían a salvo. Y, de no ser porque los jinetes se creyeron sus nobles mentiras, habría funcionado. A pesar de que nunca he sido estudioso de la Luz, recé con fuerza por la vida de la mujer de Sven mientras plantaba cara a aquellos terribles jinetes. \"Por favor\", recé. \"Haz que se lo crean.\"" },
		[200] = { file = "200", len = 39.784, text = "Se quedaron ahí, paralizados, mientras ella los miraba a los ojos con tranquilidad. Uno de los jinetes miró hacia arriba, como si escuchase una llamada a lo lejos. Extrajo de sus ropajes una pequeña gema y miró en su interior. Luego hizo un gesto, apuntando con la gema hacia la mujer de Sven. Una luz se deslizó desde el jinete hasta la mujer, adquiriendo la forma de una mano blanca y lúgubre. Ella contempló la luz, inmutable, pero pude observar cierta incertidumbre tras su máscara de confianza. Cuando la mano la alcanzó, rodeó su cabeza con los dedos. Luego la apretó con fuerza." },
		[201] = { file = "201", len = 31.216, text = "La mujer de Sven permaneció rígida como una tabla y sus ojos se abrieron al máximo. A pesar de que sus labios hicieron la mueca de un grito, no dejaron escapar sonido alguno. Tras unos minutos de tortura, la mano soltó a la mujer, dejándola caer de rodillas. El jinete que sujetaba el abalorio se irguió sobre su silla y una potente voz emergió de su interior. \"Esta mujer miente\", afirmó en un tono que aún retumba en mis sueños. \"No ha visto la Guadaña.\"" },
		[202] = { file = "202", len = 15.334, text = "Tras este suceso, los hombros del jinete se encorvaron ligeramente, como si un espíritu hubiese abandonado su cuerpo. Luego, en el antiguo tono chirriante, pronunció las siguientes palabras: \"El Señor ha hablado. Matadlos.\"" },
		[203] = { file = "203", len = 34.612, text = "No puedo describir lo que ocurrió a continuación. Los recuerdos son vívidos, pero mi alma desgraciada no puede plasmar sobre el papel lo que allí sucedió en aquellos espeluznantes momentos. Solo puedo escribir que la familia de Sven fue asesinada. Poco después, Sven regresó a este escenario de muerte y horror. Estaba tan destrozado, que tuve miedo de salir de mi escondite. Tanto temía que me encontrara, que huí de mi refugio en el granero. No sé dónde está Sven ahora, pero espero que, algún día encuentre la paz." },
		[205] = { file = "205", len = 30.563, text = "Después de liberar la Guadaña, emergieron desde todos los rincones, clavando sus zarpas en nuestros tobillos desde ocultos agujeros, o cayendo sobre nosotros desde lo alto. La mitad de nuestros hombres cayeron en esos primeros minutos de pánico. El resto, entre los que me incluyo, intentaron escapar. A medida que corría, veía a mis hermanos atrapados por la zarpa y el colmillo, oí tantos alaridos truncados o desvaneciéndose en el silencio." },
		[206] = { file = "206", len = 35.265, text = "Solo puedo suponer por qué sobreviví aquella noche. Siempre he sido cuidadoso, rápido a la hora de escapar de las fauces de alguna bestia, o cuando se trataba de saltar algún escollo. Mi sobrenombre tiene que ver con esta característica. Así que tal vez fue el don de la prudencia el que me salvó... O tal vez fue la guadaña que extraje de los escombros. No puede ser la guadaña, puesto que la perdí durante mi frenética huida. Pero si fui yo quien atrajo a los huargen al Bosque del Ocaso, quizás me hayan hecho un extraño obsequio. ¡Los maldigo!" },
		[207] = { file = "207", len = 33.959, text = "Tras sobrevivir a la huida de la Condena de Roland, me oculté en el granero de un hombre llamado Sven. Pasé unos cuantos días en el granero y aquel horror caló tan hondo en mí que nunca me presenté ante Sven o su familia. Pero considerando lo que vi desde mi escondite, me di cuenta de que aquellos granjeros eran personas bastante decentes. De haber salido de mi refugio, seguramente me habrían aceptado, pero me cuesta confiar en los demás. Y mucho más después de aquella impresión en la mina. Así que permanecí escondido." },
		[208] = { file = "208", len = 2.429, text = "El resto del libro está en blanco" },
		[209] = { file = "209", len = 29.1, text = "INFORME: Kóbolds La actividad de los kóbolds ha aumentado en las cercanías de Valle de Villanorte. Acampan al norte de la abadía y dentro de la Mina del Eco, y sus cifras son alarmantes. He convocado paladines, guerreros y otros habitantes locales para que me ayuden a deshacernos de estas alimañas. Estamos teniendo un buen avance. Informaré conforme sea necesario." },
		[210] = { file = "210", len = 24.215, text = "INFORME: Ladrones Una pandilla humana de ladrones más peligrosa que los kóbolds ha aparecido en el valle. Usan pañuelos rojos y se refieren a sí mismos como hermandad. Este nivel de organización puede traer problemas, tanto aquí como en todo el Bosque de Elwynn. Hemos identificado a uno de sus líderes, un tal Garrick Piesuaves, y esperamos llevarlo pronto ante la justicia." },
		[211] = { file = "211", len = 21.081, text = "INFORME: Lobos Según los informes, los ataques de estos animales han aumentado en Villanorte. Eagan cree que los lobos que hay en el valle fueron desterrados desde el Bosque del Ocaso. Aunque los lobos rara vez cazan humanos, su elevado número provocó ciertos incidentes con los granjeros. Y varias reses desaparecieron." },
		[212] = { file = "212", len = 22.674, text = "DISTINCIÓN: El portador de estos documentos será condecorado con el rango de Ayudante de Alguacil del ejército de Ventormenta, por haber servido a Villanorte con entusiasmo y especial atención. Confío en que esta persona les resulte útil en el bosque de Elwyyn. Firmado: Alguacil Douglas McBride, Ejército de Ventormenta, Villanorte" },
		[213] = { file = "213", len = 21.264, text = "Estofado de los Páramos de Poniente 3 partes de carne fibrosa de buitre 3 morros de dentosangre 3 ojos de múrloc 3 okras Mezclar todos los ingredientes y poner a hervir. Hervir a fuego lento al menos durante dos horas antes de servir." },
		[214] = { file = "214", len = 25.992, text = "Querida Yvette, Encomendaré esta carta a $Gnuestro corredor:nuestra corredora; más veloz. Espero que pueda avanzar sin contratiempos por las zonas en que habitan las fuerzas que nos rodean. También ruego para que puedas leer estas palabras, pues son lo último que sabrás de mí. Mi único consuelo en estos días aciagos es el alivio que me produce saber que no tendrás la misma suerte que yo." },
		[218] = { file = "218", len = 37.146, text = "Temo que la guerra entre los Pedregosa y los Maclure acabe con el incipiente romance entre Tommy Joe y Maybell, así que, en tiempos como estos, en los que los rumores de guerra se ciernen sobre nosotros, es preciso cultivar la juventud y el amor. De ahí el favor que te pido: te pido que uses tus habilidades y fabriques una poción o elixir para ayudar a estos dos jóvenes en su misión de reunirse. Gracias, William. Y por favor, si puedes apartarte un poco del trabajo, ven a visitarme. Te invito a que nos riamos un poco recordando el pasado. Mildred" },
		[219] = { file = "219", len = 36.519, text = "De la mano de Baros Alexston, Oficina del arquitecto de la ciudad Ventormenta Vuestra Majestad, Hay muchas razones por las que consideré que era preciso presentar un informe sobre los asuntos recientes de la Hermandad Defias y sus actividades en todo el reino. Para poneros en antecedentes, haré un poco de historia. Como sabréis, o quizás desconocéis, empecé a servir a la ciudad de Ventormenta como miembro de la Hermandad de los Albañiles. Durante años de intenso trabajo, terminamos la reconstrucción de" },
		[220] = { file = "220", len = 38.322, text = "Ventormenta, momento en el que las facturas y los honorarios de la Hermandad de los Albañiles quedaron sin pagar y sin explicación alguna. En aquella época, Edwin VanCleef había sido elegido Maestro de la Hermandad de los Albañiles y exigió las retribuciones por el trabajo realizado. En respuesta, la Casa de Nobles de Ventormenta ordenó la disolución de la Hermandad de los Albañiles, lo que molestó a VanCleef, como es de suponer. VanCleef encabezó un motín de los Albañiles en las afueras de la ciudad. Antes de continuar, debo mencionar otros acontecimientos que tuvieron lugar durante" },
		[221] = { file = "221", len = 36.362, text = "esta época, que conviene resaltar. En primer lugar, fue en aquel momento cuando me ofrecieron trabajar como arquitecto de la ciudad si no me unía a VanCleef. Debido a ciertas diferencias ideológicas, elegí permanecer en Ventormenta. Durante el levantamiento, el teniente y hombre de confianza de VanCleef, Bazil Thredd, fue capturado y recluido en prisión. A la espera de ser juzgado e interrogado, Thredd estuvo a punto de ser olvidado en las mazmorras. Al regresar con VanCleef, después de dirigir lo que quedaba de" },
		[222] = { file = "222", len = 33.515, text = "los Albañiles fuera de Ventormenta, aprovechó la relativa falta de protección de los Páramos de Poniente y utilizó su mano de obra considerable para expulsar a muchos granjeros y tomar posesión de un puñado de minas de oro. Utilizando los recursos de que disponía, VanCleef urdió un plan de retribución contra el gobierno de Ventormenta. Esta información fue revelada recientemente con la ayuda del portador de este documento, cuya actuación resultó decisiva a la hora de esclarecer esta importante conspiración." },
		[223] = { file = "223", len = 35.291, text = "Difundan esta información como consideren necesario. Comando Regional de Tirisfal Capitán Melrose Capitán Vachon Capitán Perrine Órdenes del Alto Señor. Capitán Perrine, es preciso reforzar más su posición en la torre del sudoeste (tal como se especificó anteriormente). Más adelante enviaremos suministros adicionales. Mientras tanto, deberían conseguir materiales en las granjas vecinas. Asimismo, es preciso realizar nuevos trabajos de reconocimiento e información" },
		[224] = { file = "224", len = 28.5, text = "sobre la organización de los no-muertos en Rémol. Capitán Vachon, al parecer, los no-muertos han intensificado sus maniobras cerca de la torre del norte. Hay que ocuparse de esta rebelión de forma rápida y contundente. Capitán Melrache, nos preocupa el nivel de organización de los no-muertos cerca de las fronteras de las Tierras de la Peste. En las próximas semanas le enviaremos un nuevo contingente de hombres. Gloria a todos en la Luz" },
		[229] = { file = "229", len = 24.764, text = "Primer día Se me ha roto el depósito, pero sé que por estas colinas encontraré el mineral de Quiron. Le dije a Podomartillo que se quedara para vigilar nuestros depósitos. Continuaré buscando yo solo. Si no logro regresar, este diario será mi último testamento. Buron Hondocuesta, piloto Brigada de Tanques de Vapor de Forjaz" },
		[230] = { file = "230", len = 25.104, text = "Segundo día Mi búsqueda continúa y sigo sin encontrar el mineral. Me pregunto si lo del mineral es solo un rumor o una broma de Roscapiedra. Si es así, ¡cuando vuelva al Almacén de Brasacerada le voy a partir el cráneo! Anoche, cuando preparaba mi campamento, escuché el eco de un gruñido desde los cañones. No era un lobo. Antes parecía un oso." },
		[231] = { file = "231", len = 17.241, text = "Tercer día Los gruñidos se prolongaron durante toda la noche y me han seguido a lo largo del día, distrayéndome de mi labor de búsqueda del mineral. ¡Creo que un oso me está siguiendo! Espero que se acerque todo lo posible. ¡Así podré enterrarle mi pico en la cabeza!" },
		[232] = { file = "232", len = 28.16, text = "Cuarto día Mis provisiones se están agotando. Aún me queda bastante comida, pero no había planeado quedarme tanto tiempo en la selva, lejos de mi tanque, con tan solo dos barriles de cerveza. He permanecido despierto las últimas dos noches, escuchando ese maldito gruñido y ¡casi me bebo los barriles enteros! Tengo que regresar mañana con Podomartillo y nuestros tanques de vapor. No quiero perderme aquí, sin cerveza." },
		[233] = { file = "233", len = 33.019, text = "Quinto día ¡El maldito oso me dejó destrozado! Me atacó al mediodía, gruñendo y embistiéndome por la espalda. De haberse aproximado contra el viento, habría percibido su olor... ¡su hedor era espantoso! ¡El olor de su pelaje roñoso y su aliento podrido bastaban para aniquilar a cualquiera! ¡Luché contra esa bestia, pero al final dio un buen bocado a mi pierna. Ahora no puedo moverme, me he quedado sin cerveza y, finalmente, no he logrado encontrar el mineral. ¡Maldición!" },
		[234] = { file = "234", len = 26.645, text = "Sexto día El oso aún no ha vuelto... ¡Debí darle una buena paliza! Pero sigo escuchando sus gruñidos. ¡Creo que está esperando a que muera! Si encuentras este libro, debo encomendarte una tarea. Mata a ese oso asqueroso. Mátalo y luego lleva el libro a mi amigo Podomartillo. Él querrá saber qué ocurrió. También puedes coger mi armadura. ¡La necesitarás para luchar contra Sarnagarra!" },
		[235] = { file = "235", len = 36.101, text = "Saludos, Ello Cerranegro, Alcalde de Villa Oscura. Me temo que traigo noticias para tu ciudad. Noticias graves. Sabes, soy un creador. He engañado al portador de esta nota para que me ayudase en mi última y más directa creación: ¡un demonio de carne, hueso y metal retorcido! Cuando leas esto, esta bestia estará junto a mi humilde morada, rechinando sus dientes y esperando mis órdenes para masacrar a alguien. Pronto tendrás noticias mías. El embalsamador" },
		[236] = { file = "236", len = 24.085, text = "El estudio de diversas criaturas fosilizadas me ha permitido deducir que, en la antigüedad, una gran peste asoló las aguas del lago Lordamere. ¿Qué la causó? Tal vez nunca lo sepamos. Pero el nivel de contaminación parece ser muy alto, considerando las elevadas concentraciones de restos adheridos en el fondo del lago." },
		[237] = { file = "237", len = 29.022, text = "En un intento por descubrir los secretos del pasado, he empezado a examinar las criaturas del presente con la intención de encontrar el eslabón que falta para resolver el misterio. Los vagadores del Lago y los trepadores del Lago son antiguas bestias que habitan las islas que pueblan el centro del lago Lordamere. Hay un musgo que crece en ellas y que se asemeja a los restos de algunos fósiles. Debo indagar más para especular sobre el significado de este vínculo." },
		[238] = { file = "238", len = 34.377, text = "Al intentar recoger muestras de musgo, presencié una sangrienta batalla. La tribu de los múrlocs Anca Vil estaba siendo asediada por una banda de maleantes gnoll. Había cadáveres gnoll y múrloc desperdigados por el campo de batalla. Cuando pasé junto a un múrloc destrozado, advertí que tenía un tumor endurecido que sobresalía de la herida. Al mirar el tumor más de cerca, me di cuenta que tenía propiedades similares a las del musgo que he estado recogiendo. Desafortunadamente, no pude encontrar más tumores, salvo este." },
		[244] = { file = "244", len = 24.66, text = "Lord Bethor Duroyelo: Tal como me ordenó, le envío a la agente que ha solicitado. Es quien lleva esta nota. Esta persona ha demostrado ser confiable y capaz de seguir órdenes, es eficaz contra las fuerzas de la Plaga y por eso la he elegido para su misión. Que su reinado sea absoluto, -Magistrado Sevren" },
		[245] = { file = "245", len = 31.922, text = "Desaparecido: Cabo Keeshan Fue visto por última vez durante la sangrienta batalla del Fuerte de Petravista. Según los informes, fue arrastrado por los orcos Roca Negra. Se cree que permanece retenido como prisionero de guerra en el campamento Roca Negra, al norte de Villa del Lago, justo al oeste del paso que conduce a las Estepas Ardientes. Por mandato del magistrado Solomon, todo aquel que colabore en el rescate del cabo Keeshan será recompensado por el Alguacil Marris." },
		[246] = { file = "246", len = 36.127, text = "He pasado las últimas semanas de un lado para otro, sin permanecer mucho tiempo en ningún sitio por miedo a los jinetes. Ahora me encuentro en la ciudad abandonada de Cerro del Cuervo, oculto, como siempre. No podría enfrentarme al poder que utilizaron contra la mujer de Sven y sé que continúan buscando la Guadaña en el Bosque del Ocaso. La he perdido y, gracias a la Luz esto es así, puesto que, de conservarla, sé que me habrían encontrado. De hecho, en lo más profundo sigo convencido de que me encontrarán. Estoy tan cansado." },
		[248] = { file = "248", len = 27.899, text = "Saludos, maestro: Te pido disculpas por el sistema de envío de este mensaje. Mis magos de la sombra en Alterac están concentrados en sus tareas, obligándome a utilizar un mensajero extraño, reclutado entre nuestros nuevos \"aliados\", para hacerte llegar este informe. Pero he encriptado esta carta con uno de nuestros cifrados más esotéricos. Sus palabras están a salvo de estos palurdos." },
		[249] = { file = "249", len = 31.295, text = "Valik, Vigila al esclavo hasta que regresemos. No es seguro mantenerlo aquí más tiempo. Lo llevaremos al norte, lo más lejos posible para evitar que lo vean. Son animales, pero no obstante son animales despiadados. Si fueran bastantes, tendríamos motivos para preocuparnos. Lo mejor es evitar cualquier señal que pueda entenderse como una provocación. Lo último que queremos es darles razones para que nos ataquen en masa." },
		[250] = { file = "250", len = 28.761, text = "Un grupo procedente del puesto de mando de los Defias se pondrá en contacto con el Coleccionista y él trasladará el oro recogido. Asegúrate de que este proceso se lleve a cabo con cuidado y con la mayor discreción. El Coleccionista es responsable del traslado del oro, pero, en última instancia, es responsabilidad de todos los miembros de la Hermandad Defias garantizar que su papel se desempeñe con atención y disciplina." },
		[251] = { file = "251", len = 11.755, text = "Recordad, hermanos míos que un día fuimos orgullosos artesanos. Realizaremos nuestro trabajo con la misma precisión que utilizamos en nuestro oficio anterior. EVC" },
		[252] = { file = "252", len = 26.227, text = "Creo que mi padre cometió un grave error cuando decidió quedarse en casa para defenderla. Las fuerzas de la Plaga asolan los Claros de Tirisfal y, aunque estamos fortificados y bien abastecidos, después de la traición de mi hermano Devlin carecemos de fuerza y tropas suficientes para hacer frente a sus continuos asaltos. Yvette, si recibes esta carta, deberás saber que Devlin es un traidor." },
		[253] = { file = "253", len = 31.295, text = "Devlin perdió la esperanza e intentó escapar a nuestro infortunio, por lo que hizo un pacto con la Plaga. No sé qué se le prometió a cambio de su traición, pero lo que sí puedo asegurar es que estaba tejido de mentiras. Si ves a mi hermano, huye de él. Es un demonio. Hace un par de noches asesinó a dos de nuestros vigilantes y ayudó a un pequeño grupo de Soldados de la Plaga a entrar por la brecha, conduciéndolos hacia donde muchos de los nuestros dormían." },
		[254] = { file = "254", len = 34.142, text = "Su emboscada fue brutal. Asesinaron a un tercio de nuestras tropas antes de que pudiéramos responder. Ahora solo contamos con hombres para vigilar nuestras fronteras. Solo es cuestión de tiempo: en cuanto bajemos la guardia, la Plaga nos atacará. Y aunque vi el rostro de Devlin en medio de todos esos hombres desesperados y las fuerzas de la Plaga aquella noche maldita, se escabulló antes de que pudiera atraparlo. Tal vez esté muerto, o viva aún como agente de la Plaga. En cualquier caso, es un monstruo." },
		[255] = { file = "255", len = 23.954, text = "Devlin nos advirtió que si intentábamos enfrentarnos a la Plaga, estaríamos condenados. Nos lo dijo cuando entró por primera vez en los Claros de Tirisfal, antes de que rodearan nuestro hogar. Quizás estaba suplicando que nos marcháramos, o quizás se deleitaba. Siempre ha sido difícil comprender las razones de Devlin. Desde que era niño, siempre fue un misterio para nosotros." },
		[256] = { file = "256", len = 22.988, text = "Pero tenía razón. Estábamos perdidos. La familia Agamand está condenada a la desaparición. Aunque yo viva aún, sé que pronto moriré. No tengo miedo, y no lamento haberme quedado con los míos. Pero debes saber que mi último pensamiento te lo dedicaré a ti. Sigue con vida, mi amada Yvette, para poder irme en paz, Thurman" },
		[257] = { file = "257", len = 18.26, text = "Nuestros planes avanzan adecuadamente: como dije antes, nos aliamos con un grupo de humanos que se hacen llamar la Hermandad. Sus líderes son antiguos nobles de Alterac y ansían volver a dominar estos territorios. Por eso hemos llegado a un acuerdo. Un acuerdo que lamentarán." },
		[258] = { file = "258", len = 33.959, text = "La Hermandad apenas tiene influencia en estas tierras, pero conocen bien la zona y cuentan con suficiente mano de obra para realizar los próximos trabajos. Con un buen guía, confío en que pronto la Hermandad volverá a reinar en Alterac. Además, les hemos pedido que vuelvan a tomar la ciudad de Stromgarde, cerca de las Tierras Altas de Arathi. Esta ciudad es campo de batalla para nuestras fuerzas, ogros y humanos de Stromgarde, pero creemos que con tácticas bien coordinadas recuperaremos nuestra ciudad, antiguamente hermosa." },
		[259] = { file = "259", len = 17.241, text = "Y cuando esto ocurra, podremos iniciar la siguiente etapa de nuestro plan. Con una nación propia y una base de poder en esta región, allanaremos el camino para el Tercer Ejército. ¡Pronto, los Señores de la Legión nos volverán a recompensar con su lluvia de fuego!" },
		[261] = { file = "261", len = 35.082, text = "Pero, ¿por qué digo todo esto? Lo afirmo para dar credibilidad a lo que voy a escribir, ya que estas fueron palabras de Kegan y es mi deseo que, después de leer este diario, mis compañeros entiendan por qué creo en ellas: \"Vestigios de dioses antiguos yacen en las huecas profundidades del mundo. Ahora, las nuevas fuerzas intentan utilizar aquel antiguo poder, por lo que aquellos que lo consigan, tendrán en sus manos un arma terrible para combatir a sus enemigos.\"" },
		[262] = { file = "262", len = 32.679, text = "Magistrado Rutherford Ladoquemao Todas las deudas saldadas. Herrero Avery Verrintan Todas las deudas saldadas. Dependiente Horracio Corzalbal Todas las deudas saldadas. Concejal Giligil Todas las deudas saldadas. Concejal Garfios Todas las deudas saldadas. Granjero Getz Todas las deudas saldadas. Granjero Ray Deuda pendiente. Promesa de pago en productos agrícolas durante la cosecha. Granjero Lyion Deuda pendiente. Expulsado de sus tierras." },
		[266] = { file = "266", len = 37.146, text = "Kegan Darkmar, líder de una pequeña banda de no-muertos que vino a vernos en busca de asilo para escapar de sus \"hermanos\", desafía nuestras actitudes habituales en relación con los de su especie. Puede que su piel se esté pudriendo o que la sangre hace tiempo que no fluye por sus venas, pero actúa con nobleza, mostrando más preocupación por la seguridad de sus compatriotas que por la suya propia. De hecho, percibo en él una humanidad que, siendo franco, a veces echo de menos en algunos humanos que conozco." },
		[267] = { file = "267", len = 31.791, text = "Pero, ¿por qué digo todo esto? Lo afirmo para dar credibilidad a lo que voy a escribir, ya que estas fueron palabras de Kegan y es mi deseo que, después de leer este diario, mis compañeros entiendan por qué creo en ellas: \"Vestigios de antiguos dioses yacen en las huecas profundidades del mundo. Ahora, las nuevas fuerzas intentan utilizar aquel antiguo poder, por lo que aquellos que lo consigan, tendrán en sus manos un arma terrible para combatir a sus enemigos.\"" },
		[268] = { file = "268", len = 35.892, text = "Tales fueron las palabras pronunciadas por Kegan cuando extendió su colgante de sangrita hacia mí, y había en sus ojos temor, tal vez reverencia. Cuando sus manos se unieron a las mías, permanecieron inmóviles, como si se negara a entregar el colgante. Sentí cierta repugnancia, pero no recuerdo si mi rechazo se debía a la carne muerta apretando mi mano o si era el colgante el que me hacía estremecer. Pero puedo asegurar que notaba una fuerza en su interior. Una fuerza profunda, oculta, sedienta. Anhelando ser liberada." },
		[269] = { file = "269", len = 16.64, text = "Aunque mis compañeros en Dalaran tomaron la precaución de estudiar las sangritas que Kegan y sus seguidores llevaban encima, en lugar de poner a los cuatro refugiados en cuarentena y dejar las sangritas en sus cuerpos, la sinceridad de Kegan me obligó a estudiar su colgante." },
		[270] = { file = "270", len = 24.085, text = "Deseaba comunicar a mis compañeros que este tipo de piedra tenía propiedades mágicas, y si nosotros, los zahoríes de Dalaran, no teníamos la intención de aprovechar los poderes de las sangritas, al menos debíamos conocer sus propiedades, porque estaba claro que nuestros enemigos las utilizarían contra nosotros tarde o temprano. Y así fue como inicié mi investigación." },
		[271] = { file = "271", len = 29.753, text = "Realicé algunas pruebas, suponiendo que la sangrita era un tipo de roca, como el cuarzo o la obsidiana. Por ello llevé a cabo una serie de procedimientos para determinar lo siguiente: qué minerales contenía la sangrita, qué fuerzas actuaban para producir su color y dureza, así como otras propiedades comunes a las rocas y a los minerales. Pero para mi decepción, el colgante de sangrita no reaccionó a mis pruebas como lo haría un mineral corriente." },
		[272] = { file = "272", len = 26.958, text = "De hecho, ¡solía reaccionar de la forma contraria a la esperada! Era como si el colgante estuviera boicoteando mis experimentos deliberadamente. Como si tuviera vida y mente propias. $GEnfadado:Enfadada;, pero sin desanimarme, descarté la idea de que el colgante fuera un trozo de roca inerte, cobrando mayor fuerza la teoría de que se trataba de un ser vivo. Pero nuevamente, me equivoqué." },
		[273] = { file = "273", len = 34.847, text = "Ninguna de mis pruebas reveló información alguna sobre el origen de la sangrita. Aquella vez, lo único que saqué en claro era que la sangrita no estaba ni viva... ni muerta. Pero fue en ese momento, a punto de fracasar, cuando se produjo el mayor avance. En mi última prueba, utilicé un vaso de precipitados cuyo borde estaba roto, quedando un pequeño orificio irregular en la parte superior. Al acabar la prueba, sin resultado alguno, fui a limpiar la mesa de trabajo y me corté con el vaso." },
		[274] = { file = "274", len = 14.472, text = "El corte no era profundo, sin embargo, brotó mucha sangre de la herida. Antes de ponerme un vendaje, buena parte de mi sangre cayó sobre la mesa de trabajo. Y cuando volví a limpiarla, advertí algo muy extraño..." },
		[275] = { file = "275", len = 21.159, text = "La sangre que había derramado cerca del colgante de sangrita se desplazaba lentamente hacia la gema, como si esta poseyese una extraña fuerza de atracción. La sangre que había entrado en contacto con el colgante aparentemente desapareció y el tono púrpura de la piedra aumentaba a medida que bebía de mi sangre." },
		[276] = { file = "276", len = 37.433, text = "Después de presenciar este fenómeno, la cabeza empezó a darme vueltas, quizás por mi herida reciente (aunque realmente no creí que fuera la causa, puesto que no había perdido tanta sangre) o quizás por mi descubrimiento, tras innumerables intentos, de una de las propiedades de la sangrita. Tanteando a mis espaldas, arrastré mi taburete, me senté y cavilé durante un rato. Numerosas preguntas rondaban mi cabeza, mareándome y amenazando con hacerme perder el equilibrio. ¿Acaso la sangrita bebe sangre? ¿Está sedienta de sangre? ¿Atrae la sangre?" },
		[277] = { file = "277", len = 21.29, text = "¿O acaso está hecha de sangre? Y si es así, ¿de quién es la sangre? ¿La mía? ¿O la de cualquier humano? ¿La de algún animal? O quizás esta gema sea la sangre de algo desconocido, algo que Kegan temía y veneraba al mismo tiempo cuando me dio su colgante. Esta es la pregunta que necesita respuesta. Es la clave." },
		[278] = { file = "278", len = 24.163, text = "La llama de la curiosidad se reavivó en mi interior y volví a mis experimentos. Esta vez no hice conjeturas, realizando las pruebas de forma metódica. Esto requirió mucho más trabajo, pero había mayores probabilidades de hacer descubrimientos. Y aunque mi laboratorio es pequeño y no dispongo de ayudantes, descubrí otra cualidad más inquietante en la sangrita..." },
		[279] = { file = "279", len = 21.786, text = "Además de sangre, hay fuerzas elementales fundidas en la piedra. Fuego, agua, truenos y roca se mezclan con la sangre (sí, pero ¿la sangre de quién?) y, si bien esta mezcla es inerte en el exterior, todas estas fuerzas parecen chocar entre sí en el interior. Este sorprendente y premonitorio material planteaba nuevas preguntas." },
		[280] = { file = "280", len = 27.063, text = "Pero para responder a estas preguntas, era necesario realizar más estudios y experimentos en el colgante y mucho me temo que el Campo de Reclusión de Lordamere no puede conseguir ni la mano de obra ni el equipo para llevar a cabo esta tarea. Así que envié el colgante de sangrita con un mensajero a Dalaran con instrucciones específicas sobre el tipo de pruebas que era necesario realizar para evitarles mis iniciales decepciones." },
		[281] = { file = "281", len = 23.066, text = "Mientras esperaba los resultados de estas pruebas, me dediqué a hablar con Kegan. Aunque constantemente le presioné para que me revelara lo que sabía sobre las sangritas, nunca me contó nada distinto de lo que me dijo el día que me entregó el colgante. Y no solía hablar sobre la época que pasó con el grupo de \"Renegados\", nombre con el que se refería a su clan de no-muertos." },
		[282] = { file = "282", len = 19.331, text = "Pero Kegan estaba ansioso de hablar de otras cosas, particularmente de su infancia en Lordaeron, antes de su caída. Sigue amando aquel reino perdido, aunque ahora esté arruinado y muerto. Mi creciente afecto por Kegan me llenó de paciencia, mientras esperaba los resultados de mis pruebas." },
		[283] = { file = "283", len = 31.033, text = "Pero transcurridas varias semanas sin tener noticias, mi paciencia se agotó, así que, tras realizar varias averiguaciones sobre Dalaran, supe que la sangrita nunca había llegado a su destino. Mi emisario se había perdido en el camino y el colgante de sangrita ¡se había perdido con él! No eran graves noticias, porque, aunque Kegan y sus seguidores siguen conservando ejemplares de sangrita con los que hacer experimentos, temo que el colgante haya caído en las manos equivocadas." },
		[284] = { file = "284", len = 13.113, text = "He enviado a otro mensajero a Dalaran y he oído que, hasta el momento, siguen buscando el colgante en las ruinas que están fuera de nuestra esfera de protección. Solo espero que no sea demasiado tarde." },
		[285] = { file = "285", len = 28.918, text = "Cuento de Gri'lek el Trotamundos [...El comienzo de la tablilla estaba desgastado y borrado. Pero el final era legible...] Gri'lek caminaba ruidosamente por la jungla. Sus ojos eran dos llamas y su pecho rugía, pues la ira lo consumía. Enfurecido, rugió mirando al cielo y levantó un brazo. Alzó el brazo izquierdo, que era fuerte y certero porque cazaba sin su gemelo. Y es que el brazo derecho de Gri'lek ya no estaba y no volvería nunca más." },
		[286] = { file = "286", len = 30.224, text = "LEYENDAS DE LOS TROLS, VOLUMEN III Piedra de las Mareas Escrito por Archimago Ansirem Tejepista Dalaran INTRODUCCIÓN El antiguo Imperio Gurubashi alimentó leyendas inquietantes y fascinantes que, sin duda, pueden rastrearse en la zona, ya que el estudio de sus sistemas de creencias y prácticas sociales han señalado la gran importancia del entorno natural. Mientras ahondaba en muchos" },
		[287] = { file = "287", len = 33.071, text = "Kurdran Martillo Salvaje Afamado cazador de dragones. Maestro de grifos de Pico Nidal. Comandante de la División de jinetes de grifos adscrita a la Expedición de la Alianza que marchó hacia Draenor, tierra de los orcos. Presuntamente fallecido. Oiremos el llamado de Cielo-Ree surcar los vientos. Oiremos el rugir de tu martillo bordeando las cumbres. Cabalga hasta el más allá, hermano. Las salas de nuestros ancestros te aguardan. - Falstad Martillo Salvaje - Señor de Pico Nidal" },
		[288] = { file = "288", len = 33.045, text = "Capitana forestal Alleria Brisaveloz Afamada cazadora de trols de Quel'Thalas. Jefa de exploradores y agente de inteligencia para la Expedición de la Alianza que marchó hacia Draenor, tierra de orcos. Presuntamente fallecida. Hermana, tu espíritu fue inquebrantable, como el recorrido de una flecha en el viento. Fuiste la más brillante de nuestra orden, la más amada de nuestro linaje. - Sylvanas Brisaveloz - General Forestal de Quel'Thalas" },
		[289] = { file = "289", len = 24.189, text = "Archimago Khadgar del Kirin Tor Antiguo aprendiz de Medivh. Comandante Mayor de la Expedición de la Alianza que marchó hacia Draenor, tierra de orcos. Presuntamente fallecido. Nadie exploró tan altruistamente las oscuras entrañas de la magia y la guerra. Te deseamos lo mejor, audaz aventurero… estés donde estés. - Antonidas - Archimago de Dalaran" },
		[290] = { file = "290", len = 32.078, text = "General Turalyon Antiguo teniente de Lord Anduin Lothar. Caballero de la orden de la Mano de Plata. Alto general de la Expedición de la Alianza que marchó hacia Draenor, tierra de orcos. Presuntamente fallecido. Esarus thar no'Darador' - Servimos por la sangre y el honor. Viejo amigo, fuiste la mano derecha de la justicia y la virtud. Honraremos tu nombre en nuestras salas… por siempre. Lord Uther el Iluminado, Caballero de la orden de la Mano de Plata" },
		[291] = { file = "291", len = 30.563, text = "Danath Aterratrols Comandante de Milicia de Stromgarde. Consejero táctico del general Turalyon, Comandante de Fuerza de la Expedición de la Alianza que marchó hacia Draenor, tierra de orcos. Presuntamente fallecido. Querido sobrino, honramos tu memoria y valoramos tu sacrificio. Desde la fundación de nuestro glorioso imperio, la senda del valor siempre se ha abonado con la sangre de los héroes. Thoras Aterratrols, Señor de Stromgarde" },
		[292] = { file = "292", len = 32.313, text = "Aquí yace Uther el Iluminado Primer paladín, fundador de la orden de la Mano de Plata Uther vivió y murió para defender el reino de Lordaeron. Aunque fue traicionado por su discípulo más amado, creemos que su espíritu pervive. Continúa observándonos, aun cuando las sombras acechen nuestra tierra desolada. Su luz es la luz de toda la humanidad y, siempre que hagamos honor a su memoria, esta nunca se perderá. Anónimo" },
		[293] = { file = "293", len = 34.403, text = "aspectos de su adoración a las culebras, en volúmenes anteriores de este estudio, analizo aquí la interesante y peculiar relación de los trols con el mar. EL MARE MAGNUM El Imperio Gurubashi estaba rodeado por el mar en tres de sus costados, así que no resulta sorprendente que el agua desempeñara un papel preponderante en su sociedad. Si bien los trols eran capaces de ir de un lado a otro y controlar vastas extensiones de jungla dentro de su imperio, el mar los eludía. Era vasto e inconmensurable, sin" },
		[294] = { file = "294", len = 32.627, text = "duda un vecino desconcertante para los poderosos trols. Es preciso aclarar que recientes descubrimientos sugieren que los trols no mostraban demasiado interés en explorar las tierras que había más allá del Mare Magnum. Aunque se han hallado especies de trols en toda la extensión de Azeroth, Khaz Modan y Lordaeron, apenas se han encontrado vestigios de su civilización en las tierras recientemente descubiertas de Kalimdor o en las islas de los Mares del Sur. Tanto si esto demuestra la nula disposición de" },
		[295] = { file = "295", len = 35.37, text = "los trols a aventurarse fuera de sus tierras, como si se trata de la ausencia de tecnologías para acometer tal empresa, es preciso una investigación y un análisis que escapan al alcance de estos escritos. No obstante, resulta difícil ignorar una presencia tan importante. De hecho, nuevos hallazgos en las extensas ruinas trol de la Vega de Tuercespina muestran un aspecto de su relación con el mar anteriormente desconocido y no documentado. LA PIEDRA DE LAS MAREAS Recientes descubrimientos efectuados durante el reconocimiento" },
		[296] = { file = "296", len = 33.437, text = "de las ruinas trol de la Vega de Tuercespina contienen referencias a un objeto conocido como la \"Piedra de las Mareas\". Diversos fragmentos de leyendas trol pueden unirse para pintar un cuadro bastante completo de la Piedra y establecer su significado para el Imperio Gurubashi. Al parecer, la Piedra de las Mareas ofrecía a su portador el control del agua en sus diversas formas: ríos, lluvia y mareas. Dadas las historias relacionadas con el uso de la Piedra de las Mareas, he conjeturado que se trata" },
		[297] = { file = "297", len = 31.216, text = "en realidad, de una manifestación física de los poderes del Señor del Agua, un poderoso elemental de los mares. La razón y la manera en que un objeto de estas características escapa al control del Señor del Agua y cae en manos de los trols es otra cuestión que está fuera de mi alcance. EL PORTAMAREAS Imitando el movimiento de las olas, la Piedra de las Mareas entró y salió del mundo de los trols, sin permanecer en manos de ellos más de una generación cada vez." },
		[298] = { file = "298", len = 30.772, text = "Según las leyendas trol, la primera vez que la Piedra de las Mareas entró en el Imperio Gurubashi, fue encontrada por un guerrero trol que caminaba por la costa de Tuercespina. Halló una misteriosa piedra azul que contenía unos filamentos lechosos que flotaban y fluían en su interior. Intrigado por la piedra, el guerrero la guardó y continuó su camino. Tras unas semanas, o quizás meses, el guerrero descubrió que la piedra le había otorgado el control sobre el agua. Podía invocar" },
		[299] = { file = "299", len = 32.366, text = "elementales de agua, criaturas hechas totalmente de agua, realizando hazañas solo propias de los poderosos magos del Kirin Tor. El guerrero viajó a Zul'Gurub, en pleno corazón del Imperio, para mostrar sus nuevas habilidades al Emperador. Le escucharon en la corte tras demostrar sus poderes en el centro de la capital imperial. Estos poderes sorprendieron al Emperador Gurubashi, quien de inmediato le otorgó un sitio de honor en la corte, nombrándolo guerrero \"Portamareas\", dejando atrás su" },
		[300] = { file = "300", len = 35.631, text = "antiguo nombre. Durante años, el Portamareas sirvió al Imperio Gurubashi, invocando en la batalla a los elementales de agua sometidos a su voluntad y manipulando el cauce del agua en la Vega de Tuercespina para beneficio del Imperio. Pero con el paso de los años, el Portamareas se volvió cada vez más solitario, tendiendo a permanecer largos periodos fuera de la corte. El Portamareas ocultaba un secreto a la atenta mirada la corte. Las cualidades que le otorgaba la Piedra de las Mareas incluían una maldición. Con el paso de" },
		[301] = { file = "301", len = 34.586, text = "los años, el Portamareas se fue desvaneciendo. Cada vez que la marea subía y bajaba, el Portamareas iba perdiendo paulatinamente su forma corpórea original, cobrando y perdiendo vida de forma intermitente. Hasta que, en el ocaso de su existencia, viajó al lugar en el que había encontrado la Piedra, se internó en el mar y desapareció para siempre. Generaciones más tarde, la Piedra de las Mareas regresó a las playas de Tuercespina y eligió a otro Portamareas, un trol que la condujo hasta" },
		[302] = { file = "302", len = 24.581, text = "Zul'Gurub. Este proceso se repitió durante generaciones: la Piedra aparecía con la marea y, posteriormente, el Portamareas desaparecía en el mar. En varios sitios se cuentan versiones modernas del mito de la Piedra de las Mareas, pero lo cierto es que resulta sorprendente que un objeto tan poderoso apareciera con tanta regularidad, por designios de un ser desconocido." },
		[303] = { file = "303", len = 30.145, text = "Órdenes de los Velasangre Poned atención a estas palabras, mis valientes, ya que solo podremos echar un trago en la Bahía del Botín. He enviado al viejo Dunken para que explore el norte y le he dicho que espere a la señal. La Damisela Afortunada fondeará en el cabo del sur por motivos de reabastecimiento. El retaco del Capitán Aguaserena va a preparar a su tripulación para reunir todo el botín robado. Estoy seguro de que el burro de Brutus estará al frente de todo." },
		[306] = { file = "306", len = 25.835, text = "Quiero que el capitán Volcayecto lleve el Mareas Vivas a la costa desde el sudeste. Enviaremos a su tripulación a pie cuando se dé la señal. El bruto de Fausal puede convencer a los hombres fácilmente. Quiero que marquéis a Revilgaz y a Cuernomarino. Por mí que se pudran en el fondo del mar. Os hago responsables de que rescatéis todo lo que podamos usar en nuestro pequeño proyecto con VanCleef en las Minas de la Muerte." },
		[307] = { file = "307", len = 32.993, text = "Daré la orden a Parchierro para que abra fuego. La descarga de artillería evitará que los barcos de los Aguasnegras entren o salgan del puerto. Después de que el Velo Carmesí haya descargado sus cañones, lo llevaré junto al Mareas Vivas para que sirva de apoyo y proporcione suministros. Una vez que Fausal y sus hombres hayan bombardeado la ciudad y todos estén en cubierta, zarparemos y cañonearemos la bahía una vez más desde la Costa Salvaje para asegurarnos. Maestro de flota Firallon" },
		[308] = { file = "308", len = 19.592, text = "Escapar de Zanzil en ese buque destartalado parecía buena idea en otros tiempos, pero creo que la muerte habría sido un destino más apropiado. Pensé que mis ancestros me han ayudado al permitirme escapar de su ira. Pero ahora me pregunto qué gano con vivir aquí encarcelado." },
		[309] = { file = "309", len = 26.697, text = "La bestia que gobierna esta isla es terriblemente poderosa. Las otras criaturas que la habitan se encogen de miedo ante su presencia: El gorila Cieloleno y el acechador Jaguero, ambos por igual. Todavía puedo oír esos rugidos que me hacen estremecer. Estas criaturas seguro que detendrían a cualquiera que viniera a la isla. Debo tener fe en mis ancestros." },
		[310] = { file = "310", len = 20.689, text = "Echo de menos a mi tribu, mi hogar. Prefiero mil veces el viento de las extensas planicies o el atardecer en Cima del Trueno al calor de esta jungla. Puedo ver el océano desde aquí, pero esto no refresca mi cuerpo ni alivia mi ánimo. Solo me recuerda mi encarcelamiento." },
		[311] = { file = "311", len = 50.939, text = "Primer día: 6.00 a 11.00: campamento alto 11.00 a 11.30: descanso para comer 11.30 a 4.00: paso del cañón 4.00 a 7.30: campamento alto Segundo día: El mismo itinerario que el del primer día Tercer día: El mismo itinerario Cuarto día: El mismo itinerario, con una excepción. Justo antes del atardecer, Thorsen me pidió que lo cubriera mientras atravesaba el paso del cañón. Supongo que fue a encontrarse con nuestros agentes. Pero regresó una hora más tarde. Esto me sorprendió. Esperaba que se reuniera con nuestros agentes y que se reincorporara a Kurzen. Algo va mal." },
		[312] = { file = "312", len = 33.437, text = "Quinto día: Thorsen estuvo muy inquieto hoy. Aquello que vio o la persona que encontró en su excursión de ayer debió de asustarle mucho. Creí que nuestros agentes habían hablado con él, pero cuando pregunté a Thorsen adónde había ido mientras yo lo cubría, permaneció callado. Él se considera mi amigo y cree que me está protegiendo de un secreto peligroso. Su lealtad es errónea, pero fuerte. Cuando se reincorpore a nosotros, será una adquisición valiosa para las fuerzas de Kurzen." },
		[313] = { file = "313", len = 31.53, text = "Sexto día: A primera hora de la mañana, Thorsen habló largamente con el sargento Yohwa. Tuve que fingir que dormía para permanecer cerca y oír la conversación. Pero supongo que hablaron de la excursión de Thorsen. Lo observé atentamente durante la comida y vi que Yohwa hacía lo mismo. Más adelante, Doren llamó a Thorsen. Los tres comparten un secreto. Doren y Yohwa deben saber que Thorsen se está quedando con tus agentes. Hace de espía para los rebeldes." },
		[314] = { file = "314", len = 23.406, text = "No podemos darle a Thorsen más información y debemos matarlo. Ya no es útil para nuestro Coronel. Acabaré con Thorsen en cuanto tenga la oportunidad, pero si recibes esta carta, sabrás que aún no he podido hacerlo. En tal caso, propongo que la siguiente reunión de Thorsen con nuestros agentes sea decisiva. Salve Kurzen, M" },
		[315] = { file = "315", len = 14.602, text = "El Consejo fue sabio al nombrarte líder del Despertar de Argus para defender sus estrategias en tierra de humanos y enanos. Y me honra servirte en Alterac. En el nombre de Sargeras, Nagaz, Heirofante de Argus" },
		[316] = { file = "316", len = 33.28, text = "¡Idiotas inútiles! Mi plan era destruir ambos puentes simultáneamente. ¿Y qué habéis hecho vosotros, estúpidos ingenuos? Habéis hecho solo la mitad del trabajo, alertando a toda la Alianza sobre nuestras intenciones. ¡So animales! Tenéis una única oportunidad de enmendar vuestro error. Tenemos explosivos de reserva en las Tierras Altas de Arathi, cerca del puente. ¡Acabad el trabajo si valoráis vuestras míseras vidas! Kam Furiahonda" },
		[317] = { file = "317", len = 19.879, text = "Dun Modr de los Humedales Mi Querida Sara, Las señales son muy fuertes en pocos días nos moveremos para tomar el Puente Thandol. No sé si podre escribirte de nuevo. Me siento impulsado a escribir unas líneas que puede que sean las últimas que tus ojos lean." },
		[318] = { file = "318", len = 18.651, text = "Nuestra tarea puede que solo sea de unos pocos días, y me colmaría, y puede que sea una que me cueste la vida. Si es necesario estoy listo para caer en el campo de batalla de la Alianza. No me cabe duda de la causa a la que estoy comprometido y de que no vacilaré ante ella." },
		[319] = { file = "319", len = 22.178, text = "Sé con qué fuerza el Reino de Forjaz apoya en el triunfo de la Alianza, y cuán grande es la deuda que tenemos con aquellos que nos han precedido con su sangre y sufrimiento de las grandes guerras, y yo estoy dispuesto, perfectamente dispuesto a sacrificar todas las alegrías en esta vida para ayudar a mantener esta alianza y pagar esa deuda." },
		[320] = { file = "320", len = 16.744, text = "Sara, mi amor por ti es inmortal, parece como si me atasen poderosos cables que ni la omnipotencia podría romper, pero el amor de mi Reino me sobreviene como un viento fuerte y me lleva irresistiblemente con todas estas cadenas al campo de batalla." },
		[321] = { file = "321", len = 28.055, text = "Los recuerdos de todos esos momentos felices que he pasado contigo vienen arrastrándose sobre mí y me siento más profundamente agradecido a la Luz y a ti por haber disfrutado tanto y lo difícil que es para mí renunciar a ellos y reducir a cenizas la esperanza de los años venideros que aún podríamos haber vivido y haberno amado juntos y ver crecer a nuestros hijos en nuestra aldea como honorables enanos" },
		[322] = { file = "322", len = 29.309, text = "Sé que tengo poco que pedirle a la Divina Providencia, pero algo me murmura - tal vez es la plegaria de mi pequeño Edgar - que voy a volver sano y salvo con mis seres queridos. Si no lo hiciese, nunca mi querida Sara olvides lo mucho que te quiero y cuando mi último aliento escape en el campo de batalla susurrare tu nombre. Perdona mis muchos defectos y el dolor que pude causarte, lo desconfiado, y lo tonto he sido muchas veces." },
		[323] = { file = "323", len = 25.678, text = "Con qué gusto limpiaré con mis lágrimas cada pequeño momento de tu felicidad y lucharé con todas las desgracias de este mundo para protegerte a ti y a mis queridos hijos del mal. Pero no puedo. Te miraré desde el Vacío Abisal y pasaré cerca de ti mientras te zarandea la tormenta con tu preciada carga y espero triste con paciencia hasta que nos encontremos para no separarnos más." },
		[324] = { file = "324", len = 30.171, text = "Una torre de agua se eleva desde el océano... Neptulon ha enviado descomunales Krakken al desolado I'lalai. Eran tan descomunales sus formas que selvas de algas colgaban de sus miembros, y estos leviatanes nadaban entre los cuerpos. El Krakken más grande levantó sus brazos y los estrelló contra el océano, lanzando enormes olas a su alrededor. Y estas azotaron las costas de I'lalai." },
		[325] = { file = "325", len = 30.38, text = "Los Krakken rugieron y sus voces resonaron como una tormenta marina: \"Allá vamos.\" Sin titubear, Min'loth invocó su magia. Las olas que llegaron hasta I'lalai se separaron a ambos lados, inundando la jungla en toda su extensión. Min'loth pidió entonces a sus esbirros que pronunciaran hechizos de vínculo y se escuchó un intenso barullo cuando decenas de trols elevaron sus cánticos. Una voz destacó sobre las demás." },
		[326] = { file = "326", len = 30.38, text = "Min'loth bramó y su magia recogió el poder de los hechizos de su esbirro, lanzándolos hacia los Krakken que se aproximaban. Las aguas se separaron y el hechizo de Min'loth viajó veloz hacia los siervos de Neptulon. Los relámpagos desgarraron el cielo y el hechizo alcanzó a los monstruos. Miles de truenos cayeron sobre el agua hirviendo y los cráteres ardieron en la tierra. Min'loth aulló victorioso, seguro de que su hechizo derrotaría a las enormes bestias." },
		[327] = { file = "327", len = 27.246, text = "Pero los Krakken son viejos, muy viejos. Recordaban cuando la tierra había surgido por primera vez del mar. Recordaban cuando los Antiguos reinaban y cuando los Viajeros llegaron y los expulsaron. Recordaban cuando la magia era una novedad. Son viejos y guardan muchos secretos. Y aunque el hechizo de Min'loth era poderoso, al igual que el trol, era mortal. Por eso falló." },
		[328] = { file = "328", len = 35.605, text = "No pudo atrapar a los Krakken, pero logró enfurecerlos. Durante miles de años, ningún mortal les había causado daño y el encantamiento de los trols resultó doloroso. Y así, se liberaron de los vínculos del encantamiento de Min'loth, pero luego, bramaron y se enfurecieron. Se oyó un gran estruendo cuando se elevaron grandes olas desde las profundidades, dirigiéndose a la tierra. Cuando alcanzaron l'lalai, proyectaron una sombra sobre la ciudad. Pero antes de destruirla, los Krakken se detuvieron, quedando suspendidos." },
		[329] = { file = "329", len = 34.22, text = "Los médicos brujos trol temblaron y profirieron gritos a su maestro. Min'loth contempló las montañas del mar, con aire fatal y desafiante. Se volvió hacia sus adeptos y susurró unas palabras, y los trols grabaron sus últimas palabras en piedra. Luego, Min'loth se volvió hacia los Krakken que se avecinaban. Hizo una mueca y agitó su báculo, su último acto enérgico. Luego, los Krakken hicieron caer toda su furia en Min'loth y el océano se precipitó sobre l'lalai. Y desapareció." },
		[330] = { file = "330", len = 37.094, text = "A continuación, las aguas cayeron sobre la jungla, inundándolo todo a su paso. Los trols y las bestias gritaron mientras las aguas los golpeaban y los sumergían. Muchos Gurubashi se preguntaban por qué el océano se los tragaba, pero morían igualmente, sin conocer la causa. Y, finalmente, cuando las aguas alcanzaron las montañas, se detuvieron. Cuando se aplacaron, se retiraron hacia la costa y dejaron un rastro de muerte. Las aguas se retiraron, pero rodearon completamente l'lalai, que permaneció anegada para siempre." },
		[331] = { file = "331", len = 16.98, text = "Y el jefe Var'gazul, a salvo tras las montañas en Zul'Gurub, se dirigió a la jungla y vio que su gente había desaparecido. Se sintió desesperado, ya que sus sueños de conquista se habían roto. Y Min'loth, la Serpiente, nunca fue encontrada." },
		[332] = { file = "332", len = 36.806, text = "Oh Sara, pero si los muertos pueden volver a Azeroth y volar alrededor de los que aman, voy a estar más cerca de tí tanto en los días más agradables como en las noches más oscuras para que tengas momentos de felicidad siempre, siempre. Y si sientes la suave brisa sobre tus mejillas esta sea mi respiración, como los ventiladores de aire fresco a tu palpitante templo, asi sea mi espíritu para tí. Sara, no llores mi muerte, piensa que me he ido y espero por tí, para que nos reunamos nuevamente. --Sully" },
		[333] = { file = "333", len = 25.182, text = "A mi Honorable Rey: Este no es lugar para que de la esposa de un humilde soldado cuestione las acciones de un gran líder como usted. Las batallas que rugen través de nuestras tierras están siendo luchadas para preservar nuestro estado de bienestar, desde las frías aguas del Loch Modan a los imponentes picos nevados de Dun Morogh." },
		[334] = { file = "334", len = 22.648, text = "Pero las guerras que emprendemos en nombre de la preservación ¿qué precio pagamos por ellas? La muerte del soldado caído, acaso ¿no nos damos cuenta de que la misma vida que nos esforzarnos en guardar se nos escapa en el campo de batalla? ¿Bajo cuantas espadas y hachas debemos lanzar nuestro futuro? ¿Bajo cuántos pies de suelo patrio tenemos que enterrar nuestro pasado?" },
		[335] = { file = "335", len = 33.045, text = "Este no es lugar para que la esposa de un humilde soldado haga tales preguntas. Sin embargo, os escribo ahora como la viuda que soy de un soldado humilde. Mi esposo fue uno más de los miles de soldados que marchan con usted. Para mí él era el gran Balloo Sully, el padre de mis hijos y mi pareja en esta vida. Perdóname si mi pregunta a usted, oh gran líder, suena inapropiada. Pero los muertos no pueden hacer estas preguntas por sí mismos .... Su Leal súbdito , Sara Balloo" },
		[336] = { file = "336", len = 29.78, text = "A los Schneider, Buenos días: Confío en que hacer negocios en el Distrito del Canal resulta conveniente. Estamos en auge, en la plaza de los comerciantes. Necesitamos prendas de vestir tejidas, ya que nuestras existencias se han acabado. Por favor, envíen un cargamento estándar tan pronto como puedan. Buena suerte y confío en que los estudios de su hijo Thurman progresen adecuadamente, Harlan Bagley" },
		[337] = { file = "337", len = 32.235, text = "Órdenes oficiales para la Flota Kul'Tiras Yo, el almirante Valiente, dirigiré el primer desembarco en las costas de Kalimdor. En mi ausencia, el teniente Benedict será el segundo en la cadena de mando. Todas las cuestiones militares de Kul'Tiras de carácter doméstico serán gestionadas por él. Si no envío mensaje alguno desde el Fuerte de Tiragarde transcurridos 12 meses, el teniente Benedict dirigirá la segunda oleada para conquistar la posición." },
		[338] = { file = "338", len = 34.717, text = "Mientras tanto, envío al teniente Alverold en una misión de exploración por el continente de Kalimdor. Sus fuerzas deben completar la misión y luego deben reunirse con nuestras fuerzas en el Fuerte de Tiragarde. Se da por supuesto que la misión del teniente Alverold tardará tiempo en realizarse. La nueva tierra parece vasta y peligrosa. Pero si la mala fortuna nos alcanza a Benedict o a mí, las tropas de Alverold volverán a tomar el Fuerte. ¡Enviaremos oleada tras oleada hasta que el fuerte sea nuestro! Almirante Valiente" },
		[340] = { file = "340", len = 18.573, text = "Registro de Reclutamiento de la Horda Esta persona ha demostrado tener una gran fuerza y destreza en nombre de la Horda. Debería asignarse para trabajar en El Cruce de inmediato. Respetuosamente: Creo que está bien. - Takrin Abrecaminos" },
		[341] = { file = "341", len = 18.155, text = "Registro de Reclutamiento de la Horda Esta persona ha demostrado tener una gran fuerza y destreza en nombre de la Horda. Debería ser asignada para trabajar inmediatamente en El Cruce. Respetuosamente, - Takrin Abrecaminos" },
		[342] = { file = "342", len = 36.519, text = "La excavación de Bael Modan El equipo de exploración original enviado por la Liga de Expedicionarios acertó en sus descubrimientos. El suelo oculta artefactos de valor ilimitado para nuestra gente. Indudablemente, encontraremos muchas respuestas en nuestra búsqueda de sabiduría entre las arenas y las rocas de Bael Modan. Sin embargo, la geología de la región implica que debemos extremar la precaución. Muchos de los depósitos de arena se han solidificado, debido a las duras condiciones y al cambiante clima." },
		[343] = { file = "343", len = 30.798, text = "Sin embargo, la solución resulta muy simple. Utilizando pasta de madera como absorbente, podemos combinar partes de nitroglicerina con nitrato sódico para desarrollar una potente carga explosiva, capaz de pulverizar incluso las masas más densas. Todo esto será ruidoso y perturbador, pero nuestra búsqueda tiene mucha más importancia que la comodidad de los habitantes locales. De hecho, ya hemos expulsado a una banda de minotauros de la zona, que resultaron ser un incordio." },
		[344] = { file = "344", len = 33.097, text = "El hecho de que estemos tratando con verdaderos bribones me lleva a creer que necesitaremos la ayuda del ejército del rey. La excavación no solo requerirá apoyo militar. De hecho, teniendo en cuenta el mundo de la política en su estado actual, tengo la sensación de que la propia situación de Bael Modan podría tener un alto valor estratégico para la Alianza. Vaya, me he apartado de la cuestión. Bajo estas rocas, hay mucho trabajo que hacer. He estado demasiado tiempo escribiendo, en lugar de excavar..." },
		[350] = { file = "350", len = 41.796, text = "La consola de control de churumbele puede utilizarse para regular automáticamente el flujo de los combustibles, gases, líquidos y otra maquinaria relacionada. Una vez que se haya completado la configuración inicial, debería funcionar sin problemas, con un mantenimiento mínimo. Breve listado de los componentes de la consola de control (de izquierda a derecha) I. Palanca de potencia principal La posición de conexión activa el churumbele. Cuando la palanca esté en posición desactivada, el mecanismo de control no se desconectará de forma automática. Simplemente, esto hará que" },
		[352] = { file = "352", len = 38.975, text = "Supervisor Fizsprocket: Junto a esta nota, encontrarás un listado del equipamiento que has solicitado, aprobado por el presidente Razdunk. Me ha pedido que te recuerde que haga hincapié en el especial interés que tiene Ventura y Cía. en realizar operaciones en Kalimdor. Nuestros puestos de perforación y actividades mineras en los Baldíos han demostrado ser rentables y eficaces, pero aún esperamos conseguir mejores cifras de producción de Mulgore, tu jurisdicción. El consejo consultivo comprende las dificultades que supone poner en marcha" },
		[353] = { file = "353", len = 36.415, text = "una operación a gran escala tan cerca de la tierra natal de los tauren, pero no creas que esto supone un gran impedimento para nuestros planes generales de negocio en el área. Nos complace oír que han comenzado los trabajos de minería en las ricas planicies mineras de Mulgore. Por esta razón, el consejo ha aprobado concederte el equipo que solicitas. Además de las riquezas mineras, creemos que Mulgore tiene mucho más que ofrecer en lo que respecta a los aserraderos, por tanto, te enviaremos alguna de nuestras trituradoras último modelo y materias primas para construir un" },
		[354] = { file = "354", len = 1.097, text = "molino." },
		[355] = { file = "355", len = 36.859, text = "comienza el proceso de enfriamiento y, a partir de entonces, tardará aproximadamente uno o dos minutos en desactivarse, dependiendo de la situación. NOTA IMPORTANTE: La palanca de alimentación principal solo puede utilizarse cuando se hayan desconectado las tres válvulas de control en la maquinaria real. Dichas válvulas pueden desconectarse en cualquier orden. La primera es la VÁLVULA DE CONTROL PRINCIPAL, que se encuentra en la base de la gran chimenea vertical. A continuación, la VÁLVULA DE CONTROL DE COMBUSTIBLE se encuentra en la gran tubería que conecta los" },
		[356] = { file = "356", len = 28.395, text = "tanques de combustible (debe haber tres) con la chimenea. Finalmente, la VÁLVULA REGULADORA se encuentra en la parte inferior de los dos grandes tanques cilíndricos que se introducen en la chimenea. II. Indicadores de combustible Muestra la presión actual en los tanques de combustibles primario, secundario y terciario. III. Indicador de flujo Muestra la tasa de flujo actual dentro del sistema." },
		[357] = { file = "357", len = 16.588, text = "IV. Controles de flujo Aumentan o disminuyen las tasas de flujo. Es controlado automáticamente por el mecanismo de control del acelerador. V. Indicador de temperatura Muestra la temperatura operativa del sistema en general." },
		[361] = { file = "361", len = 35.082, text = "Maestro Delgren, Es como te temías. Tu teoría acerca de la Torre de Althalaxx ha resultado ser cierta. Se ha reunido un culto en la torre, incluyendo a muchos brujos, así como a un nauseabundo sátiro. Se llaman a sí mismos el Culto de la Facción Oscura. No puedo imaginarme qué vil propósito los ha reunido, pero me preocupa. Disculpa el carácter lacónico de esta carta, pero el peligro merodea en el bosque y solo puedo decir un par de palabras para describir la situación. Yo..." },
		[371] = { file = "371", len = 41.979, text = "L. F. ordenó incrementar la agresión contra los tontos de la Alianza. A continuación hay un listado de los materiales necesarios para una importante misión contra Costasur: raciones de viaje de 1 semana para 20 hombres 20 trajes de noche de color negro 20 pares de zapatos nuevos 25 espadas nuevas 30 cuchillos para lanzar 20 máscaras negras 10 viales de aceite inflamatorio 50 dosis de veneno paralizante 5 uniformes de guardia de Costasur robados, si están disponibles 100 monedas de plata Barón V. Intendente" },
		[372] = { file = "372", len = 22.309, text = "La Estrella de Xil'yeh Grel'borg el Avaro tiene la Estrella. Es un ogro avaricioso que pasa sus días en las montañas Alterac, en las Ruinas de Alterac, buscando adornos. La mayor parte de su colección es inútil, pero un objeto, la Estrella de Xil'yeh, tiene valiosas propiedades." },
		[373] = { file = "373", len = 36.728, text = "La Mano de Dagun Los textos antiguos afirman que las zarpas de Dagun excretan un veneno que no mata a sus presas, pero las hace mutar en algo distinto: un miembro de las razas antiguas. Su valor para nosotros está fuera de cuestión. Dagun vive en las profundidades del mar, pero es atraído regularmente por una tribu de múrlocs Ancalodos en el Marjal Revolcafango. Sus oráculos lo invocaron con un alga marina encantada. Si matas suficientes oráculos, podrás encontrar el alga. Luego, colócala en el altar múrloc y Dagun aparecerá." },
		[374] = { file = "374", len = 19.278, text = "El Corazón Heredado Mogh el Eterno es un médico brujo trol de Tuercespina. Posee el Corazón Heredado, del que se afirma que aquellos que desvelen sus secretos pueden sortear a la muerte. Encontrarás a Mogh en las Ruinas de Zul'Mamwe. Derrótalo, si puedes, y tráeme el Corazón Heredado." },
		[375] = { file = "375", len = 8.986, text = "Tráeme estos tres objetos: la Estrella, la Mano y el Corazón, y el Compendio de Yagyin será tuyo. G.B." },
		[376] = { file = "376", len = 26.462, text = "La Estrella de Xil'yeh Un ogro de Alterac, Grel'borg el Avaro, fue el último poseedor de esta gema, de la que se dice que transmite a su dueño la facultad de entrar en contacto con otros mundos. Hay fuentes que afirman que Grel'borg merodea en las Ruinas de Alterac en las montañas del mismo nombre, rebuscando mas reliquias entre los escombros y las basuras." },
		[377] = { file = "377", len = 24.372, text = "La Mano de Dagun Dagun es una criatura de aguas profundas, adorada por los múrlocs en el marjal Revolcafango. Las atraen a la superficie con un alga marina especial, encantada por sus chamanes. Atrapa a los múrlocs, recoge sus algas encantadas y luego colócalas sobre el altar de los múrlocs. Dagun aparecerá y te quedarás esperando. Quiero esa mano." },
		[378] = { file = "378", len = 22.1, text = "El Corazón Heredado Los viejos textos afirman que quien posea el Corazón Heredado no debe tener temor a la tumba. Tal vez esto sea cierto, ya que el dueño del corazón, el trol Mogh, es conocido como Mogh el Eterno. Mogh, médico brujo de la tribu Machacacráneos, habita en Tuercespina en las Ruinas de Zul'Mamwe." },
		[379] = { file = "379", len = 9.064, text = "Tráeme estos objetos: la Estrella, la Mano y el Corazón, y tendrás una copia del Compendio de Yagyin. El guardián" },
		[380] = { file = "380", len = 18.338, text = "Informe de Misiones de Mortacechador Agentes: Rane Yorick, Quinn Yorick, Erland McKree Misión Principal: Realizar un reconocimiento en el norte de los Argénteos, y determinar los niveles de amenaza de la vida silvestre y la Plaga." },
		[381] = { file = "381", len = 33.228, text = "Los agentes comenzaron sus investigaciones y descubrieron una importante presencia de huargos. Se recomienda enviar equipos de caza para eliminar el problema. Gnolls no muertos fueron encontrados en la granja de la zona llamada El Campo Muerto. La razón de su presencia aquí es desconocida, pero sus movimientos y acciones sugiere una acción militar inminente. Durante nuestras observaciones, ningún líder notable fue detectado entre los Gnoll. Se deduce que esperan la llegada de líderes o refuerzos." },
		[382] = { file = "382", len = 23.406, text = "Continuando la investigación, nuestros agentes fueron detenidos en la granja de Ivar. Ivar, la mayor parte de su familia y sirvientes sucumbieron a la Plaga y se convirtieron en sus esbirros. Nuestros agentes han sido atacados y, aunque se las arreglaron para derrotar a sus atacantes, algunos sufrieron graves heridas, en particular, el agente Quinn." },
		[383] = { file = "383", len = 19.696, text = "Adoptaron una posición defensiva en la vieja casa de Ivar, y mientras Rane hacía guardia, Erland continuó la misión de reconocimiento. Erland fue clavado por los huargos en un huerto del norte, y logró escapar con la ayuda de otro agente de Renegados. Este agente es el portador de este informe." },
		[386] = { file = "386", len = 27.899, text = "Cabe señalar que el portador de este informe no sólo desempeñó un papel decisivo en el éxito de nuestra misión, sino que también en la derrota de Ivar el Hediondo, el rescate de Erland, y la entrega de este informe. Hacemos llegar nuestra gratitud, y recomendar que el comando reconozca a este individuo otorgándole el premio acorde a su conducta meritoria, como demostró en el campo. Mortacechador Rane Yorick, Líder de la Misión" },
		[387] = { file = "387", len = 22.491, text = "Y así deambuló y continuó buscando. Y su brazo permaneció perdido. Y, mientras andaba, maldijo y rugió. Pero hace mucho tiempo que Gri'lek dejó de escuchar a los espíritus, y estos estaban airados y no querían atender sus maldiciones. Gri'lek estaba condenado. Condenado a vagar inerme." },
		[394] = { file = "394", len = 17.868, text = "Una fuerza maligna los creó, Se sienta cómodamente en la Cima Calígine, Se ríe de ti y de tu amigo, Sus elementales no tienen fin, Pronto deberás enfrentarte a este mago, Su furia solo se aplacará con la muerte." },
		[395] = { file = "395", len = 13.845, text = "El Santuario de Mel'Thandris \"Que la luz de Elune brille sobre este valle eterno e ilumine los caminos del bosque como ha ocurrido desde tiempo inmemorial.\"" },
		[396] = { file = "396", len = 35.944, text = "Elune ha atendido a mis deseos. Las vidas de mis camaradas caídos no habrán sido en vano, y vengaré sus muertes utilizando la Guadaña de Elune. Es un objeto antiguo, una rama torcida y nudosa que puede ser incluso más antigua que los kaldorei. Durante muchas horas he examinado la herramienta que me ha concedido la diosa. No es un arma ordinaria, esto está claro, ni se trata de un simple aditamento mágico. Con ella... incluso es posible traspasar las barreras del tiempo y el espacio. Con la Guadaña" },
		[397] = { file = "397", len = 36.362, text = "en mis manos, he tenido una visión del caos. Lobizones... los huargen... combatían contra un enemigo increíble. Los huargen luchaban salvajemente, como corresponde a su raza primitiva, pero su enemigo permanecía intacto: Los señores de la Llama Esmeralda. Y así fue como me di cuenta del verdadero poder de la Guadaña. Centrándome en ella, logré llegar a comunicarme con los huargen. Sin embargo, el contacto no se realizaba mediante lenguaje hablado. Era algo distinto... no podría describirlo. Lo que importa es que los huargen me oían" },
		[398] = { file = "398", len = 30.25, text = "y me entendían. Canalizando la energía hacia la Guadaña, las barreras se debilitaron aún más y pude traer huargen a nuestro mundo. En mi primer intento pude invocar a treinta. Me siguieron en la batalla y, con su fuerza bruta y bajo mis órdenes, arremetimos contra los demonios de Frondavil. Elune ha atendido a mis deseos. El bosque quedará libre de alimañas. Que Elune me conceda sus bendiciones hasta que logre terminar mi trabajo." },
		[399] = { file = "399", len = 31.713, text = "Todo marcha bien. He reunido a un gran número de huargen para que luchen a mi lado. Aunque son de pensamiento simple, han demostrado una impresionante habilidad para coordinar sus ataques y actúan muy bien en grupo. He identificado a los líderes de estos grupos. Los he organizado en pequeños grupos de guerreros. Atacamos el bosque desde varios lugares y mi campaña contra los demonios es bastante provechosa. Que Elune me conceda sus bendiciones hasta que logre terminar mi trabajo." },
		[400] = { file = "400", len = 29.153, text = "Un grupo se perdió. He enviado a los huargen a que recorran el bosque e identifiquen áreas infestadas por demonios, pero no han regresado. He empezado a preocuparme por los líderes, a los que encomendé el control. Tienen una mente simple y seguramente han llevado al extremo la escasa autoridad que les confié. ¿Estoy perdiendo el control? Tal vez debería dejar de invocar más huargen. Que Elune me conceda sus bendiciones hasta que logre terminar mi trabajo." },
		[401] = { file = "401", len = 31.138, text = "Aunque no he invocado nuevos huargen, su número continúa aumentando. La Guadaña ya no requiere mi intervención para el proceso de invocación. Esto resulta problemático. He reunido tantas manadas como pude encontrar y las he ordenado para que permanezcan en el Santuario de MelThandris. Mientras tanto, he buscado en las bibliotecas de Darnassus y he consultado con el Círculo de los Ancestros en Costa Oscura. No encontré ningún dato sobre los huargen. He escuchado informes," },
		[402] = { file = "402", len = 31.686, text = "murmullos, procedentes de un zahorí del Kirin Tor llamado Arugal. Según he oído, es posible que él también haya invocado huargen. Consultaré con este zahorí, a pesar de lo desagradable que pueda ser, y veré qué es lo que sabe. Los huargen son peligrosos y me gustaría tenerlos controlados. Mañana bajaré al puerto en los Baldíos y reservaré un pasaje para el nuevo mundo. Que Elune me conceda sus bendiciones hasta que logre terminar mi trabajo." },
		[403] = { file = "403", len = 28.918, text = "Comencé a escribir este diario para guardar notas acerca de mi investigación para ayudar a Vallefresno. Estos acontecimientos ocurridos no hace mucho están envueltos en misterio y, con suerte, podré desvelar algunos de ellos para así ayudar a mi gente. Empezaré comentando ciertos hechos para evitar olvidarlos más adelante. Me he dado cuenta de que los rumores acerca de los esfuerzos del zahorí Dartol son ciertos." },
		[404] = { file = "404", len = 39.915, text = "Si bien antes pensé que sería absurdo que un humano llegara a nuestras tierras y aprendiera nuestras costumbres, este zahorí, este hombre malvado, llegó aquí y no solo sobrevivió, sino que obtuvo parte de nuestra sabiduría. Todavía no sé bien cómo lo hizo... Durante mi investigación, no pude descubrir sus objetivos, pero su plan parecía simple: utilizando magia druídica, intentó primero hacerse amigo y luego controlar a los fúrbolgs. Si hubo un intento de causar daño a mis parientes o cualquier otro propósito malicioso, espero encontrar la explicación antes de acabar mis pesquisas." },
		[405] = { file = "405", len = 32.679, text = "Sin embargo, por lo visto había tenido algo de éxito al llevar a cabo sus planes. ¿Quería probar sus planes con los fúrbolgs antes de ponerlos en práctica con mi gente? ¿Tenían los fúrbolgs algo que él codiciaba? ¿Quién sabe? Usando un objeto que creó (una vara o bastón de algún tipo), intentó infiltrarse en las tribus de fúrbolg de Vallefresno. En algún momento, aquí los detalles aún no están claros, los fúrbolgs lo descubrieron mientras intentaba manipularlos para que actuaran los unos contra" },
		[406] = { file = "406", len = 35.526, text = "los otros. Como estoy seguro de que ocurriría con los elfos, los fúrbolgs estaban airados, pero reaccionaron con mucha mayor fuerza y mataron a Dartol. Los fúrbolgs, al menos en ese momento, no eran las mismas criaturas corruptas que llegaron a ser posteriormente. Entonces, aún eran racionales e inteligentes, y su relación con nuestra gente era amistosa. Tengo la esperanza de que si vuelvo a crear la vara con la ayuda de una dríade llamada Shael'dryn, podré utilizar su poder para ayudar a nuestra gente... y a los fúrbolgs." },
		[407] = { file = "407", len = 35.631, text = "No todos los fúrbolgs han sido corrompidos. Algunos aún viven en el bosque e intentan protegerlo. Durante el periodo en el que se corrompieron, algunos de los fúrbolgs huyeron, muchos fueron asesinados y otros fueron desterrados de sus tribus. Encontré a un venerable fúrbolg de la tribu Maderiza que vive encima del lago Mystral. Su nombre es Krolg. Estuve observándolo durante días y creo que, si me hubiera acercado a él disfrazado de fúrbolg, podría haberle ayudado y haber descubierto una forma de restablecer los lazos entre nuestros pueblos." },
		[408] = { file = "408", len = 29.179, text = "Además de matar a Dartol, los fúrbolgs dividieron la vara en tres partes para que nadie volviera a usarla en su contra. No ha sido fácil, pero creo saber dónde pueden estar. La gema La primera parte de la vara, una gema resplandeciente, fue oculta en un santuario en el noroeste de Vallefresno. Creo que ahora este santuario son las ruinas en el centro del Lago Falathim. Según las centinelas, ahora están invadidas por múrlocs." },
		[409] = { file = "409", len = 36.728, text = "Si no puedo localizar la gema oculta en el santuario, puede que se encuentre en posesión de uno de los múrlocs. El asta Esta parte de la vara fue confiada a los antárboles cerca de lo que hoy se conoce como Frondavil. Ni los fúrbolgs ni nosotros podríamos haber sospechado nunca que estas magníficas criaturas pudieran caer en las garras de la corrupción que asoló la tierra. Mis investigaciones indican que los guardianes conservan la pieza en un pequeño claro, dentro de un arcón. Para averiguar más detalles, tendré que hablar con Shael'dryn." },
		[410] = { file = "410", len = 15.386, text = "1. Toma uno u ocho hombres 2. Golpea al hombre con fuerza 3. Golpea más al hombre 4. Coloca al hombre en el fuego 5. Cómete al hombre" },
		[411] = { file = "411", len = 33.802, text = "Shael'dryn es una dríade que protege la Poza de la Luna al noreste del Lago Iris. Se niega a abandonar el bosque o a dejarlo caer en la corrupción. Sé que ella tiene el poder y los conocimientos necesarios para reparar la vara o, al menos, decirme cómo puedo hacerlo por mí mismo. El pomo Se entregó el pomo de la vara a los druidas de Dor'danil. No obstante, esto supone un problema importante: los druidas están muertos. Ahora, sus espíritus ocupan el área y ya no se muestran hospitalarios." },
		[412] = { file = "412", len = 35.187, text = "Puede que esto requiera más investigación. No estoy seguro de tener poder suficiente para luchar contra los espíritus de mis parientes muertos... Intentaré escarbar las profundidades de Dor’danil y encontrar el pomo. (Nota: Durante mis preparativos en Astranaar, me he encontrado recientemente con un enano cazador que pasó bastante tiempo en Vallefresno, intentando ayudar a mi gente. Procedía de un lugar llamado Ventormenta. Una noche estuvimos hablando, mientras tomábamos algunas cervezas, y sus relatos me han dado nuevas esperanzas de poder encontrar el pomo..." },
		[413] = { file = "413", len = 34.586, text = "Me dijo que recorrió todo Dor'danil y que nunca vio un cofre o cualquier otra clase de contenedor que pudiera albergar el pomo. Asimismo, me dijo que babosas en podredumbre habitaban el área y que devoraban prácticamente todo aquello más pequeño que ellas. Vio cómo se \"comían\" mesas, esculturas, osos ¡e incluso gnomos! Las babosas parecen obtener gran parte del alimento a partir de objetos mágicos. Si el cofre que contiene el pomo estuviera encantado, habría muchas posibilidades de que las babosas se hayan comido." },
		[414] = { file = "414", len = 15.517, text = "Se trata de un juego, pero en este momento no dispongo de otras pistas... Cuando averigüe más, lo escribiré en estas páginas, pero hasta entonces, intentaré localizar las partes de la vara y trataré de ayudar a Vallefresno." },
		[417] = { file = "417", len = 40.281, text = "Vale, deberás tener tus cargas NG-5 y tus detonadores preparados. Los he etiquetado para ti... El azul corresponde a la serrería. El rojo, a la mina Cortaviento. He reconocido un poco el terreno y he encontrado suficientes explosivos en el Risco Cortaviento, de manera que no debería ser un problema para ti llegar hasta allí, colocar los explosivos y marcharte antes de detonarlos. Recuerda, esto es una distracción. Aléjate de los carros antes de que los goblins vayan a ver qué ha ocurrido y luego escabúllete detrás de ellos." },
		[418] = { file = "418", len = 34.56, text = "Por cierto, ten cuidado con ellos. Basta el nitromirgliceronio para reducirte a polvo. He colocado parte del líquido en tubos de cobre para mantenerlo estable y seguro. He utilizado en las cajas del detonador el pergamino que te entregó Collin. Ahora, ellos enviarán un mensaje silencioso a las cargas NG-5 después de que las hayas preparado. He utilizado un sencillo mecanismo Stalthwargon para garantizar que la conductividad sea óptima y el flujo de nitromirgliceronio entre el fluido diferencial sea superior a la media." },
		[419] = { file = "419", len = 30.302, text = "Antes de que pueda volver a los detalles sobre mi diseño, déjame explicarte dónde debes colocar los explosivos. Plan A: la serrería. Hay un carro justo en frente de la serrería (está al noreste de la zona deforestada y del ensamblaje para el almacenamiento de la madera). Sospecho que los planes de ingeniería se encuentran dentro de la serrería. Para colocar la carga, dirígete a la parte trasera del carro. Una vez que esté colocada, date prisa y aléjate del lugar." },
		[420] = { file = "420", len = 31.477, text = "Cuando estés $Glisto:lista;, pulsa el detonador. Me he asegurado que haya una señal fuerte, canalizando cables de cobre y plata con un conjunto de antenas meltusianas bajo la cubierta de la caja. Esto debería garantizar que todo vaya perfectamente. Simplemente, ten cuidado de los goblins que estén cerca. Si te cogen con las manos en la masa, no creo que aprecien mucho mi creación. Ah, por si aún no lo tienes claro, trata de alejarte del carro cuando explote. Puede hacerte bastante daño." },
		[421] = { file = "421", len = 27.115, text = "Plan B: Mina Cortaviento: He visto que los goblins utilizan otro carro de explosivos situado al norte de la entrada de la mina. Creo que es un sitio bastante bueno para colocar una carga de NG-5 (roja). Una vez que hayas colocado la carga en la parte trasera del carro, toma distancia y pulsa el botón. Si los goblins no vienen corriendo a ver qué ha sucedido, probablemente es porque la montaña se les haya venido encima." },
		[422] = { file = "422", len = 28.552, text = "Las cartas de Ventura y Cía. están situadas fuera de la mina... Creo que están sobre unos cajones que están en el nivel inferior. Buena suerte... y recuerda... Carga azul: serrería Carga roja: mina Ah, y, una vez que hayas cumplido esta misión, destruye esta carta. Mmm, debería inventar un medio para que estas cosas se autodestruyan una vez leídas. No es mala idea..." },
		[424] = { file = "424", len = 34.116, text = "--Primer día: ¡Finalmente, mi viaje a Forjaz me ha traído hasta Kalimdor! El prospector Khazgorm de Bael Modan está haciendo grandes progresos. Hoy descubrió un fósil que los sabios del lugar consideran un trozo de hueso de un antiguo dios. Khazgorm tiene la certeza de que forma parte de un misterio mayor. Mientras supervisa la excavación, me ha encargado la tarea de descubrir los fósiles que unan la historia. Dirígete al sur en busca de más pistas." },
		[425] = { file = "425", len = 30.485, text = "--Segundo día: Las tierras de los Baldíos son extensas. Mi viaje ha sido largo y arduo y, hasta el momento, no ha producido nada de interés para la Liga de Expedicionarios. El único incidente notable tuvo lugar cerca del Camino de Oro. A la distancia, vi unas criaturas extrañas. Mitad cerdo, mitad humano. Rápidamente me escondí y vi pasar a las nauseabundas criaturas. ¡Menuda pestilencia dejaban al paso!" },
		[426] = { file = "426", len = 27.246, text = "--Tercer día: ¡Qué gran descubrimiento! Mientras exploraba, he descubierto algo fascinante: muchos restos de lo que parece haber sido una criatura semejante a un jabalí. Su cráneo era mucho más grande que yo. Cada diente de la bestia podría compararse a medio enano... a uno entero. De las tamañas dimensiones del descubrimiento, creo que puede tratarse de los restos de uno de los dioses antiguos." },
		[427] = { file = "427", len = 29.571, text = "De regreso en el puesto de mando de la Liga de Expedicionarios en Forjaz, recuerdo una conferencia que pronunció el arqueólogo jefe Mostachogris. En ella mencionó un dios de esta clase, que fue adorado por extraños elfos de Darnassus, debido a su supuesta naturaleza altruista. ¡Bah! Un momento. He oído cómo resoplaban fuera de la tienda. Seguramente, se trata de algunos jabalíes intentando coger las manzanas que tengo escondidas..." },
		[428] = { file = "428", len = 18.86, text = "--Cuarto día: ¡Capturado! Me han atacado hombres jabalí de la tribu Rajacieno. Creía que me iban a llevar a los grandes restos de jabalí del dios caído, pero bordearon los grandes fósiles y fueron directamente hacia el oeste de la calavera gigante, a través del Camino del Oro." },
		[429] = { file = "429", len = 20.689, text = "Me han arrastrado violentamente hasta un apestoso y espinado zarzal llamado Horado Rajacieno. Me han arrojado a una rústica cabaña y me han hecho prisionero junto con un elfo de la noche moribundo. No tengo otras posesiones salvo este diario, mi pluma y mi reloj de bolsillo... Alguien se acerca..." },
		[430] = { file = "430", len = 21.159, text = "--Quinto día: Mi compañero de celda, el elfo de la noche, sufre graves heridas. Los hombres jabalí le han pegado repetidamente y creo que a menos que una partida de rescate nos libre de este traicionero lugar, morirá en breve. Se desmaya a menudo. Cuando se despierta, intento darle de beber agua." },
		[431] = { file = "431", len = 38.87, text = "La última noche, fue capaz de hablar por primera vez. Es un druida, llamado Heralath, enviado a este lugar para verificar los rumores acerca de la existencia del dios jabalí caído. Con su débil voz, me contó que creía que la gran calavera de jabalí estaba situada en el lugar en el que el gran dios jabalí Agamaggan cayó combatiendo contra la Legión Ardiente hace unos 10000 años durante la Guerra de los Ancestros. Su voluminoso cuerpo quedó aplastado contra el suelo y su sangre penetró en la tierra. En el lugar bañado por su sangre crecieron retorcidos arbustos espinosos..." },
		[432] = { file = "432", len = 23.51, text = "Heralath y su gente intentaban descubrir la fuente de la corrupción de este sitio. Me dijo que se creía que Agamaggan era un dios puro. Ciertamente, la razón por la que estas hediondas criaturas y los malignos arbustos marcaban esta tierra es un misterio. Antes de que pudiera obtener más información, Heralath volvió a caer en su sueño intermitente..." },
		[433] = { file = "433", len = 28.264, text = "--Sexto día: El estado de Heralath empeora. Hoy, sus ojos solo se abrieron una vez. Habló con dolor, pero fue claro. Si escapo de mi condena aquí en Horado Rajacieno, Díscolo Falfindel, que está en Thalanaar, debe saber que Charga Filonavaja enardece seguidores al sur de Los Baldíos. Su poder aumenta a diario. Debemos detener a la Bruja antes de que la plaga de su corrupción se extienda del Horado." },
		[434] = { file = "434", len = 27.141, text = "El pobre Heralath tiene la palidez de un hueso. Su fiebre empeora por minutos. Mientras tanto, los hombres jabalí se están preparando para una gran acción militar. Me temo que si no intento escapar rápido, mi destino será el mismo que el de mi compañero de celda. Mi plan es escabullirme cuando los hombres jabalí partan a realizar su próxima batida. Mis guardianes son perezosos y, a menudo, duermen en sus turnos." },
		[435] = { file = "435", len = 23.327, text = "Una vez que me escape del Horado, iré hacia las Mil Agujas y, a continuación, hacia Thalanaar, en los confines del misterioso bosque de Feralas. Allí buscaré al druida llamado Díscolo Falfindel. Lo que comenzó como un intento de explorar el pasado de mi gente se ha convertido en algo mucho más grande. La protección de la Alianza está en mis manos..." },
		[436] = { file = "436", len = 22.7, text = "NÚMERO DE ENCARGO: 45TK-3 COMPRADOR: Kravel Karbarbán FACTURA: Carraca hidráulica (3) Pernos de repetición (50) 30\" tubos de cobre calibre 20 (12) Tabaco marca Furiahonda (1) Prismas de alta graduación (3)" },
		[437] = { file = "437", len = 21.42, text = "te debería entregar este mensaje en mano, pero debo irme, no sea que me pierda algún acontecimiento de gran importancia. Si deseas saber más acerca de mis observaciones sobre la torre de Althalaxx, $gel portador:la portadora; de este mensaje me ha servido de gran ayuda y creo que se puede confiar en $gél:ella;. A toda prisa, Balthule Golpesombra" },
		[438] = { file = "438", len = 31.033, text = "El goblin Nazz Vaporio es realmente el hijo de un príncipe mercante goblin (¿Qué príncipe? El precio de esta información es alto). Parece que le gusta mucho más gastar el dinero que ha hecho su familia que ganarlo por sí mismo. Así que ha robado una pequeña fortuna del tesoro familiar y ahora se oculta en el Desierto de Sal. Si su padre supiera dónde está, seguro que iría a buscarlo y lo volvería a llevar a casa... castigándolo por su insolencia." },
		[439] = { file = "439", len = 33.071, text = "Sr. Pinchabujas: $GEl portador:La portadora; de esta carta y yo mismo estamos montando un negocio conjunto en el que nos gustaría que participaras. Como bien sabes, he pasado mucho tiempo en el Desierto de Sal (el negocio mencionado anteriormente está relacionado con las carreras que se organizan en este desierto. Si te interesan las carreras y, para ser más específicos, apostar a ellas, querrás continuar leyendo, ya que creo que tus conocimientos sobre Tuercespina serían muy útiles en nuestro negocio." },
		[440] = { file = "440", len = 31.451, text = "Sr. Pinchabujas: La bebida que entregaste a mi socio ha tenido un gran éxito. No solo se trata de una bebida fuerte, que adormece los sentidos, sino que parece tener cierta cualidad adictiva. Estoy seguro de que los que la han probado querrán repetir. Estamos en deuda contigo, Loquillo. Te invito a venir al Desierto de Sal, o a alguien de tu confianza, para aprovechar las nuevas oportunidades en relación con el juego. Kravel" },
		[441] = { file = "441", len = 32.287, text = "Mi buen Martek: Estoy en un problema y necesito tu ayuda. Mi hermano y yo estamos intentando organizar una carrera de coches y necesitamos pistones robustos. Nada de lo que hemos probado es lo suficientemente resistente. Nada soporta la velocidad de nuestro nuevo coche. De esta manera, ¡el motor se rompe constantemente! Eres un gran experto trabajando el metal. Debes ayudarnos. Eres el único que puede hacerlo." },
		[442] = { file = "442", len = 35.239, text = "Para enfrentarte a Faucehielo, debes atraerlo con la carne de su presa favorita. Dirígete a las montañas de Alterac en Azeroth y caza un león de montaña de gran tamaño. Mátalo y luego lleva su cuerpo a la Caverna Estrecha, un lugar que los bestiales wendigo consideran sagrado. Coloca el cuerpo sobre la Llama de Uzel para que el olor de la carne quemada se disperse en el aire, hacia el exterior de la caverna. Comprobarás que, transcurrido un tiempo, Faucehielo vendrá." },
		[443] = { file = "443", len = 35.291, text = "No deja de maravillarme lo útil que resulta el odio para que los demás cedan a tus deseos. Los orcos y los trols fueron los más fáciles de engañar, ya que su odio a la Alianza los convierte en serviles sujetos de la Facción Oscura. ¿Acaso tienen idea del poder superior al que sirven? Ese paladín exasperante, Delgren el Purificador, se ha estado metiendo en nuestros asuntos del bosque de Vallefresno, mientras que su lacayo, Balthule, espía mi torre, creyendo que no me percato de su presencia. Delgren nos considera" },
		[444] = { file = "444", len = 24.921, text = "una amenaza menor, tal vez otro culto a la muerte. No sabe que somos nada más y nada menos que... una de las facciones del Consejo de la Sombra. Cuando era niño, me hablaron de un insecto cuya picadura era mortal, pero cuyo aspecto era el de una simple mosca, un puntito difícil de reconocer. Son las cosas que subestimas las que más te hieren, si dejas que la herida se encone." },
		[445] = { file = "445", len = 32.679, text = "Los coches cohete que compiten por los desiertos han sido preparados y requieren bastante mantenimiento. Por eso no debe sorprender que haya equipos de boxes por todas partes. Estos equipos comprueban constantemente el estado de sus coches y efectúan reparaciones y modificaciones cuando es necesario. Es la única manera de que los coches alcancen el máximo rendimiento. Por esta razón, buscamos la manera de provocar algún fallo en las maniobras del equipo de boxes para que el coche se averíe rápidamente." },
		[446] = { file = "446", len = 27.272, text = "Si somos capaces de controlar qué coche está en plena forma y cuál no, entonces... No tengo que explicarte las ventajas que esto nos proporciona en el juego. Por eso, Pinchabujas, necesitamos que nos proporciones algo para hacer que el equipo de boxes cometa fallos. ¿Hay en Tuercespina alguna planta, hierba o bebida que pueda usarse para trastocar la mente de los gnomos y los goblins? K. Karbarbán" },
		[447] = { file = "447", len = 31.869, text = "He investigado a fondo a los Aspectos y a sus creadores titanes, profundizando en lo que a un humano le llevaría toda la vida. Había cinco Aspectos cuando los titanes dejaron este mundo; se trataba de poderosos dragones cuyo cometido era proteger el mundo de Azeroth. Sus historias son extensas y variadas y, aún hoy, a pesar de toda la información que he recogido, sé que tengo mucho que aprender sobre estas magníficas criaturas." },
		[448] = { file = "448", len = 34.22, text = "Boticario Lydon, Espero que esta carta os llegue rápidamente y que su portador se encuentre sano y salvo. En el lejano Kalimdor han tenido lugar ciertos acontecimientos que hacen que requiramos de tus servicios. Seré breve. Hay una crisis en la Sierra Espolón, cerca de Mulgore, tierra natal de los aliados tauren. La empresa goblin Ventura y Cía está extrayendo todo el mineral y talando toda la vegetación en aquellas montañas, enfureciendo a los espíritus de la montaña." },
		[449] = { file = "449", len = 33.776, text = "Imagino que la conmoción que estos espíritus les causan a través de los chamanes y druidas tauren los distraen. Y es que los tauren consideran la presencia de Ventura y Cía. en la Sierra Espolón una seria amenaza. Tanto si son una amenaza como si no lo son, debemos ayudar a nuestros aliados. Lydon, posees un vasto conocimiento sobre toxinas. ¿Podrías crear una que pudiéramos usar para extender una plaga entre los goblins en la Sierra Espolón? Recibe un sabio saludo, P. Zamah" },
		[450] = { file = "450", len = 31.295, text = "Gran parte del conocimiento que poseo ahora no lo habría podido adquirir por mi cuenta. Por esta razón, siento una infinita gratitud hacia los elfos de la noche. Ahora conozco muchísimos detalles exclusivamente gracias a su ayuda. Como resultado de nuestra relación, tengo la impresión de que sus orígenes guardan un vínculo mucho más estrecho con los Aspectos que lo que creía inicialmente. No obstante, guardan sus secretos con tanto celo, que incluso a mí me ocultan toda la verdad." },
		[451] = { file = "451", len = 15.203, text = "Todos mis conocimientos sobre los Aspectos los comparto aquí para que sirvan como referencia en el futuro. Sé que serán de extrema utilidad, pues presiento que los dragones tendrán un impacto mucho mayor en el mundo con el paso del tiempo." },
		[452] = { file = "452", len = 26.122, text = "Alexstrasza: Alexstrasza fue la antigua y poderosa Reina de los Dragones, llamada la Protectora por los titanes. Fue la primera en ser creada por los titanes para proteger el mundo tras su partida. Se dice que presenció el nacimiento de todas las razas modernas en toda la faz de Azeroth. Su Vuelo Rojo, conocido por su orgulloso comportamiento, gobernó antiguamente sobre las demás especies de dragones." },
		[453] = { file = "453", len = 13.113, text = "Corrían ciertos rumores entre los elfos de la noche que sugerían que a Alexstrasza y al semidiós Cenarius los unía una fuerte amistad, y que fue él quien la llamó durante la primera invasión de la Legión Ardiente." },
		[454] = { file = "454", len = 25.913, text = "Ysera: Ysera, la Soñadora, representa el subconsciente de los mortales. Es ella quien induce al Sueño Esmeralda. Aunque aprecia la imaginación y la creatividad, aprobando la ambición de las razas mortales, ella y su Vuelo consideran el mundo real como una mera ilusión. Ysera es una de las criaturas más agraciadas y poderosas que cualquier mortal haya podido contemplar." },
		[455] = { file = "455", len = 27.324, text = "Malygos: Malygos se conoce como Administrador de la Magia o Tejedor de Hechizos. Su aspecto natural no es el de un dragón al uso y se dice que puede cambiar de forma a voluntad. Se le ha visto muy pocas veces tras su retiro en el extremo norte y casi siempre guarda la apariencia de una suerte de insecto, pero cuando adquiere forma de dragón, él y sus vástagos se distinguen por ser de color azul, en toda su gama." },
		[456] = { file = "456", len = 31.504, text = "Nozdormu: Nozdormu se conoce como Maestro del Tiempo o el Atemporal. Él y su escuadrilla tienen una tonalidad broncínea y son muy astutos. Nozdormu siempre se ha interesado en coleccionar artefactos del pasado, ya que poco le importa la realidad de las razas mortales o incluso los asuntos de sus compañeros, los Aspectos. Sin embargo, su indiferencia hacia los asuntos políticos de los demás no supone displicencia frente a lo que ocurre en el resto del mundo." },
		[457] = { file = "457", len = 27.429, text = "Considerados protectores, el Vuelo Bronce siente una fuerte atracción por ciertos aspectos de la civilización. El dragón y su escuadrilla son muy pacientes por naturaleza y se basan siempre en la observación, por lo que, antes de apresurarse, actúan siguiendo un plan. Nozdormu siempre intentará proteger el fluir del tiempo y a las razas mortales cuando se vean amenazadas por enemigos más poderosos." },
		[458] = { file = "458", len = 35.579, text = "Neltharion: Neltharion, llamado, tras su creación, el Guardián de la Tierra, fue el Aspecto más leal y protector de Azeroth. Su Vuelo Negro fue el responsable de la creación de las montañas y otras formaciones rocosas, incluyendo las fronteras entre las razas mortales. Qué provocó su descomposición sigue siendo un misterio, ciertamente, se desconoce si fue una influencia externa o algo que se corrompió en su interior. Me pregunto si tal vez los dioses antiguos no tuvieron que ver con la corrupción del gran dragón negro." },
		[507] = { file = "507", len = 29.388, text = "--Decimotercer día Ha aumentado la actividad de las tropas cerca de Theramore. Muchos humanos abandonaron la ciudad y se trasladaron al oeste. --Decimocuarto día Más tropas abandonan la ciudad. Seguí a un pequeño grupo y vi cómo se quitaban los uniformes. ¿Desertores? --Decimoquinto día Oí a unos soldados de Theramore hablar hoy de guardias desertores. Mis sospechas deben ser verdad." },
		[527] = { file = "527", len = 30.041, text = "El Gorrión Sangrante: Manifiesto (20) barriles de ron. Destino: Theramore (50) sacos de harina. Destino: Theramore (2) cajas de herramientas gnómicas variadas. Destino: Trinquete (30) rollos de paño de algodón. Destino: Theramore (4) cajas de especias. Destino: Theramore (3) pasajeros. Destino: Theramore" },
		[528] = { file = "528", len = 36.18, text = "Jorgen, Mis temores se han materializado: han actuado de un modo del que no los creía capaces. Jamás pensé que pudieran llegar tan cerca, y lo han hecho. Te pido ayuda para el portador de esta nota y que lo envíes hacia ÉL. Honestamente, dada la gravedad de este asunto, creo que nos ayudará. Si se tratara de cualquier otro peligro, probablemente continuaría ignorándonos, desdeñando los problemas de nuestra bella ciudad. Gracias, viejo pescador. Siempre estaré en deuda contigo. Tu amigo, DeLavey" },
		[548] = { file = "548", len = 24.085, text = "--Decimosexto día Uleg y Thargil regresaron de su misión al puerto de Theramore. Vieron un nuevo barco en el puerto: el Gorrión Sangrante. El barco partió de Menethil en Azeroth. Mañana, Uleg y Thargil regresarán al puerto y se colarán en el barco. Creen que hallarán documentos políticos que revelarán la relación entre Theramore y la Alianza." },
		[572] = { file = "572", len = 24.451, text = "Con el éxito de Kel'Thuzad en Lordaeron, el Rey Exánime realizó los preparativos finales para asaltar la civilización humana. Tras volcar su energía corrupta sobre diversos artefactos portátiles llamados calderas de peste, Ner'zhul ordenó a Kel'Thuzad que llevara las calderas a Lordaeron, ocultándolas en varios poblados leales." },
		[573] = { file = "573", len = 27.585, text = "Las calderas, protegidas por cultores seguidores, actuarían como generadores de peste, dispersándola a través de los indefensos campos y ciudades del norte de Lordaeron. El plan del Rey Exánime funcionó perfectamente. Muchos poblados del norte de Lordaeron se contaminaron casi de inmediato. Como ocurrió en Rasganorte, los ciudadanos que contrajeron la peste murieron y renacieron como esclavos voluntarios." },
		[574] = { file = "574", len = 27.925, text = "Los seguidores de Kel'Thuzad deseaban morir para renacer al servicio del señor de las tinieblas. Se regocijaban ante la perspectiva de la inmortalidad de los no-muertos. Con la propagación de la peste, cada vez más zombis ferales se alzaron en las tierras del norte. Kel'Thuzad observó el ejército del Rey Exánime y lo nombró la Plaga, pues pronto marcharía hasta las puertas de Lordaeron... borrando a la humanidad de la faz del mundo." },
		[575] = { file = "575", len = 31.869, text = "Nadie sabe exactamente cómo se originó el universo. Algunos conjeturan que una terrible explosión cósmica lanzó hacia la vasta inmensidad de la Gran Oscuridad mundos infinitos que giraron en órbita, mundos que posteriormente albergarían diversas formas de vida, extraordinarias y terribles a la vez. Otros creen que el universo, tal como existe hoy, fue creado como un todo por una entidad singular y todopoderosa." },
		[576] = { file = "576", len = 33.228, text = "Si bien los orígenes exactos del caótico universo siguen sin esclarecerse, existe la certeza sobre el nacimiento de una raza de seres poderosos que puso orden en los mundos, para garantizar un futuro seguro para las criaturas que seguirían sus pasos. Los titanes, dioses colosales de piel metálica procedentes de los confines del cosmos, llegaron hasta aquí y empezaron a ocuparse de los planetas que encontraron. Configuraron estos espacios, levantando poderosas montañas y formando vastos océanos." },
		[577] = { file = "577", len = 29.727, text = "Originaron cielos y atmósferas tormentosas, siguiendo un plan insondable para crear orden a partir del caos. Incluso otorgaron poderes a las razas primitivas para que se ocuparan de sus trabajos y mantuvieran la integridad de sus respectivos universos. Los titanes, gobernados por una secta de élite conocida como Panteón, llevaron el orden a cientos de millones de mundos diseminados por la Gran Oscuridad del Más Allá durante los primeros años de la creación." },
		[578] = { file = "578", len = 29.78, text = "El benevolente Panteón, con la intención de salvaguardar las estructuradas sociedades de estas razas, estaba siempre atento a la amenaza de seres malignos y extradimensionales de El Vacío Abisal. El Vacío Abisal, una dimensión etérea de magia caótica que interconectaba miríadas de planetas, albergaba un número infinito de seres malignos y demoníacos cuya única finalidad era destruir la vida y agotar las energías del universo viviente." },
		[579] = { file = "579", len = 17.842, text = "--Décimoséptimo día Uleg ha vuelto de su misión. Falló y Thargil fue capturado. Envié a Uleg a entregar este informe a Nazeer. Me quedaré aquí. Ha aumentado la actividad naval en la costa de Theramore. Seguiré vigilando e informaré de cualquier novedad." },
		[580] = { file = "580", len = 29.571, text = "¡Nuestro primer plan ya ha fracasado! Puño tuvo éxito al cambiar los turnos de los guardias que patrullaban los túneles esa noche, pero debido a movimientos imprevistos de ciertos ciudadanos de Ventormenta, nuestro objetivo pudo escapar del lugar antes de que pudiéramos capturarlo. No obstante, esto ya lo habíamos previsto. El plan B ya estaba en marcha incluso antes de realizar nuestra emboscada en Ventormenta." },
		[581] = { file = "581", len = 16.144, text = "Este plan es igualmente sencillo, pero requiere más paciencia. Ya hemos pagado a nuestro hombre en Menethil por este trabajo y lo ha llevado a cabo de forma brillante. Una vez que hallamos zarpado, no debería existir ningún problema en la captura de nuestro objetivo." },
		[582] = { file = "582", len = 26.749, text = "El ataque está previsto a unos cuantos kilómetros de su destino. Allí es donde nuestros \"aliados\" estarán esperando. No sé por qué nos hemos visto obligados a formar una alianza con las criaturas, pero no dejo de pensar que nos están coaccionando. En última instancia, no importa. ¡Siempre que el objetivo esté bajo nuestra custodia, habremos iniciado el proceso de recuperación de Ventormenta de las manos de quienes nos la robaron!" },
		[607] = { file = "607", len = 20.558, text = "Maestro Barbalarga Como podrás saber, los Pico Tormenta sabemos apreciar lo bueno y la calidad de tus escudos es famosa entre nosotros. Por ello, es un placer para mí encomendarte la fabricación de un escudo. He incluido las especificaciones en la siguiente página:" },
		[627] = { file = "627", len = 36.075, text = "La devastadora Segunda Guerra contra la horda orca dejó la Alianza de Lordaeron en un estado de desolación y confusión. Los sanguinarios orcos, dirigidos por el poderoso Jefe de Guerra Orgrim Martillo Maldito, no solo destrozaron todo lo que encontraron a su paso en las tierras de Khaz Modan, en poder de los enanos, sino que también arrasaron muchas provincias centrales de Lordaeron. Los orcos implacables llegaron a arrasar el remoto reino elfo de Quel’Thalas antes de que les pararan los pies." },
		[628] = { file = "628", len = 34.612, text = "Los ejércitos de la Alianza, dirigidos por Sir Anduin Lothar, Uther el Iluminado y el almirante Valiente, expulsaron a los orcos hacia el sur, hasta la tierra desolada de Azeroth, el primer reino que cayó ante el ataque despiadado de los orcos. Las fuerzas de la Alianza, bajo las órdenes de Sir Lothar, lograron expulsar a los clanes de Martillo Maldito de Lordaeron, confinándolos en las tierras de Azeroth controladas por los orcos. Las fuerzas de Lothar rodearon la ciudadela volcánica de la Cumbre de Roca Negra y sitiaron sus defensas." },
		[629] = { file = "629", len = 30.354, text = "En su encarnizada defensa, Martillo Maldito y sus lugartenientes llevaron a cabo una audaz ofensiva desde la Cumbre y combatieron a los paladines de Lothar en el centro de las Estepas Ardientes. Martillo Maldito y Lothar se enzarzaron en una titánica batalla que dejó a los dos poderosos combatientes apaleados y exhaustos. Si bien por poco Martillo Maldito derrota a Lothar, la muerte del gran héroe no tuvo el efecto que el Jefe de Guerra habría deseado." },
		[630] = { file = "630", len = 24.686, text = "Turalyon, el lugarteniente más leal de Lothar, cogió el escudo de este manchado de sangre y convocó a sus hermanos apesadumbrados para emprender un atroz contraataque. Bajo los raídos estandartes de Lordaeron y Azeroth, las tropas de Turalyon masacraron a casi todas las fuerzas restantes de Martillo Maldito, sometiéndolas a una gloriosa, pero terrible derrota." },
		[631] = { file = "631", len = 32.496, text = "Para los andrajosos y dispersos supervivientes orcos no quedaba otra opción que escapar al último bastión de las fuerzas orcas: el Portal Oscuro. Turalyon y sus guerreros persiguieron a los orcos supervivientes por el inmundo Pantano de las Penas, hasta Las Tierras Devastadas corruptas en las que se hallaba el Portal Oscuro. Allí, junto al colosal portal, la horda destrozada y la inquebrantable Alianza se enfrentaron en lo que sería la última y más sangrienta batalla de la Segunda Guerra." },
		[632] = { file = "632", len = 20.767, text = "Inferiores en número y enloquecidos por la maldición de su sed de sangre, los orcos sucumbieron inevitablemente a la ira de la Alianza. A Martillo Maldito lo hicieron prisionero y lo escoltaron hasta Lordaeron, mientras sus clanes rotos fueron acorralados y expulsados al norte, de nuevo en Lordaeron." },
		[633] = { file = "633", len = 32.131, text = "Unos pocos meses tras el final de la batalla de Nethergarde, las fuerzas del Portal Oscuro se unieron y abrieron una nueva entrada a Draenor. Los clanes orcos restantes, bajo el mando del anciano chamán Ner’zhul, volvieron a atacar Azeroth. En el intento de robar ciertos artefactos mágicos que aumentarían el poder de Ner'zhul, los orcos planearon abrir nuevos portales en Draenor que les permitieran escapar a su mundo maldito para siempre." },
		[634] = { file = "634", len = 31.425, text = "Convencidos de que Ner'zhul estaban planeando una nueva ofensiva contra la Alianza, el rey Terenas de Lordaeron envió sus tropas a Draenor para acabar con la amenaza orca de una vez por todas. Bajo las órdenes de Khadgar y el general Turalyon, las fuerzas de la Alianza pelearon contra los orcos en las tierras ardientes. Aun con la ayuda de la élfica capitana forestal Alleria, el enano Kurdran y el Soldado veterano Danath, Khadgar no pudo evitar que Ner'zhul abriera sus portales a otros mundos." },
		[635] = { file = "635", len = 34.325, text = "Las terribles tormentas mágicas causadas por las energías convergentes de los portales empezaron a destruir el mundo, ya devastado. Ner'zhul, seguido de sus más fieles siervos, logró escapar a través de uno de los portales, mientras Khadgar luchaba desesperadamente para devolver a sus compañeros a Azeroth. Ante la certeza de que estaban atrapados en el mundo agonizante, Khadgar y sus compañeros decidieron destruir el Portal Oscuro para evitar que Azeroth fuera destruido por el violento ataque de Draenor." },
		[636] = { file = "636", len = 11.912, text = "Según cuentan todos, los héroes lograron destruir el portal y salvar a Azeroth, pero tanto si escaparon como si no, el terrible final de Draenor resulta evidente." },
		[637] = { file = "637", len = 31.687, text = "Diez mil años antes de que los orcos y los humanos se enfrentaran en la Primera Guerra, el mundo de Azeroth era un vasto continente rodeado por mares infinitos. Aquella masa de tierra, conocida como Kalimdor, albergaba numerosas razas y criaturas dispares, pugnando por sobrevivir entre los salvajes elementos del mundo naciente. En el centro del continente oscuro había un lago misterioso de energías incandescentes." },
		[638] = { file = "638", len = 32.888, text = "El lago, conocido posteriormente como el Pozo de la Eternidad, fue el corazón de la magia y de los poderes naturales del mundo: Absorbiendo la energía de la Gran Oscuridad infinita del más allá, el Pozo actuaba como fuente mística, lanzando sus poderosos flujos por todo el espacio, diseminando la vida en todas sus formas, variadas y sorprendentes. A través del tiempo, una tribu primitiva de humanoides nocturnos llegó cautelosamente hasta los confines del fascinante lago encantado." },
		[639] = { file = "639", len = 32.679, text = "Los nómadas humanoides ferales, atraídos por las extrañas energías del Pozo, fabricaron rudimentarias casas junto a sus serenas orillas. Con el paso del tiempo, el poder cósmico del Pozo afectó a la extraña tribu, haciéndola fuerte, sabia y prácticamente inmortal. La tribu adoptó el nombre de kaldorei, que en su lengua significaba \"hijos de las estrellas\". Para celebrar el nacimiento de su sociedad, construyeron magníficas estructuras y templos en la periferia del lago." },
		[640] = { file = "640", len = 34.926, text = "Los kaldorei, o elfos de la noche, tal como se les conoció posteriormente, adoraban a la diosa de la luna Elune, convencidos de que, durante el día, dormía en las refulgentes profundidades del Pozo. Los antiguos sacerdotes y videntes de los elfos de la noche estudiaron el Pozo con insaciable curiosidad, dedicándose a desentrañar sus insondables secretos y poderes. A medida que su sociedad prosperó, los elfos de la noche exploraron las tierras de Kalimdor y descubrieron a sus innumerables moradores." },
		[641] = { file = "641", len = 23.797, text = "Las únicas criaturas que les dieron tregua fueron los antiguos y poderosos dragones. Aunque las enormes bestias serpenteantes solían recluirse, ayudaban en gran medida a proteger las tierras conocidas de potenciales enemigos. Los elfos de la noche creían que los dragones se consideraban los protectores del mundo y que era mejor dejarlos solos con sus secretos." },
		[642] = { file = "642", len = 32.157, text = "Con el tiempo, la curiosidad de los elfos de la noche les condujo a conocer y entablar amistad con diversos seres poderosos, entre los cuales estaba Cenarius, un semidiós de los bosques primigenios. El benévolo Cenarius simpatizaba con los inquisitivos elfos de la noche y pasaba largas horas instruyéndolos en el conocimiento del mundo natural. Los serenos kaldorei desarrollaron una fuerte empatía por los bosques vivientes de Kalimdor y se deleitaban en el armonioso equilibrio de la naturaleza." },
		[643] = { file = "643", len = 28.029, text = "Sin embargo, con el paso del tiempo, que parecía eterno, la civilización de los elfos de la noche se expandió territorial y culturalmente. Sus templos, caminos y viviendas poblaban la totalidad del continente oscuro. Azshara, la bella e inteligente reina de los elfos de la noche, construyó un magnífico e inmenso palacio a la orilla del Pozo, en el que habitaba su servidumbre selecta, rodeada de fastuosas riquezas." },
		[644] = { file = "644", len = 30.851, text = "La selecta servidumbre, llamada Quel'dorei o nobleza, estaba al servicio de la reina y se consideraba superior al resto de sus hermanos de casta inferior. Si bien la reina Azshara era amada por todos sus súbditos, la nobleza era odiada en secreto por las masas envidiosas. Azshara, que compartía con los sacerdotes la curiosidad por conocer los secretos del Pozo de la Eternidad, ordenó a la educada nobleza que desentrañara sus misterios y los difundieran por todas partes." },
		[645] = { file = "645", len = 28.264, text = "Los nobles se enfrascaron en su trabajo y estudiaron el Pozo incansablemente. Con el tiempo, desarrollaron la habilidad de manejar y controlar las energías cósmicas del Pozo. A medida que sus insensatos experimentos avanzaron, los miembros de la nobleza advirtieron que podían usar sus nuevos poderes para crear o destruir a voluntad. Los desafortunados nobles se tropezaron con la magia primitiva y habían resuelto dominarla." },
		[646] = { file = "646", len = 28.317, text = "Si bien sabían que, si se manipulaba irresponsablemente, la magia era inherentemente peligrosa, Azshara y sus nobles empezaron a practicar sus hechizos con imprudente abandono. Cenarius y muchos de los viejos y eruditos elfos de la noche advirtieron que jugar con las volátiles artes del encantamiento solo podría traer la ruina. Pero Azshara y sus seguidores continuaron extendiendo tenazmente sus incipientes poderes." },
		[647] = { file = "647", len = 26.723, text = "A medida que sus poderes crecieron, se produjo un cambio evidente en Azshara y los nobles. Los altivos y distantes aristócratas se volvieron cada vez más insensibles y crueles con los demás elfos de la noche. Un oscuro y perturbador manto envolvió la otrora fascinante belleza de Azshara. Se distanció de sus súbditos más cercanos y se negó a tratar con nadie que no fuera sus fieles sacerdotes aristócratas." },
		[648] = { file = "648", len = 23.536, text = "Un joven y audaz estudiante llamado Furion Tempestira, que había dedicado gran parte del tiempo al estudio de los efectos del Pozo, empezó a sospechar que un terrible poder estaba corrompiendo a los nobles y a su amada reina. Si bien consideraba inconcebible el mal que los acechaba, sabía que las vidas de los elfos de la noche pronto cambiarían para siempre..." },
		[649] = { file = "649", len = 21.368, text = "-Totalmente redondo, cubre toda el área, desde el puño hasta el codo. -Clavos en los bordes. Pieza de plata. -Un clavo grande de plata en el centro, con un ancho de tres dedos. Pieza de plata. -De roble, reforzado con hierro. Mi nombre, Gringer Pico Tormenta, grabado en el borde superior." },
		[650] = { file = "650", len = 15.386, text = "El pago se realizará por los medios habituales. Abona al portador de esta petición una remuneración estándar por la entrega. Puedes cargarlo en el precio del escudo. Un cordial saludo y muchas gracias, --Gringer Pico Tormenta" },
		[669] = { file = "669", len = 23.902, text = "La llegada de los no-muertos a Azeroth no se produjo inicialmente con la corrupción del príncipe Arthas, sino mucho antes de aquel acontecimiento. Los hechos que provocaron la caída de Lordaeron se desencadenaron mucho antes de ese momento: con la llegada de los clanes orcos y la Legión Ardiente." },
		[670] = { file = "670", len = 26.932, text = "Los orcos de Draenor (el mundo del que procedían originalmente) eran nobles y chamánicos. Eran poderosos guerreros, corpulentos y de férrea voluntad. Esta era la razón por la que la Legión Ardiente los buscaba. Kil'jaeden, un demonio de gran poder en la Legión, deseaba someter a los clanes orcos y usarlos como escudo contra los mundos que la Legión Ardiente pretendía conquistar." },
		[671] = { file = "671", len = 22.282, text = "Kil'jaeden se dirigió al líder de los clanes, un poderoso chamán llamado Ner'zhul. Prometió transmitirle a Ner'zhul infinitos poderes místicos y conocimientos ocultos si hacía un pacto con el demonio capaz de someter a los clanes de la Legión Ardiente. Este pacto no solo selló para siempre su destino, sino el de todo su mundo." },
		[672] = { file = "672", len = 19.827, text = "El tiempo transcurrió y Ner'zhul se dio cuenta de que el destino de los clanes estaba en manos de la Legión Ardiente, por lo que el chamán orco empezó a desafiar a Kil'jaeden. El demonio, disgustado con Ner'zhul, se dirigió a Gul'dan, el propio aprendiz del chamán, mucho más propenso a la corrupción que Ner'zhul." },
		[673] = { file = "673", len = 27.559, text = "De hecho, fue Gul'dan el responsable del declive del chamanismo entre los clanes. Las promesas de poder y control sobre el enemigo hicieron sus ofertas aún más tentadoras. Con la ayuda de Kil'jaeden, Gul'dan empezó a manipular a los clanes. Los orcos, otrora nobles, se convirtieron en bestias salvajes y corruptas. Con sangre demoníaca inoculada en sus cuerpos, los orcos fueron mucho más despiadados y bárbaros." },
		[674] = { file = "674", len = 30.798, text = "Aunque Kil'jaeden había corrompido a Gul'dan tras fracasar con Ner'zhul, odiaba al chamán, por lo que juró respetar su pacto original. Kil'jaeden capturó a Ner'zhul y sometió al chamán a una tortura física increíblemente lenta. Mientras Ner'zhul suplicaba que lo matasen, Kil'jaeden le recordó que su pacto original seguía vigente. Kil'jaeden mató al orco, pero solo físicamente. Kil'jaeden capturó el espíritu del chamán orco antes de que partiera al Vacío Abisal." },
		[675] = { file = "675", len = 18.651, text = "Encerró el espíritu de Ner'zhul en un bloque de hielo procedente de El Vacío Abisal. Atrapado en el hielo, infundió aún más poder al témpano. La pérdida de su cuerpo físico y la absorción de aquel increíble poder marcaron el inicio de la transformación de Ner'zhul." },
		[676] = { file = "676", len = 23.719, text = "Kil'jaeden arrojó el bloque de hielo a través de múltiples dimensiones hasta Azeroth, aterrizando en el continente de Rasganorte e implantando su inmensa maldad en nuestro mundo. Ner'zhul se había ido para siempre, dejando tras de sí un trono de hielo y odio. El antaño respetado líder de los chamanes se había convertido en el increíblemente poderoso Rey Exánime." },
		[677] = { file = "677", len = 22.517, text = "Puesto que Kil'jaeden no confiaba en el Rey Exánime, envió a sus aterradores guerreros a vigilar su espíritu, para así asegurarse de que el rey siguiera sus órdenes. Los vampíricos esbirros vinieron a Azeroth de buen grado, atraídos por la destrucción y el poder del Rey Exánime, ante la posibilidad borrar toda una raza de la faz del planeta." },
		[678] = { file = "678", len = 31.504, text = "Transcurrió más de una década. Durante ese tiempo, el Rey Exánime usó sus vastos poderes para controlar las mentes de las criaturas de Rasganorte, a quienes ordenó construir una gran ciudad sobre su trono congelado. Una vez que Rasganorte fue conquistado, el Rey Exánime sabía que tenía que empezar a infiltrarse en Lordaeron. Atrapado en el hielo, el antiguo chamán orco halló nuevas mentes para manipularlas y controlarlas. Su llamada atravesó continentes enteros." },
		[679] = { file = "679", len = 32.052, text = "Las invocaciones del Rey Exánime no pasaron desapercibidas, especialmente para un puñado de poderosos individuos. Entre ellos estaba el archimago Kel'Thuzad, miembro de la junta de gobierno de Dalaran, el Kirin Tor. Su interés por las fuerzas ocultas infringía la política del Kirin Tor, que se oponía al aprendizaje de la magia negra. Kel'Thuzad abandonó el Kirin Tor y todos sus vínculos con el pensamiento convencional y juró aprender todos los secretos del Rey Exánime." },
		[680] = { file = "680", len = 27.664, text = "Ambos sellaron un pacto. A cambio de servir al Rey Exánime, Kel'Thuzad obtendría la inmortalidad e inmensos poderes. La primera tarea que Kel'Thuzad habría de realizar consistía en usar su inmensa riqueza e influencia en Lordaeron para fundar el Culto de los Malditos. El Culto prometía igualdad y vida eterna a todos sus miembros, siempre y cuando juraran obediencia a Ner'zhul, el dios del Culto de los Malditos." },
		[681] = { file = "681", len = 20.193, text = "Ner'zhul creó, a continuación, artefactos diseñados para diseminar la peste entre las civilizaciones humanas de Lordaeron. Entregó los artefactos a Kel'Thuzad y ordenó al zahorí que los extendiera por todo el territorio. Los seguidores de su culto debían proteger estos artefactos a toda costa." },
		[682] = { file = "682", len = 24.895, text = "Una vez extendida, la peste empezará a filtrarse en la tierra, afectando a sus ignorantes moradores. Kel'Thuzad pudo advertir cómo el ejército del Rey Exánime crecía rápidamente, haciéndose con el control de grandes extensiones de tierra. Este ejército se conoció como la Plaga, pues su único propósito era el exterminio de la humanidad de la tierra de Azeroth." },
		[690] = { file = "690", len = 20.611, text = "La palabra TRAIDOR aparece escrita toscamente sobre el epitafio finamente grabado, cuyo texto dice: Aquí yace Yuriv. Padre, esposo y paladín. Sus hijos deberán saber que su dedicación a la Luz fue incuestionable. Nunca exigió a los demás nada que él no hiciera." },
		[696] = { file = "696", len = 36.754, text = "Diario - Cuarto día Llevo 4 días varado en la isla, a solas con mis pensamientos. Los plátanos son sabrosos, pero cuesta mucho trepar para alcanzarlos. Cuando no estoy buscando comida o protegiéndome de la periódica lluvia, todos mis pensamientos se centran en el rescate. No estaría tan esperanzado de no ser por las cajas de botellas y papel que fueron arrojadas a esta orilla. Ahora me río por todo el tiempo que he estado maldiciendo en el barco por ir acompañado de un cargamento de alquimistas y escribas." },
		[697] = { file = "697", len = 36.336, text = "Diario - Día 512 Los plátanos han empezado a hablar conmigo y he aprendido mucho acerca de su cultura. He abandonado la insensible destrucción de sus hogares y el consumo de sus crías. Cuán poco sabía de la gran civilización que estaba destruyendo. Pasando a otra cosa, creo que se me están acabando las botellas y el papel. Cuando veía inicialmente las enormes pilas de papel que llegaron hasta aquí, pensé que nunca se acabarían. Ay de mí, mi diario pronto llegará a su fin." },
		[698] = { file = "698", len = 33.567, text = "La tierra de Azeroth alberga incontables maravillas. Flora, fauna, culturas y magia pueblan su superficie. Ciertamente, los curiosos encontrarán aquí una ilimitada variedad de formas de vida y maravillas sorprendentes. Basta echar un ligero vistazo. Si se mira con suficiente detenimiento, se abre una ventana a mundos desconocidos y cada uno alberga sus propios secretos. De la misma manera que cada uno guarda sus propios horrores." },
		[699] = { file = "699", len = 20.271, text = "Este es el propósito de mi libro: catalogar a aquellos seres, extraños mefistos decididos a destruir nuestras tierras, para que los exploradores que los encuentren sepan lo que tienen delante. Si te consideras un guardián de Azeroth, sigue leyendo. y conoce a tu enemigo. Ur Mago de Dalaran" },
		[700] = { file = "700", len = 24.215, text = "El mefisto sobre el que escribo es el huargen. El folklore popular recoge historias sobre estas criaturas, pues ¿qué hijo de granjero no ha oído historias de lobizones bestiales acechando en los bosques y las marismas, fuera de este poblado? Estas historias encierran cierta verdad; tal vez nos advierten acerca de la presencia de los huargen, convertidos en mito para asustarnos." },
		[701] = { file = "701", len = 23.275, text = "Pero antes de rechazar tales historias, debo asegurar al lector: los huargen son reales. Quizás no sean de este mundo, pero existen caminos entre sus moradas y las nuestras, ocultos poderes que los atraen hasta nosotros. Es mejor no pronunciar los conjuros que invocan a estas bestias, pues allí donde van, siembran el terror y la destrucción." },
		[702] = { file = "702", len = 30.642, text = "Los huargen se reconocen por su similitud con los lobos de nuestro mundo. Los huargen se distinguen fácilmente por su grueso pelaje, sus orejas puntiagudas y sus alargados hocicos, similares a los de los lobos que conocemos. Pero las diferencias también son claras: el grueso pelaje cubre el cuerpo musculoso de la bestia, que luce dos largos colmillos y zarpas afiladas como puñales. Su aullido esconde una malevolencia que ninguna otra bestia natural posee." },
		[703] = { file = "703", len = 31.19, text = "El hábitat del huargen es un lugar oscuro, un lugar de pesadilla. Si en este mundo existen espacios a salvo de los malignos huargen, mis investigaciones no reflejan tales bastiones. Si tenemos en cuenta la ferocidad y la maldad de los huargen, lo más probable es que estos bastiones no existan. Se dice que los huargen viven a gusto en su mundo, pues, aunque algunos poseen mágicos poderes, no han intentado acercarse a Azeroth por impulso propio. Eso nos hace afortunados." },
		[704] = { file = "704", len = 19.984, text = "Como he dicho anteriormente, algunos huargen son diestros en las artes místicas, utilizando poderes oscuros y siniestros. Son habituales en ellos las maldiciones y los venenos sobrenaturales, de modo que queda advertido: aquellos que se enfrenten a un mago huargen deberán protegerse del poder de la sombra." },
		[705] = { file = "705", len = 24.503, text = "Realmente deseo que ningún zahorí de Dalaran busque a los huargen, aun cuando sean plenamente conscientes de lo que hacen. Pues no hay acuerdo posible, no revelarán secreto alguno y nada bueno puede obtenerse de estas bestias. Es mejor dejarlas en paz en su mundo. Si llegan al nuestro y no son destruidos, estaremos en grave peligro..." },
		[711] = { file = "711", len = 28.813, text = "Helgrum, Deseo dar mi enhorabuena a aquel que haya dado la orden de establecer nuestra base en Kargarth, en las Tierras Inhóspitas. Es un lugar perfecto para adiestrar a nuestras tropas. El clima riguroso, su fauna salvaje y la falta absoluta de asistencia convierten a este enclave en un crisol que solo dará lugar a los mejores guerreros y exploradores. Bien pensado. Bien hecho." },
		[731] = { file = "731", len = 4.101, text = "Eliza Amada esposa, que la tierra sacie tu apetito." },
		[751] = { file = "751", len = 30.537, text = "Estas son las especificaciones del pistón: Longitud: 32 EB Ancho: 12 EB Peso: 23,5 GD a 25,5 GD Conducción: 70 RDP Fuerza de corte: 98 o superior Tasa de combobulación: \"Superfuerte\" o superior En caso de que hayas olvidado las medidas gnómicas: EB = \"Extensión de los bigotes\" GD = \"Gramos diminutos\" RDP = \"Rizos de los dedos de los pies\"" },
		[752] = { file = "752", len = 32.392, text = "Eh, colega. Lleva esta carta a Frang, en el Valle de los Retos. Suele estar fuera de El Cubil, entrenando a jóvenes guerreros que desean luchar por la Horda. Necesita guerreros astutos como tú para enseñar a los orcos a pelear usando algo más que sus músculos. Eres más rápido y listo que la mayoría, pero no te jactes de eso: a los orcos no les gusta que los insulten. Son buenos aliados y quizás te enseñen un par de cosas. Tarsere" },
		[771] = { file = "771", len = 38.661, text = "ALIMENTACIÓN Y CUIDADOS: Nos comprometemos a proporcionarte todo lo que necesitas para cuidar a tu mascota. Nuestros clientes esperan este nivel de servicio de Snuff Inc, ¡y estamos de acuerdo en ofrecerlo! Para ello, hemos diseñado unos robustos cajones para husmeador taltuza con pequeños orificios, perfectos para mantener a tu mascota en un lugar seguro, alejado de la luz. Para tu comodidad, dentro de cada cajón hay un recipiente con gránulos de comida, ¡impregnados con el atrayente aroma de los tubérculos hojazul (el alimento favorito de husmeadores taltuza)!" },
		[791] = { file = "791", len = 35.892, text = "Describir las tierras vecinas teniendo en cuenta las tareas de reconocimiento de los exploradores de Kargath. Se trata de colinas rojizas y rocosas y de planicies secas, resultando poco habitables. El sol es abrasador y hay fuertes vientos. No hay lagos ni corrientes. Ni siquiera charcas aisladas. Para encontrar agua, los nativos deben cavar pozos profundos y llenos de barro, o bien succionar la escasa humedad de los cactus o hierbajos espinosos. En resumen: aquí la vida es difícil, en un entorno muy caluroso." },
		[793] = { file = "793", len = 16.222, text = "No hace falta decir que los que acampamos en Kargath estamos muy contentos con nuestra misión. Aquí nos hacemos fuertes, porque si nos descuidamos, morimos. Y no quisiera que fuera distinto. Neeka Marca de Sangre Jefa de exploradores, Kargath" },
		[794] = { file = "794", len = 29.701, text = "Nuestro mundo está cargado de historia. Una historia de razas modernas y antiguas. Una historia de guerras pasadas y presentes. Una historia de dioses que vienen del cielo. Y una historia de dioses antiguos que dormitan sobre la tierra. Ahora hablaré de esos seres, los dioses antiguos. Aquellos que habitaron y rugieron por todo el territorio de Azeroth cuando el mundo estaba en ciernes." },
		[795] = { file = "795", len = 41.456, text = "Los dioses antiguos son la voluntad de nuestro mundo. En cada tormenta se escucha la risa estruendosa de un dios antiguo. Sus penetrantes miradas son teas incandescentes. A su paso, la tierra retumba y se resquebraja, mientras las criaturas menores gritan de pánico y rasgan su propia carne en medio de la desesperación. Su desesperación tiene razón de ser, pues, al igual que el fuego no se detiene ante la mano curiosa de un niño, los dioses antiguos no se preocupan por los seres inferiores. Con suerte, nos tratan como peones. A veces, incluso, somos sus juguetes." },
		[796] = { file = "796", len = 29.414, text = "Fueron los primeros amos del mundo y reinaron sembrando el terror. Pero ahora duermen encadenados, mientras sus siervos vagan por el mundo y nosotros, insignificantes mortales, no estamos a la altura de su poder. Aquellos que intentan enfrentarse a ellos son devorados. Pero los que son conscientes de su situación, los que suplican de rodillas a los siervos de los dioses antiguos, los que sacrifican su mente y su alma, solo ellos son bien recibidos." },
		[797] = { file = "797", len = 31.53, text = "Aku'mai, Princesa de la Profundidad, sirve a los dioses antiguos. Habita en las cavernas de Brazanegra, bendiciéndolas con su antigua sabiduría. Conducida hasta las Profundidades por mortales antiguos, Akumai es símbolo de divinidad. Apenas goza de una pequeña parte del poder y la fiereza de los dioses antiguos y, aun así, estas cualidades son inconmensurables en ella. Y por ello es venerada. Y también es temida y amada. Lorgalis" },
		[811] = { file = "811", len = 34.011, text = "El plan se ha puesto en marcha. Utiliza como campamento base el que antaño fuera el gran bastión de fe, la Vigilia de los Héroes, y empezaremos a enviarte refuerzos desde los Páramos de Poniente cuando nos mandes un mensaje que indique que ya está preparado. El área en cuestión no ha sido olvidada por los ciudadanos y Soldados de Ventormenta y debería ser un centro de operaciones perfecto desde el cual realizar nuestros ataques. ¡Los Defias recuperarán Ventormenta! Aguardo tu respuesta." },
		[812] = { file = "812", len = 37.433, text = "Los asquerosos troggs son fáciles de engañar. Su odio por nuestra especie hace que resulten mucho más fáciles de dominar para utilizarlos como peones. Me llena de asombro que pueda existir cualquier tipo de alianza, pero lo cierto es que nosotros suponemos una amenaza mucho mayor para su existencia... al menos por ahora. No obstante, los ataques harán que ambos bandos se debiliten y resultará fácil destruirlos. Llévate la granja al sur del lago de Helm y espera nuevas instrucciones. Forjaz será nuestra." },
		[831] = { file = "831", len = 15.7, text = "En las páginas siguientes, encontrarás un listado con todo el material necesario para fabricar una armadura de mallas endurecida con fuego. Buena suerte, guerrero. Furen Barbalarga" },
		[832] = { file = "832", len = 18.834, text = "Colmillos de araña agostados: El mineral de incendicita que se encuentra en una cueva situada en las inmediaciones de Roca Thelgen ha agostado a las arañas que allí habitan. El veneno de sus colmillos hierve y hace reacción con los propios colmillos, dando lugar a una sustancia muy resistente." },
		[833] = { file = "833", len = 20.323, text = "Cuernos carbonizados: Al igual que los colmillos de araña agostados, los cuernos carbonizados de las quimeras que habitan en la Vega Carbonizada, en la Cima del Espolón de Kalimdor, poseen cualidades muy apreciadas. Tras ser aplanadas a golpes y tratadas, se vuelven extremadamente resistentes a la tensión física." },
		[834] = { file = "834", len = 15.308, text = "Cuerno galvanizado: La dureza del escaso cuerno galvanizado es la clave fundamental de la armadura que voy a crear, así que es preciso conseguirlo. Se puede obtener de la también escasa quimera matriarca que habita en la Vega Carbonizada." },
		[835] = { file = "835", len = 23.171, text = "Vial de flogisto: La última fase de la creación de la armadura requiere una forja a temperaturas extremas. Para obtener la temperatura necesaria, necesito un vial de flogisto. El único fabricante de esta sustancia es el legendario jabaespín Roogug, y no te la dará sin antes luchar. Roogug habita en el Horado Rajacieno, en el sur de los Baldíos." },
		[856] = { file = "856", len = 12.826, text = "Vidarraíz: Se encuentra en estado salvaje o puede obtenerse de las lodobestias parramustias del marjal Revolcafango. Su poder será necesario para extraer la esencia vital de Ciclonio." },
		[857] = { file = "857", len = 17.11, text = "Colmillos de Sangrapellejo: Los colmillos de los trols Sangrapellejo de la Vega de Tuercespina tienen una extraña cualidad. La perversidad de los Sangrapellejo se concentra en sus colmillos que, cuando se muelen hasta obtener un fino polvo, sus poderes se desencadenan." },
		[858] = { file = "858", len = 22.23, text = "Esencia del exilio: Esta esencia se obtiene mediante la fusión de tres talismanes de los exiliados elementales de las Tierras Altas de Arathi. Reúne talismanes del trueno, talismanes ardientes y talismanes blasonados de los elementales y luego vierte ocho de cada uno en mi caldera. A partir de los talismanes se formará la esencia del exilio." },
		[871] = { file = "871", len = 35.004, text = "$N, Antes de continuar, permíteme que te vuelva a dar las gracias por todo lo que hiciste por mi mujer. Le salvaste la vida y no me bastan cien vidas para agradecértelo. Ella lo es todo para mí. Si hubiera muerto... no sé qué habría hecho. Aquí tienes un listado con todo lo que tienes que reunir para fabricarte un arma sagrada. He puesto todos los elementos ordenados según lo fácil que resulta conseguirlos. Espero que eso te facilite las cosas." },
		[872] = { file = "872", len = 40.046, text = "Un poco de madera de roble de Piedrablanca: Esta madera abundaba en las minas que hay debajo de Arroyo de la Luna, en los Páramos de Poniente, antes de que fueran usurpadas. De hecho, la usaban para construir algunos de los enrejados y herramientas más importantes, debido a su resistencia al calor y a la presión. Fue llevada hasta allí después de que la trajeran en barco desde algún lugar de ultramar. Se trata de una madera escasa suficientemente resistente como para usarla en la fabricación de tu arma. En el caso de que aún haya restos de esta madera en las minas, lo más probable es que los goblins Tallamadera tengan un poco." },
		[873] = { file = "873", len = 29.936, text = "Mineral refinado: Hay un enano en Thelsamar, un herrero al que he instruido durante un tiempo, llamado Bailor Petramano. Obtiene una aleación muy especial que creo que sería perfecta para tu arma. Esperaba un cargamento de esa aleación cuando estaba en Forjaz, pero aún no he recibido noticias de él. Encuéntralo y averigua qué ha pasado con ese cargamento. Y si mi antiguo maestro ya no está en Loch Modan, al menos me gustaría saber qué ha sido de él." },
		[874] = { file = "874", len = 32.235, text = "Martillo de herrería: Antes de la llegada de la Peste y de la traición de Arthas, yo vivía en una ciudad llamada Piroleña, enclavada en el hermoso bosque de Argénteos. El bosque ha perdido el esplendor del pasado, y el fuerte en el que aprendí los secretos del acero ya no es lo que era, pues ahora lo habitan criaturas de maldad inimaginable. Cuando mi mujer y yo escapamos de lo que ahora se conoce como el Castillo de Colmillo Oscuro, abandonando algunas de nuestras más queridas pertenencias." },
		[875] = { file = "875", len = 33.175, text = "Entre ellas estaba el martillo de herrería que me dejó mi padre. Cuando era joven no hice caso a sus palabras al afirmar que ese martillo estaba encantado. Fue el último recuerdo que tuve de él antes de que la Plaga lo matara. Tráeme mi martillo, $N, para que vuelva a infundirme todo el entusiasmo. Si realmente está encantado, solo nos será útil a ambos. Lo dejé en los establos en el patio principal del fuerte. A menos que las criaturas que allí viven hayan decidido dedicarse a la herrería, espero que siga ahí." },
		[876] = { file = "876", len = 34.351, text = "Una gema Kor - Según me ha contado, estas gemas las utilizan algunos hechiceros para obtener su energía y sus poderes, lo que los hace aún más peligrosos. Un elfo de la noche a quien un día ayudé, Thundris Tejevientos, podrá darte más detalles, pues irás de mi parte. Creo que ciertas energías almacenadas en la gema pueden servir para crear tu arma. Cuando hablamos por última vez, Thundris estaba en Auberdine, un pueblo en medio de Costa Oscura, el bosque corrupto que salpica la costa bajo la sombra de la tierra de los elfos de la noche." },
		[891] = { file = "891", len = 11.807, text = "Los símbolos y pictogramas que rellenan las páginas de este manual son esotéricos y están más allá de la comprensión." },
		[911] = { file = "911", len = 16.222, text = "Consigue un trozo de jade.Se ocultan en diversos lugares. Se trata de una piedra escasa, pero si hablas con un herrero o un ingeniero, es posible que les quede alguna." },
		[931] = { file = "931", len = 30.067, text = "$N, estos son los objetos necesarios para fabricar tu armadura: Lingotes de hierro humeante de los kóbolds Cortaviento que hay en la mina Cortaviento de la Cima del Espolón. Azurita en polvo de los mineros de Trabalomas. Barras de hierro de los mineros o de los depósitos de hierro, en el caso de que te dediques a la minería. Vial de flogisto de un jabaespín llamado Roogug, en el Horado Rajacieno." },
		[951] = { file = "951", len = 42.71, text = "(Solo resultan visibles algunos fragmentos del diario a causa de las manchas). Uldaman, Tercer día No puedo creer lo idiota que he sido. Dejar que los enanos Forjatiniebla me atacaran por sorpresa solo le ocurre a los novatos. Mis heridas se curan lentamente y estoy infectado por su veneno. Noto cómo la energía me abandona. No obstante, tengo que seguir explorando... ... para empeorar las cosas, ¡el collar que $Gel:la; gnomo hizo para mí se ha hecho añicos! Tres de las gemas más grandes engarzadas en él se han perdido. Debo encontrarlas, ya que, sin ellas, el collar carece de todo poder..." },
		[971] = { file = "971", len = 23.014, text = "Uldaman, cuarto día Pude encontrar la primera en las profundidades de Uldaman, ya que uno de los troggs más salvajes que he visto estaba blandiendo un gran zafiro que habría encajado perfectamente en el collar. Escuché a los enanos Forjatiniebla mencionar el nombre de las bestias: Grimlok. Vaya panda de guardianes que tiene el tosco de Grimlok, no obstante..." },
		[972] = { file = "972", len = 38.949, text = "Uldaman, quinto día ... el trogg, cuando arrancó el topacio a sus \"hermanos\" asesinados, se dirigió a la caverna lateral que hay cerca de la entrada de la sala... ... rápidamente para colocar el topacio en una urna grande y llamativa que había en la parte trasera de la cámara... ... ¡sobre todo, enanos! Además, había tres de ellos. Actualmente los utilizan como escudos vivientes contra los troggs. Llamarlos habría sido un suicido, ya que esto habría atraído a los apestosos troggs... y yo en este estado calamitoso... Sin embargo, en cuanto dé con la tercera gema, voy a..." },
		[973] = { file = "973", len = 14.785, text = "Uldaman, Sexto día ... ¡qué hambre! Me he quedado sin provisiones, hasta tal punto que un pan mohoso sería ahora un festín. De hecho, vi cómo la cabeza de un trogg se convertía en un jugoso filete delante de mí..." },
		[974] = { file = "974", len = 30.694, text = "Uldaman, Séptimo día ... es mi última oportunidad para reparar mis errores. Creo que el rubí está cerca de las últimas barricadas que los enanos construyeron contra los troggs. Las batallas que libran, sin duda por el control de las gemas y otros artefactos de este sitio, son continuas. Lo más probable es que esos viles enanos lo hayan escondido por esa zona. De todas maneras, tengo que hacer algo al respecto. Tal vez sea mejor salir a la superficie repentinamente..." },
		[991] = { file = "991", len = 27.298, text = "Busca una zarza electrificada. Para obtenerla, reúne 10 palos de tótem de los trols Secacorteza procedentes de las Tierras Altas de Arathi. Lleva los palos al Círculo de Vínculo Exterior, un círculo de piedras que hay en las tierras altas. Coloca los palos sobre la piedra central del círculo y espera a que un rayo caiga encima de ellos. Cuando esto ocurra, se formará la zarza electrificada." },
		[992] = { file = "992", len = 9.77, text = "$GEl portador:La portadora; de este certificado obtendrá el respeto y la consideración que merece un ratero o un ladrón." },
		[1011] = { file = "1011", len = 30.224, text = "¡He encontrado un método para entrar en la cámara de Khaz?mul! Coge el medallón de Gni?kiv que hay en mi cofre. Derrota al trogg Revelosh en la cámara, delante del cuarto de mapas, y recupera el bastón de Tsol. Une el medallón y el bastón para formar el Bastón de Prehistoria. Usa el bastón en el cuarto de mapas para abrir la puerta que conduce a la cámara de Khaz?mul. ¡Haz todo esto y la cámara será tuya! Baelog" },
		[1031] = { file = "1031", len = 31.086, text = "¡He encontrado un método para entrar en la cámara de Khaz?mul! Coge el medallón de Gni?kiv que hay en mi cofre. Derrota al trogg Revelosh en la cámara, delante del cuarto de mapas, y recupera el bastón de Tsol. Une el medallón y el bastón para formar el Bastón de Prehistoria. Usa el bastón en el cuarto de mapas para abrir la puerta que conduce a la cámara de Khaz?mul. ¡Haz todo esto y la cámara será tuya! Baelog" },
		[1051] = { file = "1051", len = 36.153, text = "Los guardias de esta torre parecen ser especialmente vulnerables a mis ataques. Mientras exploraba la parte trasera de la torre, una patrullera me vio y me atacó. Pude matarla de un disparo, asestándole después una puñalada por la espalda. Me oculté y esperé a que llegara su compañero para averiguar qué había pasado. El patrullero se acercó a los arbustos hasta donde yo había arrastrado el cadáver e inició la búsqueda. Lentamente y con cuidado, me le acerqué por detrás, procurando evitar que descubriera mi emboscada." },
		[1052] = { file = "1052", len = 26.828, text = "Cuando tuve la oportunidad, ¡clavé mi puñal en su espalda! Sus pulmones fallaron rápidamente ante la fuerza del ataque, mientras su cadáver caía al suelo con un ruido sordo. Fue una emboscada tan rápida y violenta, que el pobre idiota no tuvo siquiera tiempo de gritar de dolor. Curiosamente, cuando extraje el puñal de su espalda, el cuerpo del patrullero acuchillado desprendió un hedor espantoso." },
		[1053] = { file = "1053", len = 20.506, text = "Al parecer, lo que Klaven ha guardado en el cofre bajo llave está afectando negativamente a los habitantes de la torre. Sospecho que los demás guardias presentan un decaimiento similar y, tal vez, incluso el propio Klaven también está afectado. Agente Amber Kearnen IV:7 Espía raso, R8" },
		[1071] = { file = "1071", len = 21.316, text = "Comandante, regresa a Orgrimmar. Tus fuerzas son insuficientes. Debemos volver a analizar nuestra posición en base a los nuevos datos. Hay un gran número de miembros del clan Sombra Jurada y ogros. Los demonios vigilan el Portal Oscuro. Thrall, Jefe de Guerra de la Horda" },
		[1091] = { file = "1091", len = 27.455, text = "La marra de Zul'Farrak Para crear la marra de Zul'Farrak, primero hay que viajar al Altar de Zul y obtener la maza sagrada de un guardián trol. A continuación, debes llevar la maza sagrada al altar, en lo alto de la ciudad trol de Jintha'alor. Si usas esta maza sagrada en el altar, adquirirá los poderes necesarios y se convertirá en la maza de Zul'Farrak." },
		[1131] = { file = "1131", len = 77.531, text = "TARJETA DE DATOS VITALES CODIFICADOS TRIPLE 01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100001 01101110 01100100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01101001 01110100 01110100 01101001 01101110 01100111 00100000 01101001 01101110 00100000 01100001 00100000 01110100 01110010 01100101 01100101 00101100 00100000 01001011 00101101 01001001 00101101 01010011 00101101 01010011 00101101 01001001 00101101 01001110 00101101 01000111" },
		[1151] = { file = "1151", len = 19.435, text = "La empresa Ventura y Cía.\010texto ilegible\010Al parecer, esos idiotas casi eliminan toda la operación, intentando estabilizar la mezcla.\010muchas páginas parecen haber sido arrancadas" },
		[1152] = { file = "1152", len = 10.397, text = "Lo que he notado es que la carga radiactiva es absolutamente letal. Imagina si\010texto ilegible\010¡Ja, ja, ja, ja!" },
		[1153] = { file = "1153", len = 16.274, text = "¿Estoy perdiendo el juicio? Hoy le abrí la cabeza a uno de mis patrulleros más fieles para poder ver mejor dentro de su alma. Mientras observaba detenidamente su conducto respiratorio destrozado, pensé: ¡No he comido nada en varios días!" },
		[1154] = { file = "1154", len = 16.144, text = "Mathias Shaw había mandado a su chico de los recados para que me matara.\010texto ilegible\010Él ahora patrulla el exterior. Esclavo autómata descerebrado y sin vida. ¡Ja, ja, ja. ja!" },
		[1155] = { file = "1155", len = 17.946, text = "VanCleef...\010texto ilegible\010¿Me ha llamado para que ENTRARA?? ¿¿QUIÉN SE CREE QUE ES?? ¡Soy Klaven Mortoalerta! ¡Un insecto como él no puede decirme lo que tengo que hacer!\010faltan las páginas restantes del libro" },
		[1156] = { file = "1156", len = 15.229, text = "Curgle, Llevo esperando tu nuevo invento con ansiedad. No puedo esperar a usarlo para documentar mis estudios. Por favor, confíaselo a mi $Gmensajero:mensajera;. Un saludo, Daryn Brisela" },
		[1191] = { file = "1191", len = 17.319, text = "¡DATOS EXTREMADAMENTE VITALES! ¡NIVEL DE SEGURIDAD 5122! " },
		[1192] = { file = "1192", len = 53.185, text = "¡No permitir que esta información caiga en manos del enemigo! 01010100 01101000 01100101 00100000 01100111 01101110 01101111 01101101 01100101 00100000 01101011 01101001 01101110 01100111 00100000 01110111 01100101 01100001 01110010 01110011 00100000 01101110 01101001 01100111 01101000 01110100 00100000 01100101 01101100 01100110 00100000 01110101 01101110 01100100 01100101 01110010 01110111 01100101 01100001 01110010" },
		[1193] = { file = "1193", len = 98.247, text = "Nivel de seguridad 10^10000 ¡datos súper confidenciales! TARJETA DE DATOS VITALES CODIFICADOS TRIPLE 01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100001 01101110 01100100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01101001 01110100 01110100 01101001 01101110 01100111 00100000 01101001 01101110 00100000 01100001 00100000 01110100 01110010 01100101 01100101 00101100 00100000 01001011 00101101 01001001 00101101 01010011 00101101 01010011 00101101 01001001 00101101 01001110 00101101 01000111" },
		[1194] = { file = "1194", len = 11.05, text = "¡El nivel de seguridad de estos datos es TAN alto, que aún no se ha inventado una cifra que sirva para describirlo!" },
		[1211] = { file = "1211", len = 36.806, text = "SACAR A PASEAR AL HUSMEADOR TALTUZA Al husmeador taltuza le gustan los lugares oscuros y pequeños. Y es muy asustadizo. Si deseas sacar a pasear a tu husmeador taltuza, deberás llevarlo a lugares en los que se sienta a gusto. ¡Y DEBES llevarlo allí donde pueda oler su comida favorita: tubérculos hojazul! El lugar que más adecuado es la zona de las \"zanjas\" del Horado Rajacieno. Si abres la caja del husmeador taltuza cerca de la zanja y el animalillo huele los tubérculos hojazul que hay cerca de ahí, se atreverá a salir y te seguirá." },
		[1212] = { file = "1212", len = 27.716, text = "LA VARA DE MANDO DE HUSMEADOR (R) El husmeador taltuza es un animal sorprendente. No solo inspira amor y afecto en el zancudo de llanura más irritable, ¡sino que puede oler un tubérculo hojazul enterrado a unos 45 metros! Si deseas que tu husmeador taltuza vaya a buscar un tubérculo hojazul, puedes usar tu vara de mando patentada (se adquiere por separado). En la página siguiente encontrarás la dirección..." },
		[1213] = { file = "1213", len = 38.792, text = "Todos nuestros husmeadores están altamente adiestrados. Un simple movimiento de la vara de mando hará que cualquier husmeador taltuza que esté cerca entre en el \"modo de búsqueda.\" A continuación, olfateará el suelo en busca de tubérculos hojazul y, si encuentra uno, irá a buscarlo y lo desenterrará. Si vuelves a mover el mando mientras el husmeador busca su tubérculo, abandonará la búsqueda y regresará contento a tu lado. ¡Confiamos en que nuestros husmeadores taltuza te parezcan animales bien adiestrados, útiles y esponjosos, que querrás apretujar a todas horas." },
		[1214] = { file = "1214", len = 34.795, text = "Lamentamos tener que informar que en Snuff Inc. sabemos de la existencia de ciertos glotones cazadores de tubérculos a los que poco importa la seguridad de sus adorables mascotas, enviándolas a lugares oscuros y peligrosos en busca de tubérculos. No aprobamos esta conducta irresponsable, así que con el propósito de satisfacer a nuestros clientes, hemos incluido una garantía con cada husmeador taltuza vendido, ofreciendo a los nuevos dueños la posibilidad de volver al punto de venta y recuperar a su husmeador taltuza perdido. ¡Feliz caza!" },
		[1231] = { file = "1231", len = 19.644, text = "Este documento sirve para verificar si $N asesinó a Margol la Furibunda, miembro de la Plaga en la Garganta de Fuego. El museo de Forjaz reconoce esta hazaña y agradece $Gal portador:a la portadora; por su generosa contribución. Comisario Torio Tiernorroca" },
		[1251] = { file = "1251", len = 41.744, text = "Estos meses he tenido tiempo para reflexionar, barajar el perder mis viejas creencias y fanatismos. ¿Alianza? ¿Horda? ¿Bien? ¿Mal? Los significados de estas palabras, una vez aclaradas, ahora borrosas en mis ojos cuando fijo mi mirada al infinito mar. Ahora sé lo que importa. Los plátanos están tras mí. Colgados en lo alto del árbol, me miran con malévola frialdad. Y el último que intenté comerme ¡casi me amordaza! Casi lo pude oír gritar cuando lo tiré medio mordido, a las rocas del mar. Es la guerra, y la voy a ganar." },
		[1271] = { file = "1271", len = 37.094, text = "Las disciplinas de ingeniería Si bien resulta discutible qué raza creó la ciencia de la ingeniería en Azeroth, apenas si cabe duda de cuáles son sus principales razas defensoras en la actualidad: los gnomos y los goblins. Su dedicación a la ingeniería como colectivo no solo ha dado lugar a fantásticos inventos durante lo que podría considerarse la asombrosa Era de la Invención, sino que también ha alimentado su intensa rivalidad racial. Esto resulta especialmente evidente en sus disciplinas divergentes." },
		[1272] = { file = "1272", len = 31.112, text = "Ingeniería gnómica Los gnomos, como raza, suelen ser excelentes diseñadores de objetos destinados a manipular y controlar el mundo que los rodea. Si bien los gnomos tienen conocimientos elementales de explosivos y armamento, la ingeniería gnómica se centra en aquellos objetos que hacen la vida más fácil y accesible. Su disciplina se basa en la materialización de probabilidades teóricas fundadas en la experiencia gnómica. Sin embargo, algunas no se materializan jamás." },
		[1273] = { file = "1273", len = 39.34, text = "Ingeniería de los goblins Como raza que adopta una posición neutral en casi todos los conflictos, los goblins han hecho avances importantes a la hora de rentabilizar sus logros científicos. De esta manera, dominan las aplicaciones prácticas de la ingeniería, como demuestran sus innovadores diseños de explosivos, armas de fuego y maquinaria. La ingeniería goblin solo evidencia un interés superficial por la teoría. De hecho, sus inventos no suelen presentar problemas de funcionamiento, antes al contrario, funcionan demasiado bien. Ciertamente no es una materia apta para pusilánimes." },
		[1274] = { file = "1274", len = 31.347, text = "Estudio de la disciplina Los gnomos y los goblins no comparten sus conocimientos entre sí hasta tal punto, que resulta casi imposible acceder a ambas disciplinas simultáneamente. Cada raza, independientemente de su afiliación política, solo transmite el conocimiento de su disciplina a aquellos que renuncian a la disciplina de los otros. Así, por ejemplo, si un estudiante elige la ingeniería gnómica, no se le transmitirán nunca conocimientos de ingeniería de los goblins." },
		[1275] = { file = "1275", len = 30.328, text = "Decisiones permanentes En la sección anterior se destacó un aspecto importante sobre las dos disciplinas de ingeniería que conviene resaltar. Si alguien opta por una de las dos disciplinas, los modelos de la otra disciplina no estarán a su disposición para su estudio. Aunque esta finalidad puede resultar desalentadora para el ingeniero neófito, el experto comprende que los gnomos y los goblins guardan sus secretos con absoluto celo, pues afirman que es mejor tener algún conocimiento que ninguno." },
		[1276] = { file = "1276", len = 27.716, text = "Citas \"¿Deseas aprender ingeniería de los goblins? Intenta pedírselo a uno de los mejores y más brillantes ingenieros. Creo que lo llaman Nubby Muñoncitos. ¿Quieres saber por qué lo llaman así? ESO ES ingeniería goblin.\" Ringo Tragedicción, ingeniero gnomo \"Podrás pensar lo que quieras sobre los gnomos, pero una cosa sí te voy a decir: ¡TENEMOS EXPLOSIVOS!\" Yazz Nitrocerdo, bombardero goblin" },
		[1277] = { file = "1277", len = 26.775, text = "¡Más citas! \"¿Conoces la sensación que te produce fabricar algo y encenderlo por primera vez, experimentando el poder y la alegría de inventar una máquina que cobra vida gracias a tu ingenio? Los gnomos no.\" Nixx Muellepiñón, maestro ingeniero goblin de Gadgetzan \"¡La ingeniería consiste en utilizar la fantasía para crear lo fantástico!\" Rovis McCrankenspank, inventor gnomo" },
		[1291] = { file = "1291", len = 32.549, text = "Los conjuros de la bestia: Para invocar al rastreador manáfago, deberás usar el Orbe vil. Notas: El rastreador manáfago solo permanecerá como entidad en este mundo durante treinta minutos. El rastreador manáfago mágico solo te ayudará a encontrar formaciones de azsharita. El rastreador manáfago mágico NO hará lo siguiente: Trucos, atacar, ayudar, bailar, destruir seres arcanos. Siguiente página..." },
		[1292] = { file = "1292", len = 32.705, text = "El control de la bestia: Los rastreadores manáfagos solo responden a los gruñidos de la bestia. Para que tu rastreador manáfago rastree formaciones de azsharita, ¡deberás rugirle con fuerza! (Apunta al rastreador manáfago y /rugir). Cuando un rastreador manáfago encuentra una formación, corre velozmente hacia ella, sin tener en cuenta los seres que lo rodean. Si bien no resulta necesario proteger al rastreador, tal vez convenga estar cerca de él para que no se pierda." },
		[1293] = { file = "1293", len = 20.323, text = "Pérdida de la bestia: Transcurridos treinta minutos, la bestia regresará a su hogar en El Vacío Abisal. Nota: En su afán, la bestia PODRÍA caer por el acantilado o rodar por la ladera de una montaña. No lamentes la pérdida de un rastreador manáfago, mejor invoca a otro." },
		[1311] = { file = "1311", len = 24.294, text = "A quien corresponda: Si lees esta nota, significa que estás en uno de estos dos lugares: (1) En la península del sur de Azshara. (2) En las entrañas de un gigante del acantilado. Ambas opciones son poco deseables. Debo señalar que anteriormente fui el primero y mientras escribo esta carta, el último." },
		[1312] = { file = "1312", len = 19.801, text = "Permanecer en el interior de un gigante le da a uno tiempo para reflexionar. Mientras mi cuerpo se cristaliza, he llegado a la conclusión de que tal vez no hagan falta más héroes en este mundo. ¡Cuando salga de este apuro, voy a agarrar a ese orco por su fantasmagórico cuello! Windan Shay" },
		[1313] = { file = "1313", len = 29.544, text = "¿En qué estaba pensando? Quizás sería mejor preguntar: ¿Qué hago escribiendo una nota mientras estoy aquí atrapado en el vientre de un gigante? Son dos buenas preguntas para las que no tengo una respuesta inmediata... Tengo que admitir que la mía no era una misión conciliadora. Vine en busca de azsharita, un cristal único en el sur de Azshara. ¡Ah, cuántas riquezas podría tener! ¡Bah! Ahora miradme..." },
		[1314] = { file = "1314", len = 12.513, text = "Si algún ser con vida inteligente encuentra esta nota, deberá preguntarse lo siguiente: \"¿Cómo es posible que ellos estén jugando con violentos gigantes de casi diez metros de altura?\" Mook" },
		[1331] = { file = "1331", len = 29.962, text = "01001101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01110100 01101111 00100000 01000011 01100001 01110011 01110100 01110000 01101001 01110000 01100101 00111010 00100000 01111001 01101111 01110101 01110010 00100000 01101100 01100001 01110101 01101110 01100100 01110010 01111001 00100111 01110011 00100000 01110010 01100101 01100001 01100100 01111001 00100000 01100110 01101111 01110010 00100000 01110000 01101001 01100011 01101011 01110101 01110000 00101110" },
		[1392] = { file = "1392", len = 27.899, text = "Hermano Neals, ¡Mis uvas se han salvado! $N, el portador de este informe, entró en mi viñedo lleno de matones y recogió todas las uvas que yo no pude cosechar. Si bien los Defias siguen deambulando por el río, casi toda mi cosecha se ha salvado. Puedes agregar a tus almacenes un cargamento de varias fanegas de uvas. Que la Luz nos proteja, Milly Osworth" },
		[1431] = { file = "1431", len = 15.047, text = "Vorfalk Guarda de hierro Vorfalk trabaja en el almacén del Tragapenas, y sus sacrificios en nombre de los Guardas oscuros ha dejado honda huella. Que su espíritu conserve la fuerza." },
		[1432] = { file = "1432", len = 12.904, text = "Bethek Tormenceño Las andanzas de Bethek le llevan a adentrarse en Roca Negra. Los secretos de la montaña lo atraen. Que su espíritu nunca decaiga." },
		[1433] = { file = "1433", len = 13.453, text = "Uggel Manomartillo Uggel es un diestro y solemne grabador, y cuando no está poseído por la llave oscura, sus manos modelan grandes piezas en la Sala de los Oficios." },
		[1434] = { file = "1434", len = 18.991, text = "Zimrel Dienteoscuro Cuando Zimrel recibe el influjo de la llave oscura, solo los gritos de los moribundos lo calman. Para su sacrificio, siempre tendrá un banco en el coliseo. Que nuestros deportes de sangre aplaquen la furia de su corazón." },
		[1435] = { file = "1435", len = 19.827, text = "Ofgut Puñopiedra Son incontables los caídos bajo el martillo del guarda oscuro Ofgut. Los Soldados del Cuartel del Oeste se inclinan sobrecogidos a su paso. ¿Quién ha podido escudriñar los ojos de Ofgut para conocer los secretos que la llave oscura le susurra?" },
		[1436] = { file = "1436", len = 25.913, text = "Pelver Pasofuerte El guarda oscuro Pelver es nuestro discípulo más honorable. Ha soportado la carga de la llave durante más tiempo que ninguno y esto le ha costado muy caro. Cuando se le pide el cargamento, es custodiado en el Domicilio. Su sacrifico es muy apreciado y él permanecerá en nuestros corazones por muchos años... cuando la oscuridad se lo lleve." },
		[1491] = { file = "1491", len = 17.894, text = "MANUAL DE INSTRUCCIONES DE LA TORRE DE CRISTAL \"Una guía para coleccionar y usar los cristales de poder del cráter de Un'Goro\" Capítulo 1: La torre del norte Capítulo 2: La torre del este Capítulo 3: La torre del oeste" },
		[1511] = { file = "1511", len = 14.968, text = "Capítulo 1: LA TORRE DEL NORTE La torre del norte acepta cristales amarillos, rojos, y verdes. La torre se centra en la energía que se puede generar usando los cristales amarillos como fuente principal de poder." },
		[1512] = { file = "1512", len = 22.021, text = "Combinación de cristales del norte Hay dos efectos posibles: uno produce daño y el otro lo anula. CARGA DE CRISTAL: Requiere cristales rojos y amarillos. Esto produce una gran explosión. CRISTAL DE RESTAURACIÓN: Requiere cristales amarillos y verdes. Este cristal te proporcionará un aura de curación." },
		[1513] = { file = "1513", len = 2.194, text = "DIAGRAMA DE LA TORRE DEL NORTE" },
		[1514] = { file = "1514", len = 14.132, text = "Capítulo 2: LA TORRE DEL ESTE La torre del este acepta cristales azules, amarillos y verdes. La torre se centra en la energía que se puede generar usando los cristales azules como fuente principal de poder." },
		[1515] = { file = "1515", len = 24.137, text = "Combinación de cristales del este Hay dos efectos posibles: uno proporciona puntos adicionales para el espíritu y el otro crea un escudo de ataque. FUERZA DE LOS CRISTALES: Requiere el uso de cristales azules y verdes. Esto aumentará tu espíritu. AGUJA DE CRISTAL: Requiere cristales azules y amarillos. Creará un escudo que hará daño a los atacantes." },
		[1516] = { file = "1516", len = 2.194, text = "DIAGRAMA DE LA TORRE DEL ESTE" },
		[1531] = { file = "1531", len = 14.054, text = "Capítulo 3: LA TORRE DEL OESTE La torre del oeste acepta cristales rojos, verdes y azules. La torre se centra en la energía que se puede generar usando los cristales rojos como fuente principal de poder." },
		[1532] = { file = "1532", len = 24.816, text = "Combinación de cristales del oeste Hay dos efectos posibles: uno que incrementa tu protección de daño y otro que debilita las defensas del enemigo. SALA DE CRISTAL: Requiere cristales rojos y verdes. Esto aumentará tu armadura. COSECHA DE CRISTALES: Requiere cristales azules y rojos. Esto puede reducir la armadura de un objetivo específico." },
		[1533] = { file = "1533", len = 2.534, text = "DIAGRAMA DE LA TORRE DEL OESTE" },
		[1551] = { file = "1551", len = 29.806, text = "¡Saludos, aventureros! Yo, Krinkle Buenacero, necesito gente dispuesta a arriesgarse para realizar algunas de mis tareas más arduas. Debido a mis numerosas obligaciones y al volumen de trabajo que he logrado asumir, garantizo que cualquiera que sea lo suficientemente valiente como para recoger esta lista de objetos y traérmelos intactos será generosamente recompensado. La lista se detalla en las siguientes páginas..." },
		[1552] = { file = "1552", len = 29.388, text = "Patas de cristal sólido Las arañas cristalderma de la Garganta de Fuego están hechas de un material muy similar al cristal. Sus patas, si no se dañan cuando se las mata, constituyen excelentes conductores en algunos experimentos de ingeniería de algunos de mis compañeros. Voy a necesitar unas cuantas para realizar pruebas. Las arañas, al tener ocho patas, no deberían suponer problema alguno para un fornido guerrero o para un mago experimentado." },
		[1553] = { file = "1553", len = 35.135, text = "Un paquete que no llega a tiempo a su destino He contratado a alguien a quien creí un piloto fiable para que me trajera un paquete desde Theramore. Por lo visto, me equivoqué. Y, a pesar de que el piloto vivió para contarla, abandonó su zeppelín y todo su cargamento para salvar su pellejo. Lo cierto es que necesito ese paquete. Según me ha dicho Beezil, se estrelló al oeste de la bahía en el marjal Revolcafango. Yo bajé justo después de que él atravesara las colinas, bordeando la costa. Mmm... nunca me dijo cuál fue la causa de que se estrellara..." },
		[1554] = { file = "1554", len = 33.776, text = "Flameberge equilibrada de Buenacero Finalmente, deseo recuperar una de mis obras más finas creadas hasta la fecha. Esta Flameberge fue una espada increíble que otorgué a quien consideraba un honorable y excelente guerrero. Sí, pero ¿no fue derrotado por un múrloc llamado Jarquai? Más o menos eso ocurrió. Ocurrió cuando viajaba por la costa del Pantano de las Penas cuando tuvo la idea de atacar a la criatura. Fracasó en su intento y, aparentemente, huyó, pero no sin antes abandonar el arma a merced del múrloc." },
		[1556] = { file = "1556", len = 7.732, text = "Búscame esos objetos y regresa a Gadgetzan con todos ellos, junto con este libro de contabilidad, y te recompensaré." },
		[1591] = { file = "1591", len = 7.941, text = "Este yunque es propiedad de Jordan Fontana. ¡NO lo utilicen! Jordan" },
		[1611] = { file = "1611", len = 38.139, text = "Las páginas están cubiertas por antiguas runas élficas.\010Las páginas siguientes contienen recuerdos de los sucesos que tuvieron lugar en la recolección y la creación de los componentes necesarios para crear un arcano mayor. Que nuestros enemigos nunca tengan acceso a estos tratados. Quisiera vivir lo suficiente como para volver a contemplar la pálida luz de la luna sobre Quel'Thalas. Si muero, que sea por la gracia de Kael'thas. Si muero asesinado, que sea por la gloria de Illidan. Maestro Telmius Buscasueños" },
		[1631] = { file = "1631", len = 35.056, text = "Las páginas aparecen cubiertas por antiguas runas élficas.\010Estas páginas guardan memoria de los acontecimientos que tuvieron lugar durante la búsqueda y la creación de objetos necesarios para la obtención de un arcano menor. Que nuestros enemigos jamás tengan acceso a estos tratados. Deseo vivir para volver a ver la pálida luz de la luna sobre Quel'Thalas. Deseo morir por la gracia de Kael'thas. Deseo matar por la gloria de Illidan. Maestro Telmius Buscasueños" },
		[1632] = { file = "1632", len = 35.5, text = "Las páginas aparecen cubiertas por antiguas runas élficas.\010Estas páginas guardan memoria de los acontecimientos que tuvieron lugar durante la búsqueda y la creación de objetos necesarios para la obtención de un arcano menor. Que nuestros enemigos jamás tengan acceso a estos tratados. Deseo vivir para volver a ver la pálida luz de la luna sobre Quel'Thalas. Deseo morir por la gracia de Kael'thas. Deseo matar por la gloria de Illidan. Maestro Telmius Buscasueños" },
		[1633] = { file = "1633", len = 34.482, text = "Las páginas aparecen cubiertas por antiguas runas élficas.\010Estas páginas guardan memoria de los acontecimientos que tuvieron lugar durante la búsqueda y la creación de objetos necesarios para la obtención de un arcano menor. Que nuestros enemigos jamás tengan acceso a estos tratados. Deseo vivir para volver a ver la pálida luz de la luna sobre Quel'Thalas. Deseo morir por la gracia de Kael'thas. Deseo matar por la gloria de Illidan. Maestro Telmius Buscasueños" },
		[1634] = { file = "1634", len = 36.65, text = "Las páginas aparecen cubiertas por antiguas runas élficas.\010Estas páginas guardan memoria de los acontecimientos que tuvieron lugar durante la búsqueda y la creación de objetos necesarios para la obtención de un arcano menor. Que nuestros enemigos jamás tengan acceso a estos tratados. Deseo vivir para volver a ver la pálida luz de la luna sobre Quel'Thalas. Deseo morir por la gracia de Kael'thas. Deseo matar por la gloria de Illidan. Maestro Telmius Buscasueños" },
		[1711] = { file = "1711", len = 20.611, text = "Mensaje urgente para Vigiarisco Cuernolargo Un gran ejército de centauros procedentes del campamento E'thok han atacado a nuestras caravanas de suministros. Todos los miembros de la caravana se perdieron junto con todas nuestras provisiones. Fue un ataque sin precedentes de los centauros y mucho me temo que habrá más." },
		[1731] = { file = "1731", len = 17.998, text = "Aquí yace el rey Terenas Menethil II, último rey verdadero de Lordaeron. Grandes fueron sus hazañas, largo su reinado, inconcebible su muerte. \"Que el padre no sea inculpado por los actos de su hijo. Que la corona manchada de sangre permanezca en el olvido.\"" },
		[1751] = { file = "1751", len = 16.849, text = "Los restos del pantagruélico dragón rojo se encontraron en Los Humedales poco después de la batalla de Grim Batol. Se dice que Tyrannistrasz fue el consorte más anciano de Alexstrasza, reina de los dragones." },
		[1752] = { file = "1752", len = 23.536, text = "Esta garfa petrificada se encontró en las costas del sur de Tuercespina. Los ecologistas creen que la garfa pertenece a un antiguo roc de sol. Si bien las criaturas desempeñan un papel preponderante en la primitiva mitología tauren, la existencia de esta garfa sugiere que realmente existieron en algún momento de la historia." },
		[1753] = { file = "1753", len = 8.542, text = "Los zancudos más grandes de la llanura, los geru, son aves raras y escasas en número." },
		[1754] = { file = "1754", len = 23.301, text = "Esta es una réplica a escala de un esqueleto de rechinador. Este legendario carnero fue el asombro de Khaz Modan y el protagonista de muchas historias del folklore popular enano. Hasta el momento, los ecologistas no han podido determinar el tamaño descomunal o la resistencia física de este carnero." },
		[1755] = { file = "1755", len = 21.603, text = "Encontrado en la remota selva tropical del cráter de Un’Goro, su huevo albergaba un embrión de demosaurio. El material genético de los saurios ha resultado ser de incalculable valor para los ecologistas de la liga, que están más cerca que nunca de inventar un suero para atenuar el veneno del demosaurio." },
		[1756] = { file = "1756", len = 20.715, text = "Este esqueleto de pteradon intacto fue descubierto en el remoto cráter de Un'Goro. Basándonos en la estructura del esqueleto, resulta evidente que aún no se ha determinado su género. Este esqueleto quizás se conservó durante varios siglos bajo el rico suelo de la región." },
		[1757] = { file = "1757", len = 27.298, text = "Recuperado de las ruinas submarinas de Suramar, este astrolabio funcional fue fabricado por los elfos de la noche Altonato hace doce mil años. Los Altonato, obsesionados con la magia, lo oculto y la astronomía, desarrollaron una serie de ingeniosos aparatos. Este dispositivo proporciona valiosa información sobre el saber científico de los antiguos elfos de la noche." },
		[1758] = { file = "1758", len = 20.532, text = "Estas antiguas piezas de barro se extrajeron de las excavaciones de Uldaman. Si bien es poco probable que se trate de sugerentes runas o jeroglíficos, ofrecen un aspecto revelador de la destreza con que la antigua raza enana fabricaba sus accesorios de uso cotidiano." },
		[1759] = { file = "1759", len = 26.932, text = "Estos corredores grabados en relieve son quizás el hallazgo más importante de las primeras cámaras de Uldaman. Los grabados sugieren que existió un fuerte vínculo entre los terráneos gólem y la raza enana. En el caso de que se encontraran pruebas adicionales, se podría demostrar que las teorías de nuestra supuesta creación por parte de los míticos titanes son ciertas." },
		[1760] = { file = "1760", len = 28.918, text = "Hallado en los sofocantes restos del Desierto de Tanaris, este peculiar huevo sigue siendo un misterio para los ecologistas modernos. Las pruebas sugieren que el huevo podría tener hasta mil años de antigüedad. Si bien ciertos elementos indican estructuras insectoides, no resulta posible determinar sus verdaderos orígenes. Las especies que pusieron huevos tan distintos siguen sin conocerse." },
		[1761] = { file = "1761", len = 11.05, text = "Estos restos de la Segunda Guerra constituyen un conmovedor recuerdo de lo cerca que la Horda estuvo de conquistar la montaña de Forjaz." },
		[1762] = { file = "1762", len = 29.649, text = "Estas placas demoníacas fueron utilizadas por la criatura que por primera vez inoculó en nuestra gente la sed de sangre. Por el heroico acto de un valiente orco, que fue derrotado. Mannoroth el destructor ha desaparecido para siempre. Que estas placas nos recuerden siempre lo lejos que llegamos y lo mucho que luchamos para recuperar nuestro honor. Thrall, Jefe de Guerra de la Horda" },
		[1771] = { file = "1771", len = 12.722, text = "La consecuencia de la Segunda Guerra sirve como un conmovedor recordatorio de cuán peligrosamente la agitación de la Horda llegó a conquistar la montañas de Forjaz." },
		[1772] = { file = "1772", len = 23.589, text = "Vermiothalak: He recibido órdenes directas de tu maestro, Nefarian, para castigarte como crea conveniente en el caso de que más forasteros entren en la ciudadela. No olvides quién te manda, reptil. El hijo de Puño Negro: Maestro de la espada y la batalla. El verdadero Jefe de Guerra. Rend" },
		[1773] = { file = "1773", len = 36.493, text = "Con el tiempo, seres demoníacos lograron entrar en los mundos de los titanes desde El Vacío Abisal y el Panteón eligió a Sargeras, su guerrero más destacado, para combatir en primera línea. Noble gigante de bronce fundido, Sargeras desempeñó su papel durante incontables milenios, buscando y destruyendo a los demonios allí por donde iba. Durante millones de años, Sargeras se enfrentó a dos poderosas razas demoníacas, las cuales se habían propuesto obtener el poder y el dominio sobre el universo físico." },
		[1774] = { file = "1774", len = 17.241, text = "Los eredar, una raza insidiosa de malignos hechiceros, utilizó la brujería para invadir y dominar diversos mundos. Las razas autóctonas de estos planetas experimentaron mutaciones causadas por los malignos poderes de los eredar y se convirtieron en demonios." },
		[1775] = { file = "1775", len = 28.473, text = "Si bien los poderes casi ilimitados de Sargeras fueron más que suficientes para derrotar a los malvados eredar, tuvo grandes problemas generados por la corrupción de las criaturas y al mal que todo lo consume. Incapaz de comprender tanta depravación, el gran titán cayó en una amarga depresión. A pesar de su creciente malestar, Sargeras liberó al universo de la presencia de los brujos, recluyéndolos en un rincón de El Vacío Abisal." },
		[1776] = { file = "1776", len = 23.589, text = "Mientras su confusión y tristeza crecían, Sargeras se vio obligado a luchar contra otro intento del grupo de perturbar el orden de los titanes: los Nathrezim. Esta raza oscura de demonios vampíricos (también conocidos como señores del terror), conquistó varios planetas densamente poblados, poseyendo a sus habitantes y convirtiéndolos en sombras." },
		[1777] = { file = "1777", len = 16.353, text = "Los nefastos e intrigantes señores del terror enfrentaron a todas las naciones entre sí, manipulándolas hasta el odio irreflexivo y la desconfianza. Sargeras derrotó a los Nathrezim fácilmente, pero su corrupción lo afectó profundamente." },
		[1778] = { file = "1778", len = 22.883, text = "Puesto que la duda y la desesperación ensombrecieron los sentidos de Sargeras, perdió toda la fe no solo en su misión, sino también en la visión que los titanes tenían de un universo ordenado. Finalmente, llegó a creer que el concepto de orden era una locura, y que el caos y la depravación eran los valores absolutos del oscuro y solitario universo." },
		[1779] = { file = "1779", len = 27.141, text = "Sus compañeros titanes intentaron persuadirlo de su error y apaciguar su trastorno, pero él no creyó en las afirmaciones optimistas de los titanes, considerándolas engaños y artimañas interesadas. Abandonando a sus compañeros para siempre, Sargeras partió en busca de su propio lugar en el universo. Si bien el Panteón lamentaba su partida, los titanes no podían imaginar hasta dónde llegaría su hermano extraviado." },
		[1780] = { file = "1780", len = 19.931, text = "Cuando la locura de Sargeras había consumido los últimos vestigios de su valiente espíritu, llegó a creer que los propios titanes eran los responsables del error de la creación. Finalmente, decidió cambiar las cosas en todo el universo, creando un ejército imparable capaz de destruir todo el universo físico." },
		[1781] = { file = "1781", len = 18.73, text = "Incluso la forma titánica de Sargeras experimentó una deformación ocasionada por la corrupción que había poseído su otrora noble corazón. Sus ojos, sus cabellos y su barba desprendían fuego, y su piel color bronce se cuarteó, revelando un manantial de furia abrasadora." },
		[1782] = { file = "1782", len = 25.391, text = "En su ira, Sargeras echó abajo las prisiones de los eredar y los Nathrezim, liberando a los repugnantes demonios. Estas malvadas criaturas se inclinaban ante la inconmensurable furia del titán oscuro y ofrecieron servirle de todas las formas posibles. Entre las filas de los poderosos eredar, Sargeras eligió a dos campeones para dirigir a su demoníaco ejército de destrucción." },
		[1783] = { file = "1783", len = 19.54, text = "Kil'jaeden el Impostor fue elegido para reclutar a las razas más oscuras del universo y alistarlas en las filas de Sargeras. El segundo Campeón, Archimonde el Rapiñador, fue elegido para dirigir los vastos ejércitos de Sargeras en la lucha contra todo el que se resistiera a la voluntad del titán." },
		[1784] = { file = "1784", len = 33.097, text = "La primera medida de Kil'jaeden fue esclavizar a los vampíricos señores del terror bajo su terrible poder. Los señores del terror actuaban como agentes personales del titán por todo el universo, eligiendo para su maestro razas primitivas susceptibles de ser corrompidas y doblegadas. El primer señor del terror era Tichondrius el Ensombrecedor. Tichondrius era el Soldado perfecto de Kil'jaeden y accedió a propagar el mal abrasador de Sargeras por todos los rincones oscuros del universo." },
		[1785] = { file = "1785", len = 15.203, text = "Archimonde también otorgó poderes a sus propios agentes. Congregando a los malvados señores del infierno y a su bárbaro líder Mannoroth el Destructor, Archimonde preparó una élite de guerra capaz de exterminar todo rastro de vida de la creación." },
		[1786] = { file = "1786", len = 20.48, text = "Cuando Sargeras vio que tenía un ejército poderoso y listo para seguir todas sus órdenes, lo hizo rastrear todos los rincones de la Gran Oscuridad. Llamó a su ejército la Legión Ardiente. Hasta el momento, no se sabe cuántos planetas han sido exterminados por este ejército en su nefasta Cruzada Ardiente por todo el universo." },
		[1787] = { file = "1787", len = 21.473, text = "Desconociendo el empeño de Sargeras en destruir sus grandes hazañas, los titanes continuaron viajando de un planeta a otro, ordenando y sembrando de paz los sitios a los que iban. Durante el trayecto, hallaron un pequeño planeta cuyos habitantes llamaron Azeroth." },
		[1788] = { file = "1788", len = 20.323, text = "Mientras los titanes examinaban el paisaje originario, encontraron a numerosos elementales hostiles. Estos elementales, que veneraban a una raza de seres de insondable maldad conocidos como los dioses antiguos, juraron que echarían a los titanes y protegerían su entorno de la presencia metálica de los invasores." },
		[1789] = { file = "1789", len = 26.566, text = "El Panteón, inquieto por las inclinaciones malignas de los dioses antiguos, declaró la guerra a los elementales y a sus maestros oscuros. Los ejércitos de los dioses antiguos actuaban bajo las órdenes de los tenientes elementales más poderosos: Ragnaros, el Señor de Fuego; Therazane, la Madre Pétrea; Al'Akir, el señor del viento y Neptulon, el Cazamareas." },
		[1790] = { file = "1790", len = 20.846, text = "Sus caóticas fuerzas rugieron por todo el universo y se enfrentaron a los colosales titanes. Aunque los elementales tenían un poder más allá de toda comprensión, sus fuerzas conjuntas no podían detener a los poderosos titanes. Uno a uno, los señores elementales cayeron y sus fuerzas se dispersaron." },
		[1791] = { file = "1791", len = 35.213, text = "Los miembros del Panteón arrasaron los reductos de los dioses antiguos y encadenaron a los cinco dioses malignos en el subsuelo del planeta. Sin el poder de los dioses antiguos para mantener sus furiosos espíritus atados al mundo físico, los elementales fueron desterrados a un plano Abisal, donde lucharían entre sí por toda la eternidad. Tras la partida de los elementales, la naturaleza se apaciguó y en el mundo reinó una pacífica armonía. Al acabar con la amenaza, los titanes se pusieron manos a la obra." },
		[1792] = { file = "1792", len = 31.608, text = "Así, otorgaron poderes a numerosas razas para que les ayudaran a construir un nuevo mundo. Para ayudarles a cavar las insondables cavernas subterráneas, los titanes crearon a los terráneos, similares a los enanos, utilizando mágicas piedras vivientes. Para crear los mares y elevar la tierra por encima del nivel del mar, los titanes crearon a los inmensos, pero gentiles gigantes marinos. Durante varias eras, los titanes moldearon la tierra hasta crear un continente perfecto." },
		[1793] = { file = "1793", len = 30.589, text = "En el centro del continente, los titanes crearon un lago misterioso de energías incandescentes. El lago, llamado Pozo de la Eternidad, constituía la fuente de la vida de todos los seres que habitaban el planeta. Sus poderosas energías alimentaron los huesos de todo ser viviente y sembraron de vida aquel rico suelo. Con el tiempo, plantas, árboles, monstruos y criaturas de todas las clases empezaron a prosperar en el continente primigenio." },
		[1794] = { file = "1794", len = 11.024, text = "En el crepúsculo del último día de sus obras de creación del mundo, los titanes dieron al continente el nombre de Kalimdor: \"tierra de la eterna luz estelar\"." },
		[1795] = { file = "1795", len = 25.26, text = "Satisfechos con el pequeño universo que habían creado, los titanes se prepararon para abandonar Azeroth. No obstante, antes de partir, encomendaron a las grandes especies del planeta la tarea de vigilar Kalimdor, para evitar que fuerzas adversas amenazaran su perfecta armonía. En aquella época, existían muchas clases de dragones." },
		[1796] = { file = "1796", len = 25.495, text = "Sin embargo, había cinco grupos que dominaban a sus hermanos. Estos cinco grupos fueron elegidos por los titanes para guiar al mundo naciente. Los miembros más destacados del Panteón transmitieron parte de su poder a los jefes de los vuelos de dragones. Estos dragones majestuosos (que se describen a continuación) eran conocidos como los Grandes Aspectos o los Dragones Aspectos." },
		[1797] = { file = "1797", len = 23.667, text = "Aman'Thul, Alto Padre del Panteón volcó parte de su poder cósmico sobre el gigantesco dragón de bronce Nozdormu. El Alto Padre otorgó poderes a Nozdormu para que vigilara él mismo el transcurrir del tiempo y supervisara los intrincados caminos de la fortuna y el destino. El estoico y honorable Nozdormu era conocido con el nombre de El Atemporal." },
		[1798] = { file = "1798", len = 25.783, text = "Eonar, guardiana de la vida, otorgó parte de su poder a la gigantesca Alexstrasza. Mucho tiempo después, Alexstrasza recibió el nombre de la Protectora, pues su misión era defender a todas las criaturas vivientes del planeta. Gracias a su suprema sabiduría y a su ilimitada compasión por todos los seres vivos, Alexstrasza fue nombrada reina de los dragones por los de su especie." },
		[1799] = { file = "1799", len = 23.171, text = "Eonar también bendijo a la hermana menor de Alexstrasza, la ágil dragona verde Ysera, con una porción de su influencia sobre la naturaleza. Ysera cayó en un trance eterno, atada al Sueño de la Creación. Conocida como la Soñadora, vigilaría las extensas áreas salvajes del mundo desde su verdeante reino, el Sueño Esmeralda." },
		[1800] = { file = "1800", len = 15.569, text = "Norgannon, titán guardián del conocimiento y mago maestro, cedió al dragón Azul Malygos parte de su vasto poder. A partir de entonces, Malygos fue conocido como el Tejechizos, el guardián de la magia y el arcano oculto." },
		[1801] = { file = "1801", len = 24.242, text = "Khaz'goroth, creador de titanes y forjador del mundo, confirió parte de su extenso poder al poderoso dragón Negro Neltharion. Al bondadoso Neltharion, conocido posteriormente como el Guardián de la Tierra, se le otorgó el dominio de la tierra y los rincones más recónditos del orbe. Encarnaba la fortaleza del mundo y actuaba como gran protector de Alexstrasza." },
		[1802] = { file = "1802", len = 22.021, text = "Con estos poderes, los Cinco Aspectos tenían la misión de defender al mundo en ausencia de los titanes. Cuando los dragones ya estaban preparados para vigilar su creación, los titanes abandonaron Azeroth para siempre. Desafortunadamente, el descubrimiento del nuevo mundo por parte de Sargeras era solo cuestión de tiempo." },
		[1803] = { file = "1803", len = 28.735, text = "El uso temerario de la magia de los Altonato envió ondas energéticas desde el Pozo de la Eternidad hasta la Gran Oscuridad en el más allá. Las ondas expansivas de energía fueron percibidas por terribles mentes de otros mundos. Sargeras, el Gran Enemigo de la vida y Destructor de los Mundos, percibió las poderosas ondas y se sintió atraído por su distante punto de origen." },
		[1804] = { file = "1804", len = 17.946, text = "Al descubrir el mundo primigenio de Azeroth y las energías ilimitadas del Pozo de la Eternidad, Sargeras experimentó un apetito insaciable. El gran dios oscuro del Vacío sin nombre decidió destruir el mundo en ciernes y reclamar las energías como suyas." },
		[1805] = { file = "1805", len = 25.417, text = "Sargeras reunió a su vasta Legión Ardiente y se dirigió hacia el desprevenido mundo de Azeroth. La Legión estaba formada por un millón de demonios que vociferaban, todos procedentes de los reinos más apartados del universo, ávidos de conquista. Los tenientes de Sargeras, Archimonde el Rapiñador y Mannoroth el Destructor, prepararon a sus esbirros infernales para el ataque." },
		[1806] = { file = "1806", len = 26.984, text = "La reina Azshara, inmersa en el terrible éxtasis de la magia, fue víctima del innegable poder de Sargeras y accedió a concederle la entrada en su mundo. Incluso sus siervos Altonato se rindieron ante la inevitable corrupción de la magia y veneraron a Sargeras como a un dios. Para demostrar su lealtad a la Legión, los Altonato ayudaron a su reina a abrir un enorme portal en las profundidades del Pozo de la Eternidad." },
		[1807] = { file = "1807", len = 24.424, text = "Una vez realizados todo los preparativos necesarios, Sargeras inició la devastadora invasión de Azeroth. Los demonios guerreros de la Legión Ardiente invadieron el planeta a través del Pozo de la Eternidad y sitiaron las ciudades dormidas de los elfos de la noche. Dirigidos por Archimonde y Mannoroth, la Legión irrumpió sobre las tierras de Kalimdor, dejando a su paso cenizas y dolor." },
		[1808] = { file = "1808", len = 34.926, text = "Los demonios brujos invocaron malignos infernales que cayeron como mortíferos meteoros sobre las cimas de los templos de Kalimdor. Una banda de matones sanguinarios conocidos como Guardias apocalípticos arrasaron los campos de Kalimdor, asesinando a todo el que se cruzaba en su camino. Manadas de canes manáfagos saquearon el campo sin encontrar resistencia. No obstante, los valientes guerreros kaldorei defendieron su antigua tierra natal, pero poco a poco se vieron obligados a ceder terreno ante el ataque furibundo de la Legión." },
		[1809] = { file = "1809", len = 22.517, text = "Malfurion Tempestira decidió buscar ayuda para su gente asediada. Tempestira, cuyo propio hermano Illidan practicaba la magia de los Altonato, estaba indignado por la creciente corrupción entre estos nobles. Convenciendo a Illidan de que abandonara su peligrosa obsesión, Malfurion buscó a Cenarius y reunió fuerzas para iniciar la resistencia." },
		[1810] = { file = "1810", len = 25.652, text = "La bella y joven sacerdotisa Tyrande accedió a acompañar a los hermanos en nombre de Elune. Aunque Malfurion e Illidan amaban por igual a la idealista sacerdotisa, el corazón de Tyrande pertenecía solo a Malfurion. Illidan sentía celos por el romance de su hermano con Tyrande, pero sabía que su mal de amores no era nada comparado con el dolor que le causaba la adicción a las artes de la magia." },
		[1811] = { file = "1811", len = 19.331, text = "Illidan, que sentía una creciente dependencia de las poderosas energías de la magia, luchó para controlar su abrumador deseo de volver a vaciar las energías del Pozo. No obstante, con el paciente apoyo de Tyrande, pudo dominarse y ayudó a su hermano a encontrar al solitario semidiós Cenarius." },
		[1812] = { file = "1812", len = 22.491, text = "Cenarius, que habitaba en los Claros de Luna sagrados del distante del Monte Hyjal, accedió a ayudar a los elfos de la noche, encontrando a los antiguos dragones y enviándolos en su ayuda. Los dragones, dirigidos por la colosal Alexstrasza, ordenaron a sus poderosos Vuelos enfrentarse a los demonios y a sus infernales maestros." },
		[1813] = { file = "1813", len = 33.228, text = "Cenarius, invocando a los espíritus de los bosques encantados, armó un ejército de antiguos hombres árbol y los condujeron hacia el combate contra la Legión en un temerario asalto terrestre. Cuando los aliados de los elfos de la noche se reunieron en el templo de Azshara y en el Pozo de la Eternidad, se desató la guerra total. A pesar de la fortaleza de sus nuevos aliados, Malfurion y sus compañeros se dieron cuenta de que la Legión no podía ser derrotada solo mediante el poder militar." },
		[1814] = { file = "1814", len = 32.757, text = "Cuando la titánica batalla tuvo lugar en torno a la capital de Azshara, la reina ya estaba esperando la llegada de Sargeras. El señor de la Legión estaba preparándose para atravesar el Pozo de la Eternidad e irrumpió en aquel planeta en guerra. Cuando su sombra inconmensurable se acercó a la superficie del Pozo, Azshara reunió a sus más poderosos seguidores Altonato. La unión de sus poderes mágicos en un solo hechizo fue el único medio capaz de crear una entrada lo suficientemente grande para permitir la entrada a Sargeras." },
		[1815] = { file = "1815", len = 30.772, text = "Cuando la batalla asolaba los campos en llamas de Kalimdor, se produjo un hecho insólito. Los detalles se han perdido en el tiempo, pero se sabe que Neltharion, el Dragón Aspecto de la Tierra, enloqueció en un combate feroz contra la Legión Ardiente. Empezó a desmoronarse al tiempo que las llamas y la ira brotaban de su oscuro pelaje. Adoptando el nombre de Alamuerte, el dragón ardiente se volvió en contra de sus hermanos y retiró a los cinco vuelos de dragones del campo de batalla." },
		[1816] = { file = "1816", len = 24.607, text = "La repentina traición de Alamuerte fue tan destructiva, que las cinco bandadas de dragones jamás se recuperaron. Herida y conmocionada, Alexstrasza y otros nobles dragones se vieron obligados a abandonar a sus mortales aliados. Malfurion y sus compañeros, ahora terriblemente diezmados, apenas sobrevivieron a la matanza que sobrevino a continuación." },
		[1817] = { file = "1817", len = 31.974, text = "Malfurion, convencido de que el Pozo de la Eternidad era el cordón umbilical de los demonios con el mundo físico, insistió en que debía ser destruido. Sus compañeros, que sabían que el Pozo era la fuente de su inmortalidad y sus poderes, estaban horrorizados ante tal perspectiva. No obstante, Tyrande comprendió la sabia teoría de Malfurion y convenció a Cenarius y a sus compañeros a que atacaran el templo de Azshara y encontraran la manera de cerrar el Pozo por el bien de todos." },
		[1828] = { file = "1828", len = 28.787, text = "Los escasos elfos de la noche que sobrevivieron a la explosión se subieron a rústicas balsas y lentamente se dirigieron a la única masa de tierra visible. De algún modo, por la gracia de Elune, Malfurion, Tyrande y Cenarius sobrevivieron al Gran Cataclismo. Los maltrechos héroes guiaron a sus compañeros supervivientes y se establecieron en un nuevo lugar." },
		[1829] = { file = "1829", len = 22.126, text = "Mientras viajaban en silencio, examinaron los restos de la catástrofe y comprendieron que sus pasiones habían sido la causa de la destrucción del planeta. Aunque Sargeras y su Legión habían sido aniquilados por la destrucción del Pozo, Malfurion y sus compañeros sobrevivieron para reflexionar sobre el terrible precio de la victoria." },
		[1830] = { file = "1830", len = 18.364, text = "Por su parte, muchos Altonato salieron ilesos del cataclismo. Se dirigieron a las costas de la nueva tierra, junto con los otros elfos de la noche. Aunque Malfurion desconfiaba de los Altonato, estaba tranquilo porque no podían causar verdadero daño sin las energías del Pozo." },
		[1831] = { file = "1831", len = 35.448, text = "Cuando los elfos de la noche arribaron a las costas de la nueva tierra, advirtieron que Hyjal, la montaña sagrada, había sobrevivido a la catástrofe. Con la intención de establecer un nuevo hogar para todos, Malfurion y los elfos de la noche subieron por las laderas del Monte Hyjal y llegaron a la cima azotada por el viento. Al descender en la boscosa hondonada, entre los enormes picos de las montañas encontraron un pequeño lago de aguas mansas. Aterrorizados, descubrieron que las aguas del lago estaban contaminadas por la magia." },
		[1832] = { file = "1832", len = 20.663, text = "Illidan, que también había sobrevivido al Diluvio, había subido a la cima del Monte Hyjal mucho antes que Malfurion y sus elfos de la noche. En su locura por conservar un reducto para la magia en el mundo, Illidan volcó en el lago de la montaña el contenido de sus viales: las preciosas aguas del Pozo de la Eternidad." },
		[1833] = { file = "1833", len = 31.373, text = "Las potentes energías del Pozo ardieron rápidamente y se fusionaron para crear un nuevo Pozo de la Eternidad. El exultante Illidan, que creía que el nuevo Pozo era un regalo para las futuras generaciones, se sorprendió al advertir la ira de Malfurion. Este explicó a su hermano que la magia era inherentemente caótica y que su uso conduciría inevitablemente a la propagación de la corrupción y la guerra. No obstante, Illidan se negó a renunciar a sus poderes mágicos." },
		[1834] = { file = "1834", len = 31.765, text = "Conociendo de sobra hacia dónde conducirían los implacables planes de Illidan, Malfurion decidió neutralizar de una vez por todas a su hermano enloquecido por el poder. Con la ayuda de Cenarius, Malfurion encerró a Illidan en un gran túmulo subterráneo, en el que permanecería encadenado e impotente hasta el final de sus días. Para garantizar el confinamiento de su hermano, Malfurion encargó a la joven celadora Maiev Cantosombrío la tarea de vigilar personalmente a Illidan." },
		[1835] = { file = "1835", len = 27.324, text = "Preocupado ante la certeza de que la destrucción del nuevo Pozo conllevaría una catástrofe aún mayor, los elfos de la noche decidieron dejarlo en su lugar. No obstante, Malfurion declaró que nadie volvería jamás a practicar las artes de la magia. Bajo la mirada atenta de Cenarius, empezaron a estudiar las antiguas artes de los druidas con el propósito de sanar el planeta herido y replantar sus bosques amados en la base del Monte Hyjal." },
		[1836] = { file = "1836", len = 28.552, text = "Durante muchos años, los elfos de la noche trabajaron incesantemente para reconstruir su antigua tierra natal. Abandonando sus templos destruidos a merced de la maleza, construyeron sus nuevos hogares en medio de verdeantes árboles y frescas colinas junto al Monte Hyjal. Con el tiempo, los dragones que habían sobrevivido al Gran Cataclismo salieron de sus secretas moradas." },
		[1837] = { file = "1837", len = 22.178, text = "Alexstrasza la roja, Ysera la verde y Nozdormu el broncíneo descendieron por los serenos claros de los druidas y supervisaron los frutos del trabajo de los elfos de la noche. Malfurion, que se había convertido en un archidruida de inmenso poder, saludó a los magníficos dragones y les habló de la creación del nuevo Pozo de la Eternidad." },
		[1838] = { file = "1838", len = 23.432, text = "Los grandes dragones, alarmados al escuchar tan nefasta noticia, creyeron que, mientras el Pozo de la Eternidad existiera, la Legión podría volver con el propósito de destruir el planeta nuevamente. Malfurion y los tres dragones hicieron un pacto para proteger el Pozo y asegurarse de que los agentes de la Legión Ardiente jamás volvieran a poner pie en el planeta." },
		[1839] = { file = "1839", len = 22.909, text = "Alexstrasza la Protectora, colocó una bellota encantada en el corazón del Pozo de la Eternidad. La bellota, activada por las poderosas aguas mágicas, brotó rápidamente hasta convertirse en un árbol colosal. Las potentes raíces del árbol se extendieron desde las aguas del Pozo y la verdeante copa abarcó la inmensidad del cielo." },
		[1840] = { file = "1840", len = 20.715, text = "El árbol será un símbolo eterno del vínculo de los elfos de la noche con la naturaleza y sus energías portadoras de vida se extenderán por todas partes para curar a los habitantes del planeta. Los elfos de la noche dieron al Árbol del Mundo el nombre de Nordrassil, cuyo significado era \"corona de los cielos\" en su lengua nativa." },
		[1841] = { file = "1841", len = 12.33, text = "Nozdormu el Atemporal lanzó un encantamiento sobre el Árbol del Mundo que garantizaría que, siempre que el árbol estuviese en pie, los elfos de la noche jamás envejecerían ni enfermarían." },
		[1842] = { file = "1842", len = 24.764, text = "Ysera la Soñadora también lanzó un hechizo sobre el árbol, vinculándolo a su propio reino, la dimensión etérea conocida como el Sueño Esmeralda. El Sueño Esmeralda, un mundo espiritual eternamente cambiante, existía más allá de las fronteras del mundo físico. Desde el Sueño, Ysera regulaba las mareas de la naturaleza y la evolución del mundo propiamente dicho." },
		[1843] = { file = "1843", len = 31.138, text = "Los druidas de los elfos de la noche, incluyendo al propio Malfurion, crearon un vínculo con el Sueño a través del Árbol del Mundo. En un pacto místico, los druidas aceptaron dormir simultáneamente durante siglos para que sus espíritus pudieran recorrer las infinitas sendas de los sueños de Ysera. Aunque los druidas sufrían ante la perspectiva de perder tantos años de sus vidas entregándose a la hibernación, mantuvieron desinteresadamente su pacto con Ysera." },
		[1844] = { file = "1844", len = 33.358, text = "Con el transcurso de los siglos, la nueva sociedad de los elfos de la noche se fortaleció y se expandió por el bosque en ciernes conocido como Vallefresno. Muchas de las criaturas y especies que abundaban antes del Gran Cataclismo, como los fúrbolgs y los jabaespines, reaparecieron y prosperaron en aquellas tierras. Bajo la benévola mirada de los druidas, los elfos de la noche disfrutaron de una era de paz y tranquilidad sin precedentes bajo las estrellas." },
		[1845] = { file = "1845", len = 31.425, text = "No obstante, muchos de los Altonato supervivientes estaban cada vez más inquietos. Al igual que Illidan, tuvieron que retirarse ante la pérdida de sus codiciados poderes. Se vieron tentados a extraer las energías del Pozo de la Eternidad y reiniciar sus prácticas en el terreno de la magia. Dath'Remar, el extrovertido líder de los Altonato, empezó a burlarse abiertamente de los druidas, llamándolos cobardes por negarse a utilizar la magia que consideraban suya por derecho." },
		[1846] = { file = "1846", len = 20.872, text = "Malfurion y los druidas hicieron caso omiso a los argumentos de Dath'Remar y advirtieron a los Altonato que cualquier uso de la magia sería castigado con la muerte. En un insolente y desventurado intento de convencer a los druidas de revocar sus leyes, Dath'Remar y sus seguidores desataron una terrible tormenta mágica sobre Vallefresno." },
		[1847] = { file = "1847", len = 33.62, text = "Los druidas no podían soportar la idea de ver morir a los suyos, por lo que decidieron desterrar a los insensatos Altonato de sus tierras. Dath'Remar y sus seguidores, satisfechos por librarse al fin de sus primos conservadores, embarcó en varios navíos especialmente diseñados y se fue a recorrer los mares. Si bien ninguno de ellos sabía lo que les aguardaba al otro lado de las aguas de la tempestuosa Vorágine, deseaban fundar un nuevo territorio en donde poner en práctica sus codiciados poderes con total impunidad." },
		[1848] = { file = "1848", len = 27.481, text = "Los Altonato o Quel'dorei, como Azshara los había llamado en épocas pasadas, desembarcaron en la tierra del este llamada Lordaeron por sus habitantes. Planearon construir allí su propio reino mágico llamado Quel'Thalas, rechazando los preceptos de los elfos de la noche que los hacía venerar a la luna y a desarrollar actividades nocturnas. De ahí en adelante, adoraron al sol y se llamaron a sí mismos altos elfos." },
		[1849] = { file = "1849", len = 22.282, text = "Con la partida de sus caprichosos primos, los elfos de la noche volvieron a centrarse en la protección de su tierra encantada. Los druidas, conscientes de que se acercaba el momento de hibernar, se prepararon para su largo sueño y abandonaron temporalmente a sus seres queridos y familiares." },
		[1850] = { file = "1850", len = 23.458, text = "Tyrande, que se había convertido en la suma sacerdotisa de Elune, pidió a su amado Malfurion que no la abandonara para partir al Sueño Esmeralda de Ysera. Pero Malfurion ponía en juego su honor si no penetraba en las cambiantes sendas de los sueños, de modo que se despidió de la sacerdotisa y le juró que no se separarían jamás si mantenían vivo su amor." },
		[1851] = { file = "1851", len = 27.35, text = "Sola, ante la perspectiva de proteger a Kalimdor de los peligros que acechaban al nuevo mundo, Tyrande reunió a un poderoso ejército de hermanas elfas de la noche. Las intrépidas y diestras guerreras, decididas a defender Kalimdor, eran conocidas como las Centinelas. Aunque preferían patrullar los frondosos bosques de Vallefresno ellas mismas, contaban con muchos aliados a los que podían recurrir en momentos difíciles." },
		[1852] = { file = "1852", len = 23.223, text = "El semidiós Cenarius permaneció cerca de los Claros de la Luna del Monte Hyjal. Sus hijos, conocidos como los Guardianes de la Arboleda, vigilaron de cerca a los elfos de la noche y ayudaron constantemente a las Centinelas a mantener la paz en aquellas tierras. Incluso las tímidas hijas de Cenarius, o dríades, salían al exterior con mayor frecuencia." },
		[1853] = { file = "1853", len = 30.746, text = "La tarea de vigilar Vallefresno mantuvo ocupada a Tyrande, pero sin Malfurion a su lado, apenas sonreía. A medida que los siglos transcurrieron, los druidas seguían inmersos en su sueño y el temor de Tyrande creció ante la posibilidad de una segunda invasión demoníaca. No la abandonaba la turbadora sensación de que la Legión Ardiente seguía merodeando al otro lado de la Gran Oscuridad, planeando su venganza contra los elfos de la noche y el reino de Azeroth." },
		[1854] = { file = "1854", len = 30.929, text = "Los elfos nobles, dirigidos por Dath'Remar, abandonaron Kalimdor y desafiaron las tormentas de la Vorágine. Sus flotas recorrieron las ruinas del mundo durante muchos años, descubriendo a su paso nuevos misterios y reinos perdidos. Dath'Remar, que había adoptado el nombre de Caminante del Sol (o \"el que camina de día\"), buscó lugares que resultaran aptos para construir en ellos un nuevo hogar para su gente." },
		[1855] = { file = "1855", len = 34.064, text = "Su flota finalmente desembarcó en las playas del reino cuyos habitantes denominaron Lordaeron. Tomando posiciones en tierra, los elfos nobles fundaron su sede en los tranquilos Claros de Tirisfal. Transcurridos unos años, muchos de ellos empezaron a enloquecer. Existía la teoría de que bajo aquellas tierras se ocultaba una fuerza maligna, pero estos rumores nunca se confirmaron. Los elfos nobles llevaron su campamento a otra parte y se dirigieron al norte en dirección a otras tierras ricas en energías naturales." },
		[1856] = { file = "1856", len = 26.096, text = "Durante el trayecto de los elfos nobles por las escarpadas montañas de Lordaeron, el viaje se hizo cada vez más peligroso. Puesto que fueron totalmente privados de las energías vivificadoras del Pozo de la Eternidad, muchos de ellos enfermaron a causa del gélido clima o murieron de hambre. Sin embargo, el hecho más desconcertante era que ya no eran inmortales ni inmunes a los elementos." },
		[1857] = { file = "1857", len = 25.809, text = "También encogieron de tamaño y su piel perdió la tonalidad violeta que los caracterizaba. A pesar de las penurias, conocieron maravillosas criaturas jamás vistas en Kalimdor. Asimismo, encontraron tribus de humanos primitivos que cazaban en los antiguos bosques. No obstante, la mayor amenaza que los acechaba la constituían los voraces y maliciosos trols del bosque de Zul?Aman." },
		[1858] = { file = "1858", len = 31.477, text = "Estos trols con la piel recubierta de musgo tenía el poder de regenerar sus miembros mutilados y curar graves heridas físicas, pero conformaban, sin duda, una raza bárbara y maligna. El Imperio Amani se extendió por la mayor parte del territorio del norte de Lordaeron y sus trols lucharon incansablemente para mantener a los forasteros alejados de sus tierras. Los elfos desarrollaron una profunda aversión contra los despiadados trols y los mataban siempre que podían." },
		[1859] = { file = "1859", len = 35.239, text = "Transcurridos muchos años, los elfos nobles finalmente encontraron una tierra que les recordaba a Kalimdor. En el interior del bosque que había al norte del continente, fundaron el reino de Quel?Thalas y prometieron crear un vasto imperio que eclipsaría al de sus primos kaldorei. Desafortunadamente, pronto descubrieron que Quel?Thalas había sido fundada sobre una antigua ciudad trol que esta raza aún consideraba sagrada. Casi de inmediato, los trols empezaron a atacar en masa los asentamientos de los elfos." },
		[1860] = { file = "1860", len = 28.97, text = "Los tozudos elfos, que no estaban dispuestos a ceder su nuevo territorio, utilizaron la magia que habían obtenido del Pozo de la Eternidad y mantuvieron a raya a los salvajes trols. Liderados por Dath'Remar, pudieron derrotar a las bandas de guerra Amani, que eran diez veces más numerosas. Algunos elfos, que recordaban las antiguas advertencias de los kaldorei, temían que el uso de la magia pudiera atraer la atención de la desterrada Legión Ardiente." },
		[1861] = { file = "1861", len = 27.063, text = "Por ello, decidieron proteger sus tierras con una barrera que les permitiera seguir desarrollando sus encantamientos. Construyeron una serie de runas monolíticas en varios puntos de los alrededores de Quel?Thalas, marcando las fronteras de la barrera mágica. Las runas no solo encubrían la magia de los elfos ante amenazas extradimensionales, sino que también les ayudaban a ahuyentar a las supersticiosas bandas trol." },
		[1862] = { file = "1862", len = 27.324, text = "Transcurrido cierto tiempo, Quel'Thalas se convirtió en un bello monumento a los esfuerzos de los elfos nobles y a sus hazañas mágicas. Sus hermosos palacios fueron construidos siguiendo el mismo estilo arquitectónico que el de las antiguas salas de Kalimdor, si bien se entremezclaban con la topografía natural de la tierra. Quel'Thalas se había convertido en una joya que los elfos siempre habían deseado crear." },
		[1863] = { file = "1863", len = 31.634, text = "A continuación, se fundó la Asamblea de Lunargenta para gobernar Quel?Thalas, si bien la dinastía de los Caminante del Sol conservaba cierto poder político. Compuesto por siete elfos nobles mayores, la Asamblea se encargó de velar por la seguridad de la tierra de los elfos y de sus gentes. Rodeados por su barrera protectora, los elfos nobles hicieron caso omiso a las advertencias de los kaldorei y continuaron usando la magia con total libertad en todos los aspectos de sus vidas." },
		[1864] = { file = "1864", len = 28.682, text = "Durante unos cuatro mil años, los elfos nobles vivieron pacíficamente en su reino aislado y protegido. No obstante, los vengativos trols no se conformaban fácilmente con su derrota. Planearon su venganza en las profundidades de los bosques y esperaron a que sus tropas crecieran. Finalmente, un poderoso ejército de trols partió de los oscuros bosques y, nuevamente, sitiaron las relucientes cumbres de Quel?Thalas." },
		[1865] = { file = "1865", len = 23.014, text = "Cuando los elfos nobles hacían frente al feroz ataque de los trols, los dispersos humanos nómadas de Lordaeron lucharon por consolidar sus propias tierras tribales. Las antiguas tribus humanas atacaban asentamientos hermanos sin contemplar valores tales como la unificación racial o el honor." },
		[1866] = { file = "1866", len = 16.353, text = "No obstante, una tribu conocida como los arathi advirtió que los trols se estaban convirtiendo en una amenaza demasiado importante como para ignorarla. Los arathi deseaban dominar a las demás tribus para unificar fuerzas contra el ejército trol." },
		[1867] = { file = "1867", len = 23.432, text = "En seis años, los astutos arathi se mostraron más hábiles y derrotaron a las tribus rivales. Tras cada victoria, los arathi ofrecieron paz e igualdad al pueblo conquistado, obteniendo la lealtad de los pueblos derrotados. Finalmente, la tribu de los arathi conquistó numerosas tribus dispares, logrando que su ejército creciera de forma significativa." },
		[1868] = { file = "1868", len = 32.575, text = "Confiando en su capacidad de contener a las bandas de los trols con sus tropas o, incluso, con los aislados elfos si era necesario, los señores de la guerra arathi decidieron construir una poderosa ciudad fortificada en las tierras del sur de Lordaeron. La ciudad estado, llamada Strom, se convirtió en la capital de la nación arathi, Arathor. A medida que Arathor prosperaba, los humanos que habitaban en todo el continente viajaban hacia el sur para garantizar la protección y la seguridad de Strom." },
		[1869] = { file = "1869", len = 35.056, text = "Unidos bajo la misma bandera, las tribus humanas desarrollaron una cultura sólida y optimista. Thoradin, rey de Arathor, sabía que los elfos misteriosos de las tierras del norte padecían el constante asedio de los trols, pero se negó a arriesgar la seguridad de su gente en defensa de los desconocidos. Varios meses después, llegaron rumores del norte sobre una supuesta derrota de los elfos. De no ser porque los embajadores de Quel’Thalas llegaron agotados a Strom, Thoradin no se habría percatado de la magnitud de la amenaza de los trols." },
		[1870] = { file = "1870", len = 25.234, text = "Los elfos informaron a Thoradin acerca del tamaño de los ejércitos de los trols, asegurando que una vez que estos hubieran destruido Quel’Thalas, irían a las tierras del sur para atacarlas. Los elfos, desesperados, ante la necesidad real de ayuda militar, accedieron a enseñar a unos cuantos humanos escogidos a utilizar la magia a cambio de su ayuda para combatir a las bandas trol." },
		[1871] = { file = "1871", len = 13.819, text = "Thoradin, receloso ante cualquier tipo de magia, aceptó ayudar a los elfos. Casi de inmediato, los hechiceros élficos llegaron a Arathor y empezaron a instruir a un grupo de humanos en las artes de la magia." },
		[1872] = { file = "1872", len = 34.586, text = "Los elfos observaron que, si bien los humanos eran torpes por naturaleza en el uso de la magia, mostraban, por el contrario, una natural afinidad hacia todo lo mágico. Cien hombres adquirieron conocimientos básicos sobre los secretos mágicos de los elfos: solo los que eran absolutamente necesarios para combatir a los trols. Convencidos de que sus discípulos humanos estaban preparados para ayudarles en la lucha, los elfos abandonaron Strom y viajaron hacia el norte junto con los poderosos ejércitos del rey Thoradin." },
		[1873] = { file = "1873", len = 24.712, text = "Los ejércitos unidos de los elfos y los humanos se enfrentaron a las incontenibles bandas de guerra trol al pie de las Montañas de Alterac. La batalla duró varios días, pero los constantes ejércitos de Arathor no se cansaban ni cedían un ápice de terreno al ataque trol. Los señores élficos consideraron que había llegado el momento de liberar los poderes de su magia sobre el enemigo." },
		[1874] = { file = "1874", len = 17.606, text = "Los cien magos humanos y la multitud de hechiceros élficos invocaron la furia de los cielos, prendiendo fuego a los ejércitos de los trols. Los fuegos elementales impidieron que los trols regeneraran sus heridas y quemaron sus cuerpos torturados desde las entrañas hasta la superficie." },
		[1875] = { file = "1875", len = 36.885, text = "Cuando los ejércitos trol se desmoronaron e intentaron huir, las tropas de Thoradin les dieron caza y aniquilaron hasta el último de los Soldados trol. Los trols jamás se recuperarían por completo de su derrota y la historia jamás volvería a presenciar su ascenso como nación. Seguros de que Quel'Thalas estaba a salvo de la destrucción, los elfos prometieron lealtad y amistad hacia la nación de Arathor y el linaje de su rey, Thoradin. Los humanos y los elfos establecerían una relación pacífica durante los próximos siglos.|n" },
		[1876] = { file = "1876", len = 17.92, text = "Sin la presencia de los trols en las tierras del norte, los elfos de Quel'Thalas centraron sus esfuerzos en reconstruir su gloriosa tierra. Los ejércitos victoriosos de Arathor volvieron a casa, en las tierras del sur de Strom." },
		[1877] = { file = "1877", len = 27.272, text = "La sociedad humana de Arathor creció y prosperó, no obstante Thoradin, temeroso de que su reino se desintegrase al adquirir un tamaño demasiado grande, afirmó que Strom sería el centro del imperio de Arathor. Tras muchos años de paz y crecimiento económico, el poderoso Thoradin murió en edad avanzada, ofreciendo a las jóvenes generaciones de Arathor libertad para expandir el imperio más allá de las fronteras de Strom." },
		[1878] = { file = "1878", len = 32.157, text = "Los cien magos originales, que fueron instruidos en la magia por los elfos, ampliaron sus poderes y estudiaron con mayor detenimiento las disciplinas místicas de los hechizos. Estos magos, inicialmente escogidos por su fuerza de voluntad y nobleza de espíritu, siempre habían practicado su magia con cuidado y responsabilidad. No obstante, transmitieron sus secretos y poderes a una nueva generación que no tenía idea de los rigores de la guerra o del principio de moderación." },
		[1879] = { file = "1879", len = 8.986, text = "Estos jóvenes magos empezaron a practicar la magia para darle un uso personal, sin tener en cuenta su responsabilidad hacia sus congéneres." },
		[1880] = { file = "1880", len = 29.309, text = "A medida que el imperio creció y adquirió nuevas tierras, los jóvenes magos también se establecieron en las tierras del sur. Mediante el uso de sus poderes místicos, los magos protegían a sus hermanos de las criaturas salvajes de la tierra e hicieron posible la construcción de nuevas ciudades estado en medio de la jungla. No obstante, a medida que aumentaba su poder, los magos se hicieron cada vez más engreídos y se aislaron del resto de la sociedad." },
		[1881] = { file = "1881", len = 23.51, text = "La segunda ciudad estado de Arathor, Dalaran, fue fundada en las tierras del norte de Strom. Muchos magos noveles abandonaron los confines de Strom y viajaron a Dalaran, en donde esperaban usar sus poderes con mayor libertad. Así, emplearon sus habilidades para construir las cimas encantadas de Dalaran y centrarse en la continuación de sus estudios." },
		[1882] = { file = "1882", len = 19.853, text = "Los ciudadanos de Dalaran toleraron los esfuerzos de los magos y consolidaron una economía ágil bajo la protección de sus defensores magos. Sin embargo, a medida que aumentaba el número de magos que ponían en práctica sus artes, el manto de realidad que rodeaba Dalaran empezó a resquebrajarse." },
		[1883] = { file = "1883", len = 24.111, text = "Los siniestros agentes de la Legión Ardiente, que habían sido desterrados durante la desaparición del Pozo de la Eternidad, se interesaron nuevamente por el planeta, gracias a la atención que en ellos despertaron los hechizos de los magos de Dalaran. Si bien estos demonios relativamente débiles no manifestaban su poder, sí sembraban la confusión y el caos en las calles de Dalaran." },
		[1884] = { file = "1884", len = 22.857, text = "La mayoría de estos encuentros demoníacos eran acontecimientos aislados, de manera que los magócratas en el poder hicieron lo que pudieron para mantener estas ceremonias en secreto. Los magos más poderosos fueron enviados a capturar a los escurridizos demonios, pero muchas veces se vieron superados por los solitarios agentes de la imponente Legión." },
		[1885] = { file = "1885", len = 36.18, text = "Transcurridos unos cuantos meses, los supersticiosos campesinos empezaron a sospechar que sus hechiceros gobernantes les estaban ocultando algo terrible. Rumores de revolución empezaron a extenderse por las calles de Dalaran, al tiempo que los ciudadanos paranoicos cuestionaban los motivos y las prácticas de los magos a quienes habían admirado en el pasado. Los magócratas, temiendo que los campesinos se levantarían y que Strom actuaría en su contra, acudieron al único grupo que consideraron capaz de comprender su particular problema: los elfos." },
		[1886] = { file = "1886", len = 32.392, text = "Tras conocer las actividades demoníacas de los magócratas en Dalaran, los elfos rápidamente enviaron a sus zahoríes más poderosos hacia tierras humanas. Los zahoríes élficos estudiaron las corrientes energéticas que fluían en Dalaran y realizaron informes detallados sobre toda la actividad demoníaca que encontraron. Concluyeron que, si bien solo había unos cuantos demonios dispersos por aquel territorio, la Legión sí constituía una verdadera amenaza si los humanos continuaban utilizando poderes mágicos." },
		[1887] = { file = "1887", len = 26.305, text = "El Consejo de Lunargenta, que gobernaba sobre los elfos de Quel'Thalas, firmó un pacto secreto con los señores magócratas de Dalaran. Los elfos contaron a los magócratas la historia del antiguo continente de Kalimdor y la Legión Ardiente, historia que aún amenazaba al planeta. Advirtieron a los humanos que, siempre que utilizaran la magia, debían proteger a sus ciudadanos de los agentes malvados de la Legión." },
		[1888] = { file = "1888", len = 31.66, text = "Los magócratas propusieron la idea de asignar poderes a un solo Campeón mortal para librar una guerra secreta interminable contra la Legión. Resaltaron que la mayor parte de los humanos no debía saber nada acerca de los Guardianes o de la amenaza de la Legión, para evitar disturbios causados por el miedo y la paranoia. Los elfos aceptaron la propuesta y fundaron una sociedad secreta para supervisar la elección del Guardián, ayudando a contener el aumento del caos en el mundo." },
		[1889] = { file = "1889", len = 30.981, text = "La sociedad mantuvo sus reuniones secretas en los Claros de Tirisfal, donde los elfos nobles se habían establecido por primera vez en Lordaeron. Así, llamaron a su secta secreta los Guardianes de Tirisfal. Los campeones mortales que fueron elegidos por los Guardianes recibieron increíbles poderes élficos y humanos. Si bien solo podía existir un Guardián cada vez, su poder era tan inconmensurable que podía responder a los ataques de la Legión sin ayuda de nadie en cualquier parte del planeta." },
		[1890] = { file = "1890", len = 21.368, text = "El poder del Guardián era tal, que solo el Consejo de Tirisfal podía elegir a los potenciales sucesores. Cada vez que un Guardián envejecía demasiado, o se cansaba de guardar los secretos de guerra contra el caos, el Consejo elegía a un nuevo Campeón y, bajo un estricto control, transmitían formalmente los poderes del Guardián a su nuevo agente." },
		[1891] = { file = "1891", len = 22.361, text = "Con el transcurso de las generaciones, los Guardianes defendieron a la humanidad de la invisible amenaza de la Legión Ardiente por todo el territorio de Arathor y Quel'Thalas. Arathor creció y prosperó, al tiempo que el uso de la magia se extendió por todo el imperio. Mientras tanto, los Guardianes vigilaban cuidadosamente cualquier señal de actividad demoníaca." },
		[1892] = { file = "1892", len = 25.051, text = "En la antigüedad, cuando los titanes partieron de Azeroth, sus hijos, conocidos como los terráneos, continuaron dando forma y vigilando los oscuros recovecos del planeta. Los terráneos eran indiferentes a los asuntos de las razas que poblaban la superficie y solo les interesaba sondear las lóbregas profundidades de la tierra." },
		[1893] = { file = "1893", len = 37.956, text = "Los terráneos quedaron muy afectados tras la implosión del Pozo de la Eternidad que había destruido el planeta. Al no poder recuperarse del dolor causado por la destrucción de la tierra, los terráneos perdieron gran parte de su identidad y se encerraron en las cámaras de piedra en las que habían sido creados inicialmente. Uldaman, Uldum, Ulduar... eran los nombres de las antiguas ciudades de los titanes que los terráneos habían construido al principio. Enterrados en las profundidades del planeta, los terráneos descansaron en paz durante casi ocho mil años." },
		[1894] = { file = "1894", len = 26.357, text = "Aunque se desconoce qué fue lo que los despertó, los terráneos confinados en Uldaman finalmente despertaron de su sueño auto impuesto. Se dieron cuenta de que habían cambiado significativamente durante la hibernación. Sus rocosos pelajes se habían suavizado, convirtiéndose en tersas pieles, mientras que sus poderes sobre la piedra y la tierra habían menguado. Se habían convertido en criaturas mortales." },
		[1895] = { file = "1895", len = 17.397, text = "Los últimos terráneos se hicieron llamar enanos y abandonaron las salas de Uldaman para aventurarse en el mundo de los seres despiertos. Adormecidos aún por la paz y las maravillas de las profundidades, fundaron un vasto reino bajo la montaña más alta de la tierra." },
		[1896] = { file = "1896", len = 19.931, text = "Llamaron a su tierra Khaz Modan, o \"Montaña de Khaz\", en honor a su creador, el titán Khaz'goroth. Al construir un altar para su padre titán, los enanos crearon una gran fragua en el corazón de la montaña. Por ello, la ciudad que creció en torno a la fragua recibió el nombre de Forjaz." },
		[1897] = { file = "1897", len = 16.17, text = "Los enanos, fascinados por la talla de la piedra y las gemas, se dedicaron a excavar las montañas vecinas para encontrar ricos y preciosos minerales. Satisfechos con sus trabajos subterráneos, permanecían aislados de lo que acontecía a sus vecinos de la superficie." },
		[1898] = { file = "1898", len = 26.358, text = "Strom continuaba siendo el centro de Arathor, pero como ocurrió con Dalaran, aparecieron nuevas ciudades estado por todo el continente de Lordaeron. Gilneas, Alterac y Kul Tiras fueron las primeras ciudades estado y, aunque cada una tenía sus propias costumbres y sistemas de intercambio, todas se sometían a la autoridad indiscutible de Strom." },
		[1899] = { file = "1899", len = 21.682, text = "Bajo la atenta mirada de la Orden de Tirisfal, Dalaran se convirtió en el centro principal de enseñanza de la magia en todo el territorio. Los magócratas, que gobernaban Dalaran, fundaron el Kirin Tor, una secta especializada, encargada de catalogar e investigar cada hechizo, artefacto y objeto mágico conocido hasta el momento." },
		[1900] = { file = "1900", len = 32.888, text = "Gilneas y Alterac se convirtieron en fuertes defensores de Strom y formaron poderosos ejércitos que exploraron las tierras montañosas del sur de Khaz Modan. Durante este periodo, los humanos se encontraron por vez primera con la antigua raza de los enanos y viajaron a su cavernosa ciudad subterránea de Forjaz. Los humanos y los enanos compartieron muchos secretos acerca de la metalurgia y la ingeniería, al tiempo que descubrieron que sentían un amor común por las batallas y la narración de historias." },
		[1901] = { file = "1901", len = 28.395, text = "La ciudad estado de Kul'Tiras, fundada sobre una gran isla situada al sur de Lordaeron, desarrolló una próspera economía basada en la pesca y la industria naviera. Con el tiempo, Kul'Tiras armó una poderosa flota de buques mercantes que navegaron recorriendo las tierras conocidas en busca de productos exóticos para comerciar con ellos. Si bien la economía de Arathor floreció, sus elementos más poderosos comenzaron a desintegrarse." },
		[1902] = { file = "1902", len = 27.481, text = "Con el tiempo, los señores de Strom intentaron trasladar sus propiedades a las exuberantes tierras del norte de Lordaeron, abandonando las áridas tierras del sur. Los herederos del rey Thoradin, los últimos descendientes de la línea de sangre arathi, alegaron que Strom no debía ser abandonada y, de esta manera, provocaron el descontento de la mayor parte de la ciudadanía, ya que la mayoría estaba ansiosa por marcharse." },
		[1903] = { file = "1903", len = 29.44, text = "Los señores de Strom, intentando lograr la pureza y la iluminación en el norte virgen, decidieron abandonar su antigua ciudad. Hacia el norte, lejos de Dalaran, los señores de Strom construyeron una nueva ciudad estado que denominaron Lordaeron. Todo el continente adoptó este nombre a partir de la denominación de la ciudad estado. Lordaeron se convirtió en la meca de los peregrinos religiosos y de todos aquellos que buscaban la paz interior y la seguridad." },
		[1904] = { file = "1904", len = 29.44, text = "Los descendientes de los arathi, abandonados tras los desmoronados muros de la vieja Strom, decidieron marcharse hacia el sur, más allá de las rocosas montañas de Khaz Modan. Finalmente, su viaje terminó tras largas jornadas y se asentaron en la región norteña del continente que denominaran Azeroth. En un fértil valle fundaron el reino de Ventormenta, que rápidamente se transformó en una potencia autosuficiente por derecho propio." },
		[1905] = { file = "1905", len = 34.691, text = "Los escasos guerreros que quedaron en Strom decidieron guardar los viejos muros de su ciudad. Strom ya no era el centro del imperio, sino que se convirtió en una nueva nación conocida como Stromgarde. Si bien cada una de las ciudades-estado alcanzó la prosperidad por sí misma, el imperio de Arathor terminó por desintegrarse. A medida que cada nación desarrolló sus propias costumbres y creencias, comenzaron a estar cada vez ms separadas una de la otra. Finalmente, la visión del rey Thoradin acerca de una humanidad unificada se desvaneció." },
		[1906] = { file = "1906", len = 26.096, text = "Mientras las políticas y las rivalidades de las siete naciones humanas sufrían muchos altibajos, la línea de los Guardianes mantuvo una vigilancia constante contra el caos. Hubo muchos Guardianes, pero solo uno tenía los poderes mágicos de Tirisfal en cada momento. Una de los últimas Guardianas de la era se distinguió por su valiente lucha contra la sombra." },
		[1907] = { file = "1907", len = 17.711, text = "Aegwynn, una humana muy temperamental, obtuvo la aprobación de la orden que le concedió el manto de la custodia. Aegwynn luchó valerosamente para dar caza y erradicar a los demonios allí donde los encontró, pero, a menudo, cuestionó la autoridad del Consejo de Tirisfal." },
		[1908] = { file = "1908", len = 31.321, text = "Creía que los elfos antiguos y los elfos ancianos que presidían el consejo eran demasiado rígidos en su forma de pensar y que, a la hora de terminar de una vez por todas con el conflicto contra el caos, resultaban cortos de miras. Mostrándose impaciente cuando se trataba de discutir largamente, siempre quería probarse a sí misma ante sus pares y sus superiores y, como resultado de todo ello, frecuentemente escogió el valor antes que la sabiduría en situaciones cruciales." },
		[1909] = { file = "1909", len = 28.917, text = "A medida que creció su dominio sobre el poder cósmico de Tirisfal, Aegwynn se dio cuenta de la existencia de un gran número de poderosos demonios que acechaban la helada parte norte del continente de Rasganorte. Viajando al distante norte, Aegwynn rastreó a los demonios en las montañas. Allí cayó en la cuenta de que los demonios estaban cazando a uno de los últimos Vuelos supervivientes, despojando a las antiguas criaturas de su magia innata." },
		[1910] = { file = "1910", len = 25.731, text = "Los poderosos dragones, que habían huido de las amenazantes sociedades mortales, se encontraron enfrentados en igualdad de condiciones a los siniestros poderes de la Legión. Aegwynn se enfrentó a los demonios y, con la ayuda de los nobles dragones, terminó por erradicarlos. Aun así, cuando el último demonio desapareció del mundo mortal, se desató una gran tormenta por todo el norte." },
		[1911] = { file = "1911", len = 21.211, text = "Un enorme rostro oscuro apareció en el cielo por encima de Rasganorte. Sargeras, el rey demonio y señor de la Legión Ardiente, apareció ante Aegwynn y manifestó su infernal cólera. Comunicó a la joven guardiana que el tiempo de Tirisfal estaba a punto de llegar a su fin y que pronto el mundo perecería a manos de la Legión." },
		[1912] = { file = "1912", len = 31.086, text = "La orgullosa Aegwynn, creyéndose en igualdad de condiciones que el dios amenazante, desató sus poderes contra el avatar de Sargeras. Con una facilidad desconcertante, Aegwynn aplastó al señor de los demonios con sus poderes y consiguió matar su cuerpo físico. Para evitar que el espíritu de Sargeras sobreviviese, Aegwynn encerró el cuerpo destrozado dentro de uno de los antiguos muros de Kalimdor que terminó en las profundidades del mar cuando el Pozo de la Eternidad se derrumbó." },
		[1913] = { file = "1913", len = 25.626, text = "Aegwynn nunca llegaría a saber que hizo justamente lo que Sargeras pretendía. Sin saberlo, selló el destino del mundo mortal, ya que Sargeras, en el momento de su muerte corpórea, transfirió su espíritu al debilitado cuerpo de Aegwynn. Sin que la joven guardiana fuera consciente de ello, Sargeras permanecería encubierto en las profundidades más oscuras de su alma durante muchos años." },
		[1914] = { file = "1914", len = 25.496, text = "Los enanos de la montaña de Forjaz vivieron en paz durante muchos siglos. Sin embargo, su sociedad creció demasiado dentro de los confines de sus montañosas ciudades. Aunque el poderoso gran rey Modimus Yunquemar reinó entre los enanos con justicia y sabiduría, tres poderosas facciones se habían rebelado contra la sociedad enana." },
		[1915] = { file = "1915", len = 28.055, text = "El clan Barbabronce, dirigido por el Señor feudal Madoran Barbabronce, mantenía estrechos lazos con el gran rey, siendo los tradicionales defensores de la montaña de Forjaz. El clan Martillo Salvaje, dirigido por el Señor feudal Khardros Martillo Salvaje, habitaba en las estribaciones y los riscos situados alrededor de la base de la montaña e intentaba incrementar su grado de control sobre la ciudad." },
		[1916] = { file = "1916", len = 16.823, text = "La tercera facción, el clan Hierro Negro, estaba dirigido por el hechicero y Señor feudal Thaurissan. Los Hierro Negro se ocultaban entre las oscuras sombras de la montaña y complotaban contra sus primos Barbabronce y Martillo Salvaje." },
		[1917] = { file = "1917", len = 29.518, text = "Durante un tiempo, las tres facciones mantuvieron una frágil paz, pero las tensiones terminaron por explotar cuando murió el gran rey Yunquemar. Los tres clanes lucharon por el control de Forjaz. La guerra civil de los enanos se desarrolló bajo tierra durante muchos años. Finalmente, los Barbabronce, que disponían del ejército más poderoso, desterraron a los Hierro Negro y a los Martillo Salvaje de las profundidades de la montaña." },
		[1918] = { file = "1918", len = 34.429, text = "Khardros y sus guerreros Martillo Salvaje viajaron hacia el norte, atravesando las puertas de la barrera de Dun Algaz y fundaron su propio reino en las entrañas de la distante montaña de Grim Batol. Allí, los Martillo Salvaje prosperaron y volvieron a recuperar sus tesoros. A Thaurissan y a los Hierro Negro no les fue tan bien. Humillados y airados por su derrota, juraron venganza contra Forjaz. Conduciendo a su gente hacia el sur, Thaurissan fundó una ciudad (a la que puso su propio nombre) dentro de las bellas montañas Crestagrana." },
		[1919] = { file = "1919", len = 18.991, text = "La prosperidad y el paso de los años no lograron calmar el rencor de los Hierro Negro contra sus primos. Thaurissan y su mujer hechicera Modgud, lanzó un asalto en dos flancos contra Forjaz y Grim Batol al mismo tiempo. Los Hierro Negro intentaron reclamar la posición de la totalidad de Khaz Modan." },
		[1920] = { file = "1920", len = 29.91, text = "Los ejércitos de los Hierro Negro se lanzaron contra las fortalezas de sus primos y estuvieron muy cerca de tomar ambos reinos. No obstante, Madoran Barbabronce condujo a su clan a una victoria decisiva sobre el ejército de hechiceros de Thaurissan. Thaurissan y sus siervos huyeron para refugiarse en su ciudad, sin ser conscientes de lo que estaba ocurriendo en Grim Batol, donde el ejército de Modgud no lo estaba haciendo mejor contra Khardros y sus guerreros Martillo Negro." },
		[1921] = { file = "1921", len = 32.157, text = "Al enfrentarse a los guerreros enemigos, Modgud utilizó sus poderes para insuflar el temor en sus corazones. Bajo sus órdenes, las sombras se pusieron en marcha y surgieron oscuros objetos desde las profundidades de la tierra que acecharon a los Martillo Salvaje en sus propias salas. Finalmente, Modgud atravesó las puertas y puso la fortaleza bajo sitio. Los Martillo Salvaje lucharon desesperadamente y el propio Khardros acometió las agitadas masas para asesinar a la reina hechicera." },
		[1922] = { file = "1922", len = 20.715, text = "Perdida su reina, los Hierro Negro huyeron ante la furia de los Martillo Salvaje. Escaparon hacia el sur en dirección a la fortaleza de su rey y se encontraron con los ejércitos de Forjaz, que habían acudido en ayuda de Grim Batol. Cogidas entre dos fuegos, las fuerzas restantes de los Hierro Negro fueron destruidas por completo." },
		[1923] = { file = "1923", len = 36.833, text = "Posteriormente, los ejércitos conjuntos de Forjaz y Grim Batol se dirigieron al sur, intentando destruir a Thaurissan y a sus Hierro Negro de una vez por todas. No pudieron ir muy lejos cuando la furia de Thaurissan se materializó en un encantamiento de proporciones catastróficas. Al intentar conseguir la ayuda de un esbirro sobrenatural que garantizara su victoria, Thaurissan despertó antiguos poderes que dormían bajo el mundo. Para su sorpresa y, finalmente, para su condena, la criatura que emergió fue más terrible que cualquier pesadilla que pudiera imaginar." },
		[1924] = { file = "1924", len = 27.402, text = "Ragnaros, el Señor de Fuego, señor inmortal de todos los elementos flamígeros, había sido desterrado por los titanes cuando el mundo era joven. Ahora, liberado por la llamada de Thaurissan, Ragnaros volvió a la existencia una vez más. El renacimiento apocalíptico de Ragnaros en Azeroth hizo añicos las montañas Crestagrana y creó un rugiente volcán situado en el centro de la devastación." },
		[1925] = { file = "1925", len = 24.503, text = "El volcán, conocido como la montaña Roca Negra, limitaba al norte con la Garganta de Fuego y al sur con las Estepas Ardientes. Si bien Thaurissan fue asesinado por las fuerzas que lo habían liberado, sus hermanos que le sobrevivieron finalmente fueron esclavizados por Ragnaros y sus elementales. Hasta el día de hoy, permanecen en las profundidades de Roca Negra." },
		[1926] = { file = "1926", len = 17.606, text = "Habiendo presenciado la horrenda devastación, donde los fuegos se extendían a lo largo de las montañas del sur, el rey Madoran y el rey Khardros detuvieron sus ejércitos y regresaron a toda prisa hacia sus respectivos reinos, incapaces de hacer frente a la ira de Ragnaros." },
		[1927] = { file = "1927", len = 17.711, text = "Los Barbabronce regresaron a Forjaz y reconstruyeron la gloriosa ciudad. Asimismo, los Martillo Salvaje regresaron a casa en Grim Batol. Sin embargo, la muerte de Modgud dejó una pátina maléfica sobre la fortaleza de la montaña y resultó ser inhabitable." },
		[1928] = { file = "1928", len = 36.937, text = "Los corazones de los Martillo Salvaje sentían la amargura que suponía la pérdida de su amado hogar. El rey Barbabronce ofreció a los Martillo Salvaje un lugar donde vivir, situado en los límites de Forjaz, pero estos se negaron en redondo. Khardros condujo a su gente hacia el norte en dirección a las tierras de Lordaeron. Asentados en los exuberantes bosques de las tierras del interior, los Martillo Salvaje construyeron la ciudad de Pico Nidal, en donde los Martillo Salvaje crecieron cerca de la naturaleza e, incluso, se vincularon a los poderosos grifos de la región." },
		[1929] = { file = "1929", len = 26.514, text = "Al intentar conservar las relaciones y el comercio con sus primos, los enanos de Forjaz construyeron dos grandes arcos, el Puente Thandol, que une Khaz Modan con Lordaeron. Enriquecidos mediante el comercio mutuo, los dos reinos prosperaron. Tras las muertes de Madoran y Khardros, sus hijos encargaron conjuntamente la construcción de dos grandes estatuas en honor a sus padres." },
		[1930] = { file = "1930", len = 20.062, text = "Las dos estatuas guardarían el paso hacia las tierras del sur que, en presencia del ardiente Ragnaros, se habían convertido en tierras volcánicas. Sirvieron tanto como advertencia a aquellos que pretendían atacar los reinos de los enanos, como recordatorio del precio que pagaron los Hierro Negro por sus crímenes." },
		[1931] = { file = "1931", len = 25.208, text = "Los dos reinos mantuvieron estrechos lazos durante años, pero los Martillo Salvaje cambiaron en gran medida a causa de los horrores que presenciaron en Grim Batol. En lugar de excavar un vasto reino en el interior de la montaña, decidieron vivir en la superficie, en las laderas de Pico Nidal. Las diferencias ideológicas entre los dos clanes de enanos que quedaban condujeron finalmente a su separación." },
		[1932] = { file = "1932", len = 30.537, text = "Con el paso de los años, la guardiana Aegwynn se hizo cada vez más poderosa y utilizó las energías de Tirisfal para extender con mucho el alcance de su vida. Creyendo erróneamente que había derrotado a Sargeras para bien, continuó salvaguardando el mundo de los esbirros del rey de los demonios durante aproximadamente novecientos años. Sin embargo, el Consejo de Tirisfal decretó que su administración había llegado a su fin." },
		[1933] = { file = "1933", len = 13.479, text = "El consejo ordenó a Aegwynn que regresara a Dalaran, de manera que pudieran elegir un nuevo sucesor para la guardiana. Aun así, Aegwynn, desconfiando del consejo, decidió escoger a un sucesor por sí misma." },
		[1934] = { file = "1934", len = 24.842, text = "La orgullosa Aegwynn decidió traer un hijo al mundo al que transferir su poder. No tenía intención alguna de permitir que la orden de Tirisfal manipulara a su sucesor de la misma forma que intentaron manipularla a ella. Dirigiéndose a la nación sureña de Azeroth, Aegwynn encontró al hombre perfecto para convertirlo en padre de su hijo: un hábil mago humano conocido como Nielas Aran." },
		[1935] = { file = "1935", len = 27.063, text = "Aran era el mago y consejero de la corte del rey de Azeroth. Aegwynn sedujo al mago y tuvo un hijo de él. La afinidad natural hacia la magia de Nielas habría de influir profundamente en el niño aún no nacido y terminaron por definir los trágicos pasos que posteriormente seguiría el niño. Asimismo, el poder de Tirisfal pasó al niño, si bien no fue consciente de ello hasta alcanzar la madurez física." },
		[1936] = { file = "1936", len = 34.743, text = "Pasó el tiempo y Aegwynn dio a luz a su hijo en un bosquecillo apartado. Dándole el nombre de Medivh, que significa \"guardián de los secretos\" en la lengua de los elfos nobles, Aegwynn creyó que cuando el niño creciera, se convertiría en el próximo guardián. Desafortunadamente, el espíritu maligno de Sargeras, que se ocultaba en ella, tomó posesión del indefenso niño mientras permanecía en el seno materno. Aegwynn no tenía la menor idea de que el próximo guardián del mundo ya estaba poseído por su mayor enemigo." },
		[1937] = { file = "1937", len = 24.999, text = "Habiéndose asegurado de que su hijo estaba sano, Aegwynn envió al joven Medivh a la corte de Azeroth y lo dejó allí para que creciera junto a su padre mortal y a su gente. Luego, se internó en la jungla y se preparó para acudir a la cita con el más allá. Medivh creció hasta convertirse en un joven fuerte y no tenía idea del potencial que implicaba su derecho de nacimiento en Tirisfal." },
		[1938] = { file = "1938", len = 33.62, text = "Sargeras esperó el momento oportuno, hasta que los poderes del joven se manifestaron por sí solos. Cuando Medivh alcanzó la adolescencia, se convirtió en un personaje muy popular en Azeroth debido a sus poderes mágicos y, a menudo, corrió aventuras junto con sus dos amigos: Llane, príncipe de Azeroth, y Anduin Lothar, uno de los últimos descendientes de la línea de sangre arathi. Los tres muchachos no hacían más que meterse constantemente en líos, pero eran muy apreciados por el pueblo." },
		[1939] = { file = "1939", len = 16.457, text = "Cuando Medivh cumplió la edad de catorce años, el poder cósmico que residía en él despertó y chocó con el espíritu invasor de Sargeras que acechaba en su alma. Medivh entró en un estado catatónico que se prolongó durante varios años." },
		[1940] = { file = "1940", len = 22.779, text = "Cuando despertó de su estado de coma, cayó en la cuenta de que se había convertido en un adulto y vio que sus amigos eran los regentes de Azeroth. Si bien deseaba utilizar sus increíbles poderes para proteger la tierra que consideraba su casa, el oscuro espíritu de Sargeras tergiversó sus propósitos y emociones, conduciéndole a un final insidioso." },
		[1941] = { file = "1941", len = 12.277, text = "Sargeras se rebeló en el corazón de Medivh, ya que sabía que sus planes para una invasión del mundo estaban a punto de materializarse y el último guardián del mundo los llevaría a buen término." },
		[1942] = { file = "1942", len = 21.734, text = "En la época del nacimiento de Medivh en Azeroth, Kil'jaeden el Impostor daba vuelta entre sus seguidores en El Vacío Abisal. El astuto señor de los demonios, bajo las órdenes de su maestro Sargeras, estaba planeando la segunda invasión de Azeroth por parte de la Legión Ardiente." },
		[1943] = { file = "1943", len = 26.984, text = "Ahora no se podía cometer ningún error. Kil'jaeden suponía que necesitaban nuevas fuerzas para debilitar las defensas de Azeroth incluso antes de que la Legión pudiera poner un pie en el mundo. Si las razas mortales, como los elfos de la noche y los dragones, fueran obligadas a hacer frente a una nueva amenaza, estarían demasiado debilitadas para oponer resistencia real cuando llegara la verdadera invasión de la Legión." },
		[1944] = { file = "1944", len = 17.815, text = "Fue entonces cuando Kil'jaeden descubrió el exuberante mundo de Draenor flotando apaciblemente en el interior de la Gran Oscuridad del Más Allá. Hogar de los orcos organizados en clanes de inspiración chamánica y de los pacíficos draenei, Draenor era tan idílico como extenso." },
		[1945] = { file = "1945", len = 23.954, text = "Los nobles clanes de los orcos vagaban por las extensas praderas y cazaban por deporte, mientras los curiosos draenei construían rudimentarias ciudades dentro de los altísimos acantilados y picos del mundo. Kil'jaeden sabía que, en el caso de que fueran adecuadamente adiestrados, los moradores de Draenor tenían un gran potencial para servir a la Legión Ardiente." },
		[1946] = { file = "1946", len = 25.6, text = "De las dos razas, Kil'jaeden vio que los orcos guerreros eran más susceptibles de sucumbir a la corrupción de la Legión. Se ocupó de embelesar al chamán orco más viejo, Ner'zhul, de la misma manera que, en el pasado, Sargeras puso a la reina Azshara bajo su control. Utilizando al astuto chamán como su conducto, el demonio extendió el deseo de lucha y el salvajismo entre los clanes orcos." },
		[1947] = { file = "1947", len = 24.215, text = "No pasó mucho tiempo antes de que la raza espiritual se transformara en un pueblo sediento de sangre. Luego, Kil'jaeden urgió a Ner'zhul y a su gente a que dieran el último paso: dedicarse en cuerpo y alma a la guerra y a la muerte. Aun así, el viejo chamán, sintiendo que su gente iba a ser esclavizada en el odio para siempre, mostró resistencia ante las órdenes del demonio." },
		[1948] = { file = "1948", len = 22.648, text = "Frustrado por la resistencia de Ner'zhul, Kil'jaeden buscó a otro orco que pudiera poner a su pueblo en las manos de la Legión. Finalmente, el astuto señor de los demonios encontró al discípulo dispuesto que buscaba: Gul'dan, el ambicioso aprendiz de Ner'zhul. A cambio de su obediencia ciega, Kil'jaeden prometió a Gul'dan poderes inefables." },
		[1949] = { file = "1949", len = 23.406, text = "El joven orco se convirtió en un ávido estudiante de magia demoníaca y se transformó en el brujo mortal más poderoso de la historia. Enseñó a otros jóvenes orcos las artes Arcanas y se esforzó por erradicar las tradiciones chamánicas de los orcos. Gul'dan enseñó una nueva clase de magia a sus hermanos, un nuevo poder terrible que apestaba a condena." },
		[1950] = { file = "1950", len = 40.594, text = "Kil'jaeden, en el deseo de aumentar su dominio sobre los orcos, ayudó a Gul'dan a encontrar al Consejo de la Sombra, una secta secreta que manipulaba a los clanes y extendía el uso de la brujería por todo Draenor. A medida que más y más orcos ejercieron las artes de brujería, los suaves campos y las corrientes de Draenor comenzaron a mancillarse y a desvanecerse. Con el tiempo, las vastas praderas que los orcos habían considerado su hogar durante generaciones, se marchitaron, dejando exclusivamente estériles suelos rojizos. Lentamente, las energías demoníacas estaban acabando con el mundo." },
		[1951] = { file = "1951", len = 23.014, text = "Bajo el secreto control de Gul'dan y su Consejo de la Sombra, los orcos se volvieron cada vez más agresivos. Construyeron grandes estadios en donde ponían a punto sus virtudes guerreras en pruebas de combate y muerte. Durante este periodo, algunos jefes del clan clamaron contra la creciente depravación de su raza." },
		[1952] = { file = "1952", len = 21.159, text = "Uno de ellos, Durotan, del clan Lobo Gélido, advirtió contra la posibilidad de que los orcos se perdieran por completo en el odio y la furia. Sin embargo, sus palabras cayeron en saco roto cuando jefes más fuertes como Grom Grito Infernal del clan Grito de Guerra dieron la bienvenida a la nueva era de guerra y dominación." },
		[1953] = { file = "1953", len = 25.704, text = "Kil'jaeden sabía que los clanes orcos estaban prácticamente preparados, pero necesitaba estar totalmente seguro de su lealtad. En secreto, hizo que el Consejo de la Sombra llamara a Mannoroth el Destructor, la imagen viviente de la destrucción y la ira. Gul'dan convocó al clan de los jefes y les convenció de que beber la hirviente sangre de Mannoroth les haría virtualmente invencibles." },
		[1954] = { file = "1954", len = 19.487, text = "Conducidos por Grom Grito Infernal, todos los jefes de clan, exceptuando a Durotan, bebieron y, de esta manera, sellaron sus destinos como esclavos de la Legión Ardiente. Gracias al poder de la rabia de Mannoroth, los jefes involuntariamente extendieron su yugo a sus desprevenidos hermanos." },
		[1955] = { file = "1955", len = 17.189, text = "Consumidos por la maldición de su nueva sed de sangre, los orcos intentaron dar rienda suelta a su furia ante todo aquel que se cruzara en su camino. Sintiendo que había llegado el momento, Gul'dan reunió a los clanes guerreros en una única e imparable horda." },
		[1956] = { file = "1956", len = 28.526, text = "Sin embargo, sabiendo que varios jefes como Grito Infernal y Orgrim Martillo Maldito competían por lograr la supremacía, Gul'dan creó una marioneta para dirigir a esta nueva horda. Puño Negro el Destructor, un Señor de la Guerra orco particularmente depravado y despiadado, fue el escogido para convertirse en la marioneta de Gul'dan. Bajo la égida de Puño Negro, la Horda salió para probar su valía contra los simples draenei." },
		[1957] = { file = "1957", len = 27.794, text = "Transcurridos algunos meses, la Horda erradicó casi por completo todos los draenei que vivían en Draenor. Solo un pequeño puñado de supervivientes consiguió evitar la extraordinaria ira de los orcos. Exaltado por la victoria, Gul'dan se deleitaba con el poder y la fuerza de la Horda. Aun así, sabía que, sin enemigos que batir, la Horda se consumiría en luchas intestinas sin fin en su imparable apetito de matanza." },
		[1958] = { file = "1958", len = 18.077, text = "Kil'jaeden sabía que, finalmente, la Horda estaba preparada. Los orcos se habían convertido en el arma más poderosa de la Legión Ardiente. El astuto demonio compartió su conocimiento con su maestro y Sargeras admitió que, finalmente, había llegado el tiempo de la venganza." },
		[1959] = { file = "1959", len = 20.167, text = "Mientras Kil'jaeden preparaba a la Horda para su invasión de Azeroth, Medivh continuaba luchando por su alma contra Sargeras. El rey Llane, noble monarca de Ventormenta, recelaba de la oscuridad que parecía contaminar el espíritu de su nuevo amigo." },
		[1960] = { file = "1960", len = 16.98, text = "El rey Llane compartió sus preocupaciones con Anduin Lothar, el último descendiente de la línea de sangre arathi, a quien nombró su lugarteniente. Aun así, ningún hombre podía imaginar que el lento descenso de Medivh hacia la locura causaría los horrores que estaban por llegar." },
		[1961] = { file = "1961", len = 22.674, text = "Como incentivo final, Sargeras prometió otorgar un gran poder a Gul'dan si accedía a conducir la Horda a Azeroth. A través de Medivh, Sargeras dijo al brujo que se podía convertir en un dios viviente si localizaba la tumba sumergida donde la guardiana Aegwynn había colocado el cuerpo inútil de Sargeras hacía casi mil años." },
		[1962] = { file = "1962", len = 16.927, text = "Gul'dan accedió y decidió que, una vez que los moradores de Azeroth fueran derrotados, localizaría la legendaria tumba y reclamaría su recompensa. Persuadido de que la Horda serviría a sus propósitos, Sargeras ordenó que comenzara la invasión." },
		[1963] = { file = "1963", len = 34.325, text = "Mediante un esfuerzo conjunto, Medivh y los brujos del Consejo de la Sombra lograron abrir la puerta dimensional conocida como Portal Oscuro. Este portal unía la distancia que mediaba entre Azeroth y Draenor y era suficientemente extenso como para que los ejércitos atravesaran su interior. Gul'dan envió exploradores orcos a través del portal para supervisar las tierras que habrían de conquistar. Al regresar, los exploradores aseguraron al Consejo de la Sombra que el mundo de Azeroth estaba listo para ser conquistado." },
		[1964] = { file = "1964", len = 26.357, text = "Aun convencido de que la corrupción de Gul'dan destruiría a su gente, Durotan habló una vez más en contra de los brujos. El valiente guerrero afirmó que los brujos estaban destruyendo la pureza del espíritu orco y que esta insensata invasión sería su condena. Gul'dan, que no estaba dispuesto a acabar con un héroe tan popular, envió a Durotan y a su clan Lobo Gélido hacia los confines de este nuevo mundo." },
		[1965] = { file = "1965", len = 31.477, text = "Una vez que los exiliados Lobo Gélido arremetieron contra el portal, solo unos pocos clanes orcos les siguieron. Dichos orcos montaron rápidamente una base de operaciones dentro de La Ciénaga Negra, un área oscura e insana situada en el extremo oriental del reino de Ventormenta. Cuando los orcos comenzaron a dividirse y a explorar nuevas tierras, entraron directamente en conflicto con los defensores humanos de Ventormenta.|n" },
		[1966] = { file = "1966", len = 18.442, text = "Si bien estas escaramuzas solían acabar rápidamente, ilustran en gran medida las debilidades y los poderes de ambas especies rivales. Llane y Lothar nunca lograron reunir datos ciertos sobre el número de los orcos y solo podían suponer la magnitud de la fuerza con la que se enfrentaban." },
		[1967] = { file = "1967", len = 16.64, text = "Transcurridos algunos años, la mayor parte de los orcos se habían introducido en Azeroth, por lo que Gul'dan consideró que había llegado el momento de asestar el primer golpe contra la humanidad. La Horda lanzó toda su fuerza contra el desprevenido reino de Ventormenta." },
		[1968] = { file = "1968", len = 30.119, text = "Cuando las fuerzas de Azeroth y la Horda se enfrentaron por todo el reino, los conflictos internos comenzaron a cobrar su peaje en ambos ejércitos. El rey Llane, que creía que sus bestiales orcos eran incapaces de conquistar Azeroth, desdeñosamente mantuvo su posición en su capital de Ventormenta. Sin embargo, Lothar se convenció de que la batalla debía plantearse directamente al enemigo y se vio obligado a escoger entre sus propias convicciones y su lealtad al rey." },
		[1969] = { file = "1969", len = 16.562, text = "Decidido a seguir sus propios instintos, Lothar asaltó la torre-fortaleza de Karazhan de Medivh con la ayuda del joven aprendiz de zahorí Khadgar. Khadgar y Lothar lograron derrotar al guardián poseído, que consideraron la fuente del conflicto." },
		[1970] = { file = "1970", len = 17.998, text = "Sin darse cuenta, al acabar con el cuerpo de Medivh, Lothar y el joven aprendiz desterraron el espíritu de Sargeras al abismo. Como consecuencia de ello, el espíritu puro y virtuoso de Medivh pudo vivir... permitiéndose deambular por el plano astral durante muchos años." },
		[1971] = { file = "1971", len = 22.126, text = "Aunque Medivh había sido derrotado, la Horda continuó dominando a los defensores de Ventormenta. Cuando la victoria de la Horda parecía cercana, Orgrim Martillo Maldito, uno de los jefes orcos más grandes, empezó a comprobar por sí mismo la terrible corrupción que se había extendido entre los clanes desde su existencia en Draenor." },
		[1972] = { file = "1972", len = 31.06, text = "Su viejo camarada, Durotan, regresó del exilio y le previno una vez más contra la traición de Gul'dan. Reaccionando rápidamente, los asesinos de Gul'dan acabaron con Durotan y su familia, dejando con vida únicamente a su hijo. Martillo Maldito no supo que el hijo de Durotan fue encontrado por el oficial humano Aedelas Lodonegro y que fue hecho esclavo. Un día, este niño orco llegaría a convertirse en el líder más grande que vería su pueblo." },
		[1973] = { file = "1973", len = 21.577, text = "Indignado por la muerte de Durotan, Orgrim intentó liberar a la Horda de la corrupción demoníaca y, finalmente, asumió el rol de jefe de la Horda, eliminando a la marioneta corrupta de Gul'dan, Puño Negro. Bajo su decisivo liderazgo, la implacable Horda finalmente puso sitio al Castillo de Ventormenta." },
		[1974] = { file = "1974", len = 17.998, text = "El rey Llane había subestimado en gran medida el poder de la Horda y pudo observar inerme cómo su reino caía ante los invasores de piel verde. Finalmente, el rey Llane fue asesinado por uno de los asesinos más hábiles del Consejo de la Sombra: el medio orco Garona." },
		[1975] = { file = "1975", len = 31.739, text = "Lothar y sus guerreros, regresando a casa desde Karazhan, tenían la intención de contener la pérdida de vidas y salvar su otrora glorioso hogar. Pero regresaron demasiado tarde y encontraron su amado reino convertido en humeantes ruinas. La Horda de orcos continuó asolando el país y reclamando la propiedad de las tierras circundantes. Obligados a ocultarse, Lothar y sus compañeros hicieron un solemne juramento para reclamar su patria natal a cualquier precio." },
		[1976] = { file = "1976", len = 29.179, text = "Lothar reunió los restos de los ejércitos de Azeroth tras su derrota en el Castillo de Ventormenta y luego puso en marcha un éxodo masivo por mar hacia el norteño reino de Lordaeron. Convencido de que si no se controlaba a la Horda, derrotaría a toda la humanidad, los líderes de las siete naciones humanas se reunieron y acordaron unir esfuerzos en lo que se conocería como la Alianza de Lordaeron." },
		[1977] = { file = "1977", len = 18.181, text = "Por primera vez en prácticamente tres mil años, las naciones separadas de Arathor estaban unidas una vez más bajo un estandarte común. Nombrado Comandante Mayor de las Fuerzas Aliadas, Lord Lothar preparó a sus ejércitos para hacer frente a la llegada de la Horda." },
		[1978] = { file = "1978", len = 20.219, text = "Ayudado por sus lugartenientes, Uther el Luminoso, el almirante Daelin Valiente y Turalyon, Lothar fue capaz de convencer a las razas semihumanas de Lordaeron de la inminente amenaza. La Alianza obtuvo el apoyo de los estoicos enanos de Forjaz y de un pequeño número de elfos nobles de Quel'Thalas." },
		[1979] = { file = "1979", len = 19.931, text = "Los elfos, dirigidos en aquel tiempo por Anasterian Caminante del Sol, no estaban interesados en modo alguno en el conflicto que se aproximaba. Sin embargo, estaban dispuestos a ayudar a Lothar, ya que se trataba del último descendiente de la línea de sangre arathi, que había ayudado a los elfos en el pasado." },
		[1980] = { file = "1980", len = 22.674, text = "La Horda, ahora dirigida por el Jefe de Guerra Martillo Maldito, trajo ogros procedentes de su hogar de Draenor y reclutó trols procedentes del bosque de Amani. Comprometidos en una campaña masiva para borrar el reino enano de Khaz Modan y los límites sureños de Lordaeron, la Horda diezmó casi sin esfuerzo cualquier clase de oposición." },
		[1981] = { file = "1981", len = 34.064, text = "Las épicas batallas de la Segunda Guerra incluyeron desde escaramuzas navales a gran escala hasta ataques aéreos masivos. De alguna manera, la Horda logró desenterrar un poderoso artefacto conocido como Alma demoníaca y lo utilizó para esclavizar a Alexstrasza, antigua reina de los dragones. Amenazando destruir sus preciosos huevos, la Horda obligó a Alexstrasza a enviar a sus hijos mayores a la guerra. Los nobles dragones rojos fueron obligados a luchar para la Horda y eso es lo que hicieron." },
		[1982] = { file = "1982", len = 34.691, text = "La guerra rugió a través de los continentes de Khaz Modan, Lordaeron y el propio Azeroth. Como parte de su campaña en el norte, la Horda consiguió incendiar las tierras fronterizas de Quel'Thalas y, de esta manera, se aseguraron el compromiso final de los elfos con la causa de la Alianza. Las ciudades y los pueblos más grandes de Lordaeron quedaron destruidos y devastados por el conflicto. A pesar de la ausencia de refuerzos y de que todas las probabilidades estaban en contra, Lothar y sus aliados lograron mantener a sus enemigos a raya." },
		[1983] = { file = "1983", len = 27.402, text = "Sin embargo, durante los días finales de la Segunda Guerra, cuando la victoria de la Horda parecía casi garantizada, una terrible contienda surgió entre los dos orcos más poderosos de Azeroth. Cuando Martillo Maldito preparaba su asalto final a la ciudad capital de Lordaeron, un asalto que habría de destruir las últimas reservas de la Alianza, Gul'dan y sus seguidores abandonaron sus puestos y marcharon hacia el mar." },
		[1984] = { file = "1984", len = 13.819, text = "El perplejo Martillo Maldito, habiendo perdido prácticamente la mitad de sus fuerzas a causa de la traición de Gul'dan, se vio obligado a retroceder y a olvidar la posibilidad de obtener la mayor victoria contra la Alianza." },
		[1985] = { file = "1985", len = 23.902, text = "Gul'dan, hambriento de poder y obsesionado con convertirse en un dios, se lanzó a una carrera desesperada para llegar hasta la tumba sumergida de Sargeras, que creía guardaba los secretos de un gran poder. Habiendo condenado a sus compañeros orcos a convertirse en esclavos de la Legión Ardiente, Gul'dan consideraba que no le debía nada a Martillo Maldito." },
		[1986] = { file = "1986", len = 15.438, text = "Con el apoyo de los clanes Cazatormentas y Martillo Crepuscular, Gul'dan logró extraer la tumba de Sargeras del lecho marino. Sin embargo, cuando abrió la antigua e inundada bóveda, solo halló demonios enloquecidos que lo aguardaban." },
		[1987] = { file = "1987", len = 25.182, text = "Con la intención de castigar a los díscolos orcos por su costosa traición, Martillo Maldito envió sus fuerzas para acabar con Gul'dan y traer a los renegados de vuelta al redil. Por su imprudencia, Gul'dan fue destrozado por los demonios enloquecidos que había liberado. Con su líder muerto, los clanes renegados cayeron rápidamente ante las enfurecidas legiones de Martillo Maldito." },
		[1988] = { file = "1988", len = 16.771, text = "Aunque la rebelión había sido aplastada, la Horda fue incapaz de recuperarse de las terribles pérdidas que había sufrido. La traición de Gul'dan había permitido que la Alianza no solo renovara sus esperanzas, sino que le había concedido tiempo para reagruparse y contraatacar." },
		[1989] = { file = "1989", len = 35.553, text = "Lothar, viendo que la Horda estaba fracturada desde dentro, reunió al resto de sus fuerzas y empujó a Martillo Maldito hacia el sur, obligándole a internarse en el destruido corazón de Ventormenta. Allí, las fuerzas de la Alianza atraparon a la Horda en retirada, dentro de la fortaleza volcánica Cumbre de Roca Negra. Aunque Lord Lothar cayó en la batalla en la base de la cumbre, su lugarteniente Turalyon volvió a reunir a las fuerzas de la Alianza en la hora undécima y empujó nuevamente a la Horda hacia el abismo del Pantano de las Penas." },
		[1990] = { file = "1990", len = 18.364, text = "Las fuerzas de Turalyon lograron destruir el Portal Oscuro, la puerta mística que conectaba a los orcos con su hogar de Draenor. Sin posibilidades de obtener refuerzos y fracturada por las luchas internas, la Horda finalmente se derrumbó y terminó sucumbiendo al poder de la Alianza." },
		[1991] = { file = "1991", len = 31.242, text = "Los dispersos clanes orcos fueron rápidamente rodeados y conducidos a campos de internamiento vigilados. Aunque parecía que la Horda había sido derrotada para bien, algunos fueron muy escépticos acerca de la posibilidad de la paz. Khadgar, convertido en archimago de cierto renombre, persuadió al alto mando de la Alianza para que construyera la Fortaleza de Nethergarde, que vigilaría las ruinas del Portal Oscuro y garantizaría que no se produjeran futuras invasiones procedentes de Draenor." },
		[1992] = { file = "1992", len = 26.749, text = "Cuando se extinguieron los fuegos de la Segunda Guerra, la Alianza realizó enérgicas acciones para contener la amenaza de los orcos. Con el propósito de albergar a los orcos cautivos, se construyeron grandes campos de internamiento en el sur de Lordaeron. Vigilados tanto por paladines como por Soldados veteranos de la Alianza, los campos resultaron tener un gran éxito." },
		[1993] = { file = "1993", len = 14.132, text = "Si bien los orcos cautivos estaban tensos y ansiosos por volver a presentar batalla, los celadores de los campos, concentrados en la vieja prisión-fortaleza de Durnholde, mantuvieron la paz y el orden con firmeza." },
		[1994] = { file = "1994", len = 26.88, text = "Sin embargo, en el demoníaco mundo de Draenor, un nuevo ejército orco se preparaba para golpear a la confiada Alianza. Ner'zhul, el antiguo mentor de Gul'dan, reunió a los clanes orcos restantes bajo su oscuro estandarte. Ayudado por el clan Sombraluna, el viejo chamán planeaba abrir una serie de portales en Draenor que permitirían que la Horda retornara a nuevos e intactos mundos." },
		[1995] = { file = "1995", len = 14.968, text = "Para proporcionar poder a sus nuevos portales, necesitaba una serie de artefactos encantados procedentes de Azeroth. Para obtenerlos, Ner'zhul volvió a abrir el Portal Oscuro y envió a sus voraces sirvientes para que lo embistieran." },
		[1996] = { file = "1996", len = 24.581, text = "La nueva Horda, conducida por jefes veteranos como Grom Grito Infernal y Kilrogg Mortojo (del clan Foso Sangrante), sorprendió a las fuerzas defensivas de la Alianza y arrasó toda la campiña. Bajo la quirúrgica dirección de Ner'zhul, los orcos no tardaron de localizar los artefactos que necesitaban, regresando prontamente a la seguridad de Draenor." },
		[1997] = { file = "1997", len = 32.679, text = "El rey Terenas de Lordaeron, convencido de que los orcos estaban preparando una nueva invasión de Azeroth, reunió a sus lugartenientes más fieles. Ordenó al general Turalyon y al archimago Khadgar que dirigieran una expedición hacia el Portal Oscuro para poner fin de una vez por todas a la amenaza de los orcos. Las fuerzas de Turalyon y Khadgar marcharon hacia Draenor y se enfrentaron varias veces con los clanes de Ner'zhul sobre la devastada Península del Fuego Infernal." },
		[1998] = { file = "1998", len = 13.766, text = "Incluso con la ayuda de la elfa noble Alleria Brisaveloz, el enano Kurdran Martillo Salvaje y el Soldado veterano Danath Aterratrols, Khadgar no pudo evitar que Ner'zhul abriera sus portales a otros mundos." },
		[1999] = { file = "1999", len = 37.329, text = "Finalmente, Ner'zhul abrió sus portales a otros mundos, pero no fue capaz de prever el terrible precio que habría de pagar. Las tremendas energías de los portales comenzaron a destrozar toda la estructura de Draenor. A medida que las fuerzas de Turalyon luchaban desesperadamente para regresar a casa en Azeroth, el mundo de Draenor comenzó a derrumbarse. Grom Grito Infernal y Kilrogg Mortojo, cayendo en la cuenta de que los locos planes de Ner'zhul condenarían a toda la raza, reunieron a los orcos restantes y huyeron hacia la relativa seguridad que les proporcionaba Azeroth." },
		[2000] = { file = "2000", len = 33.045, text = "En Draenor, Turalyon y Khadgar accedieron a hacer el último sacrificio, destruyendo el Portal Oscuro desde su lado. Aunque habrían de perder sus propias vidas y las vidas de sus compañeros en el empeño, sabían que era la única forma de garantizar la supervivencia de Azeroth. Incluso aunque Grito Infernal y Mortojo se abrieron camino entre las filas humanas en una desesperada búsqueda de la libertad, el Portal Oscuro explotó detrás suyo. Para ellos, así como para los orcos que quedaban en Azeroth, no había vuelta atrás." },
		[2001] = { file = "2001", len = 23.562, text = "Ner'zhul y su leal clan Sombraluna atravesaban el mayor de los portales recientemente creados, cuando grandes erupciones volcánicas empezaron a despedazar los continentes de Draenor. Los ardientes mares comenzaron a rugir, abriendo la tierra devastada y, finalmente, el torturado mundo se consumió en una apocalíptica explosión." },
		[2002] = { file = "2002", len = 30.224, text = "Ner'zhul y sus seguidores penetraron en El Vacío Abisal, el plano etéreo que conecta todos los mundos desperdigados a través de la Gran Oscuridad del Más Allá. Desafortunadamente, Kil'jaeden y sus esbirros estaban esperándole. Kil'jaeden, que había jurado vengarse de Ner'zhul por su orgullosa rebeldía, se dedicó a despedazar lentamente el cuerpo del viejo chamán, pieza a pieza." },
		[2003] = { file = "2003", len = 24.607, text = "Kil'jaeden mantuvo el espíritu del chamán vivo e intacto y, de esta manera, dejó que Ner'zhul fuera totalmente consciente del desmembramiento que sufría su cuerpo. Aunque Ner'zhul suplicó al demonio que liberara su espíritu y le diera muerte, este replicó que el Pacto de Sangre que habían suscrito hacía mucho tiempo aún los unía y que Ner'zhul tenía un propósito que cumplir." },
		[2004] = { file = "2004", len = 28.082, text = "El fracaso de los orcos a la hora de conquistar el mundo para la Legión Ardiente obligó a Kil'jaeden a crear un nuevo ejército para sembrar el caos en los reinos de Azeroth. Este nuevo ejército debía evitar ser presa de las mismas rivalidades y luchas internas que habían diezmado a la Horda. Tendría que llevar a cabo su misión, completamente centrado en ella, actuando sin piedad. En esta ocasión, Kil'jaeden no podía fracasar." },
		[2005] = { file = "2005", len = 26.775, text = "Manteniendo el espíritu de Ner'zhul indefenso, Kil'jaeden le dio la última oportunidad de servir a la Legión o sufrir tormento por toda la eternidad. Una vez más, Ner'zhul accedió temerariamente a sellar el pacto con el demonio. El espíritu de Ner'zhul fue colocado en el interior de un bloque de hielo, duro como el diamante, especialmente elaborado, procedente de los lejanos confines de El Vacío Abisal." },
		[2006] = { file = "2006", len = 21.446, text = "Confinado en su urna helada, Ner'zhul sintió que su conciencia se expandía diez mil veces más. Deformado por los caóticos poderes del demonio, Ner'zhul se convirtió en un ser espectral de poder insondable. En ese momento, el orco conocido como Ner'zhul se hizo pedazos para siempre y nació el Rey Exánime." },
		[2007] = { file = "2007", len = 23.667, text = "Los caballeros muertos leales de Ner'zhul y los seguidores de Sombraluna también fueron transformados por las energías caóticas del demonio. Los debilitados taumaturgos fueron destrozados, siendo reconstituidos como exánimes esqueléticos. Los demonios garantizaron que, incluso en la muerte, los seguidores de Ner'zhul le sirvieran de forma incuestionable." },
		[2008] = { file = "2008", len = 23.902, text = "Cuando llegó el momento, Kil'jaeden explicó la misión para la cual había creado al Rey Exánime. Ner'zhul debía extender una peste de muerte y terror por Azeroth que habría de acabar para siempre con la civilización humana. Todos aquellos que murieran a causa de la terrible peste volverían como no-muertos y sus espíritus estarían ligados a la voluntad de hierro de Ner'zhul para siempre." },
		[2009] = { file = "2009", len = 11.546, text = "Kil'jaeden prometió que si Ner'zhul cumplía su oscura misión, exterminando la humanidad del mundo, sería liberado de su maldición y obtendría un nuevo y saludable cuerpo." },
		[2010] = { file = "2010", len = 34.56, text = "Si bien Ner'zhul accedía de buen grado y se mostraba incluso ansioso por cumplir su papel, Kil'jaeden se mostró escéptico acerca de la lealtad de su siervo. Manteniendo al Rey Exánime sin cuerpo y atrapado en una urna de cristal, garantizaba su buena conducta a corto plazo, pero el demonio sabía que debía mantenerlo bajo estricta vigilancia. Para este fin, Kil'jaeden convocó a su guardia demoníaca de élite, los Señores del Terror vampíricos, para que controlaran a Ner'zhul y se aseguraran de que cumplía su terrible tarea." },
		[2011] = { file = "2011", len = 13.166, text = "Tichondrius, el más poderoso y astuto de los Señores del Terror, se entusiasmó con el desafío. Estaba fascinado por la dureza de la peste y el desenfrenado potencial genocida del Rey Exánime." },
		[2012] = { file = "2012", len = 31.896, text = "Kil'jaeden volvió a emplazar la urna congelada de Ner'zhul en el mundo de Azeroth. El cristal endurecido centelleaba bajo la noche estrellada y chocó en el desolado continente ártico de Rasganorte, enterrándose en las profundidades del Glaciar Corona de Hielo. El cristal congelado, deformado y marcado por su violento descenso, adquirió el aspecto de un trono y el vengativo espíritu de Ner'zhul pronto comenzó a moverse en su interior." },
		[2013] = { file = "2013", len = 32.679, text = "Desde los confines del Trono Helado, Ner'zhul comenzó a expandir su vasta conciencia y a entrar en contacto con las mentes de los habitantes de Rasganorte. Casi sin esfuerzo, logró esclavizar la mente de muchas criaturas indígenas, incluyendo trols de hielo wendigo, y atrajo a sus maléficos hermanos hacia su creciente sombra. Sus poderes psíquicos resultaron prácticamente ilimitados y los utilizó para crear un pequeño ejército que habitó en los intrincados laberintos de Corona de Hielo." },
		[2014] = { file = "2014", len = 21.29, text = "A medida que el Rey Exánime aprendía a dominar sus crecientes facultades bajo la persistente vigilancia de los Señores del Terror, descubrió un remoto asentamiento humano situado en la periferia del vasto territorio del Cementerio de Dragones. En un abrir y cerrar de ojos, Ner'zhul decidió probar sus poderes con los despreocupados humanos." },
		[2015] = { file = "2015", len = 33.019, text = "Ner'zhul propagó una peste de los no-muertos, que se había originado desde las profundidades, en el interior del Trono Helado, en los páramos del ártico. Controlando la peste con su sola voluntad, la lanzó directamente hacia el poblado humano. En un plazo de tres días, todos los habitantes del asentamiento estaban muertos, pero poco después, los pobladores empezaron a revivir como cadáveres zombis. Ner'zhul podía sentir sus espíritus y pensamientos individuales, como si fueran suyos." },
		[2016] = { file = "2016", len = 17.189, text = "La colérica cacofonía en su mente hizo que Ner'zhul acumulara aún más poder, como si sus espíritus le proporcionaran el alimento necesario. Descubrió que era un juego de niños controlar las acciones de los zombis y hacer que realizaran todo aquello que deseaba." },
		[2017] = { file = "2017", len = 16.744, text = "En los siguientes meses, Ner'zhul continuó experimentando con su peste de los no-muertos, sometiendo a todos los habitantes humanos de Rasganorte. Con su ejército de no-muertos creciendo a diario, sabía que se acercaba el momento de realizar la verdadera prueba." },
		[2018] = { file = "2018", len = 35.056, text = "Mientras tanto, en las atormentadas tierras del sur, los dispersos supervivientes de la Horda luchaban por su mera supervivencia. Aunque Grom Grito Infernal y su clan Grito de Guerra habían logrado evitar ser capturados, Mortojo y su clan Foso Sangrante fueron rodeados y conducidos a campos de internamiento en Lordaeron. A pesar de estos costosos levantamientos, pronto los celadores de los campos lograron recuperar el control sobre sus salvajes prisioneros." },
		[2019] = { file = "2019", len = 35.317, text = "Sin embargo, sin que la Alianza lo supiera, una gran fuerza de orcos aún vagaba libre en los páramos del norte de Khaz Modan. El clan Faucedraco, dirigido por el infame brujo Nekros, estaba utilizando un viejo artefacto conocido como Alma demoníaca para controlar a la reina de los dragones Alexstrasza y a su Vuelo. Teniendo a la reina de los dragones como rehén, Nekros creó un ejército secreto en el interior de la abandonada fortaleza de Martillo Salvaje de Grim Batol (algunos decían que estaba maldita)." },
		[2020] = { file = "2020", len = 24.529, text = "Con la intención de liberar sus fuerzas y a los poderosos dragones rojos de la Alianza, Nekros esperaba reunir a la Horda y continuar su conquista de Azeroth. Su visión no llegó a realizarse: un pequeño grupo de luchadores de la resistencia, dirigido por el mago humano Rhonin, logró destruir el Alma demoníaca y liberar a la reina de los dragones del yugo de Nekros." },
		[2021] = { file = "2021", len = 27.141, text = "En su furia, los dragones de Alexstrasza destruyeron Grim Batol e incineraron a la mayor parte del clan Faucedraco. Los grandes planes de reunificación de Nekros cayeron por los suelos cuando las tropas de la Alianza rodearon a los orcos supervivientes y los arrojaron a los campos de internamiento. La derrota del clan Faucedraco señaló el fin de la Horda y el fin de la furiosa sed de sangre de los orcos." },
		[2022] = { file = "2022", len = 27.429, text = "Pasaron los meses y más prisioneros orcos fueron capturados, tras lo cual fueron conducidos a los campos de internamiento. Cuando los campos empezaron a estar superpoblados, la Alianza tuvo que construir nuevos campos en las planicies del sur de las Montañas de Alterac. Para mantener adecuadamente el creciente número de campos, el rey Terenas impuso un nuevo impuesto a las naciones de la Alianza." },
		[2023] = { file = "2023", len = 16.692, text = "Este impuesto, junto con el incremento de las tensiones políticas sobre disputas fronterizas, crearon intranquilidad en toda la región. Parecía como si el frágil pacto que habían forjado las naciones humanas en sus peores momentos pudiera romperse en cualquier momento." },
		[2024] = { file = "2024", len = 22.57, text = "En medio de los disturbios políticos, muchos de los celadores de los campos empezaron a observar inquietantes cambios en sus orcos cautivos. Con el tiempo, los esfuerzos de los orcos por escapar de los campos o, incluso, las luchas entre ellos, habían descendido enormemente. Los orcos parecían cada vez más distantes y aletargados." },
		[2025] = { file = "2025", len = 18.26, text = "Aunque era difícil de creer, los orcos, considerados la raza más agresiva jamás vista en Azeroth, habían perdido por completo su voluntad de luchar. El extraño letargo confundió a los líderes de la Alianza y continuó cobrando su peaje sobre los orcos cada vez más debilitados." },
		[2026] = { file = "2026", len = 25.861, text = "Como causa del desconcertante letargo, algunos especularon con la posibilidad de una extraña enfermedad que solo podían contraer los orcos. Pero el archimago Antónidas de Dalaran formuló una hipótesis distinta. Investigando detalladamente acerca de la historia de los orcos, Antónidas descubrió que estos habían sufrido la atroz influencia del poder demoníaco durante generaciones." },
		[2027] = { file = "2027", len = 19.905, text = "Especuló que los orcos habían sido corrompidos por estos poderes incluso antes de su primera invasión de Azeroth. Claramente, los demonios habían contaminado la sangre de los orcos y estos, a su vez, habían sido dotados de una fuerza, una resistencia y una capacidad de agresión ciertamente fuera de lo normal." },
		[2028] = { file = "2028", len = 14.733, text = "Antónidas consideró que el letargo colectivo de los orcos no era en realidad una enfermedad, sino la consecuencia de la abstinencia racial en relación con la volátil magia del brujo, que los había convertido en guerreros temibles y sanguinarios." },
		[2029] = { file = "2029", len = 26.384, text = "Aunque los síntomas eran claros, Antónidas fue incapaz de encontrar una cura para la enfermedad de los orcos. Posteriormente, muchos de sus compañeros magos, así como algunos notables líderes de la Alianza, argumentaron que encontrar una cura para los orcos podía ser una aventura imprudente. Considerando el misterioso estado de los orcos, Antónidas concluyó que la cura de los orcos debía tener un carácter espiritual." },
		[2030] = { file = "2030", len = 42.083, text = "El celador jefe de los campos de internamiento, Aedelas Lodonegro, vigilaba a los orcos cautivos desde su prisión-fortaleza Durnholde. Un orco en particular había llamado siempre su atención: el niño huérfano que había encontrado aproximadamente hacía dieciocho años. Lodonegro se ocupó de que el joven, aunque esclavo, tuviera un trato de favor y lo llamó Thrall. Lodonegro enseñó a los orcos táctica, filosofía y técnicas de combate. Incluso, Thrall fue entrenado como gladiador. Durante todo el tiempo, el guardián corrupto trató de moldear al orco, convirtiéndolo en un arma." },
		[2031] = { file = "2031", len = 39.236, text = "A pesar de la dureza de su educación, el joven Thrall se convirtió en un orco fuerte y mentalmente ágil, pero en su corazón sabía que la vida de esclavo no era para él. Cuando alcanzó la madurez, aprendió la historia de su pueblo, los orcos, a quienes nunca había encontrado: tras su derrota, casi todos habían sido confinados en campos de internamiento. Había rumores de que Martillo Maldito, el líder de los orcos, había escapado de Lordaeron y se había ocultado. Solo un solitario clan aún actuaba en secreto, intentando evitar la atenta mirada de la Alianza." },
		[2032] = { file = "2032", len = 29.362, text = "El resuelto pero aún inexperto Thrall decidió escapar de la fortaleza de Lodonegro y marchar en busca de otros de su clase. Durante sus viajes, Thrall visitó los campos de internamiento y vio que su raza, otrora poderosa, estaba extrañamente intimidada y aletargada. Al no encontrar a los orgullosos guerreros que esperaba descubrir, Thrall marchó en busca del último jefe orco que aún no había sido derrotado, Grom Grito Infernal." },
		[2033] = { file = "2033", len = 33.202, text = "Perseguido sin descanso por los humanos, Grito Infernal nunca perdió el insaciable apetito de la Horda por la lucha. Con la única ayuda de su devoto clan Grito de Guerra, Grito Infernal continuó librando una guerra subterránea contra la opresión de su sitiado pueblo. Desafortunadamente, Grito Infernal nunca encontró un medio de liberar a los orcos capturados de su aletargamiento. El impresionable Thrall, inspirado por el idealismo de Grito Infernal, desarrolló una fuerte empatía por la Horda y sus tradiciones guerreras." },
		[2034] = { file = "2034", len = 26.175, text = "Buscando la verdad de sus propios orígenes, Thrall viajó hacia el norte para localizar al legendario clan Lobo Gélido. Thrall supo que Gul'dan se había separado de los Lobo Gélido durante el comienzo de la Primera Guerra. Asimismo, descubrió que era el hijo y heredero del héroe orco Durotan, el verdadero jefe de los Lobo Gélido que había sido asesinado en los bosques hacía veinte años." },
		[2035] = { file = "2035", len = 31.504, text = "Bajo la tutela del venerable chamán Drek’Thar, Thrall estudió la antigua cultura chamánica de su pueblo, que había sido olvidada bajo la égida maligna de Gul'dan. Con el tiempo, Thrall se convirtió en un poderoso chamán y ocupó su lugar por derecho como jefe de los Lobo Gélido exiliados. Gracias a los poderes que le conferían los propios elementos y decidido a encontrar su propio destino, Thrall partió con el propósito de liberar a los clanes cautivos y librar a su raza de la corrupción demoníaca." },
		[2036] = { file = "2036", len = 32.862, text = "En el transcurso de sus viajes, Thrall encontró al viejo jefe guerrero Orgrim Martillo Maldito, que había estado viviendo como un ermitaño durante muchos años. Martillo Maldito, que había sido un amigo muy próximo del padre de Thrall, decidió seguir al joven y visionario orco y ayudarle en su propósito de liberar a los clanes cautivos. Con el apoyo de muchos de los jefes veteranos, finalmente Thrall alcanzó el éxito revitalizando a la Horda y proporcionando a su pueblo una nueva identidad espiritual." },
		[2037] = { file = "2037", len = 22.622, text = "Para simbolizar el renacimiento de su pueblo, Thrall regresó a la fortaleza de Lodonegro en Durnholde y puso fin, de una vez por todas, a los planes de su antiguo maestro, sitiando los campos de internamiento. Esta victoria no fue gratuita: durante el proceso de liberación de un campo, Martillo Maldito cayó en la batalla." },
		[2038] = { file = "2038", len = 32.914, text = "Thrall recogió el legendario martillo de guerra del afamado Martillo Maldito y se puso su armadura negra para convertirse en el nuevo jefe guerrero de la Horda. En el transcurso de los meses siguientes, la pequeña pero volátil Horda de Thrall liberó los campos de internamiento y frustró los mejores esfuerzos de la Alianza para contrarrestar sus inteligentes estrategias. Alentado por su mejor amigo y mentor, Grom Grito Infernal, Thrall trabajó para asegurarse de que su pueblo nunca volviera a ser esclavizado." },
		[2039] = { file = "2039", len = 26.07, text = "Mientras Thrall liberaba a sus hermanos en Lordaeron, Ner'zhul continuaba incrementando su base de poder en Rasganorte. Se erigió una gran ciudadela por encima del Glaciar Corona de Hielo y fue ocupada por las crecientes legiones de muertos. Aun cuando el Rey Exánime extendía su influencia sobre la tierra, un misterioso imperio resistió su poder." },
		[2040] = { file = "2040", len = 25.339, text = "El antiguo reino subterráneo de Azjol-Nerub, que había sido fundado por una raza de siniestras arañas humanoides, envió a su guardia de élite para atacar Corona de Hielo y terminar con el loco apetito de dominio del Rey Exánime. Para su frustración, Ner'zhul comprobó que los malvados nerubianos resultaban inmunes no solo a la peste, sino también a su dominio mediante la telepatía." },
		[2041] = { file = "2041", len = 40.072, text = "Los señores araña nerubianos dirigían grandes ejércitos y tenían una red subterránea que abarcaba prácticamente la mitad de Rasganorte. Sus tácticas, que consistían en golpear y escapar de las fortalezas del Rey Exánime, frustraron sus esfuerzos por acabar con ellos una y otra vez. Finalmente, Ner'zhul ganó la guerra contra los nerubianos mediante una estrategia de desgaste. Con la ayuda de los siniestros Señores del Terror y de innumerables guerreros no-muertos, el Rey Exánime invadió Azjol-Nerub y tomó sus templos subterráneos, aplastando las cabezas de los señores araña." },
		[2042] = { file = "2042", len = 21.943, text = "Aunque los nerubianos eran inmunes a su peste, los crecientes poderes nigrománticos de Ner'zhul le permitieron resucitar los cadáveres de los guerreros araña, logrando que siguieran su voluntad. Como testamento de su tenacidad y valor, Ner'zhul adoptó el estilo arquitectónico distintivo de los nerubianos en sus propias fortalezas y estructuras." },
		[2043] = { file = "2043", len = 17.189, text = "Pudiendo gobernar su reino sin oposición, el Rey Exánime empezó a prepararse para llevar a cabo su verdadera misión en el mundo. Intentando alcanzar las tierras humanas con su vasta conciencia, el Rey Exánime convocó a todas las almas oscuras que pudieron escucharle..." },
		[2044] = { file = "2044", len = 32.862, text = "Había un puñado de individuos poderosos esparcidos por el mundo, que oyeron las peticiones mentales del Rey Exánime desde Rasganorte. El más destacable de estos personajes era el archimago de Dalaran, Kel'Thuzad, que era uno de los miembros principales del consejo de gobierno de Dalaran, el Kirin Tor. Durante años, había sido considerado un inconformista, debido a su insistencia en estudiar las prohibidas artes de la nigromancia." },
		[2045] = { file = "2045", len = 35.918, text = "Decidido a aprender todo lo que pudiera del mundo mágico y de sus oscuras maravillas, se vio frustrado por lo que consideró una serie de preceptos pasados de moda y carentes de imaginación de sus pares. Tras oír las poderosas invocaciones procedentes de Rasganorte, el archimago concentró toda su voluntad, intentando comunicarse con la misteriosa voz. Convencido de que el Kirin Tor era demasiado impresionable como para adoptar el poder y el conocimiento inherente a las artes oscuras, se resignó a aprender todo cuanto podía del inmensamente poderoso Rey Exánime." },
		[2046] = { file = "2046", len = 25.704, text = "Olvidando su fortuna y su prestigio político, Kel'Thuzad abandonó los caminos del Kirin Tor, dejando Dalaran para siempre. Empujado por la persistente voz del Rey Exánime que oía en su mente, vendió sus vastas posesiones y guardó su fortuna. Atravesando a solas muchas leguas tanto por tierra como por mar, finalmente alcanzó las heladas costas de Rasganorte." },
		[2047] = { file = "2047", len = 24.059, text = "Intentando llegar a Corona de Hielo para ofrecer sus servicios al Rey Exánime, el archimago atravesó las saqueadas y destruidas ruinas de Azjol-Nerub. Kel'Thuzad comprobó de primera mano el alcance y la ferocidad del poder de Ner'zhul. Empezó a darse cuenta de que aliarse con el misterioso Rey Exánime podía ser al mismo tiempo una decisión sabia y potencialmente fructífera." },
		[2048] = { file = "2048", len = 20.715, text = "Tras arduos meses recorriendo las duras y baldías tierras árticas, finalmente Kel'Thuzad llegó al oscuro Glaciar Corona de Hielo. Con audacia, se acercó a la ciudadela negra de Ner'zhul y quedó muy impresionado cuando los guardias no-muertos le dejaron pasar silenciosamente, como si estuvieran esperándole." },
		[2049] = { file = "2049", len = 15.621, text = "Kel'Thuzad descendió a las profundidades de la tierra helada y se dirigió hacia la base del glaciar. Allí, en la interminable caverna de hielo y sombras, se postró ante el Trono Helado y ofreció su alma al oscuro señor de los muertos." },
		[2050] = { file = "2050", len = 24.085, text = "El Rey Exánime estaba muy complacido con su más reciente adepto. Prometió a Kel'Thuzad la inmortalidad y grandes poderes a cambio de su lealtad y obediencia. Hambriento de conocimientos y poderes oscuros, Kel'Thuzad aceptó su primera gran misión: adentrarse en el mundo de los hombres y fundar una nueva religión que adoraría al Rey Exánime como a un dios." },
		[2051] = { file = "2051", len = 30.929, text = "Para ayudar al archimago a cumplir su misión, Ner'zhul dejó intacta la humanidad de Kel'Thuzad. El viejo, pero aún carismático mago, recibió el don de utilizar sus poderes de ilusión y persuasión para adormecer a las oprimidas masas de Lordaeron y lograr que confiaran y creyeran de nuevo. Luego, una vez que lograra captar su atención, les ofrecería una nueva visión de lo que podría ser la sociedad - y un nuevo mascarón de proa al que pudieran considerar rey." },
		[2052] = { file = "2052", len = 23.615, text = "Kel'Thuzad regresó a Lordaeron disfrazado y, por espacio de tres años, utilizó su fortuna y su intelecto para reunir a una hermandad clandestina de hombres y mujeres de ideas afines. La hermandad, a la que denominó el Culto de los Malditos, prometió a sus acólitos igualdad social y la vida eterna en Azeroth a cambio de su servicio y obediencia a Ner'zhul." },
		[2053] = { file = "2053", len = 33.228, text = "A medida que pasaron los meses, Kel'Thuzad encontró muchos voluntarios ansiosos para su nuevo culto entre los cansados y explotados obreros de Lordaeron. Kel'Thuzad alcanzó sus objetivos con sorprendente facilidad: concretamente, logró convertir la fe de los ciudadanos en la Luz Sagrada en una creencia en la oscura sombra de Ner'zhul. A medida que el Culto de los Malditos creció en tamaño e influencia, Kel'Thuzad se aseguró de que sus actividades quedaran ocultas a ojos de las autoridades de Lordaeron." },
		[2054] = { file = "2054", len = 21.838, text = "Con el éxito de Kel'Thuzad en Lordaeron, el Rey Exánime realizó los preparativos finales para asaltar la civilización humana. Tras volcar su energía corrupta sobre diversos artefactos portátiles llamados calderas de peste, Ner'zhul ordenó a Kel'Thuzad que llevara las calderas a Lordaeron, ocultándolas en varios poblados leales." },
		[2055] = { file = "2055", len = 11.259, text = "Las calderas, protegidas por cultores seguidores, actuarían como generadores de peste, dispersándola a través de los indefensos campos y ciudades del norte de Lordaeron." },
		[2056] = { file = "2056", len = 18.233, text = "El plan del Rey Exánime funcionó a la perfección. Muchos poblados del norte de Lordaeron se contaminaron casi de inmediato. Como ocurrió en Rasganorte, los ciudadanos que contrajeron la peste murieron y renacieron como esclavos del Rey Exánime." },
		[2057] = { file = "2057", len = 27.925, text = "Los seguidores de Kel'Thuzad deseaban morir para renacer al servicio del señor de las tinieblas. Se regocijaban ante la perspectiva de alcanzar la inmortalidad de los no-muertos. Con la propagación de la peste, cada vez más zombis ferales se alzaron en las tierras del norte. Kel'Thuzad observó el ejército del Rey Exánime y lo nombró la Plaga, pues pronto marcharía hasta las puertas de Lordaeron... borrando a la humanidad de la faz de la tierra." },
		[2064] = { file = "2064", len = 29.074, text = "Tras largos meses de preparación, Kel'Thuzad y su Culto de los Malditos finalmente dieron el primer golpe, lanzando la peste de los no-muertos sobre Lordaeron. Uther y sus compañeros paladines investigaron las regiones infectadas con la esperanza de encontrar un medio de detener la peste. A pesar de sus esfuerzos, la peste continuó extendiéndose, amenazando con destrozar la Alianza." },
		[2065] = { file = "2065", len = 36.963, text = "Cuando las filas de no-muertos marcharon sobre Lordaeron, el único hijo de Terenas, el príncipe Arthas, asumió la dirección de la lucha contra la Plaga. Arthas logró acabar con Kel'Thuzad, pero, incluso así, los ejércitos de no-muertos aumentaron con cada uno de los Soldados que caía defendiendo la tierra. Frustrado y descorazonado por enfrentarse a un enemigo aparentemente imposible de detener, Arthas tomó una serie de medidas extremas para conquistarlos. Finalmente, los compañeros de Arthas le advirtieron que estaba perdiendo su propia humanidad." },
		[2066] = { file = "2066", len = 24.398, text = "El miedo y la resolución de Arthas resultaron ser su perdición. Siguió el rastro del origen de la peste hasta Rasganorte, intentado acabar con esta amenaza para siempre. En su lugar, el príncipe Arthas sucumbió ante el tremendo poder del Rey Exánime. Creyendo que esto salvaría a su gente, tomó la hojarruna maldita, Agonía de Escarcha." },
		[2067] = { file = "2067", len = 25.025, text = "Aunque la espada le concedió un poder inefable, también robó su alma y lo transformó en el más grande de los caballeros de la Muerte del Rey Exánime. Con su alma apartada de sí y perdida su cordura, Arthas dirigió a la Plaga contra su propio reino. Finalmente, Arthas mató a su propio padre, el rey Terenas, y aplastó Lordaeron bajo la bota de hierro del Rey Exánime." },
		[2068] = { file = "2068", len = 29.936, text = "Si bien derrotó a todos aquellos a quienes ahora veía como enemigos, el fantasma de Kel'Thuzad siguió rondándolo. El fantasma le comunicó que necesitaba revivir para llevar a cabo la siguiente fase del plan del Rey Exánime. Para este propósito, Arthas debía llevar los restos de Kel'Thuzad a la mística Fuente del Sol, oculta en el eterno reino de Quel'Thalas de los elfos nobles." },
		[2069] = { file = "2069", len = 31.477, text = "Arthas y su Plaga invadieron Quel'Thalas y pusieron sitio a las desmoronadas defensas de los elfos. Sylvanas Brisaveloz, general forestal de Lunargenta, mostró fiera resistencia, pero finalmente, Arthas acabó con el ejército de los elfos nobles hasta llegar a La Fuente del Sol. En un cruel gesto de dominio, utilizó el cuerpo exánime de Sylvanas como estandarte, que quedaría condenada a ser un alma en pena no-muerta, al servicio del conquistador de Quel'Thalas." },
		[2070] = { file = "2070", len = 21.943, text = "Finalmente, Arthas sumergió los restos de Kel'Thuzad en las aguas sagradas de La Fuente del Sol. Si bien las poderosas aguas de la Eternidad quedaron contaminadas por este acto, Kel'Thuzad renació como un hechicero exánime. Tras renacer como un ser mucho más poderoso, Kel'Thuzad explicó la siguiente fase del plan del Rey Exánime." },
		[2071] = { file = "2071", len = 15.151, text = "Cuando Arthas y su ejército de muertos se dirigieron hacia el sur, no quedaba ni un solo elfo vivo en Quel'Thalas. La gloriosa patria de los elfos nobles, que había permanecido en pie durante más de nueve mil años, había dejado de existir." },
		[2072] = { file = "2072", len = 40.307, text = "Una vez que Kel'Thuzad volvió a ser un todo, Arthas condujo a la Plaga hasta el sur de Dalaran. Allí, el exánime obtendría el poderoso libro de hechizos de Medivh y lo usaría para invocar a Archimonde y traerlo de regreso al mundo. De aquí en adelante, Archimonde en persona comenzaría a realizar la invasión final de la Legión. Incluso los zahoríes del Kirin Tor se mostraban incapaces de detener a las fuerzas de Arthas, impidiéndoles que robaran el libro de Medivh y pronto, Kel'Thuzad reunió todos los elementos para realizar su encantamiento." },
		[2073] = { file = "2073", len = 23.902, text = "Transcurridos diez mil años, el poderoso demonio Archimonde y su anfitrión emergieron una vez más en el mundo de Azeroth. Aun así, Dalaran no iba a ser su destino final. Bajo las órdenes del propio Kil'jaeden, Archimonde y sus demonios siguieron a la Plaga de los no-muertos hasta Kalimdor, con el propósito de destruir Nordrassil, el árbol del Mundo." },
		[2074] = { file = "2074", len = 24.268, text = "En medio de este caos, un solitario y misterioso profeta apareció para guiar a las razas mortales. Este profeta resultó ser Medivh, el último guardián, que había regresado milagrosamente del Más Allá para redimirse de sus pasados pecados. Medivh alertó a la Horda y a la Alianza acerca de los peligros a los que se enfrentaban y los conminó a que unieran sus fuerzas." },
		[2075] = { file = "2075", len = 24.033, text = "Ahítos de generaciones de odio, los orcos y los humanos no tenían nada en común. Medivh se vio obligado a tratar con cada raza por separado, utilizando las profecías y su habilidad para guiarlos a través del mar, hacia la legendaria tierra de Kalimdor. Pronto, los orcos y los humanos encontraron la civilización de los kaldorei, oculta durante mucho tiempo." },
		[2076] = { file = "2076", len = 29.701, text = "Los orcos, dirigidos por Thrall, sufrieron una serie de reveses hacia los baldíos de Kalimdor. Aunque contaban con la amistad de Cairne Pezuña de Sangre y sus poderosos guerreros tauren, muchos orcos empezaron a sucumbir a la demoníaca sed de sangre que los había contaminado durante años. El lugarteniente más importante de Thrall, Grom Grito Infernal, llegó incluso a traicionar a la Horda, abandonándose a sus más bajos instintos." },
		[2077] = { file = "2077", len = 33.306, text = "Mientras Grito Infernal y sus leales guerreros Grito de Guerra merodeaban por los bosques de Vallefresno, se enfrentaron a los antiguos centinelas y elfos de la noche. Persuadidos de que los orcos habían vuelto por sus fueros, retomando sus viejas costumbres, el semidiós Cenarius apareció para lograr que Grito Infernal y sus orcos regresaran. No obstante, Grito Infernal y sus orcos, vencidos por una rabia y un odio sobrenaturales, asesinaron a Cenarius y corrompieron los antiguos bosques." },
		[2078] = { file = "2078", len = 18.495, text = "Finalmente, Grito Infernal consiguió redimir su honor, ayudando a Thrall a derrotar a Mannoroth, el señor demonio que lanzó por vez primera sobre la línea de sangre de los orcos una maldición de odio y rabia. Con la muerte de Mannoroth, la maldición de sangre de los orcos llegó a su fin." },
		[2079] = { file = "2079", len = 35.082, text = "Mientras Medivh intentaba convencer a los orcos y a los humanos de la necesidad de una alianza, los elfos de la noche luchaban contra la Legión, utilizando sus propias tácticas secretas. Tyrande Susurravientos, la inmortal suma sacerdotisa de los centinelas y elfos de la noche, combatió desesperadamente para evitar que los demonios y los no-muertos arrasaran los bosques de Vallefresno. Tyrande se dio cuenta de que necesitaba ayuda y se dispuso a despertar a los druidas de los elfos de la noche de su profundo sueño de mil años." },
		[2080] = { file = "2080", len = 15.438, text = "Invocando a su antiguo amor, Malfurion Tempestira, Tyrande logró galvanizar sus defensas e hizo volver a la Legión. Con la ayuda de Malfurion, la propia naturaleza logró derrotar a la Legión y a sus aliados de la Plaga." },
		[2081] = { file = "2081", len = 20.14, text = "Mientras buscaba más druidas en hibernación, Malfurion encontró la antigua prisión-túmulo en la que había encadenado a su hermano Illidan. Convencido de que Illidan los ayudaría contra la Legión, Tyrande lo liberó. Aunque Illidan los ayudó durante un tiempo, finalmente huyó para perseguir sus propias metas." },
		[2082] = { file = "2082", len = 24.529, text = "Los elfos de la noche se prepararon y lucharon contra la Legión Ardiente con gran determinación. La Legión nunca había abandonado su deseo de conquistar el Pozo de la Eternidad, durante mucho tiempo fuente de poder del árbol del Mundo y corazón del reino de los elfos de la noche. Si el asalto que planeaban contra el árbol tenía éxito, los demonios acabarían literalmente con el mundo." },
		[2083] = { file = "2083", len = 22.282, text = "Durante la invasión de Vallefresno por parte de la Legión, Illidan fue liberado de su prisión tras diez mil años de cautividad. Aunque intentó apaciguar a sus compañeros, pronto recuperó su verdadera forma y consumió las energías de un poderoso artefacto de hechicero conocido como el Cráneo de Gul'dan." },
		[2084] = { file = "2084", len = 19.252, text = "Con ello, Illidan desarrolló poderes magníficos y rasgos demoníacos. Asimismo, logró hacerse con algunos de los viejos recuerdos de Gul'dan: especialmente los que hacían referencia a la tumba de Sargeras, la isla mazmorra en donde se decía que estaban los restos de Sargeras, el titán oscuro." },
		[2085] = { file = "2085", len = 23.092, text = "Transido de poder y libre para vagar por el mundo una vez más, Illidan procuró encontrar su sitio en el mundo. Sin embargo, Kil'jaeden se enfrentó a Illidan y le hizo una oferta que no podía rechazar. Kil'jaeden estaba enfadado por la derrota de Archimonde en el monte Hyjal, pero tenía preocupaciones más importantes que la venganza." },
		[2086] = { file = "2086", len = 22.335, text = "Viendo que su creación, el Rey Exánime, estaba adquiriendo demasiado poder como para ser controlada, Kil'jaeden ordenó a Illidan destruir a Ner'zhul y poner fin, de una vez por todas, a la Plaga de los no-muertos. A cambio, Illidan recibiría poderes ilimitados y un puesto entre los señores restantes de la Legión Ardiente." },
		[2087] = { file = "2087", len = 25.992, text = "Illidan accedió y se dirigió de inmediato a destruir el Trono Helado, la urna de cristal congelada en la que residía el espíritu del Rey Exánime. Illidan sabía que necesitaría un poderoso artefacto para destruir el Trono Helado. Utilizando el conocimiento que obtuvo a partir de los recuerdos de Gul'dan, Illidan decidió localizar la tumba de Sargeras y reclamar los restos del titán oscuro." },
		[2088] = { file = "2088", len = 19.331, text = "Exigió el pago inmediato de algunas viejas deudas de los Altonato y atrajo a los nagas serpenteantes, que habitaban en su oscura guarida bajo el mar. Dirigidos por la astuta Lady Vashj, los nagas ayudaron a Illidan a alcanzar las Islas Quebradas, en donde se rumoreaba estaba la tumba de Sargeras." },
		[2089] = { file = "2089", len = 28.526, text = "Cuando Illidan partió junto con los nagas, la celadora Maiev Cantosombrío comenzó a darle caza. Maiev había sido la carcelera de Illidan durante diez mil años y estaba entusiasmada ante la perspectiva de poder volverlo a capturar. Sin embargo, Illidan burló a Maiev y a sus guardianes y, a pesar de sus esfuerzos, logró reclamar el Ojo de Sargeras. Con el poderoso Ojo en sus manos, Illidan se dirigió a la antigua ciudad zahorí de Dalaran." },
		[2090] = { file = "2090", len = 30.224, text = "Reforzado por las líneas de poder de la ciudad, Illidan utilizó el Ojo para formular un encantamiento destructivo contra la Ciudadela de la Corona de Hielo del Rey Exánime, situada en el distante Rasganorte. El ataque de Illidan destruyó las defensas del Rey Exánime y produjo una ruptura en el techo del mundo. En el último momento, el encantamiento destructivo de Illidan fue detenido cuando su hermano Malfurión y la sacerdotisa Tyrande acudieron en ayuda de Maiev." },
		[2091] = { file = "2091", len = 21.107, text = "Sabiendo que a Kil'jaeden no le complacería su fracaso a la hora de destruir el Trono Helado, Illidan se dirigió a la dimensión baldía conocida como Terrallende: los últimos restos de Draenor, el antiguo hogar de los orcos. Allí planeó cómo escapar de la ira de Kil'jaeden y caviló acerca de sus próximos movimientos." },
		[2092] = { file = "2092", len = 17.006, text = "Tras lograr el éxito deteniendo a Illidan, Malfurion y Tyrande regresaron al bosque de Vallefresno para ayudar a su gente. Sin embargo, Maiev no abandonó tan fácilmente, y persiguió a Illidan hasta Terrallende, decidida a ponerlo en manos de la justicia." },
		[2093] = { file = "2093", len = 27.925, text = "En ese tiempo, la Plaga de los no-muertos había convertido Lordaeron y Quel'Thalas en las tóxicas Tierras de la Peste. Hubo muy pocas bolsas de resistencia de la Alianza que le hicieran frente. Uno de estos grupos, que constaba fundamentalmente de elfos nobles, estaba dirigido por el último miembro de la dinastía Caminante del Sol: el príncipe Kael'thas." },
		[2094] = { file = "2094", len = 24.398, text = "Kael, un experimentado zahorí, se mostró receloso ante el fracaso de la Alianza. Los elfos nobles se lamentaron por la pérdida de su hogar y decidieron llamarse a sí mismos elfos de sangre, en honor a sus caídos. Aun así, como intentaron mantener a la Plaga a raya, sufrieron enormemente al quedar aislados de La Fuente del Sol que les había transmitido su poder." },
		[2095] = { file = "2095", len = 26.749, text = "Desesperado al intentar encontrar un remedio para la adicción racial de su gente hacia la magia, Kael hizo lo impensable: adoptó al ancestro Altonato de su pueblo y se unió con Illidan y sus nagas con la esperanza de encontrar una nueva fuente de poder mágico que les transmitiera su energía. Los demás Comandantes de la Alianza consideraron traidores a los elfos de sangre y los desterraron por el bien de la comunidad." },
		[2096] = { file = "2096", len = 27.167, text = "Sin ningún lugar adonde ir, los elfos de sangre siguieron a Lady Vashj hasta Terrallende para combatir a la celadora Maiev, que había vuelto a capturar a Illidan. Con las fuerzas conjuntas de los nagas y los elfos de sangre, lograron derrotar a Maiev y liberar a Illidan. Instalado en Terrallende, Illidan reunió a sus fuerzas para golpear por segunda vez al Rey Exánime y a su fortaleza de Corona de Hielo." },
		[2097] = { file = "2097", len = 33.228, text = "Ner'zhul, el Rey Exánime, sabía que le quedaba poco tiempo. Prisionero en el Trono de Hielo, sospechaba que Kil'jaeden enviaría a sus agentes para destruirlo. El daño causado por el encantamiento de Illidan había roto el Trono de Hielo. De esa manera, el Rey Exánime perdía su poder diariamente. Desesperado por salvarse, trajo a su lado a su mayor sirviente mortal: el caballero de la Muerte, el príncipe Arthas." },
		[2098] = { file = "2098", len = 29.335, text = "Aunque sus poderes fueron consumidos por la debilidad del Rey Exánime, Arthas participó en una guerra civil en Lordaeron. La mitad de las fuerzas de no-muertos aún en pie, conducidos por el alma en pena Sylvanas Brisaveloz, dieron un golpe de mano para controlar el imperio de los no-muertos. Arthas, llamado por el Rey Exánime, fue obligado a abandonar la Plaga en manos de su lugarteniente, Kel'Thuzad, cuando la guerra se extendió por las Tierras de la Peste." },
		[2099] = { file = "2099", len = 20.402, text = "Finalmente, Sylvanas y sus no-muertos rebeldes (conocidos como los Renegados) reclamaron la propiedad de la destruida ciudad capital de Lordaeron. Tras construir su propio bastión bajo la ciudad en ruinas, los Renegados juraron derrotar a la Plaga y expulsar a Kel'Thuzad y a sus esbirros de aquellas tierras." },
		[2100] = { file = "2100", len = 20.271, text = "Debilitado, pero decidido a salvar a su maestro, Arthas llegó a Rasganorte para descubrir que los nagas y los elfos de sangre de Illidan estaban esperándole. Él y sus aliados nerubianos lucharon contra las fuerzas de Illidan para alcanzar el Glaciar Corona de Hielo y defender el Trono de Hielo." },
		[2101] = { file = "2101", len = 21.969, text = "A pesar de su debilidad, Arthas finalmente se mostró más hábil que Illidan y llegó primero hasta el Trono de Hielo. Utilizando su hojarruna Agonía de Escarcha, Arthas destrozó la prisión helada del Rey Exánime y, de esta manera, liberó el yelmo encantado y la coraza de Ner'zhul." },
		[2102] = { file = "2102", len = 24.973, text = "Arthas se colocó el yelmo de inimaginable poder sobre su cabeza y se convirtió en el nuevo Rey Exánime. Los espíritus de Ner'zhul y Arthas se fundieron en un único ser poderoso, tal como Ner'zhul había planeado. Illidan y sus tropas fueron obligados a huir hacia Terrallende, mientras que Arthas se convirtió en una de las entidades más poderosas que el mundo jamás había conocido." },
		[2103] = { file = "2103", len = 24.816, text = "Actualmente, Arthas, el nuevo e inmortal Rey Exánime, reside en Rasganorte. Se rumorea que está reconstruyendo la Ciudadela de la Corona de Hielo. Su fiel lugarteniente, Kel'Thuzad, dirige la Plaga en las Tierras de la Peste. Sylvanas y sus rebeldes Renegados solo conservan los Claros de Tirisfal, una pequeña parte del reino destrozado por la guerra." },
		[2104] = { file = "2104", len = 38.531, text = "Aunque la victoria fue suya, las razas mortales se encontraron con un mundo destruido por la guerra. La Plaga y la Legión Ardiente lo tenían todo, pero destruyeron las civilizaciones de Lordaeron y casi dieron por terminado su trabajo en Kalimdor. Había bosques que replantar, rencores que enterrar y hogares que fundar. La guerra había provocado profundas heridas en todas las razas, pero todas ellas habían hecho causa común para intentar un nuevo comienzo, empezando por la precaria tregua entre la Alianza y la Horda." },
		[2105] = { file = "2105", len = 17.11, text = "Thrall condujo a los orcos hacia el continente de Kalimdor, en donde fundaron un nuevo hogar con la ayuda de sus hermanos tauren. Llamándolo Durotar, para recordar al padre asesinado de Thrall, los orcos se asentaron para reconstruir su sociedad antaño gloriosa." },
		[2106] = { file = "2106", len = 25.731, text = "Ahora que la maldición del demonio había terminado, la Horda pasó de ser un gigante bélico preparado para la guerra a ser una coalición más flexible, dedicada a la supervivencia y la prosperidad antes que la conquista. Ayudado por el noble tauren los astutos trols de la tribu Lanza Negra, Thrall y sus orcos miraron hacia el futuro, esperanzados en una nueva era de paz en su propia tierra." },
		[2107] = { file = "2107", len = 30.694, text = "Las restantes fuerzas de la Alianza, bajo la égida de Jaina Valiente, se asentaron en el sur de Kalimdor. Desde la costa oriental del Marjal Revolcafango, construyeron la tosca ciudad portuaria de Theramore. Allí, los humanos y sus aliados enanos trabajaron para sobrevivir en una tierra que siempre les había sido hostil. Aunque los defensores de Durotar y Theramore trataron de mantener la tregua en vigor, la frágil paz colonial no habría de durar mucho." },
		[2108] = { file = "2108", len = 27.533, text = "La paz entre los orcos y los humanos se quebró debido a la llegada de una gran flota de la Alianza a Kalimdor. La poderosa flota, bajo las órdenes del gran almirante Daelin Valiente (el padre de Jaina), había abandonado Lordaeron antes de que Arthas destruyera el reino. Habiendo navegado penosamente durante meses, el almirante Valiente buscaba a todos los posibles supervivientes que quedaran de la Alianza." },
		[2109] = { file = "2109", len = 17.345, text = "La armada de Valiente resultó ser una seria amenaza para la estabilidad de la región. Como héroe reconocido de la Segunda Guerra, el padre de Jaina era acérrimo enemigo de la Horda y estaba decidido a destruir Durotar antes de que los orcos llegaran a poner un pie en su tierra." },
		[2110] = { file = "2110", len = 24.189, text = "El gran almirante obligó a Jaina a tomar una terrible decisión: Debía apoyarlo en la batalla contra los orcos y traicionar a sus nuevos aliados, o bien luchar contra su propio padre para mantener la frágil paz que la Alianza y la Horda habían suscrito. Tras mucho cavilar, Jaina escogió la última opción y ayudó a Thrall a derrotar a su enloquecido padre." },
		[2111] = { file = "2111", len = 18.782, text = "Desafortunadamente, el almirante Valiente murió en la batalla, antes de que Jaina pudiera reconciliarse con él o demostrarle que los orcos ya no eran aquellos monstruos sedientos de sangre. Por su lealtad, los orcos permitieron que las fuerzas de Jaina regresaran sanos y salvos a Theramore." },
		[2131] = { file = "2131", len = 37.407, text = "Throm-ka, $c. No te adularé por tus hazañas, tu fuerza o tu valor. Ya son historia. ¿Has matado a algún humano últimamente? Apuesto a que no han sido muchos. Estás perdiendo ritmo. Sin desafíos por delante, te estás ablandando. Necesito otro par de manos y me da igual lo que te digan los pelotas: tú necesitas la instrucción que solo yo puedo darte. Cuando eso te entre en la mollera, te estaré esperando bajo el dosel que está en el exterior de El Cubil. Frang, instructor de guerreros" },
		[2151] = { file = "2151", len = 9.221, text = "Arellas Hojafuego Alto zahorí de la Cruzada Escarlata Ciudadano de Quel'Thalas Atrapado en combate eterno con el nigromante Diesalven" },
		[2152] = { file = "2152", len = 9.587, text = "Almirante Barean Viento Oeste Gran almirante de la Flota Escarlata Ciudadano de Kul?Tiras Perdido en la Costa Helada de Rasganorte" },
		[2153] = { file = "2153", len = 8.829, text = "Dorgar Petrocejas Guerrero de la Cruzada Escarlata Señor de las Cavernas Rojas Visto por última vez en las montañas de Alterac" },
		[2171] = { file = "2171", len = 8.15, text = "Fellari Flechaveloz Capitán forestal de la Cruzada Escarlata Ciudadano de Quel'Thalas Perdido en los bosques de Argénteos" },
		[2172] = { file = "2172", len = 10.71, text = "Ferren Marcus Gran abad del Monasterio Escarlata Ciudadano de Stratholme Muerto defendiendo el Monasterio Escarlata en el primer asalto de la Marea de Verano" },
		[2173] = { file = "2173", len = 10.658, text = "Harthal Veramira Señor Paladín de la Cruzada Escarlata Ciudadano de Azeroth, caballero de la Mano de plata Visto por última vez entrando en la ciudad maldita de Stratholme" },
		[2174] = { file = "2174", len = 7.732, text = "Holia Escusol Defensor de la Cruzada Escarlata Asesinado mientras daba muerte al Señor del Terror Beltheris" },
		[2175] = { file = "2175", len = 9.038, text = "Invar Unibrazo Primer Jefe Asesino de la Cruzada Escarlata Ciudadano de Dalaran Visto por última vez en las costas de Rasganorte" },
		[2176] = { file = "2176", len = 8.803, text = "Orman de Stromgarde Primer Capitán General de la Cruzada Escarlata Ciudadano de Stromgarde Perdido en la boca del Glaciar Corona de Hielo" },
		[2177] = { file = "2177", len = 10.188, text = "Valea Filosgemelos Guerrero de la Cruzada Escarlata Ciudadano de Alterac Visto por última vez en las profundidades de las Tierras de la Peste del Este" },
		[2178] = { file = "2178", len = 7.811, text = "Yana Lanza de Sangre Segundo Jefe Asesino de la Cruzada Escarlata Ciudadano de Dalaran Perdido en los Claros de Tirisfal" },
		[2191] = { file = "2191", len = 27.167, text = "Hace aproximadamente unos 16000 años, antes de que los elfos de la noche provocaran imprudentemente la ira de la Legión Ardiente, los trols se enseñoreaban sobre la mayor parte de Kalimdor (entonces, un solo continente). Había dos imperios trol, el imperio Gurubashi de las junglas del sudeste y el Imperio Amani de las tierras boscosas del interior." },
		[2192] = { file = "2192", len = 14.968, text = "Había tribus más pequeñas que habitaban el extremo norte (en la región conocida actualmente como Rasganorte). Dichas tribus fundaron una pequeña nación llamada Gundrak, que nunca alcanzó el tamaño ni la prosperidad de los imperios del sur." },
		[2193] = { file = "2193", len = 31.817, text = "Los imperios Gurubashi y Amani no se tenían en gran estima, pero casi nunca entraban en guerra. En aquel tiempo, su mayor enemigo común era un tercer imperio: la civilización de AzjAqir. Los aqir eran inteligentes insectoides que ocupaban las tierras del lejano oeste. Estos astutos insectoides se expandían de forma permanente y eran increíblemente malvados. Los aqir estaban obsesionados con erradicar todos los seres vivientes que no fueran insectos de los campos de Kalimdor." },
		[2194] = { file = "2194", len = 21.211, text = "Los trols lucharon contra ellos durante miles de años, pero nunca pudieron conseguir una verdadera victoria sobre los aqir. Finalmente, debido a la persistencia de los trols, el reino aqiri se dividió en dos mitades cuando sus ciudadanos formaron colonias separadas en las regiones del extremo norte y el extremo sur del continente." },
		[2195] = { file = "2195", len = 16.692, text = "Emergieron dos ciudades-estado aqiri: Azjol-Nerub, en las tierras baldías del norte, y AhnQiraj, en el desierto del sur. Aunque los trols sospechaban que había otras colonias aqiri bajo Kalimdor, su existencia nunca fue verificada." },
		[2196] = { file = "2196", len = 27.089, text = "Cuando los insectoides marcharon al exilio, los imperios gemelos trol volvieron a sus asuntos cotidianos. A pesar de su gran victoria, ninguna civilización consiguió expandirse mucho más allá de sus fronteras originales. Sin embargo, existen textos antiguos que hablan de una pequeña facción de trols que se desgajó del Imperio Amani y fundó su propia colonia en el corazón del oscuro continente." },
		[2197] = { file = "2197", len = 18.73, text = "Allí, estos valientes pioneros descubrieron el Pozo de la Eternidad cósmico, que los transformó en seres provistos de un inmenso poder. Algunas leyendas sugieren que estos trols aventureros fueron los primeros elfos de la noche, si bien esta teoría nunca ha sido demostrada." },
		[2198] = { file = "2198", len = 40.803, text = "Aparte de sus orígenes oscuros, resulta obvio que los elfos de la noche obtuvieron el poder poco después de su descubrimiento del Pozo de la Eternidad. A pesar de los intentos de los trols de impedir que aumentaran sus territorios, los elfos de la noche construyeron un poderoso imperio que se expandió rápidamente a lo largo del Kalimdor primordial. Utilizando artes de magia nunca antes imaginada por los supersticiosos trols, los elfos de la noche lograron fácilmente aquello que los malvados aqir nunca pudieron conseguir: derrotar a los dos imperios más importantes del mundo." },
		[2199] = { file = "2199", len = 29.335, text = "Sistemáticamente, los elfos de la noche desmantelaron las defensas y las líneas de abastecimiento de los trols. Los trols, incapaces de contrarrestar la magia destructiva de los elfos, se replegaron ante las arremetidas. Los elfos de la noche demostraron ser tan astutos y sanguinarios como los salvajes trols: provocando el eterno odio y el desdén racial de estos últimos. Transcurridos pocos años, los imperios Gurubashi y Amani se fragmentaron." },
		[2200] = { file = "2200", len = 26.697, text = "Finalmente, los elfos de la noche fueron quemados por los fuegos arcanos que habían intentado controlar. El uso constante que hacían de la magia atrajo al mundo a la demoníaca Legión Ardiente. Los demonios destrozaron una gran parte de la civilización de los elfos de la noche. Aunque no hay registros que indiquen que la Legión atacó a la civilización trol, es muy probable que se produjeran batallas en todo el continente." },
		[2201] = { file = "2201", len = 19.383, text = "Al finalizar el terrible conflicto, conocido como la Guerra de los Ancestros, el Pozo de la Eternidad implosionó. La onda expansiva resultante destrozó la mayor parte de la tierra de Kalimdor. El centro del continente quedó sumergido bajo el mar, dejando atrás numerosos continentes fragmentados." },
		[2202] = { file = "2202", len = 35.135, text = "Así, grandes porciones tanto del Imperio Amani como Gurubashi existen aún en las actuales tierras de Quel'Thalas y Tuercespina, respectivamente. Los reinos Azj'Aqir de Azjol-Nerub y Ahn'Qiraj también han sobrevivido hasta el presente en Rasganorte y Tanaris, respectivamente. Ambas civilizaciones trol retrocedieron debido a la gran destrucción del mundo primordial que habían conocido. Los intrépidos trols reconstruyeron sus devastadas ciudades y progresaron para recuperar parte de su antiguo esplendor." },
		[2203] = { file = "2203", len = 31.869, text = "Los largos siglos que siguieron al Gran Cataclismo del mundo resultaron difíciles para la raza trol. El hambre y el terror eran moneda común en sus disgregados reinos. Los trols Gurubashi, conducidos a un final desesperado, buscaron ayuda en fuerzas místicas y ancestrales. Si bien ambos reinos trol compartían una creencia central en un gran panteón de dioses primitivos, los Gurubashi empezaron a adorar al más oscuro de ellos." },
		[2204] = { file = "2204", len = 25.757, text = "Hakkar el Cazador de Almas, espíritu vil y sanguinario, oyó la llamada de los trols y decidió ayudarlos. Hakkar compartió sus secretos de sangre con los Gurubashi y les ayudó a extender su civilización a lo largo de la mayor parte de la Vega de Tuercespina y ciertas islas de los Mares del Sur. Si bien les proporcionó un gran poder, Hakkar quería más y más para sus propósitos." },
		[2205] = { file = "2205", len = 27.402, text = "El dios sanguinario pidió que se sacrificaran almas en su altar diariamente. Tenía intención de lograr el acceso al mundo físico para así poder beber la sangre de todas las criaturas mortales. Con el tiempo, los Gurubashi se dieron cuenta de la clase de criatura con la que habían estado tratando y se volvieron en su contra. Las tribus más poderosas se rebelaron contra Hakkar y sus leales sacerdotes, los Atal'ai." },
		[2206] = { file = "2206", len = 22.831, text = "La terrible guerra que siguió entre los seguidores de Hakkar y el resto de las tribus Gurubashi solo se comenta en susurros. El imperio en ciernes fue destruido por la magia desatada entre el airado dios y sus criaturas rebeldes. Cuando la batalla parecía estar perdida, los trols lograron destruir el avatar de Hakkar, desterrándolo del mundo." },
		[2207] = { file = "2207", len = 17.606, text = "Incluso sus sacerdotes Atal'ai fueron expulsados de la capital de Zul'Gurub y obligados a sobrevivir en los ignotos pantanos del norte. En esos terrenos pantanosos construyeron un gran templo al dios caído, AtalHakkar, donde pudieran continuar con la obra de su maestro..." },
		[2208] = { file = "2208", len = 28.917, text = "El resto de las tribus Gurubashi se dispersaron tras la gran guerra civil que dejó sus tierras en ruinas. Las tribus Machacacráneo, Sangrapellejo y Lanza Negra marcharon con el fin de reclamar sus propias tierras en el interior de las vastas junglas de Tuercespina. Si bien hubo un momento de frágil paz en el imperio disgregado, algunos hablaban de una profecía según la cual un día Hakkar volvería a nacer en el mundo y, en ese momento, lo reduciría a cenizas." },
		[2211] = { file = "2211", len = 35.866, text = "Aquí yace Grommash Grito Infernal, jefe del clan Grito de Guerra De diversas maneras, la maldición de nuestro pueblo empezó y acabó con Grom. Su nombre significa ?corazón gigante? en nuestra antigua lengua. Hizo honor a su nombre un centenar de veces cuando se enfrentó solo al demonio Mannoroth y obtuvo nuestra libertad con su sangre. Lok'Tar ogar, gran hermano. Que el clan Grito de Guerra nunca desaparezca. Thrall, Jefe de Guerra de la Horda" },
		[2212] = { file = "2212", len = 36.598, text = "¡Oh, estoy maldito! Otrora gran mago ogro del clan Cumbrerroca, desafié a Urok Aullapocalipsis y este me robó mi magia y me maldijo. ¡Ahora debo recorrer las salas de Hordemar como una desgraciada criatura! ¡Ayudadme! ¡Enfrentaos a Urok y recuperad mi magia! No será fácil, ya que Urok permanece en las sombras y solo puede ser invocado a través de un gran desafío. Este desafío será la muerte de su ayudante más fiel, alto señor Omokk. Continúa leyendo y verás." },
		[2213] = { file = "2213", len = 25.26, text = "El alto señor Omokk gobierna a los Cumbrerroca, pero lo hace utilizando la magia de Urok. Urok embrujó a Omokk con un encantamiento que puede conducir a la muerte a cualquier ogro que ose desafiarlo. Ha utilizado este encantamiento muchas veces y apila los cráneos de sus víctimas en un recinto de poder situado encima de la cámara de Omokk. Allí es donde debes ir para enfrentarte a Urok." },
		[2214] = { file = "2214", len = 21.107, text = "Encuentra un basto pico sobre los campos del Escudo del Estigma. Suelen clavarlos junto a sus colchones, cerca de la entrada de los dominios del ogro Cumbreroca. Cuando obtengas el pico, carga contra el alto señor Omokk. Mátalo y coloca su cabeza sobre el pico. Entonces estarás $Gpreparado:preparada; para el verdadero reto." },
		[2215] = { file = "2215", len = 32.392, text = "Ve al lugar de poder situado encima del dominio de los Cumbrerroca, más allá de los Túneles de Arácnidas. En aquel lugar están apilados los cráneos de los enemigos y rivales de Urok. ¡Aquí es donde debes colocar el pico con la cabeza de Omokk! Cuando la cabeza esté en su sitio, Urok vendrá... pero primero enviará a sus esbirros que te atacarán. Derrótalos y, transcurrido un tiempo, aparecerá Urok en persona. Mata a Urok y recupera mi magia. Cuando recuperes mis poderes, te recompensaré." },
		[2216] = { file = "2216", len = 25.783, text = "Buena suerte. He aquí una pista que podrá ayudarte cuando te enfrentes a los esbirros de Urok: El encantamiento que utiliza Omokk contra los ogros, el que los lleva a la muerte, puede continuar activo aun después de muerto Omokk. Cuando luches contra los esbirros de Urok, convoca el poder en la cabeza de Omokk. ¡Con suerte, Omokk acabará con los esbirros de Urok! ¡Vaya ironía!" },
		[2217] = { file = "2217", len = 5.799, text = "Con cariño, en recuerdo de Jesse Morales" },
		[2232] = { file = "2232", len = 16.013, text = "Agasham, ¡Nuestros planes deben continuar en secreto a cualquier precio! Sería desastroso si alguna otra tribu tauren descubriese nuestra afiliación. Firmado, Heraldo Elm" },
		[2233] = { file = "2233", len = 24.424, text = "Agasham, ¡Trabajando juntos, nuestras fuerzas serán mas poderosas que las de todas las tribus tauren juntas! Aun así, necesitamos vuestra total obediencia. Recuerda, ¡tu gente solo será recompensada después de que nuestros planes hayan alcanzado el éxito! Firmado, Heraldo Rex" },
		[2234] = { file = "2234", len = 17.633, text = "Agasham, Nuestros agentes pronto se encontrarán con nuestros delegados. Cuando encontremos un lugar apropiado para nuestra cita, te informaremos al respecto. Firmado, Heraldo Grakus" },
		[2251] = { file = "2251", len = 17.058, text = "Nos atacan... desde todas partes. Puedo verlo en sus ojos. Fauces de Madera es el demonio. Enemigo. Debes proteger a la tribu. Debes proteger a Nevada. Debes expulsar a los intrusos de nuestras tierras." },
		[2291] = { file = "2291", len = 31.843, text = "Arzobispo Alonsus Faol Generoso patrón de la Iglesia de la Luz. Aunque comenzó su carrera en Stratholme, Lordaeron, el arzobispo Faol fue un gran amigo del pueblo de Ventormenta. En la época oscura posterior a la Segunda Guerra, ayudó a reformar la Hermandad de Villanorte y recaudó fondos para la reconstrucción de la ciudad de Ventormenta. Esta catedral no es solo un bastión de la Luz sagrada, sino también una prueba imperecedera del espíritu noble y generoso de este gran hombre." },
		[2292] = { file = "2292", len = 10.031, text = "Rey Llane I de la Casa de Wrynn Señor Feudal de Ventormenta Defensor de Azeroth" },
		[2293] = { file = "2293", len = 7.576, text = "Comandante de las flotas de la Alianza Amigo de Ventormenta" },
		[2294] = { file = "2294", len = 13.009, text = "Lady Mara Fordragón Alta sacerdotisa de Ventormenta Patrona de los refugiados que huyeron de Lordaeron tras la Primera Guerra. Fue la brillante madre de nuestro futuro. Que descanse en la Luz." },
		[2295] = { file = "2295", len = 21.656, text = "Antes de la Edad de la Memoria, la suave Madre Tierra lanzó su soplo sobre las doradas neblinas de la aurora. Cuando las ambarinas nubes se detuvieron, aparecieron interminables campos de fino trigo y cebada. Este era el cuenco de sus obras: la gran cesta de la vida y la esperanza." },
		[2296] = { file = "2296", len = 32, text = "Los ojos de la Madre Tierra iluminaban las tierras en las que había insuflado la creación. Su ojo derecho, Anshe (el sol), proporcionaba luz y calor a la tierra. Su ojo izquierdo, Mu'sha (la luna), proporcionaba paz y sueño a las conmovedoras criaturas de la aurora. Tal era el poder de su mirada, que la Madre Tierra cerraba un ojo soñador en cada giro del cielo. De esta manera, su amorosa mirada convirtió el día en noche para la primera alborada del mundo." },
		[2297] = { file = "2297", len = 30.406, text = "Mientras el ojo derecho iluminaba la dorada aurora, las suaves manos de la Madre Tierra se extendían a lo largo de las doradas planicies. Allí por donde se extendía la sombra de sus brazos, surgía un pueblo en el rico suelo. Los Shu'halo (los tauren) surgieron para dar gracias y para orar por su amada madre. Allí, en los interminables campos de la aurora, los hijos de la tierra juraron rendirle pleitesía y bendecir su nombre hasta el ocaso final del mundo." },
		[2298] = { file = "2298", len = 30.929, text = "Vagando por los campos de la aurora, los hijos de la tierra escucharon los oscuros murmullos procedentes de debajo del mundo. Estos murmullos enseñaron a estas criaturas las artes de la guerra y el engaño. Muchos de los Shu'halo cayeron bajo el influjo de la sombra y decidieron abrazar la malicia y la perversidad. Cambiaron el sino de sus hermanos de alma pura y su inocencia quedó a la deriva, marchando sobre las planicies." },
		[2299] = { file = "2299", len = 29.048, text = "La Madre Tierra, con el corazón dolido por las dificultades que atravesaban sus hijos, no pudo resistir la contemplación de su caída. En su dolor, se arrancó los ojos y estos salieron disparados hacia los infinitos y estrellados cielos. An'she y Mu'sha, en el intento de aplacar la tristeza del otro, apenas pudieron perseguir el tenue brillo del otro a través del cielo. En cada giro del mundo, los gemelos aún se persiguen el uno al otro." },
		[2300] = { file = "2300", len = 20.95, text = "Aun privada de la vista, la Madre Tierra no podía apartarse durante mucho tiempo del mundo de su corazón. Permanecía atenta al sonido del viento y escuchaba los sonidos de todo ser viviente que habitaba los campos de la aurora. Su gran corazón siempre estuvo con sus hijos y su amorosa sabiduría nunca los abandonó." },
		[2301] = { file = "2301", len = 28.473, text = "En los valientes corazones de sus hijos puros la Madre Tierra insufló el amor por la caza. Las criaturas de la primera aurora eran salvajes y fieras. Se escondían de la Madre Tierra, encontrando la paz en las sombras y en las tierras salvajes del lugar. Los Shu'halo se dedicaron a cazar a estas bestias allí donde las encontraron y las domesticaron con la anuencia de la Madre Tierra." },
		[2302] = { file = "2302", len = 27.533, text = "Sin embargo, un gran espíritu logró eludiros. Apa'ro (conocido como Malorne entre los elfos de la noche), era un orgulloso ciervo de pelaje blanco como la nieve. Su cornamenta hería a los mismísimos cielos y sus poderosas patas dejaban su impronta en las profundidades del mundo. Los Shu'halo empujaron a Apa'ro hacia los extremos del mundo de la aurora, creando una trampa para encerrar al orgulloso ciervo." },
		[2303] = { file = "2303", len = 27.585, text = "Intentando escapar, el gran ciervo saltó hasta el cielo. Aun así, cuando su huida parecía asegurada, su poderosa cornamenta quedó enredada en las estrellas. Aunque luchó y dio coces, Apa'ro no logró zafarse de la trampa de los cielos. Fue entonces cuando Mu'sha atrapó a su hermano, An'she, poco antes de la aurora. Musha contempló cómo luchaba el poderoso ciervo y se enamoró de él inmediatamente." },
		[2305] = { file = "2305", len = 26.201, text = "Con el tiempo, el niño Cenarius alcanzó la estatura de su orgulloso padre. Hermano de los árboles y las estrellas, el gran cazador vagó por las cuatro esquinas del mundo, entonando bellas canciones de la aurora. Todas las criaturas saludaban su gracia y su belleza: no había nadie tan bello como el hijo de la luna y el ciervo blanco." },
		[2306] = { file = "2306", len = 16.17, text = "Finalmente, Cenarius se hizo amigo de los Shu'halo y les habló del mundo que gira. Los hijos de la tierra le conocían como un hermano y juraron ayudarle a cuidar los campos de la vida y las criaturas bien amadas de la gran Madre Tierra." },
		[2307] = { file = "2307", len = 22.413, text = "Cenarius enseñó a los hijos de la tierra a hablar con los árboles y las plantas. Los Shu'halo se convirtieron en druidas y realizaron grandes hazañas mágicas para cuidar la salud de la tierra. Durante muchas generaciones, los Shu'halo cazaron junto con Cenarius y mantuvieron el mundo a salvo de las sombras que acechaban en las profundidades." },
		[2308] = { file = "2308", len = 39.236, text = "A medida que la niebla de la aurora se difuminó, dando paso a la Edad de la Memoria, el semidiós Cenarius continuó su marcha a través de los campos del mundo. Los Shu'halo (tauren) se mostraban muy apesadumbrados a su paso y, finalmente, olvidaron la mayor parte de los quehaceres propios de un druida que Cenarius les había enseñado. Cuando pasaron generaciones, terminaron por olvidar cómo hablar con los árboles y los seres salvajes de la tierra. Los oscuros murmullos procedentes de las profundidades del mundo rozaron sus oídos una vez más." },
		[2309] = { file = "2309", len = 23.353, text = "Cenarius enseñó a los hijos de la tierra a hablar con los árboles y las plantas. Los Shu'halo se convirtieron en druidas y realizaron grandes hazañas mágicas para cuidar la salud de la tierra. Durante muchas generaciones, los Shu'halo cazaron junto con Cenarius y mantuvieron el mundo a salvo de las sombras que acechaban en las profundidades." },
		[2311] = { file = "2311", len = 20.846, text = "Este esqueleto de pteradon intacto fue descubierto en el remoto cráter de Un'Goro. Basándonos en la estructura del esqueleto, resulta evidente que aún no se ha determinado su género. Es probable que este esqueleto se haya conservado durante varios siglos bajo el rico suelo de la región." },
		[2371] = { file = "2371", len = 28.317, text = "Las crónicas de Villa Darrow Villa Darrow, nombrada así por el lago Darrowmere, situado al oeste, es una ciudad que se encuentra entre las estribaciones sureñas de Lordaeron. Conocida por sus humildes pero trabajadores residentes, Villa Darrow permaneció en segundo plano en la historia de Lordaeron hasta la Segunda Guerra. Los héroes se forjaron durante la guerra. Y allí perecieron." },
		[2372] = { file = "2372", len = 25.626, text = "La Batalla de Villa Darrow La Batalla de Villa Darrow tuvo lugar en mitad de la Segunda Guerra, cuando las fuerzas de la Plaga arrasaron Lordaeron. Villa Darrow quedó aislada del grueso de las fuerzas de la Alianza, pero la ciudad fue reforzada por un cuerpo de tropas, un contingente de paladines Mano de Plata y un incondicional grupo de milicia local dirigido por el capitán Joseph Rutagrana." },
		[2374] = { file = "2374", len = 34.821, text = "Los defensores quedaron debilitados, pero fueron liberados por paladines, discípulos de los Mano de plata. Su líder, Davil Vasijan, había nacido en Villa Darrow. Condujo a sus seguidores a la ciudad cuando supo del inminente ataque y, junto con los defensores, rechazaron a los siervos de Horgus. Cuando el propio Horgus entró en batalla, se encontró con Davil. Lucharon durante varios minutos y, finalmente, Davil venció, pero sufrió una herida mortal y, poco después de derrotar al señor necrófago, murió." },
		[2375] = { file = "2375", len = 24.764, text = "La batalla continuó y el capitán Rutagrana dirigió a su milicia valientemente. Si el oscuro caballero de la Muerte Marduk el Negro no hubiera corrompido al capitán, habrían podido ganar. En medio de la refriega, Marduk se acercó a Rutagrana y, con ayuda de la magia negra, liberó el espíritu de este, convirtiéndolo en una sombra maligna del valiente capitán." },
		[2376] = { file = "2376", len = 32.392, text = "Luego, el corrupto capitán Rutagrana esparció su influencia maligna entre los defensores de Villa Darrow, que traicionaron a sus aliados y los asesinaron. A continuación, volvieron a la ciudad de Villa Darrow y mataron a todos aquellos que estaban ocultos en sus casas. El ejército restante de la Plaga, junto con el espíritu corrupto del capitán Rutagrana, abandonó posteriormente la devastada ciudad de Villa Darrow y arremetió contra Lordaeron, provocando el dolor y la muerte de la Segunda Guerra." },
		[2377] = { file = "2377", len = 28.317, text = "Los anales de Villa Darrow Villa Darrow, nombrada así por el lago Darrowmere, situado al oeste, es una ciudad que se encuentra entre las estribaciones sureñas de Lordaeron. Conocida por sus humildes pero trabajadores residentes, Villa Darrow permaneció en segundo plano en la historia de Lordaeron hasta la Segunda Guerra. Los héroes se forjaron durante la guerra. Y allí perecieron." },
		[2378] = { file = "2378", len = 25.783, text = "La Batalla de Villa Darrow La Batalla de Villa Darrow tuvo lugar en mitad de la Segunda Guerra, cuando las fuerzas de la Plaga arrasaron Lordaeron. Villa Darrow quedó aislada del grueso de las fuerzas de la Alianza, pero la ciudad fue reforzada por un cuerpo de tropas, un contingente de paladines Mano de Plata y un incondicional grupo de milicia local dirigido por el capitán Joseph Rutagrana." },
		[2379] = { file = "2379", len = 35.03, text = "Los primeros asaltos de la Plaga sobre Villa Darrow fueron espaciados. Pequeños grupos de esqueletos y cadáveres merodeadores anduvieron por las afueras de la ciudad y fueron repelidos fácilmente. Pero la Plaga percibió la tenacidad de los defensores y respondió adecuadamente. Poco después de producirse la primera ola de atacantes, apareció una segunda. Necrófagos campeones, sirvientes del señor necrófago Horgus, aullaron desde las colinas y chocaron con los asediados defensores de Villa Darrow." },
		[2380] = { file = "2380", len = 35.579, text = "Los defensores quedaron debilitados, pero fueron liberados por paladines, discípulos de los Mano de plata. Su líder, Davil Vasijan, había nacido en Villa Darrow. Condujo a sus seguidores a la ciudad cuando supo del inminente ataque y, junto con los defensores, rechazaron a los siervos de Horgus. Cuando el propio Horgus entró en batalla, se encontró con Davil. Lucharon durante varios minutos y, finalmente, Davil venció, pero sufrió una herida mortal y, poco después de derrotar al señor necrófago, murió." },
		[2381] = { file = "2381", len = 24.999, text = "La batalla continuó y el capitán Rutagrana dirigió a su milicia valientemente. Habrían podido ganar, si el oscuro caballero de la Muerte Marduk el Negro no hubiera corrompido al capitán. En medio de la refriega, Marduk se acercó a Rutagrana y, con ayuda de la magia negra, liberó el espíritu de este, convirtiéndolo en una sombra maligna del valiente capitán." },
		[2382] = { file = "2382", len = 32.418, text = "Luego, el corrupto capitán Rutagrana esparció su influencia maligna entre los defensores de Villa Darrow, que traicionaron a sus aliados y los asesinaron. A continuación, volvieron a la ciudad de Villa Darrow y mataron a todos aquellos que estaban ocultos en sus casas. El ejército restante de la Plaga, junto con el espíritu corrupto del capitán Rutagrana, abandonó posteriormente la devastada ciudad de Villa Darrow y arremetió contra Lordaeron, provocando el dolor y la muerte de la Segunda Guerra." },
		[2383] = { file = "2383", len = 33.672, text = "El destino de Horgus el Devastador Horgus el Devastador cayó en la Batalla de Villa Darrow. Pero el mal que residía en él no se consumió del todo. Las fuerzas victoriosas de la Plaga trasladaron su cráneo desde el campo de batalla de Villa Darrow y lo llevaron con ellos para sembrar el terror entre todos los seres vivientes que encontraron. Días después, la compañía de la Plaga que poseía el cráneo fue derrotada por los paladines de la Mano de Plata. El cráneo de Horgus fue lanzado al lago Bosque Negro." },
		[2384] = { file = "2384", len = 34.534, text = "El destino de Marduk el Negro Marduk sobrevivió a la Segunda Guerra, provocando mucho sufrimiento y muerte con su nauseabunda espada de runas. Aunque Marduk continúa con vida, su espada se perdió en una batalla cerca del Cruce de Corin. Un capitán enano hizo añicos la espada en su escudo encantado, obligando a Marduk a abandonar el campo, ganando la partida para la Alianza. La espada de Marduk se hundió en la tierra y la corrompió, creando un desfiladero conocido hoy con el nombre de la Cicatriz Purulenta." },
		[2385] = { file = "2385", len = 26.88, text = "El destino de Davil Forjaluz Davil Forjaluz murió en la Batalla de Villa Darrow, pero su valentía inspiró a la Alianza durante toda la guerra. Su libro, el tratado del paladín, fue recuperado por las tropas de la Cruzada Escarlata. Actualmente, permanece en el concejo de la Vega del Amparo, controlada por la Cruzada Escarlata, donde lo consultan los cruzados que desean inspirarse en la fuerza de Davil." },
		[2386] = { file = "2386", len = 30.171, text = "El destino de Joseph Rutagrana Joseph Rutagrana murió durante la Batalla de Villa Darrow. Su espíritu se corrompió y tomó una nueva forma, extendiendo el mal por Lordaeron. En la Gangrena de Gahrron, al este de Andorhal, el corrupto Rutagrana fue finalmente derrotado por las fuerzas de la Alianza. Su escudo aún descansa cerca del granero de la granja apestada y los esbirros de la Plaga aún evocan el recuerdo de este ser diabólico." },
		[2391] = { file = "2391", len = 36.258, text = "El destino de Carlin Rutagrana Hermano del capitán Joseph Rutagrana, Carlin cayó durante la Batalla de Villa Darrow. Pero, aunque resultó terriblemente herido, no murió. Días después de la batalla, agentes de El Alba Argenta encontraron a Carlin vagando, debilitado por la sed y la fiebre, cerca del Cruce de Corin. Curaron sus heridas y lo llevaron a la Capilla de la Esperanza de la Luz. Agradecido por su caridad, Carlin se unió a las filas de El Alba Argenta y ahora libra una batalla de venganza contra la Plaga." },
		[2411] = { file = "2411", len = 18.86, text = "OoOoOoO OOoOOoo OOOoOoo OOoOooO OOoOOoO OOooooO Oooooo OooOOOO OOoOOOo OOoOOoo OOoOooO OOoOOOo OOooOoO Oooooo OooOOOo OOooooO OOOoooo OOooooO Oooooo OoOoOOo OOooooO OOoOOoo OOoOOoo OOooOoO OOOOooO Oooooo OooOoOO OOoOOOo OOoOooO OOooOOO OOoOooo OOOoOoo OOOooOO Oooooo OOoOOOO OOooOOo Oooooo OooooOO OOoOooo OOooooO OOoOOOO OOOooOO" },
		[2413] = { file = "2413", len = 7.027, text = "Nieve, cegadora... Hay que proteger a la tribu. Haz que sean fuertes. Sed fuertes. No se sabe..." },
		[2414] = { file = "2414", len = 14.55, text = "Aguardiente. Haz más. Más aguardiente. El aguardiente fortalece al clan Nevada. Derrotemos a nuestros enemigos. Los Nevada no tenemos aliados. Los Nevada somos fuertes. Tenemos un enorme poder." },
		[2415] = { file = "2415", len = 18.965, text = "Incluso la forma titánica de Sargeras experimentó una deformación ocasionada por la corrupción que había infestado su otrora noble corazón. Sus ojos, sus cabellos y su barba desprendían fuego, y su piel color bronce se cuarteó, revelando un manantial de furia abrasadora." },
		[2431] = { file = "2431", len = 30.224, text = "Fecha de entrada: Desconocida Nombre: Nathanos Marris, forestal humano, señor de Lordaeron. Entrada: La oposición de Kael'thas Caminante del Sol en relación con mi decisión de permitir a Nathanos Marris ingresar en la orden resulta evidente. Asimismo, hay que tener en cuenta que Nathanos, si bien es un humano, es uno de los forestales mejor dotados que he tenido el placer de formar. (continuación)" },
		[2432] = { file = "2432", len = 39.654, text = "Nunca he estado más orgulloso de participar en este negocio como en estos últimos años. La demanda de asesinos, espías y exploradores nunca ha sido tan acuciante. Es lógico pensar que la demanda aumenta durante la guerra, pero, sorprendentemente, la guerra no es un periodo tan próspero como este: un momento en que la paz empieza a deteriorarse. Me han dicho que vendrías por aquí para aprender algunas cosas. Cuando tengas tiempo, ven a verme en los establos situados en la parte trasera de la abadía. Jorik Kerridan, instructor de pícaros" },
		[2433] = { file = "2433", len = 34.691, text = "Apuesto a que esperabas que esta fuera una nota normal escrita por tu rey o por cualquier otra persona. Bueno, digamos que algo sé acerca de cómo falsificar notas y quería asegurarme de que recibieras esta. No puedo ir llamando la atención, ¿verdad? Me he refugiado en Yunquemar, así que me encontrarás cerca de la fosa de lava. Cuando estés $Gpreparado:preparada;, ven a hablar conmigo. Solo quiero presentarme ahora que tenemos tiempo. Solm Hargrin, instructor de pícaros" },
		[2434] = { file = "2434", len = 40.202, text = "Mis saludos, . Estaba sumido en mis pensamientos cuando me llamó la atención que necesitaba escribirte. Muchas de nuestras alabanzas a nuestros chamanes son por ser nuestros líderes espirituales, como nuestro gran Jefe de Guerra. Muchos piensan que la espada y el hacha son ocupaciones aún más nobles, pero nunca hay que olvidar que las batallas - incluso las guerras - se ganan con las espaldas de los que tienen más habilidades especiales. Eso es lo que quería decirte, $N. Me Encontraras con los demás orcos en el Valle de los Retos. -Rwag, Instructor de Picaros" },
		[2435] = { file = "2435", len = 31.321, text = "$gHermano:Hermana;, espero que, cuando recibas esta runa, te encuentres bien. Deseaba tomarme el tiempo de escribirte para decirte que estoy en Yunquemar, encima del Valle de Crestanevada. Sé lo importante que es que permanezcamos juntos y, en estos tiempos de paz forzada, se hace cada vez más importante tener cerca a los nuestros. Cuando tengas tiempo, ven a mi encuentro. Solm Hargrin, instructor de pícaros." },
		[2436] = { file = "2436", len = 33.019, text = "No tomes mis palabras a la ligera, $N. Ha llegado la hora de llevar nuestras artimañas de engaño a todas las naciones... incluso a nuestra grandiosa Entrañas. Todos los fieles de Sylvanas se esfuerzan por crear un área nueva bajo el control exclusivo de los Renegados. Incluso aunque no poseamos habilidades mágicas, nuestro papel sigue siendo igual de importante. Ven a verme a la posada de Camposanto y seguiremos hablando. -David Trias, instructor de pícaros" },
		[2437] = { file = "2437", len = 36.258, text = "Sael'ah, espero que cuando recibas este sigilo te encuentres bien. Me han pedido que te ofrezca mis servicios. También estoy en Cañada Umbría, en el gran árbol de Aldrassil, y deseaba comunicarte que si necesitas instrucción, no tienes más que pedírmela. En estos tiempos tan cuestionables, creo que es prudente que aquellos que actúan furtivamente permanezcan unidos. ¿Qué otro ser sería capaz de proteger Teldrassil y nuestros caminos? Cuando puedas, ven a verme. Frahun Sombrusurro, instructor de pícaros" },
		[2438] = { file = "2438", len = 34.952, text = "Saludos, $Ghermano:hermana;. Los Mano Destrozada te saludamos y esperamos que este valle sea un lugar agradable en el que puedas desarrollar tus negocios. Es un periodo de prueba para ti, así que no pienses que no te estamos vigilando constantemente. Es mi deber evaluar tus habilidades y luego informar sobre el momento en que crea que estás preparado para aceptar retos mayores. Cuando estés $Gpreparado:preparada;, localízame en las profundidades de El Cubil. Te estaré esperando. Rwag, instructor de pícaros" },
		[2439] = { file = "2439", len = 38.374, text = "Dime, $C, ¿has oído el grito de un orco? ¿No defendías tal vez tu casa de los gnolls mientras ellos intentaban cortarte el cuello? Sí, suena horrible, ¿verdad? Bueno, si deseas proteger a los tuyos, necesitarás mi ayuda. Me encontrarás en la abadía de Villanorte. Mis conocimientos no son fáciles de obtener, pero si tienes suficiente experiencia, puedo instruirte, enseñándote una serie de estilos y movimientos que te ayudarán a hacer frente a las amenazas de Ventormenta y más allá. Llane Beshere, instructor de guerreros" },
		[2440] = { file = "2440", len = 30.746, text = "ATENCIÓN: Debes presentarte a Thran Khorman inmediatamente. Se encuentra dentro del edificio A3, también conocido como Anvilmar, por los lugareños. Una vez que contactes con Khorman, procederá a prepararte para la próxima guerra - ¡la guerra para recuperar nuestro hogar Gnomeregan! Todos los esfuerzos y las tareas esenciales deben centrarse en lograr esta directiva. Una vez lograda, se te asignará una nueva tarea." },
		[2441] = { file = "2441", len = 40.594, text = "Muchas tribus afirman que es un don ser bendecido con la capacidad de utilizar la magia o de hablar con nuestros ancestros, pero deberás saber, $C, que tú también tienes este don. Algunos no tienen suficiente fuerza en sus brazos como para blandir armas poderosas. Algunos no tienen la destreza suficiente para esquivar el golpe de un asesino o incluso para sufrir los castigos físicos de un encantador arcano, pero tú sí. Tú eres fuerte. Te ayudaré a ser más fuerte. Encuéntrame en el Campamento Narache. Harutt Tronacuerno, instructor de guerreros" },
		[2442] = { file = "2442", len = 40.542, text = "Por las barbas de Magni, hay mucho que discutir y muy poco tiempo, $N. Búscame en Yunquemar, frente al Valle de Crestanevada tan pronto como puedas. Tenemos que empezar. Podría contarte un montón de cosas para ponerte al día rápidamente, pero todo eso no tiene nada que ver con nosotros... por el momento. Lo que ahora debe centrar nuestra atención es la empuñadura de un hacha, el peso de nuestra armadura y el olor de nuestro propio sudor rodando por la frente cuando nos enfrentamos al enemigo. Empezaremos por ahí. Thran Khorman, instructor de guerreros" },
		[2443] = { file = "2443", len = 36.31, text = "Muchos de nosotros recurren a lo arcano y lo divino como medios para obtener poder, pero nosotros lo hacemos mejor, ¿no es verdad, $C? Sabemos que nuestras armas son nuestros símbolos sagrados, nuestro escudo es nuestro libro de hechizos y nuestra malla es nuestra sabiduría. Incluso en la no-muerte somos fuertes, y solo podemos hacernos más fuertes. Encuéntrame en la posada de Camposanto. Seguiré hablándote de estas cuestiones y de otras muchas. Dannal Stern, instructor de guerreros" },
		[2444] = { file = "2444", len = 37.433, text = "Espero que cuando recibas este sigilo te encuentres bien, $C. Te escribo porque nuestra gente necesita esa fuerza con la espada, la guja y otras armas. Han ocurrido muchas cosas desde que nuestro pueblo volvió a enfrentarse a las otras razas de Azeroth, de manera que tenemos una necesidad aún mayor de protectores de todas las clases. Aquí es donde apareces tú. Ya te contaré, pero creo que debo hacerlo en persona. Puedes encontrarme en Aldrassil... en los niveles inferiores. Alyissia, instructora de guerreros" },
		[2445] = { file = "2445", len = 36.049, text = "La magia tiene cuatro reglas: La Magia es poderosa. La magia corrompe. La magia es adictiva. La magia acerca a los moradores de El Vacío Abisal a aquellos que empuñan lo arcano. Estas reglas son siempre seguras. Si decides continuar tu camino como $c, gobernarán tu destino. Si eres tan iluso como para ignorar esta advertencia, ven nuevamente a hablar conmigo en el Ala de la Biblioteca de la Abadía de Villanorte. Te esperaré arriba. Khelden Bremen, instructor de magos" },
		[2446] = { file = "2446", len = 33.045, text = "La corrupción y la maldad que los rumores afirman subyace en lo arcano no son nada comparado con el dolor que ya hemos experimentado. Ya no somos víctimas, . Somos los únicos que controlamos nuestro propio destino. Sylvanas ha preparado el camino para todos nosotros: ha demostrado que la voluntad es nuestra, que ya no somos esclavos del maldito Arthas. Búscame en la iglesia y, si lo deseas, te seguiré instruyendo... Isabella, instructora de magos" },
		[2447] = { file = "2447", len = 34.325, text = "La corrupción y la maldad que los rumores afirman subyace en lo arcano no son nada comparado con el dolor que ya hemos experimentado. Ya no somos víctimas, $N. Somos los únicos que controlamos nuestro propio destino. Sylvanas ha preparado el camino para todos nosotros: ha demostrado que la voluntad es nuestra, que ya no somos esclavos del maldito Arthas. Búscame en la iglesia y, si lo deseas, te seguiré instruyendo... Isabella, instructora de magos" },
		[2448] = { file = "2448", len = 33.75, text = "$GBienvenido:Bienvenida; al despertar, colega. Los secretos arcanos están a tu alcance si eres lo suficientemente fuerte para aferrarte a ellos. Cuando estés $Gpreparado:preparada;, busca a Mai'ah. Te enseñará mucho acerca de la magia y acerca de los encantamientos que necesitas para destruir a tus enemigos. Mai'ah está cerca de El Cubil, en el Valle de los Retos. Allí la encontrarás y podrás hacerte fuerte. Podrás mostrar a otros magos cómo la magia se supedita a ti... y no tú a ella." },
		[2449] = { file = "2449", len = 39.915, text = "A menudo, algunos, como los seguidores de la Luz Sagrada, asustan a los profanos sobre lo que significa el verdadero poder, haciéndoles creer que no pueden tener acceso a ninguna de las facetas de lo arcano. Lo cierto es que no todo lo que hay en el más allá es maligno. No todas las entidades buscan dominar o subyugar a otros. Si eres bastante poderoso, estas mismas entidades pueden convertirse en tus seguidores. Esto es algo que quiero analizar más en detalle contigo. Búscame en el cementerio, a la derecha de la abadía. Drusilla La Salle, instructora de brujos" },
		[2450] = { file = "2450", len = 36.598, text = "ATENCIÓN: ¡Guarda silencio! ¡No mires a tu alrededor! Es posible que alguien te esté vigilando. Mi nombre es Alamar Grimm, $N. Entreno a aquellos que buscan el conocimiento y obtener un mayor poder de... los mundos del más allá. Me han pedido que entre en contacto contigo de forma discreta y que te haga saber que puedo instruirte más a fondo, enseñándote una variante real de la magia. Cuando puedas, búscame en la parte trasera de Yunquemar. Alamar Grimm, instructor de brujos" },
		[2451] = { file = "2451", len = 40.699, text = "Escribo este mensaje con las tintas más poderosas que soy capaz de crear, . Maldeciré instantáneamente a todo aquel que ose leerlo, exceptuándote a ti. Así de poderoso soy. Puedo invocar demonios procedentes de El Vacío Abisal a voluntad. Acabo con mis enemigos mientras duermen y en el campo de batalla. Y ahora tú también has podido comprobar hasta dónde llega mi poder. Mis hermanos no caben en sí de gozo. Búscame en las profundidades de El Cubil, una vez que hayas encontrado el camino. Tengo que contarte cosas muy importantes. Nartok, instructor de brujos" },
		[2452] = { file = "2452", len = 39.419, text = "Estamos en un grave aprieto, ¿no es verdad, $N? Apestados por el príncipe Hediondo. Rechazados y condenados al ostracismo por los nuestros. Finalmente, hacemos lo que nos place gracias a la bella Sylvanas, pero ¿de qué nos sirve ahora? Somos esclavos de un amo distinto, pero esclavos al fin. Pero ¿qué tal si nosotros fuéramos los amos? Sí, sabes lo que quiero decir, ¿no? Estamos incluso más apartados del resto de los Renegados, $N. Y esta es la razón por la que debemos comentar la jugada. Me encontrarás en la iglesia de Camposanto." },
		[2453] = { file = "2453", len = 42.292, text = "Poderosos guerreros defienden nuestro hogar. Nuestros chamanes guían nuestros espíritus y nos enseñan el pasado de nuestros ancestros. Y nuestros druidas nos ayudan a descubrir la voluntad de la Madre Tierra. Pero tú eres uno de nuestros cazadores, y nuestros cazadores aprenden a apreciar muchos de estos roles y los mezclan. Te darás cuenta de que representas el corazón de nuestro pueblo: algunos te buscarán para que los guíes y otros para que los protejas. Es mi deber asegurarme de que estás preparado para esta tarea. Búscame en el Campamento Narache. Lanka Tirolejano, instructora de cazadores" },
		[2454] = { file = "2454", len = 25.469, text = "Tú estas en buenas manos, colega. Jen'shan sabe que quieres conocer los trucos del cazador y está preparada para enseñarte... si estás $Gpreparado:preparada; para escuchar. Ven a buscarme en el Valle de los Retos. Jen'shan empezará a instruirte y a mostrarte lo poderosas que pueden llegar a ser las artes de la caza. Jen'shan, instructora de cazadores" },
		[2455] = { file = "2455", len = 34.22, text = "$gDomador:domadora; de bestias, $gmaestro:maestra; de la puntería, $gprobado rastreador:probada rastreadora;: ¿qué más quieres ser en esta vida? Estos dones implican inteligencia y grandes dosis de paciencia. La vida del cazador no es fácil, tenlo por seguro. Si quieres ser tan bueno como incluso el peor de nuestros tiradores, tendrás que entrenarte a conciencia. Pero esa es la razón por la que estoy aquí. Búscame en Yunquemar, frente al Valle de Crestanevada. Te estaré esperando. Thorgas Grimson, instructor de cazadores" },
		[2456] = { file = "2456", len = 42.214, text = "Elune está contigo, $N. El viento me lo ha susurrado y estoy contenta de poder tomar parte directamente en la formación de nuestra próxima generación de cazadores. Según me han dicho, estás cerca de Aldrassil. Cuando tengas tiempo, nos reuniremos en el gran árbol. Nuestros mayores me han pedido que me asegure de que nuestros nuevos cazadores reciban la instrucción necesaria para hacer frente a los retos que tienen por delante. Eres uno de los estudiantes que se ha incorporado más recientemente, de manera que es inexcusable que me visites. Hasta entonces, que te vaya bien. Ayanna Semprerguida, instructora de cazadores" },
		[2457] = { file = "2457", len = 32.993, text = "Es bueno saber que $Gun hermano:una hermana; de Jenshan ha venido al valle para probar su destreza. ¡Jen'shan espera con impaciencia! No tengo que decirte que eres $Gun cazador:una cazadora; fuerte y $Gastuto:astuta;: tú ya lo sabes. A Jen'shan le corresponde la tarea de lograr que seas más fuerte y más $Gastuto:astuta;. Encontrarás a Jen'shan en el Valle de los Retos. Ella te enseñará lo que tienes que saber. Entre otras cosas, te enseñará a domesticar a las bestias más temibles. Jen'shan, instructora de cazadores" },
		[2458] = { file = "2458", len = 38.531, text = "La pasada noche, los espíritus se manifestaron en mis sueños. Me dijeron que vendrías y que mi tarea consistiría en ayudarte. Tenemos mucho que hacer en un corto espacio de tiempo: disquisiciones sobre la naturaleza, los espíritus, la Madre Tierra e incluso los elfos de la noche. Pero guardaré las lecciones para cuando llegues y haré todo lo que esté en mi mano para asegurarme de que estés preparado para afrontar las pruebas que tienes por delante. Que la sabiduría te guíe. Te estaré esperando. Gart Correbruma, instructor de druidas" },
		[2459] = { file = "2459", len = 35.971, text = "Cuando me llegó la noticia de que estabas preparado, envié inmediatamente este sigilo. Todos los druidas de Cenarius han mostrado gran satisfacción al ver que nuestros números aumentan. Hasta los espíritus parecen más poderosos debido a nuestra presencia reforzada. Con el tiempo y con un poco de paciencia, esperamos recuperar algo de nuestro antiguo esplendor. Cuando estés preparado, búscame en lo más alto de Aldrassil. Seré tu guía durante todo el tiempo que estés en Cañada Umbría. -Mardant Fuerterroble, instructor de druidas" },
		[2460] = { file = "2460", len = 37.747, text = "Te saludo, joven $c. Los vientos me anunciaron tu llegada. La tierra ha elogiado tu fuerza. Ahora, los viejos espíritus susurran las tareas que tienes por delante. Nuestro pueblo siempre necesita líderes sabios y con grandeza de espíritu. A menudo, miran a los de nuestra clase en busca de ambas virtudes. Si lo deseas, te enseñaré más sobre nuestros métodos. Búscame en el Campamento Narache, en Mesa de la Nube Roja, donde hablaremos más a fondo sobre estas cosas. Meela Caminalba, instructora de chamanes" },
		[2462] = { file = "2462", len = 32.287, text = "Mis saludos $G'emano:'emana;, Lo' espiritu' dicen que estás listo para ayudar a nuestros alados. Tiene' una gran unión con lo' elementos y eres más poderoso que cuando tuvi'te tu primera lección con migo. Ahora te enviaré a que te reuna' con Shikrik, la entrenadora de chamanes en el Valle de los Retos. Ya sabe que vas a entrenarte. Enorgullece a nue'tro ancestros. Hasta que nos volvamos a ver, que tu llama te tenga caliente, y el viento a tus e'paldas. -Ishi-yo" },
		[2463] = { file = "2463", len = 37.956, text = "Espero que cuando recibas esta carta, estés bien, $c. Digo esto con mucho orgullo, ya que muchos no profesan una fe tan profunda, pero también saben que están entre la élite de los protectores de Azeroth. Recuerda siempre, por encima de todo, que tu deber consiste en luchar contra todos aquellos que quieran dañar nuestro mundo y llevar la corrupción a nuestros hogares. He recibido autorización para ocuparme de tu instrucción. Cuando estés $Gpreparado:preparada;, búscame en la Abadía de Villanorte. Hermano Sammuel, instructor de paladines" },
		[2464] = { file = "2464", len = 39.915, text = "Algunos nos temen más que a los dragones. Otros nos envidian más que a los herreros más hábiles. Otros desearían tener nuestra fuerza en la batalla. Otros se deleitan con nuestra fe. ¡Algunos nos tienen envidia porque les damos cien mil vueltas bebiendo! Pero debes saber, $c, que estás entre la élite de los protectores de todo Azeroth. La Luz Sagrada nos da tanto poder como nosotros a ella. Cuando conozcas más estas tierras, profundizaré más sobre esto último. Búscame en Yunquemar, en lo alto del valle. Bromos Grummner, instructor de paladines" },
		[2465] = { file = "2465", len = 43.389, text = "Tu conexión con el mundo, así como la conexión del mundo contigo, resultan esenciales para tu éxito como $c. La sabiduría y la compasión te permitirán ayudar a todos aquellos que tengan verdadera necesidad. Las decisiones torpes o demasiado entusiastas solo impiden que otros se hagan más fuertes o, incluso, les causan daño. Cuando empieces a comprender lo que esto significa, necesitarás más facultades y encantamientos que te sirvan de ayuda. Aquí es donde empieza mi papel: cuando quieras comenzar tu instrucción, búscame en el ala de la biblioteca de la Abadía de Villanorte. $C Anetta, instructora de sacerdotes" },
		[2466] = { file = "2466", len = 37.538, text = "Al calor de Luz Sagrada y con tantos descubrimientos hechos por nuestra gente, ser hijos de Forjaz constituye todo un orgullo. La Liga de Expedicionarios progresa cotidianamente en su búsqueda de respuestas duraderas incluso a las preguntas más antiguas. Y ahora te tenemos a ti entre nuestros fieles para ayudarnos en la batalla contra los troggs o cualquier otra amenaza para nuestras fronteras. Cuando tengas tiempo, ven a buscarme. Estaré en la parte trasera de Yunquemar, justo encima de la colina. Silo Khalder, instructor de sacerdotes" },
		[2467] = { file = "2467", len = 40.803, text = "Siéntete $Gbendecido:bendecida;, ya que tu espíritu no ha sido arrojado al abismo, $N. Incluso, siéntete más $Gbendecido:bendecida; aún, ya que he decidido que tú vales la pena y escribir este pergamino tiene sentido. El pueblo que una vez conociste, incluso que quizás cuidaste, ¡ya no existe! Debes aprender a \"vivir\" con este convencimiento durante el resto de tu vida no natural. Sugiero que asumas esto cuanto antes. Si piensas que estás $Gpreparado:preparada; para los retos que tienes por delante, búscame en la iglesia de Camposanto. Clérigo oscuro Duesten, instructor de sacerdotes" },
		[2468] = { file = "2468", len = 38.74, text = "Espero que cuando recibas este sigilo, te encuentres bien, $N. Los espíritus me han dicho que vas a venir y te he enviado este mensaje inmediatamente. Estoy ansiosa por compartir mis experiencias contigo y guiarte de tal manera que puedas prepararte para abandonar Teldrassil y realizar cometidos más importantes. Con todo lo que ha pasado en los últimos años, es mucho lo que podemos hacer para ayudar a otras razas de Azeroth. Cuando estés $glisto:lista;, búscame en Aldrassil, en el segundo nivel. Shanda, instructora de sacerdotes" },
		[2469] = { file = "2469", len = 37.016, text = "Espero que los espíritus te hayan protegido hasta ahora, colega. Tienes muchas pruebas por delante y, cuando estés preparado, estoy dispuesto a compartir mis experiencias contigo. Depende de ti decidir cuán rápido y poderoso quieres ser. Solo podré guiarte cuando estés preparado. Para algunos, esto puede llevar poco tiempo, mientras que para otros, mucho más. Pero, por el momento, no te preocupes de eso. Cuando vengas a mi encuentro, hablaremos más ampliamente. Ken'jai, instructor de sacerdotes" },
		[2471] = { file = "2471", len = 31.948, text = "Durante milenios, hemos estado aislados de los extraños. Seré el primero de los nuestros que admita los errores que se han cometido en el pasado. Los humanos nunca deberían haberse expuesto al influjo de la magia. No negaré esto último, pero no pienso ser el que nos condene a una existencia cautelosa a causa de los errores de nuestros predecesores. Es mucho lo que la coexistencia entre los Quel'dorei y otras razas de este mundo puede aportar. Debemos practicar la tolerancia. (continuación)" },
		[2472] = { file = "2472", len = 12.643, text = "Con estas palabras, niego la petición de Kael en relación con Nathanos Marris. Demostrará ser un valioso aliado. Ya verás. Sylvanas Brisaveloz General forestal de Lunargenta" },
		[2491] = { file = "2491", len = 19.827, text = "Grish: Tu petición de un tiempo de descanso ha sido aceptada. Te envío un guerrero tauren de reserva para que vigile tu puesto mientras pasas una temporada con tu familia. ¡Vuelve a presentarte en una semana! Maggran Vinculador terrestre" },
		[2511] = { file = "2511", len = 38.949, text = "Querido Zargh: Los filetes que enviaste están muy buenos. Tienen sus buenas vetas de grasa, son anchos y están recubiertos de grasa de jabalí. Justo como a mí me gustan. Cuando vaya a comerlos, pensaré en ti mientras me dedique a roer hasta el tuétano. Cerraré los ojos y veré tus fuertes manos llenas de cicatrices picando y cortando... ¡Ja! Esto me recuerda a aquella vez que tuviste el accidente y perdiste un dedo... ¡Oh, Zargh! Pensar en aquel día hace que me ría como una niña pequeña. ¡Estás tan guapo cuando sangras! Gryshka" },
		[2512] = { file = "2512", len = 33.045, text = "Osric, A continuación, encontrarás un listado de las armaduras que necesitamos: 10 cotas de malla 20 yelmos 30 refuerzos de armadura 15 botas de malla Como siempre, estamos en deuda contigo. Y cuando Páramos de Poniente se libre de los ladrones que lo amenazan, dejaré de sentirme culpable si puedo invitarte a comer a mi casa, con la generosidad propia de esta tierra en tiempos pasados. Lewis Intendente, Colina del Centinela" },
		[2513] = { file = "2513", len = 35.396, text = "Nessa, Me alegra tener noticias tuyas. La colección de huesos y escamas que me enviaste era increíble. Nunca había visto peces de ese tamaño cerca del continente. ¡Los pescadores de Rut'theran deben conseguir toneladas de pescados por día sin esfuerzo! Me da envidia el tamaño de sus presas, pero también hay algo que me inquieta. ¿Qué tal si nuestro nuevo Árbol del Mundo hace que los peces crezcan hasta ese tamaño? Y en ese caso, ¿qué otros efectos podría tener? Tantas preguntas... -Laird" },
		[2514] = { file = "2514", len = 21.159, text = "A continuación, adjunto la lista de los estudiantes que han obtenido la Estrella de Platino en la Escuela de Minas y Topografía de Brock, adquiriendo un Pico de Minero Honorario: Melia Agitapiedras Bardin Vetaferro Umi Voltiflop Rumi Voltiflop Vorel Agujacero" },
		[2515] = { file = "2515", len = 28.291, text = "Por orden del ejecutor Zygand, he aquí un listado de los elementos necesarios para mantener las existencias de Rémol: 12 espadas largas 9 dagas 8 escudos redondos 15 hachas 1000 flechas Esta orden debe considerarse como una orden directa de la Dama Oscura y los responsables serán llevados ante Su presencia, como ocurriría con cualquiera que se opusiera u obstaculizara Sus deseos." },
		[2531] = { file = "2531", len = 3.265, text = "Este documento de 3 páginas está en blanco." },
		[2551] = { file = "2551", len = 26.462, text = "Layo: Hemos recibido la generosa ayuda de nuestro valiente aventurero. Te he enviado al aventurero a Silithus para que dispongas de él como un recurso más. Asegúrate de que este recurso tan valioso no se desperdicie en tus esfuerzos por descubrir los secretos que hay allí. El Círculo espera ansiosamente noticias sobre nuevos avances. Que Cenarius vele por ti... Rabine" },
		[2571] = { file = "2571", len = 36.127, text = "El Festival de Invierno Las últimas estaciones de Azeroth se consideran tiempo de cambio en muchas culturas. Los enanos y los tauren atienden a una leyenda del próximo Festival de Invierno: la tierra se cubre de nieve y, de esta manera, anuncia un tiempo de renovación: como una época propicia para la celebración. Si bien la interpretación de las leyendas que comparten las razas de Azeroth es similar, la forma en que responden a ellas es tan distinta como las propias razas." },
		[2572] = { file = "2572", len = 34.299, text = "La Leyenda del Gran Padre Invierno Se considera que la expresión \"Festival de Invierno\" está relacionada con un ser sobrenatural citado en muchas culturas como el Gran Padre Invierno. Cuando este personaje recorre la tierra en las estaciones, el propio invierno es su manto de nubes. En su despertar, la tierra está cubierta de nieve y, de esta manera, se dice que el Gran Padre Invierno cubre la tierra con su gélido velo. Aunque ciertas zonas de Azeroth estén cubiertas de nieve, esto otorga a la tierra tiempo para el renacimiento y la renovación." },
		[2573] = { file = "2573", len = 27.742, text = "Los enanos Aun consumidos por la búsqueda de sus orígenes, los enanos eligieron celebrar la estación como un reconocimiento al propio Gran Padre Invierno. Lo consideran como la personificación de uno de los ancestros de Azeroth: los titanes. Sea cual sea el grado de parentesco que los une a estos seres místicos, consideran su nevado hogar de Dun Morogh como el principal ejemplo de las bendiciones del Gran Padre Invierno." },
		[2574] = { file = "2574", len = 33.959, text = "Los tauren Los tauren y su concepción chamánica del invierno, junto con sus recientes esfuerzos de carácter druídico, casan perfectamente con la leyenda del Festival de Invierno. Sin embargo, se encuentran casi por entero en los aspectos renovadores de la tradición, dejando el tema de la adoración para otras razas (como las contemplan ellos) que tengan una sintonía menor con la naturaleza de las cosas. Muchos tauren escogen esta época como el tiempo adecuado para dar gracias por las bendiciones de su nuevo hogar en Mulgore." },
		[2575] = { file = "2575", len = 34.56, text = "Festejos La idea de los festejos durante esta época del año hunde sus raíces en el terreno de la propia leyenda. Cuando el Gran Padre Invierno atravesaba Azeroth, mientras lo cubría todo con su gélido mando, se decía que otorgaría el premio a aquellos que le dieran la bienvenida. Por ello, la idea de organizar festejos durante el Festival de Invierno uniría a las comunidades que compartieran lo que tenían. Habitualmente, un único día de júbilo y festejos daba la bienvenida al cambio, como anticipo a la renovación de la tierra." },
		[2576] = { file = "2576", len = 32.522, text = "Observación desde al modernidad Otras culturas han empezado a reconocer el Festival de Invierno como una época digna de ser celebrada, si bien no siempre siguen las mismas tradiciones en las cuales se basa la leyenda. Las costumbres, a menudo sin otro propósito que reservar un día para la celebración y el intercambio de regalos, han llegado hasta la observación moderna de la estación. Incluso se suele utilizar la imagen del Gran Padre Invierno, pero antes que un titán sobrenatural, se ha convertido en un reclamo comercial." },
		[2591] = { file = "2591", len = 38.191, text = "En las profundidades del Valle de las Lanzas está situado el templo sagrado de Maraudon. Si no fuera suficiente con esta trasgresión, pronto descubrirás por qué le pedí a un no centauro que me ayudara en tan difícil situación. Allí, más allá de las puertas donde solo hay espíritus y solo nuestros más elevados sacerdotes y sacerdotisas pueden viajar, se encuentra uno llamado el profeta sin nombre. Es el ser más elevado de cualquier tribu en cuestiones espirituales y, al mismo tiempo, es uno de los más ancianos." },
		[2592] = { file = "2592", len = 20.584, text = "El profeta es poderoso y se comunica con los espíritus de nuestros ancestros. ¡Pero es un idiota! No tiene ni idea del verdadero poder que posee. En su persona recae el amuleto de los espíritus: de ahí procede la mayor parte de su poder. He aprendido que el amuleto es poderoso, pero está incompleto." },
		[2593] = { file = "2593", len = 28.264, text = "Al amuleto le faltan cinco gemas. Y si dichas gemas estuvieran colocadas dentro del símbolo, su poder sería muchísimo mayor de lo que es en la actualidad. He localizado las cinco gemas, pero necesito a alguien con tu talento para que me ayude a colocarlas. Matar al profeta sin nombre es, seguramente, una herejía, como sería saquear su cadáver, pero lo que voy a pedirte a continuación condenaría a cualquier centauro aun cuando solo pensara en ello." },
		[2595] = { file = "2595", len = 19.749, text = "Por el interior de las cavernas de Maraudon deambulan los espíritus de nuestros primeros khans. Los primeros hijos de nuestra Madre y nuestro Padre, y nuestros más grandes líderes, son Gelk, Kolk, Magra, Maraudos y Veng. Cada uno de estos espíritus alberga una de las gemas perdidas." },
		[2596] = { file = "2596", len = 24.451, text = "¡Utiliza el poder del amuleto de los espíritus para obligarlos a manifestarse y quítales las gemas! Luego, coloca las gemas en el amuleto de los espíritus y devuélvemelo. Una vez que tenga el Amuleto de Unidad, tendré suficiente poder como para reformar las tribus, de tal manera que, finalmente, ¡podamos llegar a ser lo que deseaban nuestros ancestros!" },
		[2611] = { file = "2611", len = 17.293, text = "... y, de esta manera, allí es donde encontrarás la legendaria espada del Alto Señor Escarlata, conocida como la Crematoria. ¿No es increíble lo que puedes encontrarte en un día de pesca cualquiera?" },
		[2631] = { file = "2631", len = 38.06, text = "Las páginas están cubiertas por antiguas runas élficas.\010Las páginas siguientes contienen recuerdos de los sucesos que tuvieron lugar en la recolección y la creación de los componentes necesarios para crear un arcano mayor. Que nuestros enemigos nunca tengan acceso a estos tratados. Quisiera vivir lo suficiente como para volver a contemplar la pálida luz de la luna sobre Quel'Thalas. Si muero, que sea por la gracia de Kael'thas. Si muero asesinado, que sea por la gloria de Illidan. Maestro Telmius Buscasueños" },
		[2632] = { file = "2632", len = 4.885, text = "Nada de lo que hay escrito en estas páginas resulta inteligible." },
		[2633] = { file = "2633", len = 36.284, text = "Las páginas están cubiertas por antiguas runas élficas.\010Las páginas siguientes contienen recuerdos de los sucesos que tuvieron lugar en la recolección y la creación de los componentes necesarios para crear un arcano mayor. Que nuestros enemigos nunca tengan acceso a estos tratados. Quisiera vivir lo suficiente como para volver a contemplar la pálida luz de la luna sobre Quel'Thalas. Si muero, que sea por la gracia de Kael'thas. Si muero asesinado, que sea por la gloria de Illidan. Maestro Telmius Buscasueños" },
		[2634] = { file = "2634", len = 8.046, text = "La tinta se desplaza, formando remolinos sobre la página. Tienes la sensación de que el libro se está burlando de ti." },
		[2635] = { file = "2635", len = 37.12, text = "Las páginas están cubiertas por antiguas runas élficas.\010Las páginas siguientes contienen recuerdos de los sucesos que tuvieron lugar en la recolección y la creación de los componentes necesarios para crear un arcano mayor. Que nuestros enemigos nunca tengan acceso a estos tratados. Quisiera vivir lo suficiente como para volver a contemplar la pálida luz de la luna sobre Quel'Thalas. Si muero, que sea por la gracia de Kael'thas. Si muero asesinado, que sea por la gloria de Illidan. Maestro Telmius Buscasueños" },
		[2636] = { file = "2636", len = 4.049, text = "Cuando contemplas estas páginas, sientes un dolor agudo." },
		[2637] = { file = "2637", len = 11.389, text = "Compendio de matar dragones de Foror es un libro grueso completamente lleno de escritos. Lamentablemente, el texto parece ser confuso y no tiene sentido para tí." },
		[2654] = { file = "2654", len = 28.996, text = "TRATADO SOBRE LOS RANGOS MILITARES Lo que sigue son los rangos militares de la Alianza, precedido por la información tal y como la conocen las razas de la Horda. Cada rango se muestra en dos secciones: los oficiales y luego, los soldados rasos, con los rangos correspondientes a cada uno, enumerados en orden descendente, del superior al inferior. ¡Larga vida a la Alianza!" },
		[2655] = { file = "2655", len = 8.15, text = "RANGOS DE OFICIALES DE LA ALIANZA Parte 1 Gran mariscal Mariscal de campo Mariscal Comandante Teniente coronel" },
		[2656] = { file = "2656", len = 8.464, text = "RANGOS DE OFICIALES DE LA ALIANZA Parte 2 Campeón caballero Capitán caballero Teniente caballero Caballero" },
		[2657] = { file = "2657", len = 6.06, text = "RANGOS DE SOLDADOS DE LA ALIANZA Alférez Sargento primero Sargento Cabo Soldado" },
		[2658] = { file = "2658", len = 7.993, text = "RANGOS DE OFICIALES DE LA HORDA Parte 1 Gran Señor de la Guerra Señor de la Guerra Gran general General Campeón" },
		[2659] = { file = "2659", len = 31.033, text = "Si echas un vistazo en el interior del Ojo, aparecerán en tu mente imágenes de una gran batalla. Este terrible conflicto parece ocurrir en algún lugar de Lordaeron. Solo se distingue una solitaria figura femenina, de pie y rodeada de miles de cadáveres, esquivando una marea de la Plaga. No tiene esperanza alguna de hacer frente a la marea enemiga. De sus manos brotan haces de luz, abriéndose camino entre centenares de no-muertos." },
		[2661] = { file = "2661", len = 25.313, text = "RANGOS MILITARES DE LA HORDA Y DE LA ALIANZA ¡Throm'ka! En este libro encontrarás muchas listas de rangos militares de la Horda y de la insignificante Alianza. Primero aparecen los rangos de la Horda y luego de la Alianza, cada una con listados de rangos de oficiales y de soldados. Está ordenada de tal manera que los más poderosos aparecen al principio y los más débiles al final." },
		[2662] = { file = "2662", len = 8.62, text = "RANGOS DE OFICIALES DE LA HORDA Parte 1 Gran Señor de la Guerra Señor de la Guerra Gran general General Campeón" },
		[2663] = { file = "2663", len = 7.628, text = "RANGOS DE OFICIALES DE LA HORDA Parte 2 Centurión Legionario Guardia de sangre Guardia de piedra" },
		[2664] = { file = "2664", len = 6.609, text = "RANGOS DE SOLDADOS DE LA HORDA Gran capataz Capataz primero Capataz Bruto Explorador" },
		[2665] = { file = "2665", len = 8.464, text = "RANGOS DE LOS OFICIALES DE LA ALIANZA Parte 1 Gran mariscal Mariscal de campo Mariscal Comandante Teniente coronel" },
		[2666] = { file = "2666", len = 10.501, text = "Al parecer, todo para nada. Poco después, en torno a la sacerdotisa se agolpan los cadáveres de los campesinos que la rodeaban... Los caídos se han levantado." },
		[2671] = { file = "2671", len = 14.968, text = "Simone la Seductora: Encontrarás a Simone contaminando el cráter Un'Goro. No te dejes engañar por su disfraz. Aproxímate a ella con cuidado y rétala a un combate." },
		[2672] = { file = "2672", len = 10.188, text = "Klinfran el Enloquecido: Klinfran vaga por las Estepas Ardientes. Acércate a él con precaución y oblígale a mostrarte su verdadera forma." },
		[2673] = { file = "2673", len = 16.222, text = "Solenor el Destripador: En los áridos parajes de Silithus vaga el desalmado Solenor el Destripador. Indudablemente, aparecerá disfrazado y, definitivamente, es un peligro. Acércate a él y oblígale a transformarse." },
		[2674] = { file = "2674", len = 9.3, text = "Artorius el Fatídico: Artorius trae la corrupción y la maldición a todo lo que toca en Cuna del Invierno. Encuéntralo y mátalo." },
		[2675] = { file = "2675", len = 10.606, text = "Ten cuidado, cazador, debes combatir a estos demonios según sus reglas. Si sienten que no son superiores a ti, sin duda huirán. VE SOLO." },
		[2676] = { file = "2676", len = 17.659, text = "RANGOS MILITARES DE LA ALIANZA OFICIALES Gran mariscal Mariscal de campo Mariscal Comandante Teniente coronel Campeón caballero Capitán caballero Teniente caballero Caballero SOLDADOS Alférez Sargento primero Sargento Cabo Soldado" },
		[2691] = { file = "2691", len = 38.504, text = "Para vincular a un corcel nefasto, debes realizar estas tres tareas: Crear un círculo de invocación superior. Dentro del círculo, abre un portal hacia Xoroth y conduce al terrorecus a través del portal. Derrota al corcel nefasto y luego domina su espíritu. En las siguientes páginas encontrarás una explicación detallada de cómo realizar esta tarea. Puede que no sea fácil, pero has demostrado ser muy capaz. Sin duda, con concentración y habilidad, el corcel nefasto será tuyo. Continúa leyendo, Mor'zul Sangredoble" },
		[2692] = { file = "2692", len = 28.029, text = "Instrumentos de un ritual Antes de que inicies tu trabajo, deberás disponer de los siguientes instrumentos mágicos: Jarra de J'eevee Magnetita negra Glifos xorothianos Mi sirviente Gorzeeki lo tiene y te lo puede ofrecer a buen precio. No intentes siquiera realizar el ritual si no dispones de todos estos instrumentos. Todos resultan esenciales. En las siguientes páginas, describiré cómo utilizar cada uno de ellos." },
		[2693] = { file = "2693", len = 31.373, text = "Círculo de vínculo superior Es preciso crear un círculo de vínculo superior en un lugar en el que la magia tenga fuerza. En medio de las ruinas de Eldre'Thalas, encontrarás un sitio de estas características, también llamado La Masacre. En Eldre'Thalas se encuentra prisionero un ser de gran poder, Immol'thar. En el pedestal de su prisión debes realizar el ritual para crear el círculo. Encuentra tu camino hasta el pedestal y luego deja que J'eevee salga de su tarro." },
		[2694] = { file = "2694", len = 33.489, text = "La Campana, la Rueda y la Vela Cuando liberes a J'eevee, este colocará la Campana, la Rueda y la Vela, y aparecerá un círculo. Este es el comienzo del ritual. Debes estar alerta. Los objetos antes mencionados transmiten una gran cantidad de energía y son propensos a fallar. Cuando esto ocurra, deberás usar la magnetita para reiniciarlos, antes de que fracase todo el ritual. Si los tres objetos han fallado antes de que logres reiniciarlos, el ritual terminará y deberás comenzar de cero." },
		[2695] = { file = "2695", len = 34.821, text = "Además de transmitir las energías del ritual, la Campana, la Rueda y la Vela tienen propiedades únicas. Cuando suena, la Campana de Dethmoora confiere vigor y energía a los brujos que estén dentro del círculo. Cuando gira, la Rueda de la Marcha Negra protege de cualquier daño a los que están dentro del círculo. La Vela del Apocalipsis, cuando arde, envía una extraña energía a los enemigos que entran en el círculo. Gracias a estos dones, es muy importante que todos estos objetos funcionen durante el ritual." },
		[2696] = { file = "2696", len = 22.544, text = "Tienes que tener en cuenta que la magnetita, utilizada para reiniciar la Campana, la Rueda o la Vela si fracasan, requiere fragmentos de alma. Cada vez que reinicies un objeto ritual con la magnetita, se consumirá uno de tus fragmentos de alma, así que asegúrate de tener suficientes reservas de fragmentos antes de iniciar el ritual." },
		[2731] = { file = "2731", len = 28.473, text = "Aquí yace Durotan, primer jefe del clan Lobo Gélido y padre de Thrall, nuestro honorable Jefe de Guerra. Fue el más valiente de los nuestros, traicionado por aquellos que querían ver esclavizado a nuestro pueblo. Durotan dio su vida para que ganáramos la libertad. Lo glorificamos: su legado ha llegado hasta nosotros a través de su hijo. Drek'Thar, Clarividente de los Lobo Gélido" },
		[2771] = { file = "2771", len = 19.357, text = "Pelando la cebolla Guía para desmantelar a los Pico Tormenta -Por Drek'Thar En estas páginas encontrarás amplios conocimientos sobre tácticas de guerra y política. Un soldado instruido es un soldado que se apoya en la experiencia. Utiliza este libro como guía en tu batalla por el Valle de Alterac." },
		[2772] = { file = "2772", len = 37.12, text = "Capítulo 1 - El frente Desmantelar el ejército de los Pico Tormenta es una tarea similar a la de pelar una cebolla. Para llegar al núcleo, hay que empezar eliminando las capas exteriores. Las líneas del frente, que comprenden fundamentalmente a los montaraces de Pico Tormenta y los Centinelas de la Alianza, están ligadas al búnker del capitán. Es el capitán Balinda Corapernal el que da poder a estas unidades y proporciona los refuerzos necesarios cuando las líneas están bajo sitio. Golpea al capitán y las líneas del frente se quebrarán." },
		[2773] = { file = "2773", len = 28.134, text = "Capítulo 2 - Las Torres Gemelas No te equivoques, Vanndar Pico Tormenta es un enemigo astuto y, ciertamente, no es nada tonto. Una vez rota la línea del frente, es preciso destruir los objetivos defensivos de carácter secundario. Se trata de las torres gemelas de Piedrahogar y Ala Gélida, que controlan los Soldados de Pico Tormenta, lejos de Dun Baldar y de las patrullas Pico Tormenta." },
		[2774] = { file = "2774", len = 22.962, text = "Ten cuidado, Soldado, ya que ambas torres están muy bien fortificadas y están capitaneadas por uno de los Comandantes de élite de Vanndar. Cuando tus fuerzas rompan las fortificaciones, asegúrate de que el Comandante que está en su interior haya sido... silenciado. Esta última tarea también forma parte del desmantelamiento de Pico Tormenta." },
		[2775] = { file = "2775", len = 34.795, text = "Capítulo 3 - Los cuatro Comandantes La tercera capa de cebolla del ejército Pico Tormenta comprende a los cuatro Comandantes. A este respecto, Vanndar ha imitado a nuestras gloriosas defensas de Lobo Gélido. Lógicamente, él te diría otra cosa... Pero me estoy desviando de la cuestión. Los cuatro Comandantes controlan el flujo y reflujo de los Soldados de Pico Tormenta que defienden Dun Baldar con valentía. Ocúpate de silenciarlos y los Soldados Pico Tormenta caerán. Ahora solo queda una capa por pelar." },
		[2776] = { file = "2776", len = 29.597, text = "Capítulo 4 - Los búnkeres de Dun Baldar Como ya habrás advertido, las capas defensivas de Pico Tormenta están colocadas de tal manera que impidan que un movimiento enérgico pueda desmantelar todo el ejército. Antes de que preguntes, sí, coincide exactamente con la forma en que están desplegadas nuestras fuerzas... y no, no pienso modificar nuestra estructura defensiva. Ellos nos copiaron a nosotros, ¿por qué habría de cambiar?" },
		[2777] = { file = "2777", len = 20.402, text = "¿Por dónde iba? Ah, sí, los búnkeres de Dun Baldar (situados en Dun Baldar), controlan a los defensores de Pico Tormenta, las unidades de guardia de élite y los hombres de mayor confianza de Vanndar. Destruye las dos torres y los refuerzos enviados para ayudar a Vanndar dejarán de existir." },
		[2778] = { file = "2778", len = 24.451, text = "Epílogo Una vez que hayas hecho todo esto, te queda el centro de la cebolla: El dulce núcleo. Vanndar Pico Tormenta estará solo e indefenso. Las reglas de conducta militar requieren que, antes de realizar tareas de limpieza, le preguntemos si desea rendirse. En cuanto le veas, asegúrate de mencionarle lo de la rendición y luego... mátalo." },
		[2779] = { file = "2779", len = 40.176, text = "La alcachofa de los Lobo Gélido: Relatos sobre la gloria de Pico Tormenta Por Vanndar Pico Tormenta ¿Qué son los Lobo Gélido? La respuesta es sencilla: Los Lobo Gélido son salvajes que intentan acabar con nuestra imprescindible soberanía imperial. Al igual que ocurre con una alcachofa, los Lobo Gélido cuentan con un espinoso conjunto de defensas acorazadas y también, como ocurre con la alcachofa, una vez que se extrae la capa exterior, el corazón queda expuesto y listo para ser engullido con una suave salsa de ajo. ¡Delicioso!" },
		[2780] = { file = "2780", len = 33.959, text = "Capítulo 1 - El frente Las líneas del frente de las defensas de los Lobo Gélido están formadas por los guerreros Lobo Gélido. Estos guerreros están desplegados en las líneas del frente, desde la fortaleza del capitán Galvangar: Baluarte Sangre Fría. La forma más eficaz de eliminar esta capa de las defensas consiste en destruir el Baluarte Sangre Fría. Pon la fortaleza bajo sitio y destruye al capitán Galvangar. Una vez que lo hayas logrado, las líneas del frente se desmoronarán." },
		[2781] = { file = "2781", len = 37.381, text = "Capítulo 2 - Sangre Fría y Torre de la Punta Una vez desaparecida la primera capa, la segunda capa de la \"alcachofa\" quedará expuesta. Mediante la destrucción de las torres Lobo Gélido, situadas cerca de las líneas del frente, lograrás neutralizar a los Legionarios y a las patrullas que se apiñan en la retaguardia. Las torres están bien fortificadas y cada una de ellas alberga uno de los Comandantes de élite de Drek'Thar. Hay que eliminarlos. De esta manera, el camino para desmantelar las defensas Lobo Gélido quedará expedito." },
		[2782] = { file = "2782", len = 35.213, text = "Capítulo 3 - Los cuatro Comandantes Si has seguido sabiamente esta guía, en este momento, dos de los Comandantes de Drek'Thar deberían estar muertos. ¡Buen trabajo, Soldado! No obstante, su resolución continúa siendo un problema. Debes completar la tarea de romper la cadena de mando, acabando con los dos Comandantes restantes. Una vez que hayan desaparecido los cuatro Comandantes, los legionarios Lobo Gélido que cuidan el Bastión Lobo Gélido quedarán aislados y sin superiores. ¡La fruta estará madura!" },
		[2783] = { file = "2783", len = 29.623, text = "Capítulo 4 - Las torres Lobo Gélido del este y el oeste Solo te queda una capa para alcanzar la victoria. Las unidades de guardianes más poderosas y en quienes más confía Drek'Thar: Los Guardianes Lobo Gélido. Los Guardianes Lobo Gélido proceden de pelotones de la reserva situados en las torres Lobo Gélido del este y el oeste. Destruye estas torres y verás cómo los guardianes Lobo Gélido restantes huyen de forma vergonzosa." },
		[2784] = { file = "2784", len = 26.305, text = "Epílogo \"Sumerge la alcachofa en crema de ajo y mayonesa. Acompaña la comida con una reposada y embriagadora cerveza.\" Ahora Drek'Thar está solo, con los dos perros que lo acompañan. Captura el Puesto de auxilio Lobo Gélido para que te sirva de ayuda en la batalla y destruye a Drek'Thar. Cuando el general caiga, esta tierra volverá finalmente a su legítimo dueño: Los Pico Tormenta." },
		[2785] = { file = "2785", len = 21.577, text = "Te convocamos, Zanza de Zuldazar. Bendice a los que pidan tu ayuda, Loa Zanza. Bendice a aquellos que establecerían una alianza con el pueblo de Zandalar. Ayúdanos en tiempo de necesidad. Ayúdanos, Loa. Danos el poder para derrotar a nuestros enemigos. Danos el poder para derrotar una vez más al Dios de la Sangre." },
		[2786] = { file = "2786", len = 49.894, text = "¡Torneo de pesca de Tuercespina! Domingo por la tarde de las 14.00 a las 16.00. Pesca en cualquier punto situado en la costa de Tuercespina (exceptuando la Bahía del Botín) y fíjate en los cardúmenes de pezrico que aparecerán a lo largo de la costa. Asegúrate de que tu boya de pesca cae en medio del cardumen y, en lugar de pescar la variedad habitual de Tuercespina, obtendrás un pez especial. ¡La primera persona que capture cuarenta pezricos puede pedir al maestro de pesca Anzuelo, que está en la Bahía del Botín, que se los cambie por un premio! Incluso si no eres la primera persona que capture los cuarenta pezricos, aún puedes cambiarlos por dinero en efectivo. Además, aquellos que pesquen otras variedades especiales ¡también recibirán premios!" },
		[2787] = { file = "2787", len = 14.733, text = "Su nombre trajo la luz a la oscura Azeroth. Su valor derribó los muros del sufrimiento. Los Mano de Plata nunca harían nada mejor que dar al mundo el caballero que se sacrificó por los demás." },
		[2788] = { file = "2788", len = 12.513, text = "No fue la fama lo que perseguía, ni convertirse en señor para su gente. Por el contrario, escogió luchar por Lordaeron, con la esperanza de que los suyos ya no tuvieran que hacerlo." },
		[2789] = { file = "2789", len = 12.33, text = "El trágico relato de este caballero sagrado nunca terminará con su impía muerte. Lo glorificamos ¡y le daremos siempre las gracias! ¡Uther siempre conocerá la gloria y la Luz!" },
		[2790] = { file = "2790", len = 14.341, text = "Su nombre nunca morirá. Su sacrificio siempre nos mostrará el camino. Una vez rotas las cadenas que estrangulaban nuestro honor, ya no podrán esclavizarnos." },
		[2791] = { file = "2791", len = 10.919, text = "¿Puedes oír ese grito? Es un grito de batalla de la Horda: ¡Victoria o muerte! Debemos recordar su fuerza cara a la muerte. Su sueño ahora se ha hecho realidad." },
		[2792] = { file = "2792", len = 11.546, text = "¡Peligros por todas partes! Los enemigos intentan encadenarnos de nuevo. Cuando luchemos, pensad en aquel que sabía lo que había que hacer. ¡Grito Infernal por siempre!" },
		[2793] = { file = "2793", len = 24.66, text = "Han pasado casi mil años desde la 'Guerra del Mar de Dunas'. Durante esa guerra, en el corazón del desierto de Silithus, Fandral Corzocelada hubo de soportar una gran tragedia y una gran carga. Se cree que los acontecimientos descritos a continuación son los que finalmente conformaron la desagradable manera de ser del archidruida." },
		[2794] = { file = "2794", len = 19.331, text = "En el pasado, una antigua raza de insectoides sensibles, conocida como los qiraji, competía por dominar la mayor parte del territorio de Kalimdor. Fueron los presuntuosos e imperialistas Corzocelada y su ejército de elfos de la noche los que se enfrentaron cara a cara a los qiraji en la batalla." },
		[2795] = { file = "2795", len = 19.069, text = "Padre e hijo lucharon fervientemente para contener la marea creciente de enjambres de insectos en Silithus. Desde la fortaleza de Ahn'Qiraj, una corriente de silítidos, que parecía interminable, continuó reforzando las filas de las fuerzas invasoras qiraji. Todo Silithus estaba bajo sitio." },
		[2796] = { file = "2796", len = 19.017, text = "En una decisión que Corzocelada lamentaría, el Corzocelada más joven, Valstann, ordenó defender el puesto de los elfos de la noche de la Aldea de Viento del Sur. Desafortunadamente, Valstann perdió su vida el mismo día que la Aldea del Viento del Sur cayó bajo los ejércitos de Ahn'Qiraj." },
		[2797] = { file = "2797", len = 37.825, text = "Impertérrito y con el corazón endurecido, un vengativo Fandral Corzocelada habría de seguir adelante. La derrota en Silithus produciría una gran pérdida para la nación de los elfos de la noche y, posiblemente, para todo el mundo. La batalla se desarrolló por espacio de meses. Todo Silithus fue tomado por los qiraji. Corzocelada y su ejército fueron obligados a retroceder hacia Tanaris. Con un ejército diezmado e innumerables inocentes caídos, la arrogancia con la que se había conducido anteriormente Fandral Corzocelada desapareció por completo." },
		[2798] = { file = "2798", len = 19.331, text = "Con su orgullo totalmente devastado, Corzocelada habría de sentir, por segunda vez en su vida, el temblor en la boca del estómago que solo puede producir el miedo. Luego, fue en Tanaris donde Corzocelada se acercó a Anacronos, progenie de Nozdormu, y rogó la ayuda del Vuelo Bronce." },
		[2799] = { file = "2799", len = 15.752, text = "Inicialmente, Anacronos rechazó la posibilidad de implicar al Vuelo Bronce en los asuntos de razas inferiores. Pero cuando los qiraji atacaron descaradamente las Cavernas del Tiempo, Anacronos accedió a enviar refuerzos a los elfos de la noche." },
		[2800] = { file = "2800", len = 32.653, text = "Pronto, Anacronos se dio cuenta de que incluso el poderoso Vuelo Bronce no podría contener la marea de las fuerzas invasoras qiraji. Por cada cincuenta insectos aniquilados mediante su aliento, un centenar esperaban para ocupar su lugar. Con la caída de la noche, las líneas de los elfos empezaron a resquebrajarse, y con la posibilidad de ser empujados hacia el norte en las tierras salvajes de Feralas cada vez más cerca, Anacronos decidió que los hijos de los Aspectos debían conocer la situación." },
		[2801] = { file = "2801", len = 12.513, text = "En primer lugar, convocó al Vuelo de Ysera. Merithra del Sueño respondería a su llamada y, a partir de ahí, se darían por enterados el Vuelo de Alexstrasza y el Vuelo de Malygos." },
		[2802] = { file = "2802", len = 31.843, text = "Los dragones se reunirían en la estratosfera, encima de Silithus: Cientos de metros por encima de la fortaleza de Ahn'Qiraj. Fue Anacronos, hijo de Nozdormu, Aspecto del Tiempo. Desde el Sueño Esmeralda vendría Merithra, hija de Ysera, Aspecto de la Naturaleza. Caelestrasz, hijo de Alexstrasza, Aspecto de la Vida, representaría al Vuelo Rojo. Arygos, hijo de Malygos, Aspecto de la Magia, representaría al Vuelo Azul." },
		[2803] = { file = "2803", len = 25.809, text = "Los dragones observaron como una interminable corriente de silítidos y qiraji salían en tropel de Ahn'Qiraj. Pronto les quedó claro que esta guerra no podía acabar mediante el uso de la fuerza. Desde el interior del templo principal, miles y miles de combatientes qiraji estaban esperando. Con el paso de cada segundo, se incubaban y preparaban más y más, listos para asaltar el mundo." },
		[2804] = { file = "2804", len = 31.66, text = "Arygos fue el primero en darse cuenta de las extrañas emanaciones. El templo monolítico situado en el cuadrante sur de Ahn'Qiraj irradiaba una oscura magia, distinta de todo lo que hasta ahora conocía procedente de los qiraji. Aunque lo intentaron, nadie fue capaz de penetrar en el templo para localizar la fuente de esta energía. Solo algo de inmenso poder podría autoprotegerse por completo. Tal vez... algo controla a los insectos. Quizás algo incluso controle a los qiraji." },
		[2805] = { file = "2805", len = 18.808, text = "Los dragones sabían que tenían que reaccionar con rapidez, no fuera que el mundo sufriera otra catástrofe de proporciones épicas. Tras una cuidadosa deliberación, se decidió que la mejor acción que cabía emprender consistiría en detener los ejércitos anfitriones en su origen o cerca del mismo." },
		[2806] = { file = "2806", len = 19.618, text = "Se crearía una gran barrera, originada desde la esencia de los elfos de la noche y de los dragones. Sería una barrera mágica que podría contener a los silítidos y a sus Señores Supremos dentro de los muros de Ahn'Qiraj, previniendo futuras incursiones. El propio Ahn'Qiraj se convertiría en una prisión." },
		[2807] = { file = "2807", len = 29.466, text = "Día 1 Nuestro peregrinaje ha acabado. Finalmente, llegamos a Silithus, donde vamos a establecer contacto. Hemos venido de varios sitios para colaborar en lo que es una tarea monumental. Hay una tremenda excitación en el aire. Mañana dedicaremos todas nuestras energías a construir lo que nos permitirá entrar en comunicación con ELLOS. ¡Mañana vamos a construir una piedra de viento!" },
		[2808] = { file = "2808", len = 35.526, text = "Día 2 La localización de una piedra de viento ha sido objeto de una gran discusión. Ni siquiera el más sabio de nosotros puede determinar con exactitud a qué lugar se refería exactamente la antigua profecía. He estado con el grupo original del norte e, indudablemente, el tiempo demostrará que estamos en lo cierto. El argumento de que las líneas de energía se intersecan en ángulos perjudiciales en este lugar resulta ridículo e inocente. Hemos reunido a gran velocidad los materiales de construcción necesarios." },
		[2809] = { file = "2809", len = 31.922, text = "Día 15 Nuestra dedicación ha tenido su recompensa. Somos el primer campamento que finaliza la construcción de una piedra de viento. ¡Si los otros idiotas se hubieran quedado con nosotros, habríamos terminado la tarea en menos de una semana! Mañana iniciaremos los rituales que nos permitirán invocar al barón Kazum en persona. Ha pedido ser el primero en comprobar el sistema y, puesto que se enfada con facilidad, no hemos podido decirle que no. Espero que esté muy contento con nosotros." },
		[2810] = { file = "2810", len = 37.878, text = "Para entrega inmediata a todos los miembros del Martillo Crepuscular. La búsqueda del traidor, Ortell, progresa de forma muy satisfactoria. Nuestros exploradores están estrechando el cerco en relación con una red de cavernas situadas en los Páramos de Poniente. La traición de Ortell no caerá en el olvido y la posibilidad de que se fugue representa un gran riesgo para la seguridad de nuestra organización. Cualquier individuo que oculte información sobre el paradero de Ortell será castigado debidamente. Señor Crepuscular Everun" },
		[2811] = { file = "2811", len = 30.145, text = "Para entrega inmediata a todos los miembros del Martillo Crepuscular. Considerando el estado actual de las cosas en Silithus, la distribución de todos los textos de El creyente verdadero debe realizarse utilizando una escolta de no menos de cuatro miembros armados del Martillo Crepuscular. Cualquier miembro que infrinja esta nueva política será castigado sumariamente. Señor Crepuscular D'Sak" },
		[2812] = { file = "2812", len = 22.962, text = "Para entrega inmediata a todos los miembros del Martillo Crepuscular. La siguiente información describe el uso de piedras de viento para la comunicación con nuestros maestros del Consejo Abisal. Cualquier uso frívolo de las piedras de viento será castigado con la mayor dureza. Señor Crepuscular Havunth" },
		[2813] = { file = "2813", len = 35.448, text = "Templarios Abisales Como iniciado, se te permite establecer contacto con los Templarios Abisales para celebrar rituales rutinarios. No olvides ponerte siempre la vestimenta adecuada cuando utilices piedras de viento para evitar que se activen nuestros encantamientos defensivos. Si surge cualquier clase de emergencia no prevista y no hay un sobrestante presente, estás autorizado a invocar a un Templario Abisal. Para conocer los detalles acerca de los rituales de invocación pertinentes, consulta el número de este mes de El creyente verdadero." },
		[2814] = { file = "2814", len = 30.903, text = "Duques Abisales Solo a los acólitos en posesión de un medallón de estatus se les permite establecer contacto con los Duques Abisales. Los medallones de estatus solo deben ser utilizados por aquellos individuos para los cuales se han expedido. Los miembros del Martillo Crepuscular que hayan mantenido una comunicación no autorizada con los Duques Abisales o que hayan utilizado sin permiso los medallones de estatus serán castigados y me ocuparé personalmente de infligirles el castigo." },
		[2815] = { file = "2815", len = 29.231, text = "El Alto Consejo de los Señores Abisales Solo los Señores Crepusculares podrán tener contacto con el príncipe Skaldrenox, el Alto Mariscal Whirlaxis, el Barón Kazum o Lord Skwol. Bajo ninguna circunstancia, un miembro de bajo rango del Martillo Crepuscular tiene permiso para entrar en comunicación con el Alto Consejo. Todo extraño que sea sorprendido utilizando una piedra de viento de esta manera, quedará reducido a cenizas en el acto." },
		[2816] = { file = "2816", len = 38.661, text = "Estado del culto, volumen 92 Con el corazón exultante os saludo, hermanos míos, pues la situación de nuestro culto no podría ser más dichosa. Somos legión y nuestras metas se acercan cada vez más a su cumplimiento. Se nos unen nuevos reclutas. Todo son alabanzas a nuestros señores en Costa Oscura, se inclinan con reverencia en la Garganta de Fuego, abrazan al sirviente de nuestros maestros, Aku'mai, en las Cavernas de Brazanegra. ¡Ciertamente, hermanos y hermanas, pronto un enjambre de creyentes cubrirá todo Azeroth!" },
		[2817] = { file = "2817", len = 26.227, text = "Estado del culto, volumen 127 ¡Realmente es un día muy feliz! ¡Nos han sometido a prueba en Silithus y hemos aprobado! Los informes acerca de la destrucción de nuestro campamento situado en el extremo norte pueden suponer un reto para los corazones de los no creyentes, pero esta matanza no debe considerarse como una tragedia. ¡No!" },
		[2818] = { file = "2818", len = 21.002, text = "¡Si el Alto Consejo Abisal derrama nuestra sangre, esto debe considerarse como una bendición! ¡Debemos envidiar a nuestros camaradas caídos, ya que ahora sus espíritus residen en el vientre de la bestia más justa! ¡Alabad a los dioses antiguos! ¡Alabad a los siervos! ¡Alabad al Martillo Crepuscular!" },
		[2819] = { file = "2819", len = 39.34, text = "Estado del culto, volumen 233 ¡Hermanos y hermanas, la oportunidad vuelve a llamar a nuestra puerta! El Círculo Cenarion, un culto infame de amantes de la naturaleza, está enviando agentes en contra nuestra. Seguramente, intentan evitar que invoquemos piedras rojas. ¡No podemos permitirlo! Las piedras rojas son esenciales para nuestros nuevos aliados. No podemos permitir que los perros del Círculo Cenarion tengan éxito. Manteneos firmes, mis fieles amigos. ¡Manteneos firmes!" },
		[2820] = { file = "2820", len = 29.623, text = "¿Cómo sabemos que nos quieren? Es posible que algunos se pregunten por qué los dioses antiguos y sus esbirros nos aman. ¿Acaso no nos matarán? ¿Acaso no causarán sufrimiento y dolor a todos? ¿Cómo es posible que seres tan inclinados a la malevolencia alberguen amor en sus corazones? Existe una respuesta simple a esta pregunta. Es tan simple que ni siquiera es preciso formularla." },
		[2821] = { file = "2821", len = 15.987, text = "La fe. La fe es la fuente de donde mana la alegría de la servidumbre. La fe nos dará calor en las frías noches de Silithus. La fe nos mantendrá en la gracia de nuestros Señores cuando lleguen los días del final. La fe nos salvará." },
		[2829] = { file = "2829", len = 29.649, text = "Querido diario: Hoy, mi archienemigo Narain Sabelotodo ha intentado engañarme, enviándome compinches para cubrir su sitio en la ejecución. SU ejecución. ¿Podéis creerlo? He tenido un montón de problemas diseñando este diabólico plan para apartarle de esa maldita choza ¿y ahora hace esto? Da igual... Estoy demasiado $Genfadado:enfadada; para seguir escribiendo. Volveré más tarde." },
		[2830] = { file = "2830", len = 19.801, text = "Querido diario: Después de mi última anotación, salí de mi guarida realmente ofuscado. Vaya, si lo estaba. Decidí rediseñar los uniformes de mis esbirros para reflejar mejor mi angustia. Me siento un poco mejor, pero algo falta. Vuelvo enseguida..." },
		[2831] = { file = "2831", len = 20.584, text = "Querido diario: Ahora sí me siento bien. Le he pegado a uno de mis esbirros hasta hacerlo llorar como una niña pequeña. Mmm... Ahora siento una especie de malestar. ¡Espera un momento! ¡Maldición, soy un genio del MAL! El mal, ¿sabes? Estoy tan disgustado. Vuelvo enseguida." },
		[2832] = { file = "2832", len = 35.5, text = "Querido diario: Le he dado un abrazo y le he dicho que continúe con su buena labor. Ahora me siento mejor. Que esto quede entre nosotros, diario. ¿Por dónde iba? ¡Ah, sí, NARAIN! ¡AHHH! Odio a ese tío. Después de todo, fue Narain el que descubrió la curva en todos los exámenes, cuando ambos estudiábamos en el Instituto Gnomeregan para Manitas. Fui expulsado de la escuela, ¿te lo puedes creer? ¡En lo que a mí respecta, Gnomeregan tiene lo que se merece! Esto es todo por hoy. ¡Que duermas bien, diario!" },
		[2833] = { file = "2833", len = 29.884, text = "Querido diario: Me debo estar haciendo mayor. He olvidado por completo lo que te estaba diciendo de Narain y de su engaño. ¡De cualquier manera, me enfadé tanto cuando vi a un señuelo disfrazado de Narain en lugar de este, que ordené al Número Dos que destruyera a ese idiota! Monté en mi máquina voladora y empecé a destrozar su precioso, estúpido y simple libro en dracónico. ¡Qué fanfarrón! ¿Quién lee en dracónico? ¡Lo odio tanto!" },
		[2834] = { file = "2834", len = 34.873, text = "Querido diario: Lo siento, pero me estoy durmiendo. Estuve volando enfadado mientras arrojaba capítulos enteros de este estúpido libro. ¡Vi un demonio debajo mío en Negro Rumor y decidí utilizar el primer capítulo para formar un tornado mágico de papel y hacer añicos su cuerpo! Fue liberador. Magia + papel = diversión. Me hizo tan feliz, que decidí volar hacia los Reinos del Este. Mi primera parada fue en Núcleo de Magma. ¡Narain siempre habló de este sitio! \"Núcleo de Magma esto y Ragnaros lo otro...\"" },
		[2835] = { file = "2835", len = 24.215, text = "¿Sabes una cosa? Si le gusta tanto, quizás podría intentar volver a recopilar su libro, yendo a Núcleo de Magma y rescatando el capítulo de entre las cenizas! ¡Ja! Mientras estaba en el vecindario, pensé que algunos de esos técnicos esclavizantes en el laboratorio del viejo Victor Nefarius podrían encontrar un uso para este material dracónico. ¡Bombas fuera!" },
		[2836] = { file = "2836", len = 32.13, text = "Esto está empezando a convertirse en un deporte. ¡Realmente estaba muy entusiasmado rompiendo el maldito libro! Lanzar los siguientes trozos fue muy fácil. Entrañas, hogar de los asquerosos muertos y, posiblemente, el sitio donde preparan el mejor chile, mereció un capítulo. Ventormenta, la capital del queso, el otro. Querido diario: ¿alguna vez has añadido queso de Ventormenta al chile de Entrañas? ¿HOLA? Parece que suenan algunas alarmas." },
		[2837] = { file = "2837", len = 22.674, text = "Estaba tan cansado en este momento, que me dediqué a dar vueltas con la máquina voladora y me fui a casa. Pero antes realizaré otras dos paradas. Di un paseo con mi máquina voladora sobre Lord Kazzak y sus demonios en Escara Impía (detesta que lo haga) y otro cerca de la chimenea de Onyxia. Estoy $Gcansado:cansada;. Me voy a dormir." },
		[2838] = { file = "2838", len = 21.969, text = "A quien pueda interesar, Como me gustan estos juegos que jugamos. Sólo puedo suponer que si estás leyendo esta carta, que de algún modo, a través de la intervención divina, o milagro, consiguiste vencerme. Absurdo, lo sé, pero cosas más raras han pasado en la historia de este mundo." },
		[2839] = { file = "2839", len = 25.234, text = "Como todas las cosas en la vida, hay un lado glorioso, centelleando de tragedia, el caos y el mal de esta triste historia. Aunque me has matado, lo has hecho de modo tan lento y chapucero que me ha quedado tiempo para escribir esta carta. DESPUÉS de que destruí tu única esperanza de salvar este mundo. El polvo de cristalitos rojos es todo lo que queda de tu Fragmento de Cetro." },
		[2840] = { file = "2840", len = 15.569, text = "Disfruta la Némesis y el Armamento de Tempestira que hallarás en mi tesoro. Créeme cuando te digo esto: Tengo el gran placer de saber que hice lo que mi padre no pudo... sinceramente, Lord Victor Nefarius \"Nefarian\"" },
		[2841] = { file = "2841", len = 36.258, text = "En nombre de los Pastos de Bosquehumeante, te vuelvo a dar las gracias por ocuparte de esto. No estamos seguros de cuál es el grupo que tiene a Metzen, pero investigar cualquiera de los dos puede constituir un buen punto de partida. El tiempo es oro, $Gamigo mío:amiga mía; y, en este caso, tenemos muy poco. Sé rápido en tus tareas de rescate, ya que estos grupos no deben ser subestimados en lo que respecta a lo que son capaces de hacer. En cualquier caso, las dos páginas siguientes son las notas de rescate que hemos recibido. ¡Buena suerte!" },
		[2842] = { file = "2842", len = 30.485, text = "Si quieres que el reno vuelva con vida, deberás ser rápido con la recompensa. Los Piratas de los Mares del Sur no se muestran amables cuando hay retrasos en el pago y sabemos lo valiosa que resulta esta bestia para TU forma de piratería. Trae la suma de 1000 piezas de oro a la entrada de la cala del Aparejo Perdido en Tanaris. Cualquier intento por rescatar al reno hará que Metzen dé un paseo muy largo sobre una plancha muy corta. Sí... Los Piratas de los Mares del Sur" },
		[2843] = { file = "2843", len = 34.011, text = "Tu apreciada mascota no lo está pasando demasiado bien con el implacable calor de la Garganta de Fuego... Si eres listo, deberás cumplir nuestras peticiones sin demora. Debes traernos cinco rubíes estrellados y la suma de 700 piezas de oro. Coloca todo en un solo paquete sin marca alguna. Deja el paquete en las puertas del Paso de Fraguapiedra en el plazo de una semana. Si no accedes a nuestras peticiones, Metzen se convertirá en el plato principal del Festival de Invierno de los enanos Hierro Negro. Mmmm... reno..." },
		[2844] = { file = "2844", len = 22.596, text = "Más rápido que las águilas llegaron sus corceles, y él silbó, grito y los llamó por su nombre; \"¡Arre, Mercer! ¡Arre, Chilton! ¡Arre, Jordan y Kaplan! ¡Adelante, Nagle! ¡Adelante, Pardo! ¡Adelante, Goodman y Metzen! ¡Hacia lo alto del porche! ¡Hacia lo alto del muro! ¡Ahora salid de aquí! ¡Fuera de aquí! ¡Fuera de aquí todos!\"" },
		[2854] = { file = "2854", len = 7.732, text = "RANGOS DE OFICIALES DE LA HORDA Parte 2 Centurión Legionario Guardia de sangre Guardia de piedra" },
		[2855] = { file = "2855", len = 6.844, text = "RANGOS DE SOLDADOS DE LA HORDA Gran capataz Capataz primero Capataz Bruto Explorador" },
		[2856] = { file = "2856", len = 8.803, text = "RANGOS DE OFICIALES DE LA ALIANZA Parte 2 Campeón caballero Capitán caballero Teniente caballero Caballero" },
		[2857] = { file = "2857", len = 7.262, text = "RANGOS DE SOLDADOS DE LA ALIANZA Alférez Sargento primero Sargento Cabo Soldado" },
		[2858] = { file = "2858", len = 7.105, text = "Anthony Ray Stark 1961 - 2005" },
		[2872] = { file = "2872", len = 33.306, text = "A todos los hombres y mujeres sanos: La Plaga ha regresado y, para hacer frente a esta amenaza, debemos dejar a un lado todos nuestros conflictos. El Alba Argenta acabará con todos aquellos que no empuñen las armas contra la amenaza de la Plaga. Los que han decidido defender nuestras tierras están reunidos en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este. Juntos, venceremos. Guardián de los Pergaminos El Alba Argenta" },
		[2878] = { file = "2878", len = 63.582, text = "Mi querida Emily: Hace pocos días abandonamos el campamento en este lugar dejado de la mano de la Luz, siguiendo las órdenes del rey de regresar a casa. A pesar de lo inhóspito del paisaje, mi corazón estaba henchido de gozo, ya que sabía que tras el frío y penoso viaje hacia la costa y más allá, podría solazarme entre tus brazos. Hoy alcanzamos la costa y descubrimos que nuestros barcos, con los que íbamos a regresar, se habían convertido en cascajos quemados. No podemos irnos y no tenemos otra opción que internarnos en el corazón de esta abismal tierra baldía. He ido hasta el mismo fin del mundo para mantenerte a salvo, Emily... y ahora... desearía con todo mi corazón haberme quedado contigo en Lordaeron. Estás presente en cada momento de vigilia. En esta tierra gélida, tú eres mi fuente de calor, mi amada, y nadie podrá quitarme eso. Maxwell" },
		[2880] = { file = "2880", len = 58.828, text = "Reuben, te escribo a sabiendas que quizás nunca leas esto. No puedo permanecer inmóvil escuchando los golpes contra los muros de la Vega del Amparo. Los no-muertos rodean nuestra aldea y nos atacan constantemente. Tenemos que defender a nuestra gente hasta que lleguen los refuerzos. Me rompí la pierna durante el último ataque y aquí me ves, inútil y dejando una brecha en nuestras filas. No se escucha otro sonido que el de la batalla y la muerte. El miedo se huele en el aire. El príncipe Arthas está aquí, peleando en el frente con sus hombres. Si él no estuviese aquí ya hubiésemos muerto hace tiempo. Su amor por este territorio y su gente es abrumante. Sigo sus órdenes con esmero, con mi pierna rota o no, y por ello no puedo quedarme aquí. Tengo que ayudar con mi espada en el frente. Espero que estas palabras te lleguen en un mejor momento. Tu amigo, Leagrem" },
		[2881] = { file = "2881", len = 41.064, text = "Heliana: Yo, Vargus, vivo, a pesar de que tú desees lo contrario. Desprecio profundamente ir de un lado a otro metido en esta ridícula armadura. Nuestras últimas órdenes nos hicieron marchar hacia Andorhal en busca de grano o cualquier otra idiotez. ¿Por qué habrían de importarme los almacenes de alimento en Andorhal? Estar en el ejército es completamente absurdo. Tía Heliana, ten la seguridad de que regresaré para hacerme con tu herencia. Aunque quedara gravemente herido y sin alimento, el puro rencor me llevaría en andas para hacerme con la recompensa. Vargus" },
		[2882] = { file = "2882", len = 70.113, text = "Queridísima Amelia: Esta noche he visto cosas que me rondarán hasta el final de mis días. Stratholme está en llamas... y nosotros somos los causantes del incendio. Nuestro príncipe nos condujo a las calles de la ciudad por la noche. Ordenó entrar en las casas del pueblo y... matarlos mientras dormían. Estaban apestados, según Lord Arthas y, antes de que nos mataran, debían ser asesinados. Fue una carnicería. Cientos murieron silenciosamente bajo las espadas de aquellos que habían jurado protegerlos. No pude permanecer ni un minuto más allí: Huí. Aunque me haya convertido en un desertor, no puedo cometer semejantes atrocidades. En cada casa no veía más que tu rostro o los de nuestros niños, confundidos con los de las víctimas. Si estar contra esto significa ser un traidor, entonces lo soy. Espero poder encontrar el camino de regreso que me lleve a estar contigo, pero los caminos son inseguros. Transmite a nuestros hijos mi amor en mi ausencia. James" },
		[2883] = { file = "2883", len = 58.645, text = "Samla: A medida que seguimos a Lord Arthas en dirección al norte, siempre hacia el norte, mi corazón se entristecía cada vez más. Si bien una vez estuvo tocado por la Luz, ahora siento la oscuridad del espíritu del joven paladín. Su celo está oscurecido por una inquietante y extraña pesadilla que inunda su alma, imposible de adivinar... Pronto avistaremos tierra en los gélidos páramos. Aunque muchos de sus hombres han enfermado por el frío y por las batallas con las pútridas bestias, Arthas nos comunicó que lo que está buscando en el hielo cambiará el sentido de la batalla. Pero sus palabras no me han tranquilizado, porque después de pronunciarlas... la macabra sonrisa que se dibujó en sus ondulados labios me provocó un escalofrío más profundo que el de cualquier ventisca. Reza por nosotros, Samla, y reza por nuestro mundo, Torgal" },
		[2884] = { file = "2884", len = 44.487, text = "Querida Pamela: Mañana entraremos en batalla en Andorhal y me temo, amor mío, que esta va a ser mi última carta. Los no-muertos no se cansan y nosotros solo somos humanos. No podemos enfrentarnos a ellos. Pero no te inquietes, ya que, aunque estamos seguros de que vamos a morir, nuestras esperanzas permanecen firmes. ¡La Luz vencerá! Y, querida mía, me alegra saber que, mientras estos oscuros terrores derriban nuestros muros y caen sobre nosotros, mis últimos pensamientos no serán de muerte. Te recordaré entre mis brazos y, finalmente, tendré paz. Christoph" },
		[2885] = { file = "2885", len = 53.133, text = "Hola, $N. Al parecer, he extraído cierta información procedente de esta nota. Sobre James, me temo que apenas he encontrado nada. Sin embargo, he descubierto ciertos datos familiares sobre Amelia. Si bien ni ella ni sus hijos sobrevivieron a la guerra, su hermano, un hombre llamado Alexander Calder, sí sobrevivió. Puedes encontrarlo en la Caverna Abandonada en Forjaz, estudiando la peligrosa magia de la Legión Ardiente. Ella tenía una prima a la que estaba muy unida, una mujer conocida ahora como Deze Delirioníveo, que apoyó la batalla por la Cuenca de Arathi, en el territorio de Orgrimmar. Cuando estés cerca de cualquiera de ellos, deberías ir a visitarlos. Estoy seguro de que estarán muy interesados en recibir noticias de la pobre Amelia." },
		[2886] = { file = "2886", len = 49.215, text = "Saludos, $N. He pensado que los resultados de mi investigación podrían ser de tu interés. Al parecer, tanto a Reuben como a Leagrem los sobrevivieron, por así decirlo, sus familiares. Incluso si ya saben lo que ocurrió con el Soldado perdido, visitar a cualquiera de ellos puede valer la pena. Puedes encontrar a la ex mujer de Reuben, Joanna Salablanca, en el Barrio de la Guerra de Entrañas, en donde pasa la mayor parte del tiempo. No estoy seguro de cómo recibirá la noticia sobre su ex marido. En lo que respecta a Leagrem, su tía es la supervisora del orfanato de Ventormenta, un trabajo ciertamente admirable. Hagas lo que hagas en la vida, te deseo la mejor de las suertes en tus empeños." },
		[2887] = { file = "2887", len = 49.45, text = "$N, espero que cuando recibas esta carta te encuentres bien. Tras investigar un poco, he descubierto ciertos datos sobre aquellos que escribieron la nota que recuperaste. El padre de Samla conduce a los Renegados y a los Trols durante el peregrinaje a Cima del Trueno, siguiendo los caminos de su fe. Su nombre es Miles Galés y puedes encontrarlo junto con sus fieles no-muertos en las Pozas de las Visiones. Mientras tanto, a Torgal lo sobrevivió su prima Elissa Dumas. Según he sabido, es una ermitaña y pasa sus días en el Templo de la Luna en Darnassus. Te ruego que visites a cualquiera de estas personas, $N. Quizás nadie les haya traído noticias sobre la suerte de Torgal o de Samla." },
		[2888] = { file = "2888", len = 29.832, text = "El Guardián me entregó la carta que descubriste, $N, y creo que apreciarás en lo que vale tener noticias frescas. El último \"Vargus\" superviviente que se menciona en la carta ha sido encontrado en el desierto de Silithus, en el Fuerte Cenarion. Se le conoce como Garon Hutchins. La próxima vez que vayas a los páramos, deberías hablar con él. Está muy interesado en conocer los datos que obran en nuestro poder." },
		[2889] = { file = "2889", len = 37.094, text = "Saludos. Por fin he encontrado un poco de tiempo para examinar la carta que encontraste sobre la Plaga. Aunque me tomó cierto trabajo, creo haber descubierto a un pariente vivo de los fallecidos. La hermana de Maxwell, una tal Zarena Cromvento, dirige una pequeña armería en la Bahía del Botín. Desconozco cuál era el grado de relación con su hermano, pero si pasas por ahí, deberías concertar una cita con ella. Poder disponer de datos fehacientes sobre estas cuestiones es algo muy valioso y poco habitual en estos tiempos." },
		[2890] = { file = "2890", len = 37.433, text = "Finalmente he descubierto ciertos datos sobre el antiguo Soldado que combatiste. El rastro ha sido difícil de seguir, ya que su árbol genealógico no está debidamente documentado, pero he logrado encontrar a un pariente consanguíneo. ¿Puedes creer que el custodio Alen, de la Capilla de la Esperanza de la Luz, es en realidad el hijo de Christoph? Oír noticias sobre su padre seguro que le agradará mucho. Si alguna vez vuelves a estar de servicio en El Alba Argenta en las Tierras de la Peste, por favor, habla con él. Sería todo un detalle." },
		["n0bcd5c04-f4fd-4c5d-be1a-abeaddbe2063"] = { file = "n0bcd5c04-f4fd-4c5d-be1a-abeaddbe2063", len = 38.74, text = "Archidruida, $N hoy ha prestado un gran servicio para la tierra. Gracias a su valentía, se han limpiado los pozos de Pezuña Invernal, Tronacuerno y Crinferal de los venenos de los goblins. Con el tiempo, las aguas rejuvenecidas nutrirán a todos aquellos que caminen sobre las grandes llanuras de Mulgore y la tierra sanará. Alabada sea la Madre Tierra. Si estás de acuerdo, solicito que le des una recompensa acorde a su esfuerzo en nombre de todos en Poblado Pezuña de Sangre. Con profundo respeto, Mull Tronacuerno" },
		["n1208f38d-f4cf-412e-b4b9-c765116e6079"] = { file = "n1208f38d-f4cf-412e-b4b9-c765116e6079", len = 11.206, text = "PENDIENTES Empacar equipo para el viaje de cacería Hacer ganchos para el cinturón de Grund. Reparar el visor para soldar Enviarle una tarjeta a mamá Página 45" },
		["n195b2d89-0ea0-4c22-ac71-8fb7cdaaa1d0"] = { file = "n195b2d89-0ea0-4c22-ac71-8fb7cdaaa1d0", len = 27.873, text = "Saludos, $N: Desde que los espíritus de viento elementales se esfumaron, Zephras se encuentra al borde de la catástrofe. Las aves, las bestias y hasta las raíces bajo nuestros pies nos piden ayuda. Ven a verme en la base del Gran Árbol en el Poblado Thendal. Te guiaré y te enseñaré las artes de los druidas. - Xyton Ventargento, instructor de druidas" },
		["n195fd8dc-6bd7-4020-b4a9-dfe2143a5141"] = { file = "n195fd8dc-6bd7-4020-b4a9-dfe2143a5141", len = 37.224, text = "Ejecutor Zygand: Considero que nuestras defensas no son responsables de la presencia de la Plaga dentro de la isla. He visto a nuestras fuerzas en acción en El Baluarte y en el punto de ruta del este por mucho tiempo, y se necesitaría un auténtico ejército para derribarlas. De hecho, sospecho que estamos lidiando con seres creados recientemente a manos de algún enemigo que no hemos visto aún en nuestras fronteras. Seguiré investigando en esta dirección con la esperanza de que podamos terminar con este asunto de raíz. --Kristof" },
		["n1c5a37a2-0a38-46b8-b5fa-e848b2d9fd20"] = { file = "n1c5a37a2-0a38-46b8-b5fa-e848b2d9fd20", len = 38.139, text = "Informe sobre el estado de los wendigos en las cuevas cerca de Kharanos Escrito por la montaraz Gretchen según los descubrimientos del montaraz Cornelius Los wendigos rara vez abandonan sus cuevas, pero ha habido informes de ataques a civiles alrededor de asentamientos cercanos como Kharanos y Las Birras. Se muestran cada vez más alterados mientras buscan comida. Ya hemos perdido a uno de los nuestros en el intento de contenerlos. Aunque eliminar por completo a estas bestias no es viable, los montaraces solicitan" },
		["n1f0cbf8b-70a3-4f9c-b3c7-1600ae87a7ae"] = { file = "n1f0cbf8b-70a3-4f9c-b3c7-1600ae87a7ae", len = 43.389, text = "\"Una gran parte de la flora y fauna de las Islas Cielonatas deben su forma a las fuerzas elementales que gobiernan aquí en el reino del Muro Celeste. Muchas criaturas que alguna vez estuvieron sobre la tierra ahora cuentan con atributos dignos de las aves, como picos, garfas y plumas. Otras obtuvieron la habilidad para volar, aunque tales transformaciones son menos comunes que los cambios externos. Entre los shen'dorei, la influencia del plano elemental sobre su cuerpo ha sido gradual y sutil; sin embargo, en las últimas generaciones, sus efectos se han vuelto cada vez más dramáticos. Por ejemplo, consideremos el fenómeno mejor conocido como la \"bendición celeste\"." },
		["n21235bf8-30d4-4a47-94b5-ef3bddcf09a5"] = { file = "n21235bf8-30d4-4a47-94b5-ef3bddcf09a5", len = 15.203, text = "Tocas el cristal blanco y escuchas débiles sonidos en el viento. Es algún tipo de grabación de audio.\010\"La rebelión en Eldre'thalas, parte 1\"." },
		["n332351f5-3675-4ac3-9eda-a9bdfb98c5a7"] = { file = "n332351f5-3675-4ac3-9eda-a9bdfb98c5a7", len = 37.068, text = "Cuando los viejos árboles del bosque encantado fueron arrancados y derribados, la tierra tembló. Los bosquecillos y los claros al cuidado de los hijos y las hijas de Cenarius, y las torres de piedra de los hijos de las estrellas cayeron por tierra. Estaba nuestra reina, radiante incluso en la desesperación, en el caos de las batallas. El cielo encantado mudó sus colores con la descarga de la magia, con explosiones que amenazaban con destruir el mundo. El hermano luchó contra el hermano. Los elegidos lucharon" },
		["n3bda2d80-447e-4bfb-85e7-cf3359ac903b"] = { file = "n3bda2d80-447e-4bfb-85e7-cf3359ac903b", len = 54.047, text = "Mi querida Tabitha: Es extraño prever mi propia muerte. Escribí esta nota porque no sé el momento exacto en el que me reclamará el destino y, aunque sé que este será un pésimo discurso, mi pluma no logra transmitir el dolor que siento por alejarme de ti. Cada día, me despierta la tristeza de la que no pude protegerte. Lamento no haber podido proteger a nuestro niño y lamento que mi pesar haya caído en una trampa de la que no puede escapar. Eres mi amor y mi confidente y, gracias a ti, mi vida valió más de lo que hubiera valido por su cuenta. Todas las semanas, cuando me aventuro en las ruinas de lo que fue nuestro orgulloso hogar, temo que sea la última vez, y siempre agradezco regresar contigo. Espero que nos reunamos otra vez, aunque sea brevemente." },
		["n3c59aad1-b3a7-4cd2-96c3-49c629567ffd"] = { file = "n3c59aad1-b3a7-4cd2-96c3-49c629567ffd", len = 35.344, text = "Hermano Haalien: ¡Es hora de demostrarle tu valía a Al'Aketh! Ve a Ventarrosombra y encuentra el pilón. Has comunicado tu preocupación sobre los druidas y los más importantes de nuestra orden te han escuchado. Estos fieles soldados te acompañarán en tu honrada misión. Mata a todos los druidas antes de que interfieran con nuestros planes. Tenemos ojos y oídos en Valanaar que confirmarán tu éxito. ¡La hora del juicio está cerca! ¡Nadie podrá detener el comienzo! - N" },
		["n3c80ded4-ccd7-4024-9a51-8a4c6cfb89ba"] = { file = "n3c80ded4-ccd7-4024-9a51-8a4c6cfb89ba", len = 26.566, text = "Lady Cassandra Valor, amada madre y esposa No se sabe mucho sobre Cassandra además del amor que tenía por su familia. Crió a hijos valientes y fue el sostén de un fuerte esposo, lo que llevó a algunos a pensar que la grandeza de la familia se debía a ella. Un halago que siempre rechazaba con gracia. Si ha de ser recordada por algo, que sea porque todo lo que hizo fue por su familia." },
		["n3d0f06c1-5383-4f14-b7ab-16ad96705957"] = { file = "n3d0f06c1-5383-4f14-b7ab-16ad96705957", len = 47.726, text = "\"¿Quién es Al'Akir, el Señor del Viento? Los sacerdotes de los extremistas Al'Aketh pretenden hacernos creer que él es el verdadero gobernante del Muro Celeste, el reino que ahora llamamos hogar. Según su relato, no somos más que intrusos aquí, y un día se nos presentará Al'Akir para ajustar cuentas por haber invadido su dominio dentro del plano elemental. Aunque al principio tales declaraciones puedan parecer los delirios de los equivocados o los locos, quizá haya algo de verdad en ellas. Los espíritus de viento se vuelven evasivos y agitados cuando se les pregunta sobre la naturaleza de Al'Akir. Tanto es así, que el simple hecho de mencionar el nombre del \"Señor del Viento\" parece causarles mucha inquietud, incluso quizás miedo\"." },
		["n3e785942-323a-4f29-91b7-cf3f76b25a00"] = { file = "n3e785942-323a-4f29-91b7-cf3f76b25a00", len = 25.208, text = "\"Tras el punto álgido de la guerra y el Gran Cataclismo de Kalimdor, pronto se volvió evidente que este mundo había sido despojado de la magia de la que nuestro pueblo dependía. Tortheldrin, la dinastía que gobernaba en Eldre'Thalas, rápidamente puso en marcha un plan para garantizar la estabilidad y la continuidad de nuestro estilo de vida. Sin embargo, los métodos que pretendían emplear eran preocupantes\"." },
		["n3eee442c-20a5-4313-99ae-f2fe4f436b2d"] = { file = "n3eee442c-20a5-4313-99ae-f2fe4f436b2d", len = 25.469, text = "más recursos para reducir su propagación. No podemos seguir enviando aventureros a resolver el problema y esperar lo mejor. Tarde o temprano, la comida se acabará y los wendigos se verán forzados a atacar directamente nuestras ciudades. Incluso quizás Forjaz. Ofrezco mis condolencias a la familia del montaraz Cornelius, que luchó con valor para mantener a salvo al pueblo de Dun Morogh." },
		["n418258a2-82a0-4476-affb-1417e684b02c"] = { file = "n418258a2-82a0-4476-affb-1417e684b02c", len = 25.208, text = "\"Últimamente, los magísteres de la Suma Orden se han vuelto cada vez más recelosos de las intenciones de los espíritus de viento, e insisten en que todos los poderes y peligros originados en este reino deben comprenderse mejor. Aún si tales riesgos ahora se encuentran lejos de nosotros, los magísteres sostienen que ese conocimiento nos preparará mejor para enfrentarnos a lo que sea que suceda.\"" },
		["n45d3d50e-d9b1-4a38-8729-c52fd8bc7774"] = { file = "n45d3d50e-d9b1-4a38-8729-c52fd8bc7774", len = 38.139, text = "Si alguien encuentra esto, le suplico que haga todo lo posible por detenerlos. Solo quedaban unos pocos en la torre cuando escribí esta nota a las apuradas y me arrastré lejos. También, si puedes, recupera la pluma de la suerte de Raani. Le gustaba contar historias exageradas sobre cómo se la arrancó a una especie de pájaro de fuego, y creo que querría asegurarse de que esa pluma volviera a casa. Si logras recuperar también el sello de la familia de Arvensus Cantosombrío, te pido que lo hagas. El gran ancestro Cantosombrío es su tío y querría que se lo devolvieran a la familia." },
		["n46b1ddca-3738-4ff4-8966-f071e651cf1c"] = { file = "n46b1ddca-3738-4ff4-8966-f071e651cf1c", len = 36.284, text = "Ya sentiste el llamado de algo más grande que tú: el llamado de los elementos. Los enanos tenemos una fuerte conexión con la tierra, pero, con el entrenamiento correcto, puedes aprender a hablar con todos los elementos. Los elementales pueden ser demandantes y desafiantes, pero mi trabajo es guiarte para que aprendas a comunicarte con ellos. Ven a verme en Yunquemar y te enseñaré a escuchar a los elementos y a lograr que ellos te escuchen. - Teo Mazatormenta, instructor de chamanes" },
		["n4721bbfb-146a-4ed8-99c9-914840509936"] = { file = "n4721bbfb-146a-4ed8-99c9-914840509936", len = 36.702, text = "Atacaremos la ciudad de Rémol justo antes del amanecer. Nuestra fuerza secundaria encenderá la torre del zepelín para que sea una distracción. Cuando el fuego arda y atraiga a los defensores de la ciudad, nuestra fuerza principal, liderada por el teniente, atacará desde el norte. El objetivo principal son el magistrado y los civiles. Eliminen a todos los que vean e incineren los cuerpos. Dicen que los Renegados no sienten miedo. Haremos que vuelvan a temerle a la Luz, hermanos y hermanas. ¡Por Lordaeron!" },
		["n4800f21a-5a71-440a-8e47-46e8aff84a35"] = { file = "n4800f21a-5a71-440a-8e47-46e8aff84a35", len = 15.621, text = "Tocas el cristal blanco y escuchas débiles sonidos en el viento. Es algún tipo de grabación de audio.\010\"La rebelión en Eldre'thalas, parte 3\"." },
		["n4b049160-8b12-46e5-bcda-c344e7672b61"] = { file = "n4b049160-8b12-46e5-bcda-c344e7672b61", len = 52.454, text = "Lamento muchísimo de antemano el saber cómo se encuentra al recibir esta carta, venerable anciano. Tenga presente que enviaré a su hermoso pueblo a tantos aventureros en buena condición física como me sea posible. Espero que sus capacidades compensen por la falta de ayuda que puedo brindarle en este momento. Una gran cantidad de enemigos asedian nuestras tierras. Estoy seguro de que ya conoce las desdichas de ese mundo, por lo que me apena decir que los pocos recursos que tenemos son cada vez más escasos. Si la situación cambiase, estaré encantado de ayudar, pero, incluso en ese caso, hay proyectos más cercanos que exigen prioridad. Resista. Todos estamos capeando el temporal. –Baros Alexston Arquitecto de la ciudad, Ventormenta" },
		["n4b6297b7-4196-481a-9e95-9ffe9eb7f21b"] = { file = "n4b6297b7-4196-481a-9e95-9ffe9eb7f21b", len = 30.746, text = "Continúas hojeando el diario y terminas en un diagrama que ocupa ambas páginas.\010Modificaciones para el sistema de armamentos Torreta de hielo - En funcionamiento Lanzallamas - En funcionamiento Pulso eléctrico - En funcionamiento Pulverizador de radiación - En funcionamiento Rifle automático - En funcionamiento Rayo láser cercenador - EXPERIMENTAL Cañón sónico - EXPERIMENTAL Rayo de fase - SOLO CONCEPTO Página 34 Página 35" },
		["n4ff63af9-8be7-442f-bade-5208a9104542"] = { file = "n4ff63af9-8be7-442f-bade-5208a9104542", len = 15.412, text = "Tocas el pequeño cristal blanco y oyes que el viento acarrea sonidos casi imperceptibles. Se trata de alguna especie de grabación de audio.\010\"El misterio celeste\"" },
		["n507f446f-a1b9-406b-8039-903a102b0ee7"] = { file = "n507f446f-a1b9-406b-8039-903a102b0ee7", len = 32.052, text = "Saludos, $N: Espero que te encuentres bien. Quería agradecerte por haber hablado con Ur'seris y aceptado su pedido. Gracias a tus acciones, el bosque ahora es un lugar mucho más seguro, tanto para la fauna como para los shen'dorei. No sé adónde te llevarán los vientos, pero creo que harás grandes cosas. Espero que en tus aventuras encuentres a alguien que continúe tu instrucción druídica. Aeesha'el banu Zepharaalis. Lotheluum Brisa Estelar" },
		["n54e8667e-1aa9-43a0-b4d4-5b6cfc5cf1c9"] = { file = "n54e8667e-1aa9-43a0-b4d4-5b6cfc5cf1c9", len = 15.961, text = "Tocas el cristal blanco y escuchas débiles sonidos en el viento. Es algún tipo de grabación de audio.\010\"La rebelión en Eldre'thalas, parte 4\"." },
		["n55136b37-8722-4092-9b0d-1ea4b49acf44"] = { file = "n55136b37-8722-4092-9b0d-1ea4b49acf44", len = 35.631, text = "Tu primera parada debería ser Forjaz, a donde puedes llegar en esa maravilla tecnológica conocida como el Tranvía Subterráneo. Encontrarás la entrada en el Distrito de los Enanos, aquí en Ventormenta, al suroeste de la fortaleza. El tranvía te llevará directamente al corazón de la ciudad de Forjaz. Una vez allí, explora los alrededores y busca al Manitas Mayor Mekkatorque y al rey Magni Barbabronce, en Ciudad Manitas y la Gran Fundición, respectivamente. Preséntate como agente de los cielonato y te recibirán con los brazos abiertos." },
		["n5b3f01d9-940a-4b73-ae2e-349ac45706af"] = { file = "n5b3f01d9-940a-4b73-ae2e-349ac45706af", len = 28.421, text = "\"Seguiré al servicio de nuestro pueblo aquí, en Zephras, y dedicaré gran parte de mi tiempo a fortalecer nuestra relación con los espíritus del viento, a quienes tanto debemos. Los espíritus elementales son maravillosos y sabios, y aún nos queda mucho por aprender unos de otros. Me he comprometido a que los shen'dorei prosperen en este hermoso y extraño reino, y a que lo hagan en libertad, con justicia y sin las cadenas de la tiranía\"." },
		["n66288054-3c98-4808-95ff-23fd599fa313"] = { file = "n66288054-3c98-4808-95ff-23fd599fa313", len = 20.402, text = "Tocas el pequeño cristal blanco y un tenue murmullo llega con el viento. Parece tratarse de algún tipo de grabación.\010\"Un fragmento del discurso de Shal'nan durante la revolucionaria ceremonia del Santuario de los Cuatro Vientos, en la Isla Zephras\"." },
		["n6a11a2ed-13d4-4b40-984f-798d210c5163"] = { file = "n6a11a2ed-13d4-4b40-984f-798d210c5163", len = 15.229, text = "Elfa: Como invitada de la Horda, el Jefe de Guerra te ha concedido permiso para viajar libremente por todo el territorio de la Horda. Usa esta guía para ubicarte en nuestras tierras." },
		["n7720e44b-aa2e-495c-8d98-a5368b913d8b"] = { file = "n7720e44b-aa2e-495c-8d98-a5368b913d8b", len = 31.138, text = "Día 1 La actividad de Ventura y Cía. sigue siendo motivo de preocupación. Sus operaciones mineras no dejan de expandirse, y escucho un nuevo chirrido que me hace pensar que tal vez hayan traído una nueva y siniestra maquinaria. Aunque todavía no los veo como una amenaza real para Cima del Trueno, si se los provoca, podrían lanzar un ataque efectivo contra el poblado Pezuña de Sangre desde el sur." },
		["n80dbc1a1-287c-4588-9a8c-98ce36a75acd"] = { file = "n80dbc1a1-287c-4588-9a8c-98ce36a75acd", len = 32.679, text = "Saludos, $N: Has demostrado habilidades de cacería prometedoras. Me gustaría asegurarme de que recibas la guía y el entrenamiento adecuados. Los forestales son muy buenos para vigilar a la flora y la fauna cercanas a la Arboleda Thendal, pero, fuera de nuestro territorio... Bueno, no puede decirse lo mismo. Ven a verme cerca del centro del poblado cuanto antes. La naturaleza nos llama. - Tal'ree Vistadista, instructora de cazadores" },
		["n8389c275-3a1d-4f1c-9995-fa6d30a10d88"] = { file = "n8389c275-3a1d-4f1c-9995-fa6d30a10d88", len = 32.13, text = "\"Sea cual sea la verdad, claramente nuestros benefactores no desean hablar sobre Al'Akir o sus sirvientes, y no dudan en descartar todo rumor sobre la presencia del Señor del Viento como mera fantasía, indigna de tomarse en serio. Nos aseguran que aquí, a salvo en nuestras Islas Cielonatas, no debemos preocuparnos por tales asuntos. Aunque esto ofrece consuelo a muchos, también plantea una inquietante pregunta: ¿qué, exactamente, nos ocultan los espíritus de viento?\"" },
		["n848c79f4-b581-49d8-b5d0-e31f353587e6"] = { file = "n848c79f4-b581-49d8-b5d0-e31f353587e6", len = 41.561, text = "Silvia Valor, guardia de Cerro del Cuervo Silvia Valor ya era una heroína local para el momento en el que se le ofreció unirse a la Guardia. Si había algo que no podía soportar, era a los oportunistas que se aprovechaban de quienes estaban sufriendo. Bandidos, estafadores, agitadores, no importaba. Silvia exterminaba a todos aquellos que intentaran sembrar el caos en su amado hogar. Era inevitable que termine en una posición de autoridad real para representar su visión de la justicia. Se dice que, hasta su último aliento, nunca abandonó las granjas y los hogares de Bosque del Ocaso. Y quizás ni siquiera entonces." },
		["n8dc66862-0045-43fd-81f4-a662261123e1"] = { file = "n8dc66862-0045-43fd-81f4-a662261123e1", len = 47.83, text = "Bitácora del mecánico\010El pequeño diario forrado en cuero está lleno de manchas de aceite y grasa. Tiene bocetos de esquemas y configuraciones mecánicas, todos con anotaciones y descripciones escritas. Lo abres en una página al azar.\010Esta comisión me dará de comer durante años: solo tengo que descubrir cómo evitar que el neutralizador de oscilación se sobrecaliente o termine hecho virutas. Lo que necesito es crear un vórtice para transferir el exceso de calor al centro de combustión, pero estuve postergándolo porque necesito desmantelar toda la estructura y desarmar el motor por completo. Página 17" },
		["n8f3c6feb-0da8-4627-85f0-4c0eae1a2c43"] = { file = "n8f3c6feb-0da8-4627-85f0-4c0eae1a2c43", len = 32.47, text = "\"La frustración del príncipe Tortheldrin crecía cada vez más, pues temía que los debates interminables llevaran al deterioro de su reino. Como resultado, la respuesta a esta resistencia fue rápida y cruel. En una sola noche teñida de sangre, se llevó a cabo una purga donde se destruyeron por completo decenas de casas nobles. Se silenció con violencia a todos aquellos que se oponían públicamente a Tortheldrin y, de la noche a la mañana, linajes enteros llegaron a su fin\"." },
		["n901248c4-13f0-4285-8417-7821dc68d4ce"] = { file = "n901248c4-13f0-4285-8417-7821dc68d4ce", len = 36.598, text = "Aunque seas un refugiado que vino a Forjaz por desesperación, la Luz nunca les da la espalda a los necesitados. Con el tiempo, tu devoción crecerá y aprenderás a sentir el calor de la Luz. Nuestros primos gnomos son bienvenidos en nuestras filas como cualquier otro enano. Me doy cuenta de que tienes el don de canalizar la Luz. Es una habilidad especial que deberías cultivar. Ven a hablar conmigo cuando tengas tiempo. Estaré detrás de Yunquemar, sobre la colina. - Silo Khalder, instructor de sacerdotes" },
		["n991e9ed5-044b-4d7e-bec9-522f5b81160c"] = { file = "n991e9ed5-044b-4d7e-bec9-522f5b81160c", len = 14.994, text = "Tocas el pequeño cristal blanco y oyes que el viento acarrea sonidos casi imperceptibles. Se trata de alguna especie de grabación de audio.\010\"Sobre el Señor del Viento.\"" },
		["n9c9fd63f-87cd-48eb-91a3-b1256f3ad18b"] = { file = "n9c9fd63f-87cd-48eb-91a3-b1256f3ad18b", len = 47.386, text = "La Plaga se ha expandido por El Baluarte y la estación del este sin que nadie la detectara. Las bajas crecen día tras día. Me resulta imposible comprender cómo nuestras defensas fracasan sin cesar. Como mencioné en mis informes anteriores, el grupo miserable de guardias que se le asignó a Rémol no es suficiente para afrontar lo que nos espera. La cuestión no es si nos superarán, sino cuándo lo harán. Y cuando Rémol caiga, se darán las condiciones ideales para que tomen el control de Entrañas. Mientras tengamos la oportunidad, no les sugiero, sino que les ordeno que envíen refuerzos a los lujosos puestos de Entrañas para calmar la situación. --Guardia de la Muerte Dillinger" },
		["n9dd30961-d726-43da-a0d0-8683b31790d3"] = { file = "n9dd30961-d726-43da-a0d0-8683b31790d3", len = 15.569, text = "Tocas el cristal blanco y escuchas débiles sonidos en el viento. Es algún tipo de grabación de audio.\010\"La rebelión en Eldre'thalas, parte 2\"." },
		["na039a2dd-95ce-41bd-b53a-b7b8fe4541d2"] = { file = "na039a2dd-95ce-41bd-b53a-b7b8fe4541d2", len = 23.432, text = "Estas son las escrituras de un terreno en la región de los Páramos de Poniente. Otorga a los firmantes derechos de propiedad sobre el área en cuestión, así como sobre todos los objetos fabricados y todas las estructuras construidas dentro de sus fronteras. Firman este documento: Theodore Cejade Verna Cejade" },
		["na5c99c02-73ac-4849-8161-ebeceac588cf"] = { file = "na5c99c02-73ac-4849-8161-ebeceac588cf", len = 49.763, text = "Lord Grant Valor, señor de la familia Valor Lord Grant, que en paz descanse, fue el máximo exponente del excepcionalismo de la Alianza. Como líder natural, su mano guía ayudó a llevar a los habitantes de Cerro del Cuervo a la prosperidad. Cuando la oscuridad comenzó a escabullirse hacia el bosque, fue el primero en reunir a nuestro pueblo. Para Lord Grant, no existía enemigo más hediondo que los no-muertos. Él patrullaba personalmente los cementerios de Bosque del Ocaso para mantener a raya a las hordas tambaleantes. El día que recibió un golpe grave de los monstruos, todos en la ciudad compartieron su dolor. Gracias al cuidado de su familia, pudo retomar sus obligaciones, pero había una dolencia persistente que pareció perseguirlo el resto de su vida." },
		["na5ea988c-66a9-401a-8653-5927ec40977e"] = { file = "na5ea988c-66a9-401a-8653-5927ec40977e", len = 48.64, text = "\"Hoy en día, tres de cada diez niños que nacen en las Islas Cielonatas lo hacen con una impactante piel celeste. En los últimos siglos, la aceleración de nuestras alteraciones físicas ha aumentado, y muchos eruditos creen que los últimos vestigios de nuestra herencia kaldorei podría esfumarse por completo en el transcurso de dos o tres generaciones más. Puede que jamás se comprenda la razón de esta transformación. Sin embargo, está claro que al establecernos dentro del plano elemental, nosotros como pueblo nos vemos transformados por él a su vez. El Muro Celeste es un reino de maravillas, pero esto nos recuerda con crudeza lo poco que sabemos sobre los efectos que semejante lugar puede tener en quienes no nacieron allí\"." },
		["na963f6c4-8f9f-45e5-8fb0-a76949cc66dc"] = { file = "na963f6c4-8f9f-45e5-8fb0-a76949cc66dc", len = 21.499, text = "\"Inmediatamente después de la batalla, las fuerzas de Tortheldrin se dispersaron y desorganizaron. La mayoría se dedicaron a volver a proteger a la ciudad, y esta distracción permitió que los rebeldes que habían sobrevivido escaparan y se reagruparan. Sin un lugar adonde ir, el Shal'nan llevó al resto de sus tropas hacia las costas del oeste\"." },
		["naf7e950d-f4fc-4196-9ac9-1c0ef5fa73bb"] = { file = "naf7e950d-f4fc-4196-9ac9-1c0ef5fa73bb", len = 25.26, text = "¡Saludos, joven $c! Estoy muy orgullosa del esfuerzo que has demostrado durante tu instrucción hasta el momento. Debes sentirte honrada por haberte unido a la Zarpa. Recibirás más lecciones similares. La siguiente estará disponible una vez que hayas alcanzado el nivel 14. Cuando llegue ese momento, búscame en el Enclave Cenarion de Darnassus. Mathrengyl Garroso" },
		["nb06a2697-f9dc-400f-9462-03d6b4285390"] = { file = "nb06a2697-f9dc-400f-9462-03d6b4285390", len = 34.116, text = "Te doy la bienvenida otra vez, $N: Entiendo muy bien la conmoción que sientes al encontrarte en esta situación. Haber llegado hasta aquí te diferencia del resto de los paladines recién resucitados. Descubrirás que la parte más difícil de tu nueva vida será redescubrir lo que perdiste en vida... y soportar el dolor que eso te causa. Ven a verme en Camposanto y te ayudaré a encontrar la determinación para dar los primeros pasos. - Aramis Manomartillo, instructor de paladines" },
		["nbced579b-b3a1-4c66-b44b-856f7d76d334"] = { file = "nbced579b-b3a1-4c66-b44b-856f7d76d334", len = 29.936, text = "\"Con la fundación de nuestro nuevo hogar aquí, entre las nubes, damos inicio a una nueva era de paz y prosperidad para nuestro pueblo. Todos ustedes han soportado mucho para llegar hasta aquí. He visto a nuestro pueblo convertirse en una sociedad fuerte y autosuficiente, y eso me llena de un orgullo que no podría describir por completo. Sin embargo, la mayor fuente de ese orgullo viene de haber comprendido que ya no necesito seguir actuando como nuestro único gobernante\"." },
		["nbdba780d-5b3e-4184-a04d-5d354b6d64d8"] = { file = "nbdba780d-5b3e-4184-a04d-5d354b6d64d8", len = 21.029, text = "\"Hubo quienes alzaron su voz en oposición al plan del príncipe de canalizar una fuente de energía demoníaca para potenciar su red de focos cristalinos. Muchos de los opositores eran miembros de familias nobles que no dudaban en usar su influencia para moldear la opinión pública en contra de la dinastía Tortheldrin y del plan del príncipe\"." },
		["nbe7710ce-f68d-45ea-8641-81cb0034c292"] = { file = "nbe7710ce-f68d-45ea-8641-81cb0034c292", len = 24.764, text = "Mi amado Tarrel: No pasa un día sin que me pierda pensando en tus trenzas de bronce, tu risa poderosa y las olas que se forman en tus antebrazos. Debes venir a mí, en Auberdine, a bordo del próximo barco que zarpe. Debemos estar juntos. ¡Busca en tu corazón y sabrás que es verdad! Con amor, si lo aceptas, Hollee" },
		["nc7de7ad0-8603-4ee4-8ccd-4d24e922d672"] = { file = "nc7de7ad0-8603-4ee4-8ccd-4d24e922d672", len = 37.251, text = "\"El joven príncipe Tortheldrin intentó construir una red de focos cristalinos y usarlos para darle forma a una nueva fuente de poder que proveyera de magia a nuestro pueblo. Muchos no estaban de acuerdo, pues el príncipe planeaba alcanzar sus objetivos empleando el mismo poder que casi había destruido a nuestro mundo. Su intención era extraer este poder de un mundo demoníaco dentro del Vacío Abisal. Como era de esperarse, muchos temían que esto abriera un nuevo pasaje y permitiera que las entidades demoníacas se abrieran paso nuevamente hacia nuestro mundo\"." },
		["nc946874b-ef79-4996-b483-a82a17539c3d"] = { file = "nc946874b-ef79-4996-b483-a82a17539c3d", len = 18.782, text = "\"Gracias por todo lo que han sacrificado, por todo lo que han construido y por todo lo que me han enseñado sobre cómo ser una mejor persona. Todos ustedes representan la inquebrantable determinación del pueblo shen'dorei. Prosperaremos en este hermoso mundo nuevo y alcanzaremos nuevas metas\"." },
		["ncbdcba8a-57a9-48c1-b1ae-97028faedc24"] = { file = "ncbdcba8a-57a9-48c1-b1ae-97028faedc24", len = 44.251, text = "\"Los ancestros videntes del cielo entre los Formavientos, en cambio, depositan una confianza implícita en los espíritus de viento y toman cualquier duda sobre sus designios como una ofensa hacia nuestros benefactores. Sostienen que nuestros parroquianos en el Muro Celeste ya han sacrificado mucho para traernos aquí y sustentarnos. Afirman que, si hubiera algún conocimiento más que fuera vital para nuestra supervivencia, sin duda lo revelarían a su debido tiempo. Esta diferencia de creencias ha provocado una enorme tensión entre las dos órdenes. Sea cual sea la verdad, está claro que no estamos solos en este reino y que hay muchos misterios que aún están más allá de nuestra comprensión\"." },
		["nd1296fa6-1ad0-46d1-b541-d8fbcc725a9b"] = { file = "nd1296fa6-1ad0-46d1-b541-d8fbcc725a9b", len = 44.617, text = "\"En la noche del ritual de invocación, el Shal'nan y sus fuerzas atacaron. Creían que esta era su última oportunidad de desbaratar el osado plan del príncipe Tortheldrin, por lo que llevaron a cabo una incursión en el sagrario del príncipe con la intención de detener el ritual. Entonces, ocurrió lo que el Shal'nan y los rebeldes temían: el hechizo, que había sido lanzado con descuido, estaba fuera de control y amenazaba con destruir el centro de la ciudad. En el fulgor de la batalla, la magia salvaje se expandió por las calles y abrió portales al Vacío, por los que surgieron incontables monstruosidades arcanas malévolas que atacaban con crueldad a los indefensos ciudadanos de Eldre'Thalas\"." },
		["nd2aad973-cee7-483e-ba3d-3d638fb66335"] = { file = "nd2aad973-cee7-483e-ba3d-3d638fb66335", len = 43.494, text = "\"El mensaje de resistencia transmitido por el Shal'nan empezó a volverse popular en Eldre'Thalas, debido en gran parte a la humillación pública que sufría el príncipe prácticamente todos los días mediante las operaciones de los rebeldes. En ese entonces, se extendió rápidamente por el reino la noción de un estilo de vida alternativo más naturalista. Una gran influencia eran los druidas Cenarion, que habían obtenido el control del imperio kaldorei, al norte del continente. Incluso se rumoreaba que, en secreto, los rebeldes recibían el apoyo de agentes encubiertos enviados por el líder de facto de los elfos de la noche, el archidruida Malfurion Tempestira\"." },
		["nd36dc2ce-c5f3-4289-bf0f-6c67519621f9"] = { file = "nd36dc2ce-c5f3-4289-bf0f-6c67519621f9", len = 36.049, text = "\"Es bien sabido desde nuestro ascenso al Muro Celeste que nuestro pueblo ha adoptado formas más ágiles y delgadas, pero esto ocurrió en el transcurso de muchos milenios. En contraste, el primer caso registrado de la bendición celeste (razón por la que los niños shen'dorei nacen con piel de color cerúleo intenso) se observó hace menos de cinco generaciones. En el transcurso de una generación desde que apareció por primera vez, uno de cada veinte niños nacidos entre los cielonato presentaba esta curiosa alteración. Dos generaciones después, esa cifra se había duplicado\"." },
		["nd9a98559-6cdc-4a68-afab-609528384438"] = { file = "nd9a98559-6cdc-4a68-afab-609528384438", len = 55.406, text = "Estimado Alexston de Ventormenta: Debo felicitarlo por su extenso periplo para restaurar la ciudad de Ventormenta. Muchas de las personas que transitan por Auberdine alaban el esplendor y las recias bases de la capital, tanto así que me veo en la obligación de enviarle este mensaje. Auberdine encontró su lugar en el mundo junto al mar. Los mismísimos vientos que azotan nuestras costas, otrora motivo de aislamiento, ahora son lo que nos da esperanzas. Quien le envía esta misiva es uno de los tantos viajeros que los vientos me han traído. Espero que pueda ayudar a su pueblo tanto como lo ha hecho con el mío. A cambio, me gustaría pedirle que enviara provisiones y mano de obra a Auberdine, con el fin de apuntalar la ciudad para hacer frente a la furia de este mundo que tanto nos ha quitado. Thundris Tejevientos, Anciano de Auberdine" },
		["ne40dfdf3-0e1d-4b07-bedd-71c1f72e2136"] = { file = "ne40dfdf3-0e1d-4b07-bedd-71c1f72e2136", len = 44.199, text = "\"Cuando el atribulado ejército rebelde llegó a la ciudad portuaria de Eldre'narr, los magísteres que controlaban la ciudad habían oído hablar de la ira incontenible de Tortheldrin y de la orden aún vigente de matar de inmediato a cualquier rebelde que se hallara. En un acto de misericordia que parecía obra de un milagro, los magísteres no intentaron entorpecer el progreso de los rebeldes, pues les permitieron requisar varios barcos sin oponer resistencia alguna. El Shal'nan comprendió que este acto de misericordia podría ocasionar que Tortheldrin desatara su ira sobre Eldre'narr. Aun así, aceptó amablemente este regalo inesperado y, con pesar, navegó junto a los suyos al oeste, hacia lo desconocido\"." },
		["ne46011ac-5ebc-4a47-af26-a758941bc375"] = { file = "ne46011ac-5ebc-4a47-af26-a758941bc375", len = 26.984, text = "¡Eh, tú, $c! Levanta el trasero y ven a verme detrás de la abadía. una $c blandita y verde como tú no puede ni soñar con sobrevivir, ni mucho menos prosperar en estas tierras sin algo de orientación, ¡pero el viejo Tordrin está aquí para dártela, si tienes las agallas! Tordrin Filotallo, instructor de cacería (extremadamente apuesto)" },
		["ne6b93a0d-593a-4f3d-b183-1fd0d2e27d3b"] = { file = "ne6b93a0d-593a-4f3d-b183-1fd0d2e27d3b", len = 35.318, text = "Recuerdos de Valor Un relato sobre la familia Valor y su servicio a Cerro del Cuervo No hubo familia más grandiosa en todos los Reinos del Este que la familia Valor. Sus obras para el pueblo que juraron proteger fueron milagrosas, y su derrota lo es también para todos en Cerro del Cuervo. Escribo esto para dejar las cosas claras y dar cuenta de lo maravillosos que fueron Grant, Ira, Silvia y Merrick. Que estas palabras sirvan de pequeño consuelo por lo mucho que lamento su ausencia." },
		["necdc73e4-bc52-4fbf-aac5-9c3466e5d347"] = { file = "necdc73e4-bc52-4fbf-aac5-9c3466e5d347", len = 13.166, text = "Qué sorpresa, hay un tallado extraño en los restos de la manzana.\010Manzana... ¡Ñam, ñam! Yo recolectar flores ahora." },
		["nef24927c-02e2-4019-8a80-6f96c2656d76"] = { file = "nef24927c-02e2-4019-8a80-6f96c2656d76", len = 45.192, text = "\"Al final, la intervención de los rebeldes evitó que la catástrofe fuera aún peor, pero tuvieron que pagar un alto precio. La batalla se cobró muchas vidas de ambos bandos, pero las pérdidas que sufrieron los rebeldes fueron mayores. El Shal'nan fue el único que sobrevivió al enfrentamiento final en el sagrario de Tortheldrin. Según los registros de quienes más lo conocen, las heridas que sufrió en esa última batalla lo cambiaron para siempre. En los siglos posteriores a aquella oscura época, el Shal'nan jamás pronunció una sola palabra acerca de lo que había ocurrido y, si alguien osa preguntarle al respecto, se retrae y su semblante se torna nostálgico \"." },
		["nf0c55d06-c95f-4b09-b658-5a2126557985"] = { file = "nf0c55d06-c95f-4b09-b658-5a2126557985", len = 19.958, text = "Bienvenida: Como invitada de la Alianza, se te ha concedido permiso para viajar libremente por todo el territorio de la Alianza. Este documento te servirá de guía para que puedas ponerte en contacto con las demás ciudades que forman parte de nuestra coalición." },
		["nf27a3d3e-bee3-4c4b-9cd1-26be1b390d85"] = { file = "nf27a3d3e-bee3-4c4b-9cd1-26be1b390d85", len = 41.169, text = "\"El líder de los rebeldes era una figura misteriosa conocida como el 'Shal'nan' o 'El Oculto'. Llevaba una máscara dorada sin rasgos para esconder su identidad y proteger a sus seres queridos. Pronto, el hombre se convirtió en un símbolo para los ciudadanos comunes y corrientes que deseaban sublevarse contra la opresión, y el término Shal'nan se transformó en un grito de batalla que representaba la rebelión. Mediante el sabotaje, la coerción y (según dicen los rumores) el asesinato, los rebeldes pronto se convirtieron en un obstáculo en los esfuerzos del príncipe Tortheldrin por construir su red de focos cristalinos\"." },
		["nf3ca9ff7-c618-4fc5-972c-b673fa9ee34d"] = { file = "nf3ca9ff7-c618-4fc5-972c-b673fa9ee34d", len = 22.491, text = "El culto nos tomó por sorpresa. Raani no lo vio venir y a Arvensus le clavaron una espada en las tripas. A mí me dio un rayo en el pecho y perdí el conocimiento. Ni se molestaron en acabar conmigo... Supongo que asumieron que mis heridas se encargarían de mí. Y la verdad, puede que tengan razón." },
		["nf73410fe-cdd8-443a-a65a-c07107c7588d"] = { file = "nf73410fe-cdd8-443a-a65a-c07107c7588d", len = 21.002, text = "era Asterion, el cual vivió con la gente de Bashal'Aran y fue muchas veces a Ameth'Aran para combrobar los deseos y necesidades de sus habitantes. Y fue así, a orillas del Pozo de la Eternidad, como las dos ciudades hermanas crecieron y prosperaron, mientras el mundo bajo las estrellas se sumía lentamente en la locura." },
		["nf85fec87-a643-43e5-9dc5-c325201dc9fd"] = { file = "nf85fec87-a643-43e5-9dc5-c325201dc9fd", len = 18.599, text = "Ni bien terminó la pelea, empezaron a mover cajones enormes de piedras de viento a lo alto de la torre. El líder, algún tipo de sacerdote, dijo algo de un ritual. Escribo esta nota por si no llego a Shen'dar para advertirle a Aonda, pero aquí están tramando algo. Algo malo." },
		["nf953e52b-4cd3-4c81-98b1-86ada192ed3c"] = { file = "nf953e52b-4cd3-4c81-98b1-86ada192ed3c", len = 29.388, text = "\"En los días inmediatamente posteriores a los disturbios en el Pozo de la Eternidad, el malestar se apoderó de Eldre'Thalas. Las fuerzas demoníacas que manaron del Pozo casi logran aplastar a los atribulados reinos élficos, pues arrasaron con las tierras y mataron indiscriminadamente. Si no hubiera sido por la intervención del semidiós Goldrinn y el sacrificio de innumerables héroes kaldorei, el reino de Eldre'Thalas habría sido devastado por completo\"." },
		["nfe122f81-545d-4ad6-a272-1dea085d19f3"] = { file = "nfe122f81-545d-4ad6-a272-1dea085d19f3", len = 44.304, text = "\"El terror que ocasionó esta represión descarada trajo consigo una reacción de conmoción silenciosa en el pueblo de Eldre'Thalas. Todos los comentarios sobre el plan del príncipe Tortheldrin se detuvieron de un momento a otro... Al menos por un tiempo. Por desgracia para el príncipe, cuanta más presión ejercen los tiranos sobre su gente, más ardientes son las llamas de la resistencia. Existía un grupo que estaba decidido a garantizar que nuestro pueblo no repitiera los errores de la reina Azshara. Unos eruditos que habían pertenecido a la orden de los Shen'dralar se reunieron en secreto e hicieron un pacto. Juraron detener al príncipe costara lo que costara y comenzaron a plantar las semillas de la rebelión\"." },
		["nfed77efc-cb93-4121-be4f-0e1de444c7a9"] = { file = "nfed77efc-cb93-4121-be4f-0e1de444c7a9", len = 35.631, text = "Durante mucho tiempo, los hijos de las estrellas han vivido entre los bancos de las relucientes aguas del Pozo Eterno. Para todos es sabido que Elune, luz del crepúsculo eterno, Aspecto y diosa de la luna, permanecía en sus aguas cuando descansaba de sus tareas. Sobre las orillas del Pozo, los hijos de las estrellas, favorecidos por Elune, construyeron sus moradas, si bien sus miradas se dirigían al cielo en la noche iluminada por la luna. No obstante, había muchas ciudades y asentamientos" },
	},

